var QUESTOES_LINUX_GERAL = [{"id":11650,"enunciado":"Acerca do Internet Explorer e do sistema operacional Linux, assinale a opção correta.","opcoes":["Para conectar à Internet um microcomputador que tenha instalado o sistema operacional Linux, é necessária a utilização de uma placa de rede específica.","A conexão, à Internet, de um microcomputador que possui o sistema operacional Linux instalado é mais lenta quando comparada com um que tenha instalado o Windows XP.","Se um e-mail for criado a partir de algum aplicativo do sistema operacional Linux, ele não poderá ser lido por destinatário que usa o Windows XP.","Com o Linux é possível acessar a Internet usando uma rede sem fio (wireless)."],"correta":3,"explicacao":"Gabarito: <strong>Com o Linux é possível acessar a Internet usando uma rede sem fio (wireless).</strong>.","banca":"CESPE / CEBRASPE","ano":2009,"temas_relacionados":["linux_geral"]},{"id":11651,"enunciado":"Assinale a opção correspondente a características do sistema operacional Linux.","opcoes":["multitarefa, multiusuário, open source","monotarefa, multiusuário, open source","multitarefa, monousuário, gratuito","monotarefa, monousuário, gratuito"],"correta":0,"explicacao":"Gabarito: <strong>multitarefa, multiusuário, open source</strong>.","banca":"CESPE / CEBRASPE","ano":2009,"temas_relacionados":["linux_geral"]},{"id":18933,"enunciado":"Considera-se software livre um programa de computador que pode ser usado, copiado, estudado, modificado e redistribuído, ainda que sob certas restrições.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2009,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":18934,"enunciado":"A distribuição de software livre requer que a este seja anexada uma licença de software livre e a abertura de código.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2009,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":18935,"enunciado":"A licença de software livre deve minimamente conceder ao usuário os direitos de executar o progama, estudar o códigofonte e adaptá-lo às suas necessidades, redistribuir cópias, além de aperfeiçoar e comercializar o programa.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2009,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":18937,"enunciado":"Sob a perspectiva do software livre, software proprietário e software comercial são conceitos similares.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2009,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":28607,"enunciado":"Sabendo que um usuário acessa a Internet para desfrutar os recursos aludidos nos textos III e IV a partir de um computador que tem instalado, como sistema operacional, o Red Hat, é correto concluir que esse computador utiliza uma versão Linux de sistema operacional.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":30424,"enunciado":"Os sistemas Windows XP e Linux têm kernel comum, aberto, que pode ser facilmente customizado pelo usuário.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":30425,"enunciado":"O Linux, um sistema multitarefa e multiusuário, é disponível em várias distribuições, entre as quais, Debian, Ubuntu, Mandriva e Fedora.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":30427,"enunciado":"Tanto o Linux quanto o Windows XP possuem suporte nativo ao protocolo TCP/IP para acesso à Internet.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":40426,"enunciado":"Quanto a conceitos e características do sistema Linux, assinale a opção correta.","opcoes":["O sistema operacional Linux é monousuário, multitarefa e multiplataforma.","Para que o Linux funcione adequadamente, é necessária a instalação do TCP/IP separadamente, já que esse protocolo não é nativo nesse sistema operacional.","O Linux implementa consoles virtuais que, embora permitam a execução de diversas tarefas em foreground (primeiro plano), necessitam que o aplicativo backg seja executado, para a realização de tarefas em background (segundo plano).","Na criação de uma conta de usuário no Linux, origina-se um diretório de base, o qual é populado com um conjunto de arquivos padrão, copiados do diretório /etc/skel.","No Linux, para se assegurar a exclusão de um diretório de base do usuário, é necessário utilizar o comando userdelete com a opção - r."],"correta":3,"explicacao":"Gabarito: <strong>Na criação de uma conta de usuário no Linux, origina-se um diretório de base, o qual é populado com um conjunto de arquivos padrão, copiados do diretório /etc/skel.</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"temas_relacionados":["linux_geral"]},{"id":40427,"enunciado":"Assinale a opção correta a respeito de conceitos e características do sistema Linux.","opcoes":["O sistema de arquivos do Linux é organizado em uma hierarquia de diretórios que inclui /bin, /dev e /etc. No diretório /bin, encontram-se diversos comandos Linux, como ls, sort, date e chmod.","Os comandos mkdir e cd permitem, respectivamente, criar um diretório e listar os conteúdos de um diretório.","O comando pwd permite mudar de diretório corrente.","Por meio do comando chmod 664 arquivo.txt, permite-se que o arquivo.txt seja lido e gravado por todos os usuários do sistema.","Ao ser executado no Linux, o comando useradd usuário1 cria, para um usuário, uma entrada no arquivo /etc/passwd com uma senha genérica, atribui uma ID com número maior que 500, e também inclui o usuário no grupo apropriado."],"correta":0,"explicacao":"Gabarito: <strong>O sistema de arquivos do Linux é organizado em uma hierarquia de diretórios que inclui /bin, /dev e /etc. No diretório /bin, encontram-se diversos comandos Linux, como ls, sort, date e chmod.</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"temas_relacionados":["linux_geral"]},{"id":42405,"enunciado":"A respeito do sistema operacional Linux, julgue o item abaixo.\n\nNo Linux, os comandos rm e cp permitem, respectivamente, remover e copiar um ou mais arquivos.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":43646,"enunciado":"O Linux, por ser um software livre, apresenta diversas vantagens em relação a outros sistemas operacionais, mas tem a desvantagem de não permitir a conexão de pendrive ao computador.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":43872,"enunciado":"Acerca do sistema operacional Linux, assinale a opção correta.","opcoes":["No Linux, pode-se definir um caminho de diretórios a partir do uso de barras invertidas (\\), diferentemente do Windows, em que são utilizadas barras não invertidas (/).","O Linux disponibiliza, na barra de inicialização rápida, recurso para ligar ou desligar o computador com maior velocidade, empregando o conceito de boot parcial da máquina.","O Linux tem a desvantagem, com relação ao Windows, de ser mais vulnerável a vírus de computador, que se propagam com rapidez nesse ambiente, tornando os aplicativos lentos e infectando os arquivos.","Em ambiente operacional, o gerenciador de arquivos é utilizado para se visualizar a estrutura de diretórios e respectivos arquivos. No Linux, o Konqueror constitui exemplo de gerenciador de arquivos.","O diretório raiz do Linux é o C:\\."],"correta":3,"explicacao":"Gabarito: <strong>Em ambiente operacional, o gerenciador de arquivos é utilizado para se visualizar a estrutura de diretórios e respectivos arquivos. No Linux, o Konqueror constitui exemplo de gerenciador de arquivos.</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"temas_relacionados":["linux_geral"]},{"id":44221,"enunciado":"No sistema operacional Linux típico, o subdiretório /dev do diretório raiz contém os arquivos executáveis (binários) de comandos essenciais pertencentes ao sistema, e que são usados com frequência pelas aplicações.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":44222,"enunciado":"No sistema operacional Linux, um ponto (.) no início do nome identifica os arquivos ocultos.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":49922,"enunciado":"O Unix é um sistema operacional monoprocessado, o que garante maior controle de acesso e, consequentemente, maior segurança.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2009,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":49936,"enunciado":"Por ser um aplicativo de software livre, o BrOffice somente pode ser executado no Linux e no Unix, não sendo compatível com o sistema Windows.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2009,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":53834,"enunciado":"O Kernel do Linux deve ser descompactado no diretório","opcoes":["/usr/src, após login como root.","/root/src, após login como user.","/sys/src, após login como root.","/home, após login como wrapper.","/boot, após login como kewl."],"correta":0,"explicacao":"Gabarito: <strong>/usr/src, após login como root.</strong>.","banca":"FCC","ano":2008,"temas_relacionados":["linux_geral"]},{"id":53835,"enunciado":"Para customizar o KDE e parte do sistema operacional Linux, os usuários contam com o","opcoes":["Centro de controle KDE.","Gerenciador de telas KDE.","Konqueror.","KDeveloper.","KDM."],"correta":0,"explicacao":"Gabarito: <strong>Centro de controle KDE.</strong>.","banca":"FCC","ano":2008,"temas_relacionados":["linux_geral"]},{"id":58829,"enunciado":"O sistema Linux permite a alteração do código-fonte para a criação de um novo kernel, com a finalidade, por exemplo, de se obter uma maior autonomia de controle de hardware dos computadores.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2009,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":58830,"enunciado":"O Linux é utilizado por usuários de computadores do tipo PC pela facilidade de alterações e inclusões de novas funcionalidades. No entanto, o Linux não pode ser empregado em servidores pertencentes a uma rede de comunicação.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2009,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":58832,"enunciado":"Os comandos do Linux mkdir, rm, mv e ls permitem, respectivamente, criar diretórios, renomear arquivos, limpar a tela e enviar arquivo para impressão.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2009,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":63593,"enunciado":"Com relação ao sistema operacional Linux, assinale a opção correta.","opcoes":["Em uma distribuição do sistema Linux, é possível encontrar software destinados a diversas finalidades, como para prover serviço de acesso à Internet. No ambiente Linux, também se dispõe de uma área de trabalho (GUI) para uso do sistema operacional a partir de uma interface gráfica.","Pelo fato de ser um software proprietário, qualquer usuário pode fazer alterações no ambiente e colaborar para a melhoria do sistema Linux.","O código-fonte do sistema operacional Linux não pode ser alterado; por essa razão ele não é distribuído sob a licença GPL ou GNU, que é pública e permite modificações no código.","KDE Control Center é a área de trabalho do Linux pela qual se faz acesso a aplicativos instalados no computador, como o BrOffice e outros.","O Linux não permite que sejam instalados outros sistemas operacionais na mesma máquina, pois isso afetaria o desempenho do computador, tornando-o lento."],"correta":0,"explicacao":"Gabarito: <strong>Em uma distribuição do sistema Linux, é possível encontrar software destinados a diversas finalidades, como para prover serviço de acesso à Internet. No ambiente Linux, também se dispõe de uma área de trabalho (GUI) para uso do sistema operacional a partir de uma interface gráfica.</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"temas_relacionados":["linux_geral"]},{"id":63594,"enunciado":"Assinale a opção correta com referência a edição de textos, planilhas e apresentações em ambiente Linux.","opcoes":["O BrOffice não possui interoperabilidade com outros ambientes; por isso, para que os arquivos gerados no BROffice sejam legíveis em outros computadores, é necessário salvá-los no formato .pdf","Base é o software utilizado para se criar planilhas eletrônicas a partir de dados importados de outros aplicativos, como o Math e o Calc.","O Impress permite a criação de imagens vetoriais (desenhos), as quais podem ser impressas por meio de qualquer aplicativo do BrOffice.","Os aplicativos do BROffice permitem a criação de arquivos nos formatos típicos de outros ambientes, como, por exemplo, da suíte Microsoft (MS) Office. Dessa forma, esses arquivos podem ser abertos e alterados pelo aplicativo correspondente do MS Office.","O Writer, o editor de textos do BrOffice, é capaz de gerar arquivos no formato .doc ou odt, mas não permite a edição ou alteração de arquivos em html."],"correta":3,"explicacao":"Gabarito: <strong>Os aplicativos do BROffice permitem a criação de arquivos nos formatos típicos de outros ambientes, como, por exemplo, da suíte Microsoft (MS) Office. Dessa forma, esses arquivos podem ser abertos e alterados pelo aplicativo correspondente do MS Office.</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"temas_relacionados":["linux_geral"]},{"id":72432,"enunciado":"Em um sistema GNU/Linux, a interface gráfica de uma aplicação deixa de responder subitamente, quais devem ser os comandos usados para identificar e destruir a aplicação?","opcoes":["ps e kill","ps e unlock","list e kill","top e del","list e unlock"],"correta":0,"explicacao":"Gabarito: <strong>ps e kill</strong>.","banca":"IF-SE","ano":2010,"temas_relacionados":["linux_geral"]},{"id":72433,"enunciado":"Considerando os sistemas operacionais windows XP e Linux, assinale a opção CORRETA:","opcoes":["O Linux é um sistema operacional monotarefa, enquanto que o Windows é multitarefa.","O KDE e o Gnome são dois gerenciadores de usuários do Linux.","A única maneira de executar um programa de usuário no windows é através de um ícone na área de trabalho.","O Linux é um sistema operacional gratuito, de código aberto, desenvolvido e lançado ao mundo pela primeira vez por Linus Benedict Torvalds, enquanto que o Windows é um sistema operacional de código fechado e pago.","O painel de controle de ambos os sistemas permitem a criação de arquivos e pastas."],"correta":3,"explicacao":"Gabarito: <strong>O Linux é um sistema operacional gratuito, de código aberto, desenvolvido e lançado ao mundo pela primeira vez por Linus Benedict Torvalds, enquanto que o Windows é um sistema operacional de código fechado e pago.</strong>.","banca":"IF-SE","ano":2010,"temas_relacionados":["linux_geral"]},{"id":74033,"enunciado":"Nas distribuições Linux, as principais bibliotecas de sistema e os arquivos de configuração e scripts de inicialização ficam armazenados nos seguintes diretórios:","opcoes":["/bib e /cfg","/ bib e /etc","/lib e /scr","/lib e /etc","/lib e /cfg"],"correta":3,"explicacao":"Gabarito: <strong>/lib e /etc</strong>.","banca":"FGV","ano":2010,"temas_relacionados":["linux_geral"]},{"id":74039,"enunciado":"A respeito das características do software livre, analise as afirmativas a seguir. I. É disponibilizado com a permissão para qualquer um usá-lo, copiá-lo, e distribuí-lo, seja na sua forma original ou com modificações, seja gratuitamente ou com custo. II. É gratuito com a permissão para qualquer um usá-lo ou copiá-lo, exclusivamente na sua forma original, não podendo ser modificado. III. É freeware disponível com a permissão para qualquer pessoa usá-lo e modificá-lo, não podendo ser copiado ou distribuído. Assinale:","opcoes":["se somente a afirmativa I estiver correta.","se somente as afirmativas I e II estiverem corretas.","se somente as afirmativas I e III estiverem corretas.","se somente as afirmativas II e III estiverem corretas.","se todas as afirmativas estiverem corretas."],"correta":0,"explicacao":"Gabarito: <strong>se somente a afirmativa I estiver correta.</strong>.","banca":"FGV","ano":2010,"temas_relacionados":["linux_geral"]},{"id":82129,"enunciado":"O particionamento de disco pode ser feito de maneira automática ou pode ser definido pelo usuário.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2009,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":82131,"enunciado":"Após o reboot do sistema operacional, no arquivo instal.log, em /root, encontram-se os pacotes que foram instalados.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2009,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":85374,"enunciado":"Em relação aos recursos comuns, tanto no Windows, quanto no Linux, é INCORRETO afirmar que possuem","opcoes":["sistema operacional de código aberto.","sistema operacional multiusuário e multitarefa.","suporte a vários sistemas de arquivos.","restrição de acesso a usuários, arquivos e pastas (diretórios).","administração e assistência remotas."],"correta":0,"explicacao":"Gabarito: <strong>sistema operacional de código aberto.</strong>.","banca":"FCC","ano":2011,"temas_relacionados":["linux_geral"]},{"id":88594,"enunciado":"O sistema de diretório do Linux apresenta os diretórios de maneira hierarquizada, por isso, também é conhecido como árvore de diretórios.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2011,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":91011,"enunciado":"Para a instalação de software em um computador, é sempre necessária a utilização de um CD-ROM contendo o(s) arquivo(s) do programa a ser instalado.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2011,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":91012,"enunciado":"Software livre, ou de domínio público, é o software que pode ser usado, copiado, estudado, modificado e redistribuído sem restrição.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2011,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":91177,"enunciado":"O Linux permite a utilização de pendrives em ambiente gráfico.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2011,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":91178,"enunciado":"No Linux, os arquivos de log são gravados, por padrão, no diretório /home.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2011,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":91179,"enunciado":"Durante o processo de desligamento (shutdown) do sistema operacional, o Linux, independentemente da versão utilizada, salva todo e qualquer documento que estiver aberto no diretório /bin.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2011,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":91361,"enunciado":"O Linux permite que o sistema seja inicializado tanto em modo texto, usando-se um shell orientado a caractere com um interpretador de comandos, como em um sistema de janelas, utilizando-se um shell gráfico.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2011,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":91363,"enunciado":"O Linux suporta o protocolo IP e possui navegadores web, o que permite acesso à Internet.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2011,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":91387,"enunciado":"Na partição de boot do Linux, estão localizados os diretórios /etc e /root, que são responsáveis, entre outras coisas, pela manutenção dos arquivos binários executáveis do Linux.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2011,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":93680,"enunciado":"Ubuntu é um sistema operacional com base em Linux desenvolvido para notebooks, desktops e servidores.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":93681,"enunciado":"O sistema operacional Windows é mais seguro do que o Linux, uma vez que o Linux possui código aberto e facilita a ocorrência de vulnerabilidades.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":95811,"enunciado":"Acerca da estrutura de pastas do Linux, analise as seguintes afirmativas: I. O diretório raiz está tomado pelas pastas do sistema e espera-se que o usuário armazene seus arquivos pessoais dentro da sua pasta no diretório /home. II. O diretório /bin armazena os executáveis de alguns comandos básicos do sistema, como o su, tar, cat, rm, pwd. III. a pasta /boot armazena o Kernel e alguns arquivos usados pelo Lilo (ou grub, dependendo de qual distribuição o usuário instalou), que são carregados na fase inicial do boot. Podemos afirmar corretamente que:","opcoes":["Todas as afirmativas estão corretas.","Todas as afirmativas estão incorretas.","Apenas as afirmativas I e II estão corretas.","Apenas as afirmativas II e III estão corretas."],"correta":0,"explicacao":"Gabarito: <strong>Todas as afirmativas estão corretas.</strong>.","banca":"INSTITUTO CIDADES","ano":2009,"temas_relacionados":["linux_geral"]},{"id":95812,"enunciado":"O modo de comando, no Sistema Operacional Linux, é uma forma de se comunicar com o sistema com mais opções do que seria possível através de um utilitário gráfico e obtendo respostas mais rápidas. Acerca de comando do Sistema Linux, marque a alternativa INCORRETA:","opcoes":["O comando cd serve para acessar as pastas, o comando “cd /” volta ao diretório Raiz e o comando “cd ..” sobe uma pasta.","O comando startx serve para abrir a interface gráfica a partir do prompt, caso você tenha escolhido inicializar o sistema em modo texto.","O comando ls serve para listar uma pasta.. O comando \"ls l more\" quebra a lista em páginas e serve para pausar a listagem, para que o usuário consiga ler tudo.","O comando rm serve tanto para mover arquivos quanto para renomear arquivos."],"correta":3,"explicacao":"Gabarito: <strong>O comando rm serve tanto para mover arquivos quanto para renomear arquivos.</strong>.","banca":"INSTITUTO CIDADES","ano":2009,"temas_relacionados":["linux_geral"]},{"id":147982,"enunciado":"A respeito do sistema operacional Linux, assinale a opção correta.","opcoes":["Kernel é a interface gráfica do Linux, que tem visual muito similar à interface do sistema operacional Windows XP.","O Linux funciona em dezenas de plataformas, desde mainframes até relógios de pulso, passando por várias arquiteturas e dispositivos.","O KDE é o navegador nativo do Linux que permite acesso à Internet e envio de e-mail.","O Linux adota a GPL, uma licença que permite aos interessados usá-lo, mas sem a possibilidade de redistribuí-lo."],"correta":1,"explicacao":"Gabarito: <strong>O Linux funciona em dezenas de plataformas, desde mainframes até relógios de pulso, passando por várias arquiteturas e dispositivos.</strong>.","banca":"CESPE / CEBRASPE","ano":2009,"temas_relacionados":["linux_geral"]},{"id":147993,"enunciado":"Acerca do sistema operacional Linux, assinale a opção correta.","opcoes":["No Linux, um usuário comum não pode causar danos ao sistema operacional da máquina de forma acidental.","Para gravar um CD em computadores que utilizam o Linux, é necessário instalar o programa Ubuntu que permite gerar discos de áudio e vídeo.","O Gnome é um programa nativo do Linux para tratamento de imagens.","Uma das desvantagens do Linux é a necessidade do usuário digitar comandos para realizar tarefas como gravar arquivos."],"correta":0,"explicacao":"Gabarito: <strong>No Linux, um usuário comum não pode causar danos ao sistema operacional da máquina de forma acidental.</strong>.","banca":"CESPE / CEBRASPE","ano":2009,"temas_relacionados":["linux_geral"]},{"id":148820,"enunciado":"No Linux, o gerenciamento de arquivos é realizado pelo programa Math, que possibilita criar pastas e organizá-las.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":148821,"enunciado":"Uma diferença marcante entre os software Windows e Linux é o fato de este ser um sistema de código aberto, desenvolvido por programadores voluntários espalhados por toda a Internet e distribuído sob licença pública.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":148823,"enunciado":"A compactação pode ser utilizada para minimizar o tamanho de um arquivo e, com isso, agilizar a transmissão deste pela Internet.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":152199,"enunciado":"O Linux é um sistema operacional multitarefa que pode ser instalado em servidores ou em computadores pessoais.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":199783,"enunciado":"O sistema operacional Linux não pode ser instalado em máquinas que possuam o sistema operacional OS/2.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2011,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":199784,"enunciado":"No ambiente Linux, o comando ls permite listar todos os arquivos do diretório atual.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2011,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":199785,"enunciado":"No sistema operacional Linux, se o usuário root desejar reiniciar o computador, é suficiente que ele pressione, simultaneamente, as teclas","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2011,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":199836,"enunciado":"Os clientes Windows XP de uma LAN com servidor Linux acessam os arquivos hospedados nesse servidor por meio do","opcoes":["Man","Bind","Samba","Apache","Postifix"],"correta":2,"explicacao":"Gabarito: <strong>Samba</strong>.","banca":"CESGRANRIO","ano":2011,"temas_relacionados":["linux_geral"]},{"id":199838,"enunciado":"Nos sistemas Linux, um processo pode ser interrompido por meio do comando kill. Para isso, é necessário saber o pid desse processo Qual comando deve ser utilizado para obter esse pid?","opcoes":["ps","ls","du","set","pwd"],"correta":0,"explicacao":"Gabarito: <strong>ps</strong>.","banca":"CESGRANRIO","ano":2011,"temas_relacionados":["linux_geral"]},{"id":203557,"enunciado":"Ao se comparar o sistema operacional Windows XP com o sistema operacional Linux, pode-se afirmar que:","opcoes":["Ambos realizam basicamente as mesmas funções, embora não necessariamente tenham a mesma estrutura.","No Windows tem Calculadora e no Linux não tem programa(s) equivalente(s).","No Windows tem o Paint e no Linux não tem programa(s) equivalente(s).","No Windows tem o WordPad e no Linux não tem programa(s) equivalente(s).","No Windows grande parte das configurações é concentrada em um único local, o Painel de Controle e no Linux não há recurso equivalente."],"correta":0,"explicacao":"Gabarito: <strong>Ambos realizam basicamente as mesmas funções, embora não necessariamente tenham a mesma estrutura.</strong>.","banca":"CONSULPLAN","ano":2006,"temas_relacionados":["linux_geral"]},{"id":203559,"enunciado":"O Linux é um sistema operacional: I. Considerado proprietário. II. Considerado software livre. III. Misto, isto é meio proprietário, meio livre. Assinale a alternativa correta:","opcoes":["Somente a afirmativa I está correta.","Somente a afirmativa II está correta.","Somente a afirmativa III está correta.","Todas as afirmativas estão incorretas.","Todas as afirmativas estão corretas."],"correta":1,"explicacao":"Gabarito: <strong>Somente a afirmativa II está correta.</strong>.","banca":"CONSULPLAN","ano":2006,"temas_relacionados":["linux_geral"]},{"id":239099,"enunciado":"Considere as afirmações abaixo, relacionadas à estrutura de diretórios: I. Se no Windows os arquivos do sistema estão concentrados nas pastas Windows e Arquivos de programas, localizados em discos e partições identificadas por letras (C:, D:, E:, etc), no Linux tudo faz parte de um único diretório, o diretório raiz (/), que hospeda todas as pastas do sistema, todos os arquivos, as partições de disco e até mesmo CD-ROM, floppy disk e outros dispositivos. II. O diretório \"/bin\" armazena os executáveis de alguns comandos básicos do sistema, tais como o su, tar, cat, rm e pwd, enquanto o diretório /usr acomoda a maioria dos programas, o que o torna o diretório com mais arquivos em qualquer distribuição Linux. III. Os arquivos contidos no diretório /dev, que ocupam um espaço considerável de armazenamento, na prática funcionam como ponteiros para dispositivos de hardware a fim de ajudar no trabalho dos programadores, já que, sem esses ponteiros, o acesso ao hardware do micro demandaria maior complexidade para os programas lerem e gravarem em arquivos. IV. O diretório \"/etc\" concentra os arquivos de configuração do sistema, substituindo de certa forma o registro do Windows. Os arquivos recebem o nome dos programas seguidos geralmente da extensão .conf, a exemplo do arquivo de configuração do servidor DHCP, que é identificado como: /etc/dhcpd.conf É correto o que consta em","opcoes":["I, II e IV, apenas.","II, III e IV, apenas.","I, II e III, apenas.","I, III e IV, apenas.","I, II, III e IV."],"correta":0,"explicacao":"Gabarito: <strong>I, II e IV, apenas.</strong>.","banca":"FCC","ano":2010,"temas_relacionados":["linux_geral"]},{"id":239111,"enunciado":"Considerando X para Microsoft Office 2003 e Y para OpenOffice.org 2.0, assinale a alternativa que exibe corretamente a compatibilidade dos sistemas operacionais, software de banco de dados e cliente de e-mail com os processadores de texto, planilhas eletrônicas e banco de dados, instalados nativamente em tais ferramentas de automação de escritório:","opcoes":["Compatibilidade/","Compatibilidade    Sistema Operacional  - Windows  - XY /Linux - XY  /Mac OS X - Y","Compatibilidade   -  Sistema Operacional  - Windows  - X  /Linux - Y /Mac OS X - XY","Compatibilidade - Sistema Operacional  - Windows  - XY /Linux - Y  /Mac OS X - Y","Compatibilidade  - Sistema Operacional  - Windows  -  XY /Linux -  XY/ Mac OS X - Y"],"correta":3,"explicacao":"Gabarito: <strong>Compatibilidade - Sistema Operacional  - Windows  - XY /Linux - Y  /Mac OS X - Y</strong>.","banca":"FCC","ano":2010,"temas_relacionados":["linux_geral"]},{"id":239391,"enunciado":"A denominada licença GPL (já traduzida pra o português: Licença Pública Geral)","opcoes":["garante as liberdades de execução, estudo, redistribuição e aperfeiçoamento de ´programas assim licenciados, permitindo a todos o conhecimento do aprimoramento e acesso ao código fonte.","representa a possibilidade da Administração Pública em utilizar gratuitamente de certos softwares em face da supremacia do interesse público.","representa a viabilidade do público em geral aproveitar o software em qualquer sentido porem preservando a propriedade intelectual do desenvolvedor.","garante ao desenvolvedor os direitos autorais em qualquer país do mundo. Jk","assegura apenas a distribuição gratuita de programas. X"],"correta":0,"explicacao":"Gabarito: <strong>garante as liberdades de execução, estudo, redistribuição e aperfeiçoamento de ´programas assim licenciados, permitindo a todos o conhecimento do aprimoramento e acesso ao código fonte.</strong>.","banca":"PC-SP","ano":2012,"temas_relacionados":["linux_geral"]},{"id":239395,"enunciado":"Constituem sistemas operacionais de código aberto","opcoes":["Free Solaris, MAC OS, Open BSD","DOS, Linux e Windows.","Linux, Mac OS, Windows e OS 2.","Linux, OpenBSD e Free Solaris.","Windows, Mac OS, OpenBSD"],"correta":3,"explicacao":"Gabarito: <strong>Linux, OpenBSD e Free Solaris.</strong>.","banca":"PC-SP","ano":2012,"temas_relacionados":["linux_geral"]},{"id":250334,"enunciado":"Em relação ao sistema operacional Linux, no que tange à segurança da informação, pode-se \"deletar\" (apagar) todos os dados de um arquivo, de forma destrutiva, por meio de várias regravações repetidas com dados aleatórios. O comando utilizado para essa finalidade é:","opcoes":["knode","pine","shred","rm -k","rm -1fv"],"correta":2,"explicacao":"Gabarito: <strong>shred</strong>.","banca":"VUNESP","ano":2011,"temas_relacionados":["linux_geral"]},{"id":258688,"enunciado":"A propósito de organização e gerenciamento de arquivos e pastas,julgue o  próximo  item.\n\nO sistema de arquivos VFAT do Linux possui suporte a journaling e é utilizado normalmente para transferir dados entre sistemas Windows e Linux instalados no mesmo disco, pois pode ser lido e escrito por ambos os sistemas operacionais.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2012,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":258701,"enunciado":"A respeito de ferramentas e aplicativos de navegação, julgue o  item   seguinte.\n\n\nO serviço discovery do Linux, também conhecido como zeroconf do KDE, é um recurso que possibilita ao usuário adicionar domínios nos quais serão pesquisados recursos compartilhados, tais como desktops e servidores de ssh, para conexão.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2012,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":259843,"enunciado":"No Linux, a sintaxe sudo adduser fulano criará o usuário fulano no grupo /etc/skell, bem como criará o diretório /home/fulano.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2012,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":259852,"enunciado":"No Linux, em um mesmo diretório, não podem existir dois subdiretórios com o mesmo nome, contudo, em virtude de os nomes dos diretórios serem case sensitive, é possível criar dois subdiretórios de nomes /usr/TreRJ e /usr/trerj.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2012,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":259853,"enunciado":"No Linux, o diretório /bin contém programas do sistema que são utilizados pelos usuários, não sendo necessário, para que esses programas sejam executados, que eles possuam a extensão .exe.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2012,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":274692,"enunciado":"No Linux, o sistema de arquivos pode ter um formato arbitrariamente longo. Entretanto, cada componente de um nome de caminho deve ter, no máximo, 4.095 caracteres.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2012,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":274693,"enunciado":"Os sistemas operacionais Linux podem ser inicializados tanto no modo automático como no modo manual. No modo automático, o sistema executa o procedimento de inicialização completo por sua conta, sem qualquer comando externo. No modo manual, o sistema segue o procedimento automático até determinado ponto, a partir do qual, antes de a maioria dos scripts de inicialização ter sido executada, passa o controle ao operador da máquina.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2012,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":274813,"enunciado":"Com base na situação hipotética acima apresentada, julgue o item\n\n\n\n\n\nOs sistemas operacionais Windows e Linux oferecem recursos que possibilitam separar arquivos que tratem do mesmo assunto e criar pastas ou diretórios nos discos e memórias auxiliares para gravar programas e arquivos relativos a um mesmo tema.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2012,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":274815,"enunciado":"Na situação hipotética descrita, o servidor com o sistema Windows é mais apropriado que o empregado com Linux, pois é mais vantajoso e confiável para lidar com grande volume de visitas e operações no sítio da empresa.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2012,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":275062,"enunciado":"Para modificar o grupo de um arquivo no Linux, é necessário ser o proprietário do arquivo, pertencer ao grupo que está sendo modificado ou ser o superusuário.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2012,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":275064,"enunciado":"No Linux, o sistema de arquivos apresenta-se hierarquizado de forma que se inicia no diretório \\ e percorre um número arbitrário de subdiretórios de modo unifilar, sendo o diretório \\ também denominado diretório-raiz.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2012,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":277577,"enunciado":"Ao ser utilizado em conjunto com o comando grep, o comando tail permite alterar a saída do conteúdo de arquivo de texto para html.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2012,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":277578,"enunciado":"O comando touch é utilizado para criar um arquivo vazio.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2012,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":277579,"enunciado":"O comando diff é usado para comparar arquivos de texto.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2012,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":277580,"enunciado":"O comando cut é utilizado para organizar, em ordem decrescente, o conteúdo de um arquivo de texto.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2012,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":280164,"enunciado":"Ao contrário de um software proprietário, o software livre, ou de código aberto, permite que o usuário tenha acesso ao código-fonte do programa, o que torna possível estudar sua estrutura e modificá-lo. O GNU/Linux é exemplo de sistema operacional livre usado em servidores.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2012,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":280166,"enunciado":"Quando se liga um computador, o sistema operacional é acionado, possibilitando inicializar e gerenciar o hardware e tornando possível sua utilização pelo usuário. O Linux e o Windows são sistemas operacionais distintos e possuem comandos diferentes para executar uma mesma tarefa, como listar arquivos de um diretório, por exemplo.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2012,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":294106,"enunciado":"No Linux, os nomes de arquivos podem ter até 256 caracteres, porém o nome de arquivo Um_nome_arquivo_longo+uma_longa_exntensão é inválido, pois o sinal + é um caractere reservado e não pode ser usado.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2012,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":294108,"enunciado":"O sistema operacional Linux possui vários shells com características ligeiramente diferentes e funções especiais, sendo alguns deles incapazes de diferenciar letras maiúsculas e minúsculas.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2012,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":294402,"enunciado":"No Linux é possível configurar permissões de leitura (r), escrita (w) e execução (x), tanto para arquivo quanto para diretórios. Para diretório, x indica que é possível executar o diretório como arquivo binário.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2012,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":294403,"enunciado":"No Linux o diretório padrão de usuários é o /home/user e o de aplicativos, é o /etc/bin.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2012,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":294404,"enunciado":"Tanto no Linux quanto no Windows 7 a organização de diretórios e arquivos é realizada por meio de estruturas em árvore. A diferença é que no Windows 7 com NTFS um diretório somente pode estar hierarquicamente associado a no máximo um diretório superior, enquanto no Linux com ext4, não há esta restrição.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2012,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":300347,"enunciado":"No ambiente Linux, os comandos são arquivos que têm permissão para serem executados e, normalmente, encontram-se armazenados no diretório /mnt.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2013,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":300351,"enunciado":"O kernel do Linux está constantemente em desenvolvimento por uma comunidade de programadores, mas, para garantir a sua qualidade e integridade, existem mantenedores do kernel, como o Linus Torvalds, que analisam e julgam a pertinência das alterações.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2013,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":310185,"enunciado":"No conceito de software livre a liberdade de execução do programa restringe-se a determinados propósito.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":310186,"enunciado":"O acesso ao código-fonte do software livre permite adaptá-lo às necessidades dos usuários.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":310187,"enunciado":"Como não pode ser vendido, o software livre é redistribuído aos usuários.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":310188,"enunciado":"Software livre é diferente de software em domínio público. Ainda assim, um software em domínio público pode ser considerado como um software livre.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":310189,"enunciado":"As modificações feitas por usuários são compartilhadas pelos demais, e todos têm acesso às informações, o que tem favorecido o aperfeiçoamento desse tipo de software.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":311299,"enunciado":"A respeito do sistema operacional Linux, julgue os itens que se seguem.\n\n\n\n\nO Linux é um sistema operacional de código aberto que pertence à classificação de software livre e permite a verificação de seu mecanismo de funcionamento e até mesmo a correção de eventuais falhas ou problemas.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":311301,"enunciado":"A respeito do sistema operacional Linux, julgue os itens que se seguem.\n\n\n\n\n\nUm computador cujo sistema operacional seja o Linux pode ser inicializado e acessado por um usuário que não esteja cadastrado no sistema. No entanto, para garantir certo grau de segurança e privacidade, é necessário digitar nome de usuário e senha na tela inicial do sistema.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":311302,"enunciado":"A respeito do sistema operacional Linux, julgue os itens que se seguem.\n\n\n\n\nDeterminada página do manual do programa Linux pode ser acessada por meio do comando man [seção] [comando/arquivo], em que [seção] refere-se à seção do manual que será aberta e [comando/arquivo], ao comando ou arquivo que se deseja pesquisar.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":315272,"enunciado":"Os sistemas Windows e Linux se assemelham na possibilidade de uso de interface de linha de comandos: o comando dir, no Windows, pode produzir listagem de arquivos em pasta ou diretório, assim como o comando ls, no Linux.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2013,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":315276,"enunciado":"Distintamente do que ocorre na plataforma Linux, em que há maior flexibilidade para a realização de controle do firewall, o uso de firewall pessoal nativo na plataforma Windows possibilita o bloqueio de entrada de pacotes oriundos da Internet, mas não a saída de pacotes de dados de origem interna direcionados à Internet.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2013,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":316040,"enunciado":"Sobre os comandos do sistema operacional Linux, atribua V (verdadeiro) ou F (falso) às afirmativas a seguir. ( ) ls lista o conteúdo de um diretório. ( ) tar é utilizado para descompactar arquivos. ( ) top é utilizado para mudar a prioridade de processos. ( ) kill é utilizado para enviar sinais a processos. ( ) bg é utilizado para suspender a execução de um processo. Assinale a alternativa que contém, de cima para baixo, a sequência correta.","opcoes":["V, V, F, V, F","V, F, V, V, F.","V, F, F, V, V.","F, F, V, F, V.","F, V, V, F, V."],"correta":0,"explicacao":"Gabarito: <strong>V, V, F, V, F</strong>.","banca":"COPS-UEL","ano":2013,"temas_relacionados":["linux_geral"]},{"id":316042,"enunciado":"Deseja-se criar um link simbólico do arquivo vim, o qual deverá ser chamado de vi. Assinale a alternativa que criará, corretamente, tal link simbólico.","opcoes":["cp -s vi vim","ln -s vim vi","ln -s vi vim","cp vim vi","cp vi vim"],"correta":1,"explicacao":"Gabarito: <strong>ln -s vim vi</strong>.","banca":"COPS-UEL","ano":2013,"temas_relacionados":["linux_geral"]},{"id":316043,"enunciado":"A montagem e a desmontagem de dispositivos no sistema operacional Linux utilizam arquivos presentes em que diretório?","opcoes":["/bin","/usr","/boot","/dev","/tmp"],"correta":3,"explicacao":"Gabarito: <strong>/dev</strong>.","banca":"COPS-UEL","ano":2013,"temas_relacionados":["linux_geral"]},{"id":316046,"enunciado":"A placa de rede de um computador executando Linux estava apresentando um comportamento estranho. De modo a tentar resolver o problema, digitou-se no console a seguinte sequência de comandos: ifconfig eth0 down ifconfig eth0 up Em relação ao procedimento realizado, assinale a alternativa correta.","opcoes":["O primeiro comando diminuiu a velocidade do dispositivo de rede.","O primeiro comando reiniciou o driver de rede.","O segundo comando atuou na primeira interface Ethernet.","O segundo comando aumentou o throughput do dispositivo de rede.","O segundo comando testou o dispositivo de rede."],"correta":2,"explicacao":"Gabarito: <strong>O segundo comando atuou na primeira interface Ethernet.</strong>.","banca":"COPS-UEL","ano":2013,"temas_relacionados":["linux_geral"]},{"id":316048,"enunciado":"Um dispositivo de cdrom foi montado através do seguinte comando: mount /dev/sr0 /media/cdrom -t iso9660 -o ro,exec Sobre essa montagem, assinale a alternativa correta.","opcoes":["A opção -t monta o dispositivo apenas por um período de tempo predeterminado.","A montagem permite leitura e escrita.","A montagem permite a execução de binários.","A opção iso9660 informa o modelo do dispositivo a ser montado.","O dispositivo foi montado no diretório /dev/sr0."],"correta":2,"explicacao":"Gabarito: <strong>A montagem permite a execução de binários.</strong>.","banca":"COPS-UEL","ano":2013,"temas_relacionados":["linux_geral"]},{"id":318362,"enunciado":"Considerando a situação mostrada na figura acima, que reproduz parte de uma janela do MPU no Internet Explorer, julgue os itens seguintes.\n\nO navegador Internet Explorer não pode ser executado no sistema operacional Linux, visto ter sido criado exclusivamente para ser executado no ambiente Windows.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2013,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":323625,"enunciado":"Com relação aos sistemas operacionais Linux e Windows e às redes de computadores, julgue o  item seguinte:\n\nTanto o sistema operacional Linux quanto o Windows possuem gerenciador de arquivos, que permite a organização dos dados em pastas e subpastas, também denominadas, respectivamente, diretórios e subdiretórios.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2013,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":325624,"enunciado":"No Linux, o comando que permite mudar de diretório é:","opcoes":["chmod","ls","cd","mkdir","rmdir"],"correta":2,"explicacao":"Gabarito: <strong>cd</strong>.","banca":"FUNCAB","ano":2013,"temas_relacionados":["linux_geral"]},{"id":325628,"enunciado":"No sistema operacional Linux,o comando que NÃO está relacionado a manipulação de arquivos é:","opcoes":["kill","cat","rm","cp","ftp"],"correta":0,"explicacao":"Gabarito: <strong>kill</strong>.","banca":"FUNCAB","ano":2013,"temas_relacionados":["linux_geral"]},{"id":342984,"enunciado":"Considerando a figura acima e os conceitos de sistemas operacionais Windows e Linux, julgue os itens que se seguem.\n\nO Linux é um sistema operacional monotarefa, ou seja, permite a instalação de vários programas ao mesmo tempo.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2009,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":353679,"enunciado":"Acerca de organização e gerenciamento de informações, julgue o próximo item.\n\nEm ambiente Linux, o comando mv é utilizado para mover ou renomear um ou mais arquivos e diretórios, o que facilita a organização das informações.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2013,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":357107,"enunciado":"No Sistema Operacional Linux, ao utilizar o Prompt de Comando para trabalhar, se for ordenar um arquivo de linhas alfabeticamente, o comando certo a ser utilizado será","opcoes":["head.","mkdir.","mdir.","tail.","sort"],"correta":4,"explicacao":"Gabarito: <strong>sort</strong>.","banca":"IDECAN","ano":2012,"temas_relacionados":["linux_geral"]},{"id":357108,"enunciado":"Sobre os diretórios encontrados nos Sistemas Linux, relacione corretamente as colunas. 1. bin ( ) Bibliotecas. 2. dev ( ) Diretório de usuários. 3. etc ( ) Programas binários (executáveis). 4. lib ( ) Arquivos especiais para disposivitos E/S. 5. usr ( ) Arquivos diversos do sistema. A sequência está correta em","opcoes":["3, 4, 2, 1, 5","4, 5, 1, 2, 3","1, 3, 4, 5, 2","2, 1, 3, 4, 5","5, 2, 1, 3, 4"],"correta":1,"explicacao":"Gabarito: <strong>4, 5, 1, 2, 3</strong>.","banca":"IDECAN","ano":2012,"temas_relacionados":["linux_geral"]},{"id":357109,"enunciado":"Nos computadores de hoje, facilmente pode-se ter dois sistemas operacionais instalados, sendo que a inicialização apresenta a opção de escolher o Sistema Operacional para iniciar a máquina. Esse processo denomina-se Dual Boot. O Linux utiliza um gerenciador de inicialização, o que facilita ter máquina em Dual Boot. Identifique os gerenciadores de inicialização mais utilizados no mundo Linux.","opcoes":["LILO e GRUB.","MBR e LILO.","GRUB e MBR.","BIOS e GRUB","LILO e BIOS."],"correta":0,"explicacao":"Gabarito: <strong>LILO e GRUB.</strong>.","banca":"IDECAN","ano":2012,"temas_relacionados":["linux_geral"]},{"id":363978,"enunciado":"No Linux, para executar um comando em segundo plano, deve ser informado no final do comando o caractere:","opcoes":["/","&","?",">",":"],"correta":1,"explicacao":"Gabarito: <strong>&</strong>.","banca":"FUNCAB","ano":2013,"temas_relacionados":["linux_geral"]},{"id":363985,"enunciado":"No sistema operacional Windows, qual a ferramenta que possui uma função correspondente ao comando kill do Linux?","opcoes":["Prompt DOS.","Gerenciamento do Computador.","Gerenciador deTarefas.","Visualizador de Serviços.","Painel de Controle."],"correta":2,"explicacao":"Gabarito: <strong>Gerenciador deTarefas.</strong>.","banca":"FUNCAB","ano":2013,"temas_relacionados":["linux_geral"]},{"id":367332,"enunciado":"A presença do \"super-usuário\" no modo de comandos é","opcoes":["[usuario@microx diretorio]+","[usuario@microx diretorio]#","[usuario@microx diretorio]@","[usuario@microx diretorio]$","[usuario@microx diretorio]&"],"correta":1,"explicacao":"Gabarito: <strong>[usuario@microx diretorio]#</strong>.","banca":"UNIRIO","ano":2012,"temas_relacionados":["linux_geral"]},{"id":367333,"enunciado":"Suponha o uso da seguinte sintaxe: #chmod 723 aula.txt. A permissão do dono, do grupo e outros em relação ao arquivo “aula.txt” é o dono pode","opcoes":["o dono pode gravar, apagar e executar; O grupo pode ler; Os outros podem ler e apagar.","o dono pode gravar, ler e apagar; O grupo pode gravar; Os outros podem ler e executar.","o dono pode gravar, ler e executar; O grupo pode gravar; Os outros podem gravar e executar.","o dono pode apagar, ler e localizar; O grupo pode executar; Os outros podem ler e apagar.","o dono pode gravar e executar; O grupo pode ler; Os outros podem ler e gravar."],"correta":2,"explicacao":"Gabarito: <strong>o dono pode gravar, ler e executar; O grupo pode gravar; Os outros podem gravar e executar.</strong>.","banca":"UNIRIO","ano":2012,"temas_relacionados":["linux_geral"]},{"id":367335,"enunciado":"Em uma empresa X, existem 3 usuários (Jose, Luis e Aline). A sintaxe correta para inserir estes usuários num grupo chamado “adm” é a seguinte:","opcoes":["chfn jose adm; chfn luis adm; chfn aline adm.","groupadd jose adm; groupadd luis adm; groupadd aline adm.","passwd jose adm; passwd luis adm; passwd aline adm.","chgroup jose adm; chgroup luis adm; chgroup aline adm.","adduser jose adm; adduser luis adm; adduser aline adm."],"correta":4,"explicacao":"Gabarito: <strong>adduser jose adm; adduser luis adm; adduser aline adm.</strong>.","banca":"UNIRIO","ano":2012,"temas_relacionados":["linux_geral"]},{"id":368650,"enunciado":"Com relação ao sistema operacional Linux, julgue o item seguinte\nNo ambiente Linux, um pacote é definido como um arquivo que contém os arquivos binários necessários para a instalação de um aplicativo.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":368651,"enunciado":"Com relação ao sistema operacional Linux, julgue o item seguinte\nQuando executado no console do Linux, o comando vi possibilita alterar o modo de acesso, ou seja, as permissões de um arquivo ou diretório.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":377380,"enunciado":"Os ambientes Linux e Windows têm estruturas de diretórios semelhantes, como, por exemplo, o diretório /bin, que no Linux é responsável por manter os principais comandos do sistema.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":377382,"enunciado":"No ambiente Linux, é possível manter um único arquivo em um servidor e compartilhá-lo com vários usuários, eliminando-se cópias desnecessárias desse arquivo.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":380182,"enunciado":"Com relação ao ambiente Linux, analise as afirmações a seguir. I. O KDE e o Gnome são um conjunto de bibliotecas e aplicativos para configuração do sistema e desenvolvimento de aplicativos no Linux. II. Uma das limitações ao uso do Linux em relação ao Windows é a sua dificuldade de manutenção por usuários iniciantes. III. Uma das desvantagens do Linux é a permissão de acesso ao código-fonte, podendo alterar, compilar e verificar mudanças e erros. IV. O Wine é uma solução que viabiliza o suporte a programas nativos do Windows em ambiente Linux. Então, assinale a alternativa que contempla somente afirmações corretas","opcoes":["II, III e IV","I, II e III","I, II e IV","I, II, III e IV"],"correta":2,"explicacao":"Gabarito: <strong>I, II e IV</strong>.","banca":"FUNCEFET","ano":2011,"temas_relacionados":["linux_geral"]},{"id":380186,"enunciado":"Assinale os sistemas de arquivos que, entre outros, são mais utilizados atualmente pelas distribuições Linux, e cujo desempenho é considerado muito bom.","opcoes":["VFAT e NTFS","Ext4 e FAT32","FAT32 e NTFS","Ext3 e ReiserFS"],"correta":3,"explicacao":"Gabarito: <strong>Ext3 e ReiserFS</strong>.","banca":"FUNCEFET","ano":2011,"temas_relacionados":["linux_geral"]},{"id":380188,"enunciado":"“find” é um programa de computador de busca de arquivos utilizado em plataforma Unix e derivados (Linux). Ele procura por um ou mais diretórios na árvore da estrutura do sistema de arquivos, localizando arquivos baseados em um critério estabelecido pelo usuário. Ele também suporta expressões regulares e pode ser usado para aplicar um certo comando em vários arquivos. Então, o comando find ~/ -iname *.pdf ! -size +25M","opcoes":["mostra todos os arquivos “.pdf” maiores que 25MB.","mostra arquivos criados a menos de 25 minutos e que possuem extensão “.pdf”.","mostra todos os arquivos “.pdf” que não sejam maiores que 25MB","conta quantos arquivos “.pdf” há na pasta pessoal “~/”."],"correta":2,"explicacao":"Gabarito: <strong>mostra todos os arquivos “.pdf” que não sejam maiores que 25MB</strong>.","banca":"FUNCEFET","ano":2011,"temas_relacionados":["linux_geral"]},{"id":380201,"enunciado":"Analise as seguintes afirmações sobre pacotes do Linux: . Os pacotes .tar, .deb e .rpm podem ser instalados diretamente em qualquer distribuição Linux. I. Os pacotes .tar, .deb e .rpm podem ser instalados diretamente em qualquer distribuição Linux. II. A instalação de pacotes .deb e .rpm pode ser feita tanto através do shell, quanto pelo ambiente gráfico. III. Os pacotes .deb e .rpm têm a vantagem da instalação de dependências e a fácil desinstalação. Então, a alternativa que contempla as afirmações corretas é","opcoes":["II e III.","I e II.","I e III.","I, II e III."],"correta":0,"explicacao":"Gabarito: <strong>II e III.</strong>.","banca":"FUNCEFET","ano":2011,"temas_relacionados":["linux_geral"]},{"id":402053,"enunciado":"Acerca dos sistemas operacionais Windows e Linux, julgue os itens subsecutivos.\n\nNo Windows 7 e em suas versões superiores, o ambiente gráfico é nativo do sistema operacional. O ambiente gráfico no Windows, assim como no Linux, funciona como um servidor de gráficos e é denominado prompt de comando gráfico.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":402055,"enunciado":"Acerca dos sistemas operacionais Windows e Linux, julgue os itens subsecutivos.\n\nNo Linux, ambientes gráficos são executados por meio de um servidor, geralmente Xwindows ou X11, o qual fornece os elementos necessários para uma interface gráfica de usuário.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":404074,"enunciado":"Julgue o item a seguir, a respeito dos sistemas operacionais Windows e Linux.\n\nNo ambiente Linux, os comandos executados por um usuário são interpretados pelo programa shell.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":404075,"enunciado":"Julgue o item a seguir, a respeito dos sistemas operacionais Windows e Linux.\n\nOs programas e aplicativos do Linux são os mesmos nas diversas distribuições existentes, o que o caracteriza como um sistema operacional de fácil utilização.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":436090,"enunciado":"Acerca de noções dos sistemas operacionais Linux e Windows, assinale a opção correta.","opcoes":["O Windows permite trabalhar com multiprocessadores, sendo esse sistema operacional, por esse motivo, denominado multitarefa.","As principais características do Linux são a multitarefa, o multiusuário e a conexão com outros tipos de sistemas operacionais.","O Windows é um sistema operacional projetado para desktops de usuários domésticos, enquanto o Linux foi criado para grandes corporações.","Por ser gratuito, o sistema operacional Linux não pode ser utilizado para aplicações comerciais, enquanto o Windows não possui essa limitação.","O Linux é um sistema operacional monoprogramável e não configurável."],"correta":1,"explicacao":"Gabarito: <strong>As principais características do Linux são a multitarefa, o multiusuário e a conexão com outros tipos de sistemas operacionais.</strong>.","banca":"CESPE / CEBRASPE","ano":2013,"temas_relacionados":["linux_geral"]},{"id":460149,"enunciado":"Julgue o item a seguir, relativo aos sistemas operacionais Linux e Microsoft Word 2013.\n\nComparativamente a computadores com outros sistemas operacionais, computadores com o sistema Linux apresentam a vantagem de não perderem dados caso as máquinas sejam desligadas por meio de interrupção do fornecimento de energia elétrica.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":460154,"enunciado":"Julgue o item que segue, referente a redes de computadores, às ferramentas utilizadas nessas redes e ao navegador Google Chrome.\n\nFuncionalidades disponibilizadas no aplicativo PuTTY permitem que os usuários acessem um computador com o sistema operacional Linux a partir de um computador com sistema Windows, bem como permitem a execução remota de comandos.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":481969,"enunciado":"No tocante à utilização de comandos para organização e manipulação de arquivos e diretórios no sistema operacional Linux, o comando responsável pela atribuição de permissões de arquivos é o:","opcoes":["chmod","tail","vi","nmap","top"],"correta":0,"explicacao":"Gabarito: <strong>chmod</strong>.","banca":"PR-4 UFRJ","ano":2014,"temas_relacionados":["linux_geral"]},{"id":481970,"enunciado":"No Sistema Operacional Linux, o comando ls é utilizado para:","opcoes":["listar aplicativos em execução.","excluir diretórios.","criar um diretório seguro.","criar um arquivo.","listar diretórios e arquivos."],"correta":4,"explicacao":"Gabarito: <strong>listar diretórios e arquivos.</strong>.","banca":"PR-4 UFRJ","ano":2014,"temas_relacionados":["linux_geral"]},{"id":483920,"enunciado":"Julgue o item a seguir, acerca de sistemas operacionais.\n\nNo Linux, a execução do comando ps   -aexf |  grep  arq mostrará uma lista de processos em execução que tenham em sua descrição a sequência de caracteres arq.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2015,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":483928,"enunciado":"Julgue o item subsecutivo, acerca de procedimentos de segurança e educação a distância (EAD).\n\nNo Linux, quando há mais de um administrador na rede, eles devem, sempre que possível, utilizar a conta root diretamente. Esse procedimento permite que os administradores tenham os privilégios mais elevados, sem restrição, para acessar o sistema e para executar aplicativos.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2015,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":484089,"enunciado":"Julgue o item a seguir, a respeito de noções de sistema operacional.\n\nNo Linux, o comando cd /etc/teste cria o diretório teste dentro do diretório /etc.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2015,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":484094,"enunciado":"Julgue o item a seguir, a respeito de organização e de gerenciamento de arquivos.\n\nNo Linux, todo arquivo executável tem como extensão o sufixo .exe.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2015,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":487382,"enunciado":"Acerca dos sistemas operacionais Linux e Windows, julgue o item a seguir.\n\nUma das formas de localizar arquivo ou diretório em ambiente Linux é por meio da execução do comando chmod, diretamente no console.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2013,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":487383,"enunciado":"Acerca dos sistemas operacionais Linux e Windows, julgue o item a seguir.\n\nUma das desvantagens do Linux, em relação ao Windows, é a indisponibilidade de interface gráfica ao usuário.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2013,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":488576,"enunciado":"No Linux, o comando kill:","opcoes":["finaliza um processo em execução","elimina um diretório.","elimina um arquivo.","encerra uma conexão de um usuário.","realiza um boot na máquina."],"correta":0,"explicacao":"Gabarito: <strong>finaliza um processo em execução</strong>.","banca":"FUNCAB","ano":2013,"temas_relacionados":["linux_geral"]},{"id":488581,"enunciado":"Assim como o sistema operacional Windows, o Linux também possui diversas interfaces gráficas, como:","opcoes":["KDE","Prompt.","Kernel.","Firefox.","Chrome."],"correta":0,"explicacao":"Gabarito: <strong>KDE</strong>.","banca":"FUNCAB","ano":2013,"temas_relacionados":["linux_geral"]},{"id":488585,"enunciado":"Pode-se afirmar que o que diferencia o sistema operacional Linux do sistema operacional Windows é que o sistema Linux:","opcoes":["possui estrutura de arquivos e diretórios","por concepção, seu código fonte é aberto.","possui controles de permissão de acesso, como Login e Logout.","gerencia software e hardware","permite que o computador, no qual está instalado, conecte-se à rede."],"correta":1,"explicacao":"Gabarito: <strong>por concepção, seu código fonte é aberto.</strong>.","banca":"FUNCAB","ano":2013,"temas_relacionados":["linux_geral"]},{"id":510825,"enunciado":"Suponha que o usuário do Linux esteja acessando o diretório ‘/home/func/lab/jpco/miscel/artigs’ pelo shell, e digita o comando ‘cd ../../../mnpr/miscel’ , não recebendo mensagens de erro. Pode-se dizer que o usuário agora está acessando o seguinte diretório:","opcoes":["/home/func/mnpr/miscel.","/home/func/lab/jpco/mnpr/miscel.","/home/func/lab/jpco/miscel/mnpr/miscel.","/home /mnpr/miscel.","/home/func/lab/mnpr/miscel."],"correta":4,"explicacao":"Gabarito: <strong>/home/func/lab/mnpr/miscel.</strong>.","banca":"COVEST-COPSET","ano":2015,"temas_relacionados":["linux_geral"]},{"id":510828,"enunciado":"Qual comando Linux abaixo está diretamente associado à atividade de backup ?","opcoes":["ln","tail","dump","which","ping"],"correta":2,"explicacao":"Gabarito: <strong>dump</strong>.","banca":"COVEST-COPSET","ano":2015,"temas_relacionados":["linux_geral"]},{"id":510831,"enunciado":"Qual comando Linux abaixo está diretamente associado à manipulação de arquivo?","opcoes":["diff","ps","ping","sudo","pwd"],"correta":0,"explicacao":"Gabarito: <strong>diff</strong>.","banca":"COVEST-COPSET","ano":2015,"temas_relacionados":["linux_geral"]},{"id":520017,"enunciado":"A respeito do sistema Operacional Linux, marque a única alternativa FALSA.","opcoes":["ROOT é o nome do Super usuário.","diretório raiz é representado por um sinal de adição ( +).","O Kernel é o núcleo do sistema operacional, a parte mais próxima do hardware(parte física).","Shell é nome genérico de uma classe de programas que funcionam como interpretador de comandos. Ele traduz os comandos digitados pelo usuário para a linguagem usada pelo Kernel e vice-versa. Sem o Shell a interação entre usuário e o Kernel seria bastante complexa."],"correta":1,"explicacao":"Gabarito: <strong>diretório raiz é representado por um sinal de adição ( +).</strong>.","banca":"IMA","ano":2015,"temas_relacionados":["linux_geral"]},{"id":520021,"enunciado":"Qual a função do comando shutdown no sistema Operacional Linux?","opcoes":["Apaga a conta do usuário especificado.","Limpar a tela.","Cria uma nova conta de usuário.","Desliga ou reinicia o computador."],"correta":3,"explicacao":"Gabarito: <strong>Desliga ou reinicia o computador.</strong>.","banca":"IMA","ano":2015,"temas_relacionados":["linux_geral"]},{"id":526240,"enunciado":"No que se refere ao ambiente Linux, julgue o item seguinte.\n\n\n\n\nO Linux permite que o sistema seja inicializado tanto em modo texto, usando-se um shell orientado a caractere com um interpretador de comandos, como em um sistema de janelas, utilizando-se um shell gráfico.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2011,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":526241,"enunciado":"No que se refere ao ambiente Linux, julgue o item seguinte.\n\n\n\n\nO Linux suporta o protocolo IP e possui navegadores web, o que permite acesso à Internet.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2011,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":528752,"enunciado":"Na realização de um determinado suporte técnico, é requerida a reinstalação do sistema operacional. Para tanto,há necessidade de se reinstalar um sistema operacional proprietário. Assinale, a seguir, um sistema operacional desse tipo.","opcoes":["Debian 7.1.","Windows 7.","Ubuntu 12.","FreeBSD.","CentOS."],"correta":1,"explicacao":"Gabarito: <strong>Windows 7.</strong>.","banca":"Quadrix","ano":2014,"temas_relacionados":["linux_geral"]},{"id":528753,"enunciado":"Comparando os sistemas operacionais Windows 8 e Ubuntu 14, podemos encontrar várias semelhanças e diferenças.Qual alternativa contém as semelhanças?","opcoes":["São um sistema de licenciamento.","Possuem versões 32 e 64 bits.","São um sistema de arquivos.","Possuem um único distribuidor.","Há disponibilidade do código fonte do sistema operacional."],"correta":1,"explicacao":"Gabarito: <strong>Possuem versões 32 e 64 bits.</strong>.","banca":"Quadrix","ano":2014,"temas_relacionados":["linux_geral"]},{"id":543016,"enunciado":"Acerca de noções de informática, julgue o item a seguir.\n\nEm computadores com sistema operacional Linux ou Windows, o aumento da memória virtual possibilita a redução do consumo de memória RAM em uso, o que permite executar, de forma paralela e distribuída, no computador, uma quantidade maior de programas.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2013,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":543017,"enunciado":"Acerca de noções de informática, julgue o item a seguir.\n\nConsidere que um usuário disponha de um computador apenas com Linux e BrOffice instalados. Nessa situação, para que esse computador realize a leitura de um arquivo em formato de planilha do Microsoft Office Excel, armazenado em um pendrive formatado com a opção NTFS, será necessária a conversão batch do arquivo, antes de sua leitura com o aplicativo instalado, dispensando-se a montagem do sistema de arquivos presente no pendrive.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2013,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":553121,"enunciado":"Em um determinado setor da empresa XYZ, foi detectado que um dos computadores apresenta um sistema operacional livre, e que não foi autorizado pela equipe de suporte de TI. Assinale a alternativa que representa um sistema operacional não proprietário.","opcoes":["OS/2.","MS-DOS.","MacOS X.","Windows 8.1.","CentOS."],"correta":4,"explicacao":"Gabarito: <strong>CentOS.</strong>.","banca":"Quadrix","ano":2015,"temas_relacionados":["linux_geral"]},{"id":553152,"enunciado":"Os sistemas operacionais para desktops podem ser classificados, dentre várias características, como sistemas proprietários ou livres. Entre os mais populares estão os SOs Windows e o Ubuntu, com suas diversas versões. Escolha a alternativa que apresenta semelhanças entre esses dois ambientes operacionais.","opcoes":["Ambos possuem versão de 64bits.","Possuem o mesmo sistema de arquivo.","Seu sistema de venda de software.","Ambos distribuem versões de seu código fonte à comunidade de programadores.","Os dois sistemas são oferecidos e distribuídos pela Google Corporation."],"correta":0,"explicacao":"Gabarito: <strong>Ambos possuem versão de 64bits.</strong>.","banca":"Quadrix","ano":2015,"temas_relacionados":["linux_geral"]},{"id":561250,"enunciado":"A GNU GPL (GNU General Public License) estabelece basicamente quatro pilares básicos do software livre. Considerando esses quatro fundamentos para software livre, julgue o próximo item.\nA GNU GPL estabelece que é permitido redistribuir cópias de um programa de maneira gratuita, de modo que isso venha a auxiliar outras pessoas.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2015,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":561251,"enunciado":"A GNU GPL (GNU General Public License) estabelece basicamente quatro pilares básicos do software livre. Considerando esses quatro fundamentos para software livre, julgue o próximo item.\nA GNU GPL estabelece como fundamento que um software livre deve permitir o estudo de como o programa funciona, mas não é permitido fazer alteração no código-fonte desse programa.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2015,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":565786,"enunciado":"O sistema de arquivos do Ubuntu Linux possui uma estrutura hierárquica baseada em diretórios, sendo alguns deles com funções específicas. Um deles destina-se a armazenar bibliotecas de módulos compartilhados com frequência, enquanto que outro para armazenar os scripts de configuração e de inicialização. Esses diretórios são conhecidos, respectivamente, por:","opcoes":["/tmp e /etc","/tmp e /var","/lib e /var","/lib e /etc"],"correta":3,"explicacao":"Gabarito: <strong>/lib e /etc</strong>.","banca":"Prefeitura do Rio de Janeiro - RJ","ano":2015,"temas_relacionados":["linux_geral"]},{"id":565787,"enunciado":"O Nautilus é um dos gerenciadores de pastas e arquivos utilizados no Ubuntu Linux, que disponibiliza aos usuários diversos atalhos de teclado capazes de agilizar a execução de funções importantes no ambiente gráfico. Nesse gerenciador, possuem os significados de colar e de selecionar tudo, respectivamente, os seguintes atalhos de teclado:","opcoes":["Ctrl + C e Ctrl + T","Ctrl + V e Ctrl + T","Ctrl + C e Ctrl + A","Ctrl + V e Ctrl + A"],"correta":3,"explicacao":"Gabarito: <strong>Ctrl + V e Ctrl + A</strong>.","banca":"Prefeitura do Rio de Janeiro - RJ","ano":2015,"temas_relacionados":["linux_geral"]},{"id":567393,"enunciado":"Um usuário de um ambiente com sistema operacional Linux deseja saber quanto de espaço foi utilizado no seu disco rígido. O comando para essa operação é o:","opcoes":["df.","find.","ssh.","top.","whereis."],"correta":0,"explicacao":"Gabarito: <strong>df.</strong>.","banca":"FUNCAB","ano":2015,"temas_relacionados":["linux_geral"]},{"id":567397,"enunciado":"O comando Linux, usado para listar o conteúdo de um diretório, é o:","opcoes":["cd.","dir.","ls.","md.","rm."],"correta":2,"explicacao":"Gabarito: <strong>ls.</strong>.","banca":"FUNCAB","ano":2015,"temas_relacionados":["linux_geral"]},{"id":575993,"enunciado":"Considere que no Linux temos dois arquivos de texto: 'arq1' e 'arq2'. As palavras que constam em 'arq1' são (uma por linha): 'Bola', 'Pato', 'Ave' e 'Cola'. As palavras que constam em 'arq2' são (uma por linha): 'losango', 'asa', 'bode' e 'peixe'. Considere que foi executado o comando: 'cat arq1 arq2 | sort | head –n 6 | tail –n 1 > arq3'. O conteúdo de 'arq3' é:","opcoes":["'bode'","'Pato'","'peixe'","'Cola'","'Bola'"],"correta":0,"explicacao":"Gabarito: <strong>'bode'</strong>.","banca":"COVEST-COPSET","ano":2015,"temas_relacionados":["linux_geral"]},{"id":607861,"enunciado":"No sistema operacional Linux, o cups é utilizado para","opcoes":["criar arquivos postscript.","editar arquivos de textos.","editar arquivos gráficos.","gerenciar arquivos e diretórios.","gerenciar os serviços de impressão."],"correta":4,"explicacao":"Gabarito: <strong>gerenciar os serviços de impressão.</strong>.","banca":"VUNESP","ano":2015,"temas_relacionados":["linux_geral"]},{"id":607862,"enunciado":"O administrador de um servidor com sistema operacional Linux deseja saber o tamanho, ou seja, o espaço utilizado por um determinado diretório. Para isso, ele deve utilizar o comando","opcoes":["dd.","df.","du.","top.","fdisk."],"correta":2,"explicacao":"Gabarito: <strong>du.</strong>.","banca":"VUNESP","ano":2015,"temas_relacionados":["linux_geral"]},{"id":609846,"enunciado":"Um Técnico em Informática, como super usuário, deseja desligar um computador com o sistema operacional Linux após 30 minutos. Ele deve usar o comando","opcoes":["shutdown -k","shutdown -r + 30","shutdown -h +30","Reboot +30","Restartx 30"],"correta":2,"explicacao":"Gabarito: <strong>shutdown -h +30</strong>.","banca":"FCC","ano":2015,"temas_relacionados":["linux_geral"]},{"id":614161,"enunciado":"O sistema operacional Linux, por ser tratar de um sistema acessado e utilizado por uma grande quantidade de usuários, possui o recurso de registro das ocorrências de funcionamento do hardware, de acesso dos usuários e de uso dos recursos do sistema, em arquivos em log. Por padrão, os arquivos de log são armazenados no diretório:","opcoes":["/local","/var","/opt","/usr","/log"],"correta":1,"explicacao":"Gabarito: <strong>/var</strong>.","banca":"FCC","ano":2013,"temas_relacionados":["linux_geral"]},{"id":614162,"enunciado":"Um superusuário de um computador com o sistema operacional Linux deseja adicionar os módulos do serviço DNS ao kernel. Para isso, ele pode utilizar o comando:","opcoes":["appmod","addmodul","incmod","modprobe","modul"],"correta":3,"explicacao":"Gabarito: <strong>modprobe</strong>.","banca":"FCC","ano":2013,"temas_relacionados":["linux_geral"]},{"id":614163,"enunciado":"Um computador com sistema operacional Linux possui instalada uma placa de rede Ethernet (eth0) pela qual se comunica com a WAN e uma segunda placa de rede Ethernet (eth1) para ser utilizada como interface para uma LAN. A placa eth1 está desativada e deseja-se ativá-la. Para isso, pode-se executar o comando:","opcoes":["ifup eth1","ipon eth1","ifconfig eth1 -a","ifconfig eth1 on","ipconfig up eth1"],"correta":0,"explicacao":"Gabarito: <strong>ifup eth1</strong>.","banca":"FCC","ano":2013,"temas_relacionados":["linux_geral"]},{"id":614164,"enunciado":"Os arquivos e diretórios no sistema operacional Linux possuem atributos descritos conforme estrutura apresentada a seguir: Nessa estrutura, os atributos de números 2 e 4 correspondem, respectivamente:","opcoes":["o grupo e outros.","o grupo e o proprietário.","o proprietário e outros.","o proprietário e o grupo.","outros e o proprietário."],"correta":2,"explicacao":"Gabarito: <strong>o proprietário e outros.</strong>.","banca":"FCC","ano":2013,"temas_relacionados":["linux_geral"]},{"id":614165,"enunciado":"O sistema operacional Linux foi desenvolvido, desde a sua origem, para operar em um ambiente de rede de computadores no qual há o acesso remoto dos usuários. Para verificar quais usuários estão logados no sistema, pode-se utilizar o comando:","opcoes":["ps","who","user","finger","logged"],"correta":1,"explicacao":"Gabarito: <strong>who</strong>.","banca":"FCC","ano":2013,"temas_relacionados":["linux_geral"]},{"id":617123,"enunciado":"O gerenciador de boot mais tradicionalmente utilizado no Linux é o:","opcoes":["LILO","MRV","MBR","KERNEL"],"correta":0,"explicacao":"Gabarito: <strong>LILO</strong>.","banca":"FAPEC - AL","ano":2013,"temas_relacionados":["linux_geral"]},{"id":617124,"enunciado":"A saída do sistema Linux pode ser realizada de duas formas, usando o comando exit ou o comando logout. A diferença entre os dois é que exit encerra o shell de comandos corrente e logout encerra a sessão. Vale lembrar que em várias distribuições Linux, existe já definido um atalho para o comando logout, bastando pressionar:","opcoes":["Ctrl + e","Ctrl + x","Ctrl + l","Ctrl + d"],"correta":3,"explicacao":"Gabarito: <strong>Ctrl + d</strong>.","banca":"FAPEC - AL","ano":2013,"temas_relacionados":["linux_geral"]},{"id":617127,"enunciado":"As distribuições Linux, incluindo Fedora e Ubuntu, suportam os seguintes Ambientes de trabalho:","opcoes":["Konqueror, GNOME e KDE.","Nautilus, Konqueror e KDE.","GNOME, KDE e XFCE.","Dolphin, Explorer e KFCE."],"correta":2,"explicacao":"Gabarito: <strong>GNOME, KDE e XFCE.</strong>.","banca":"FAPEC - AL","ano":2013,"temas_relacionados":["linux_geral"]},{"id":624093,"enunciado":"Embora o Kernel do Linux seja bastante estável, os programas nem sempre são, podendo ocorrer travamentos. Para fechar um aplicativo problemático no Linux, podem ser usados","opcoes":["killall, xkill e Ctrl + Alt + Esc.","killoff, killx e Ctrl + Esc.","killend, killx e Ctrl + Alt.","killoff, killend e Ctrl + Shift + Esc.","killoff, killend e Ctrl + Esc."],"correta":0,"explicacao":"Gabarito: <strong>killall, xkill e Ctrl + Alt + Esc.</strong>.","banca":"UPENET/IAUPE","ano":2015,"temas_relacionados":["linux_geral"]},{"id":624094,"enunciado":"O comando, que estabelece a versão do Ubuntu Linux, instalada na máquina, é","opcoes":["locate.","groupmod.","modinfo.","lsb_release.","whatis."],"correta":3,"explicacao":"Gabarito: <strong>lsb_release.</strong>.","banca":"UPENET/IAUPE","ano":2015,"temas_relacionados":["linux_geral"]},{"id":627018,"enunciado":"Com relação aos comandos que podem ser executados no terminal do GNU/Linux, avalie as afirmações a seguir e marque com V as verdadeiras e com F as falsas. ( ) O comando cd acessa e muda de diretório corrente. ( ) O comando ls, quando executado, lista o conteúdo de um diretório. ( ) O comando ps apresenta os processos que tiveram sua execução encerrada no sistema. ( ) O comando df apresenta o uso de espaço em disco do sistema. ( ) O comando cp é utilizado para copiar arquivos e diretórios. Assinale a alternativa que contém a sequência CORRETA, de cima para baixo.","opcoes":["V, V, V, V, F.","V, V, F, V, V.","V, F, V, V, F.","V, F, F, F, F.","F, F, V, V, F."],"correta":1,"explicacao":"Gabarito: <strong>V, V, F, V, V.</strong>.","banca":"IF-SC","ano":2014,"temas_relacionados":["linux_geral"]},{"id":638217,"enunciado":"- Qual o comando a ser dado no prompt do Linux que irá permitir listar arquivos de um diretório com detalhamento?","opcoes":["ls +1","ls –1","lt –1","lt +all","ls +g"],"correta":1,"explicacao":"Gabarito: <strong>ls –1</strong>.","banca":"CONPASS","ano":2015,"temas_relacionados":["linux_geral"]},{"id":638218,"enunciado":"Qual o comando do Linux usado para criação de diretórios?","opcoes":["cddir","dirmake","maked","mkdir","createdir"],"correta":3,"explicacao":"Gabarito: <strong>mkdir</strong>.","banca":"CONPASS","ano":2015,"temas_relacionados":["linux_geral"]},{"id":638219,"enunciado":"Qual o símbolo que aparece no prompt do Linux sinalizando que o usuário atual é um usuário comum e não um administrador?","opcoes":["#","&","*","@","$"],"correta":4,"explicacao":"Gabarito: <strong>$</strong>.","banca":"CONPASS","ano":2015,"temas_relacionados":["linux_geral"]},{"id":646745,"enunciado":"No modo texto ou não gráfico, usado para entrada de comandos no Linux, o nome do usuário que está usando o terminal vem precedido de que símbolo?","opcoes":["#","%","$","@","∞"],"correta":3,"explicacao":"Gabarito: <strong>@</strong>.","banca":"CONPASS","ano":2016,"temas_relacionados":["linux_geral"]},{"id":646746,"enunciado":"Ao se usar o comando ls no Linux, que informação é obtida?","opcoes":["A listagem de todos os arquivos de um diretório.","A quantidade de espaço usada do disco.","A quantidade de memória RAM disponível.","A criptografia de um arquivo.","A listagem dos arquivos atualmente abertos."],"correta":0,"explicacao":"Gabarito: <strong>A listagem de todos os arquivos de um diretório.</strong>.","banca":"CONPASS","ano":2016,"temas_relacionados":["linux_geral"]},{"id":646747,"enunciado":"No Linux, que comando de linha permite se obter a descrição completa do diretório atual?","opcoes":["stat","diff","pwd","lsof","tee"],"correta":2,"explicacao":"Gabarito: <strong>pwd</strong>.","banca":"CONPASS","ano":2016,"temas_relacionados":["linux_geral"]},{"id":656652,"enunciado":"Sobre o sistema operacional Linux, é INCORRETO afirmar que:","opcoes":["O usuário root, também conhecido como super-usuário, possui acesso a todos os arquivos e pastas do sistema.","O comando ls, quando executado em um terminal, é responsável por listar todos os arquivos e subdiretórios dentro de um diretório.","O comando cd /usr/temp cria o diretório temp dentro do diretório usr.","Todo e qualquer arquivo executável não precisa possuir o sufixo .exe.","Grub e Lilo são gerenciadores de inicialização."],"correta":2,"explicacao":"Gabarito: <strong>O comando cd /usr/temp cria o diretório temp dentro do diretório usr.</strong>.","banca":"COPESE - UFPI","ano":2015,"temas_relacionados":["linux_geral"]},{"id":656653,"enunciado":"Assinale a opção que corresponde a distribuições Linux.","opcoes":["KDE e Slackware.","Ubuntu e Suse.","Red Hat e Gnome.","Ubuntu e Grub.","Suse e Lilo."],"correta":1,"explicacao":"Gabarito: <strong>Ubuntu e Suse.</strong>.","banca":"COPESE - UFPI","ano":2015,"temas_relacionados":["linux_geral"]},{"id":678892,"enunciado":"O Red Hat é um (a):","opcoes":["Distribuição do Linux.","Tipo de Firewall do Windows.","Programa de manipulação de imagens.","Aplicação do Windows Explorer."],"correta":0,"explicacao":"Gabarito: <strong>Distribuição do Linux.</strong>.","banca":"MOURA MELO","ano":2016,"temas_relacionados":["linux_geral"]},{"id":678912,"enunciado":"Qual comando no Linux, cria ou atualiza o arquivo:","opcoes":["more arquivo.","touch arquivo.","mv arquivo.","ls arquivo."],"correta":1,"explicacao":"Gabarito: <strong>touch arquivo.</strong>.","banca":"MOURA MELO","ano":2016,"temas_relacionados":["linux_geral"]},{"id":678913,"enunciado":"O atalho abaixo, no Linux, apaga a linha inteira de um comando no terminal:","opcoes":["CTRL+R.","CTRL+I.","CTRL+U.","CTRL+C."],"correta":2,"explicacao":"Gabarito: <strong>CTRL+U.</strong>.","banca":"MOURA MELO","ano":2016,"temas_relacionados":["linux_geral"]},{"id":684234,"enunciado":"As funções do núcleo do Linux (escalonamento de processos, gerenciamento de memória, operações de entrada e saída, acesso ao sistema de arquivos) são executadas no espaço de núcleo. Uma característica do núcleo Linux é que algumas das funções podem ser compiladas e executadas como módulos, que são bibliotecas compiladas separadamente da parte principal do núcleo. Essas características fazem com que o núcleo do Linux seja classificado como:","opcoes":["Monolítico","Multifunções","Distribuído","Integrado","Único"],"correta":0,"explicacao":"Gabarito: <strong>Monolítico</strong>.","banca":"ESAF","ano":2016,"temas_relacionados":["linux_geral"]},{"id":684242,"enunciado":"Assinale a opção correta com relação a software livre.","opcoes":["Só pode ter o código-fonte alterado com autorização do seu desenvolvedor.","Só é gratuito na distribuição.","Permite acesso ao código-fonte.","Quer dizer software gratuito.","É dependente de tecnologias e plataformas."],"correta":2,"explicacao":"Gabarito: <strong>Permite acesso ao código-fonte.</strong>.","banca":"ESAF","ano":2016,"temas_relacionados":["linux_geral"]},{"id":708253,"enunciado":"Um analista de suporte deseja criar um grupo de vendas no sistema operacional Linux Ubuntu. Para criar corretamente esse grupo, o comando a ser utilizado é o","opcoes":["addgpr vendas.","vendas addgroup.","grp vendas.","groupadd vendas.","vendas group."],"correta":3,"explicacao":"Gabarito: <strong>groupadd vendas.</strong>.","banca":"AOCP","ano":2015,"temas_relacionados":["linux_geral"]},{"id":708254,"enunciado":"Um analista de suporte necessita executar o comando Linux que lista todos os arquivos (inclusive ocultos) de uma determinada pasta, com todos os seus detalhes. Para tanto, o comando que o analista de suporte deve utilizar é o","opcoes":["ls -A","ls -la","-ls a","ls -l","ls"],"correta":1,"explicacao":"Gabarito: <strong>ls -la</strong>.","banca":"AOCP","ano":2015,"temas_relacionados":["linux_geral"]},{"id":729296,"enunciado":"Qual é o comando utilizado para alterar a permissão de arquivos e/ou diretórios em um ambiente Linux/Unix?","opcoes":["cp.","cd.","dir.","cmp.","chmod."],"correta":4,"explicacao":"Gabarito: <strong>chmod.</strong>.","banca":"IDECAN","ano":2014,"temas_relacionados":["linux_geral"]},{"id":729301,"enunciado":"Qual a finalidade do comando apt-get install --reinstall nome_do_pacote utilizado no Linux/Unix?","opcoes":["Instalar um determinado pacote.","Atualizar o pacote especificado.","Procurar um determinado pacote.","Deletar um determinado pacote.","Reinstalar um determinado pacote."],"correta":4,"explicacao":"Gabarito: <strong>Reinstalar um determinado pacote.</strong>.","banca":"IDECAN","ano":2014,"temas_relacionados":["linux_geral"]},{"id":729302,"enunciado":"Marque a opção INCORRETA referente à funcionalidade do comando Linux.","opcoes":["RM – apagar o arquivo especificado.","PWD – informar o diretório utilizado.","NETSTAT – informar o estado de rede.","MKDIR – informar o status da fila de impressão.","LS – mostrar os arquivos e diretórios da pasta atual."],"correta":3,"explicacao":"Gabarito: <strong>MKDIR – informar o status da fila de impressão.</strong>.","banca":"IDECAN","ano":2014,"temas_relacionados":["linux_geral"]},{"id":733419,"enunciado":"Com relação ao sistema operacional Linux, assinale a alternativa que apresenta o comando que exibe a quantidade de espaço livre nas unidades de disco do computador, no qual o sistema operacional está instalado.","opcoes":["free.","cd.","ls.","pwd.","df."],"correta":4,"explicacao":"Gabarito: <strong>df.</strong>.","banca":"CETRO","ano":2014,"temas_relacionados":["linux_geral"]},{"id":733422,"enunciado":"Se estivermos trabalhando na interface de linha de comando do sistema operacional Linux, e o último caractere apresentado no prompt de comandos for o caractere “#”, é correto afirmar que significa que essa sessão de terminal","opcoes":["é uma sessão de usuário normal.","tem privilégios de administrador.","está bloqueada.","permite somente utilizar o comando de acesso à interface gráfica do sistema operacional.","será encerrada em seguida."],"correta":1,"explicacao":"Gabarito: <strong>tem privilégios de administrador.</strong>.","banca":"CETRO","ano":2014,"temas_relacionados":["linux_geral"]},{"id":746872,"enunciado":"Sobre o SO Linux, é correto afirmar que o usuário padrão que tem a permissão máxima dentro do sistema é o","opcoes":["Administrador.","Usuário.","Root.","Admin.","User."],"correta":2,"explicacao":"Gabarito: <strong>Root.</strong>.","banca":"INSTITUTO AOCP","ano":2015,"temas_relacionados":["linux_geral"]},{"id":746878,"enunciado":"Sobre o Linux, qual é o comando para confirmar a data e hora atual do sistema?","opcoes":["Time.","Date.","Hora.","Cat.","Type."],"correta":1,"explicacao":"Gabarito: <strong>Date.</strong>.","banca":"INSTITUTO AOCP","ano":2015,"temas_relacionados":["linux_geral"]},{"id":751121,"enunciado":"São exemplos de distribuição do Linux, EXCETO:","opcoes":["Ubuntu.","Debian.","Kernel.","Kurumin.","Fedora."],"correta":2,"explicacao":"Gabarito: <strong>Kernel.</strong>.","banca":"UFCG","ano":2016,"temas_relacionados":["linux_geral"]},{"id":751139,"enunciado":"No ambiente Linux o comando para criação de uma pasta é:","opcoes":["cd","ls","mkdir","mkps","crtdir"],"correta":2,"explicacao":"Gabarito: <strong>mkdir</strong>.","banca":"UFCG","ano":2016,"temas_relacionados":["linux_geral"]},{"id":751140,"enunciado":"Ainda sobre o ambiente Linux, o comando pwd retorna o seguinte resultado:","opcoes":["Exibe o caminho completo do diretório atual.","Abre um arquivo.","Lista todos os arquivos do diretório.","Remove um arquivo.","Gera senha para acesso de uma pasta."],"correta":0,"explicacao":"Gabarito: <strong>Exibe o caminho completo do diretório atual.</strong>.","banca":"UFCG","ano":2016,"temas_relacionados":["linux_geral"]},{"id":758235,"enunciado":"Muitas empresas estão optando por utilizarem o Sistema Operacional Linux. A grande vantagem desse Sistema é que não se tem a necessidade de pagamento de licença para utilizá-lo, diferente dos sistemas proprietários, da Microsoft, por exemplo, que se deve pagar uma licença para utilização. Por não ter que pagar licença, as empresas economizam e podem investir em equipamentos, infraestrutura, entre outros. Trabalhar com Linux já é uma realidade, e muitas ações são feitas utilizando-se do terminal, ou seja, usam-se os comandos pela linha de comando do Linux. Diferente do Windows, onde quase tudo é feito através da interface gráfica, no Linux os comandos podem ser usados pela linha de comando e, em algumas versões, fazendo uso de interface gráfica. “Suponha que se esteja editando um arquivo na linha de comandos do Linux, mas tenha se esquecido o diretório em que se encontra. Um desses comandos pode ser usado para a verificação de qual diretório se encontra (isso em caso do seu aviso de comandos não mostrar essa informação)”. Assinale a alternativa correta que apresenta este comando.","opcoes":["ls.","cd.","pwd.","mkdir."],"correta":2,"explicacao":"Gabarito: <strong>pwd.</strong>.","banca":"IDECAN","ano":2016,"temas_relacionados":["linux_geral"]},{"id":758241,"enunciado":"“Alguns candidatos foram convidados para uma entrevista de emprego em uma empresa que utiliza o Linux como Sistema Operacional. Na entrevista, o responsável pela empresa solocita que os candidatos usem alguns comandos para manipulação de arquivos através do terminal de comandos. No Linux, o comando rm apaga arquivos, o cp copia arquivos e o mv move arquivos. Todos esses comandos podem ser utilizados com alguns complementos (opções) que agregam funções nas suas utilizações. Uma dessas opções, respectivamente, tem as seguintes descrições, de acordo com os comandos apresentados: remove os arquivos sem perguntar; não pergunta, substitui os arquivos caso já exista; e, substitui o arquivo de destino sem perguntar.” Esse complemento (opção) aos comandos apresentados trata-se de:","opcoes":["-i.","-f.","-r.","-v."],"correta":0,"explicacao":"Gabarito: <strong>-i.</strong>.","banca":"IDECAN","ano":2016,"temas_relacionados":["linux_geral"]},{"id":758244,"enunciado":"Organizar arquivos e pastas (diretórios) é uma tarefa muito importante para os usuários do computador. Seja com qual Sistema Operacional se está trabalhando, com essa organização fica muito mais fácil encontrar aquilo que se deseja no computador. “No Sistema Operacional Linux há um comando que efetua uma procura por arquivos/diretórios no disco. Essa busca pode ser feita considerando-se critérios como: data de modificação, tamanho etc, usando algumas opções com o comando. Sua sintaxe padrão é: comando [diretório] [opções/expressão]. Neste caso, indica que a busca será realizada neste diretório, percorrendo seus subdiretórios.” Assinale a alternativa referente a este comando.","opcoes":["tail.","less.","find.","sort."],"correta":2,"explicacao":"Gabarito: <strong>find.</strong>.","banca":"IDECAN","ano":2016,"temas_relacionados":["linux_geral"]},{"id":760325,"enunciado":"Aponte a opção FALSA.","opcoes":["A suíte Microsoft Office não possui uma versão nativa para Linux.","O Linux segue os princípios do Software Livre.","O Windows não segue os princípios do Software Livre.","O gerenciador de arquivos do Linux possui uma ferramenta para compactação de arquivos.","Quando é realizada a descompactação de um arquivo no Linux, o arquivo compactado é excluído automaticamente."],"correta":4,"explicacao":"Gabarito: <strong>Quando é realizada a descompactação de um arquivo no Linux, o arquivo compactado é excluído automaticamente.</strong>.","banca":"Coperve - FURG","ano":2016,"temas_relacionados":["linux_geral"]},{"id":760326,"enunciado":"A instalação de programas através de modo gráfico no Linux Ubuntu é feita:","opcoes":["pela Central de programas de Ubuntu.","pelo dpkg.","pela Linux Store.","pela Ubuntu Play.","pelo TCP."],"correta":0,"explicacao":"Gabarito: <strong>pela Central de programas de Ubuntu.</strong>.","banca":"Coperve - FURG","ano":2016,"temas_relacionados":["linux_geral"]},{"id":771791,"enunciado":"O Linux é um Sistema Operacional de código fonte aberto que foi desenvolvido e é mantido por intermédio da colaboração voluntária de desenvolvedores de diversas partes do mundo. O Linux utiliza a licença GPL que foi criada pela Free Software Foundation. São liberdades que esta entidade defende, EXCETO:","opcoes":["Executar o programa para qualquer propósito.","Distribuir cópias de forma que o usuário possa ajudar o seu próximo.","Estudar como o programa funciona, porém não é permitido qualquer adaptação.","Melhorar o programa e liberar os seus aperfeiçoamentos, de modo que toda a comunidade se beneficie."],"correta":2,"explicacao":"Gabarito: <strong>Estudar como o programa funciona, porém não é permitido qualquer adaptação.</strong>.","banca":"IDECAN","ano":2016,"temas_relacionados":["linux_geral"]},{"id":771792,"enunciado":"Sobre comandos utilizados em Sistemas Operacionais Linux, marque V para as afirmativas verdadeiras e F para as falsas. ( ) O comando ls é utilizado para listar todos os arquivos do diretório. ( ) O comando addir é utilizado para criar um novo diretório. ( ) O comando chmod modifica as permissões de um arquivo ou diretório. ( ) O comando dir exibe o caminho completo do diretório atual. A sequência está correta em","opcoes":["V, V, F, F.","V, F, V, F.","F, V, V, F.","F, F, V, V."],"correta":1,"explicacao":"Gabarito: <strong>V, F, V, F.</strong>.","banca":"IDECAN","ano":2016,"temas_relacionados":["linux_geral"]},{"id":813159,"enunciado":"Assinale a alternativa correta sobre o utilitário de linha de comando Linux denominado dig.","opcoes":["É uma ferramenta de diagnóstico que auxilia a obtenção de informações sobre a utilização de recursos e a saúde do sistema.","É uma ferramenta de consulta a servidores de domínio DNS para obter informações sobre domínios e hosts.","É um utilitário para realização de buscas em arquivos de texto, permitindo a realização de múltiplas buscas em uma única consulta.","É um utilitário para realização de buscas em arquivos binários, permitindo a realização de múltiplas buscas em uma única consulta.","É uma ferramenta que possibilita a busca de palavras-chave em determinados websites a partir do prompt de comando do Linux."],"correta":1,"explicacao":"Gabarito: <strong>É uma ferramenta de consulta a servidores de domínio DNS para obter informações sobre domínios e hosts.</strong>.","banca":"FEPESE","ano":2017,"temas_relacionados":["linux_geral"]},{"id":813161,"enunciado":"O Linux permite a navegação entre diretórios utilizando comandos como dirs, pushd e popd. Para tanto, o Linux mantém uma estrutura de dados interna do tipo:","opcoes":["Pilha.","Grafo.","Árvore.","Lista.","Fila"],"correta":0,"explicacao":"Gabarito: <strong>Pilha.</strong>.","banca":"FEPESE","ano":2017,"temas_relacionados":["linux_geral"]},{"id":814449,"enunciado":"Utilizando o comando tar no Linux, qual linha de comando cria corretamente um arquivo contendo todo conteúdo do diretório /etc?","opcoes":["tar cvf etc.tar","tar cvf etc.tar /etc","tar mkdir etc.tar /etc","tar mkdir etc.tar","tar cvf mkdir etc.tar /etc"],"correta":1,"explicacao":"Gabarito: <strong>tar cvf etc.tar /etc</strong>.","banca":"INAZ do Pará","ano":2017,"temas_relacionados":["linux_geral"]},{"id":814456,"enunciado":"Durante a implantação de uma rede, determinado usuário digitou o seguinte comando em uma estação de trabalho que utiliza o sistema operacional Linux: “# ifconfig eth0 192.168.1.2 netmask 255.255.255.0 up”. Qual o objetivo desse usuário?","opcoes":["Definir apenas o endereço de IP da máquina manualmente","Ativar o serviço de IP e máscara de rede para a porta eth01","Definir a máscara de rede para a interface eth0 192.168.1.2 manualmente","Definir o DNS primário para o endereço cuja máscara de rede for 255.255.255.0","Desativar a máscara de rede para o IP 192.168.1.2 na porta eth01"],"correta":2,"explicacao":"Gabarito: <strong>Definir a máscara de rede para a interface eth0 192.168.1.2 manualmente</strong>.","banca":"INAZ do Pará","ano":2017,"temas_relacionados":["linux_geral"]},{"id":814458,"enunciado":"O sistema operacional Linux é um sistema onde o usuário pode utilizar de linhas de comandos para realizar qualquer operação desejada. Baseado nisso, qual comando criaria corretamente uma árvore de diretórios recursivamente, sem necessidade de criá-los um a um?","opcoes":["mrdir –p home/prova/conhecimento/oficial","mkdir –t home/prova/conhecimento/oficial","rm –r home/prova/conhecimento/oficial","mkdir –p home/prova/conhecimento/oficial","rm –t home/prova/conhecimento/oficial"],"correta":3,"explicacao":"Gabarito: <strong>mkdir –p home/prova/conhecimento/oficial</strong>.","banca":"INAZ do Pará","ano":2017,"temas_relacionados":["linux_geral"]},{"id":814497,"enunciado":"Qual a função do comando “cat /etc/passwd | head -10”, ao ser executado no sistema operacional Linux, e a funcionalidade do head neste contexto?","opcoes":["Listar os diretórios principais do sistema Linux, e o head mostra a origem dos diretórios.","Listar todos os usuários do sistema Linux, e o head limita os dez primeiros usuários.","Listar todos os arquivos do diretório /etc, e o head mostra os cabeçalhos.","Listar todos os usuários do sistema, e o head remove os dez primeiros.","Listar todos os grupos do sistema, e o head mostra a origem dos diretórios dos grupos."],"correta":1,"explicacao":"Gabarito: <strong>Listar todos os usuários do sistema Linux, e o head limita os dez primeiros usuários.</strong>.","banca":"INAZ do Pará","ano":2017,"temas_relacionados":["linux_geral"]},{"id":814500,"enunciado":"Qual o comando utilizado em sistemas operacionais Linux para desabilitar uma interface de rede?","opcoes":["Sudo ifconfig eth0 up","Sudo ifconfig kill","Sudo ifconfig -t","Sudo ifconfig eth0 down","Sudo ifconfig -an"],"correta":3,"explicacao":"Gabarito: <strong>Sudo ifconfig eth0 down</strong>.","banca":"INAZ do Pará","ano":2017,"temas_relacionados":["linux_geral"]},{"id":823937,"enunciado":"Com relação à figura e às informações acima apresentadas, julgue o item a seguir.\n\nO arquivo dentistas.pdf é de propriedade do usuário cfo e do grupo root.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2017,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":823939,"enunciado":"Com relação à figura e às informações acima apresentadas, julgue o item a seguir.\n\nCom o comando mv cro.pdf cro2.pdf, é possível renomear o arquivo cro.pdf como cro2.pdf.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2017,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":823940,"enunciado":"Com relação à figura e às informações acima apresentadas, julgue o item a seguir.\n\nO número 103165 representa a quantidade de linhas existentes no arquivo cro.pdf.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2017,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":849983,"enunciado":"Considere as afirmativas abaixo relacionadas ao gerenciador de arquivos Nautilus, utilizado no sistema operacional Ubuntu Linux: I. Permite visualizar os arquivos ordenados por tipo, tamanho ou data. II. Possui um editor de textos integrado para a edição de arquivos pequenos. III. Possui funcionalidades para a criação de pastas para organizar os arquivos. Está CORRETO o que se afirma em:","opcoes":["I e II, apenas.","I e III, apenas.","II e III, apenas.","I, II e III."],"correta":1,"explicacao":"Gabarito: <strong>I e III, apenas.</strong>.","banca":"UFV","ano":2016,"temas_relacionados":["linux_geral"]},{"id":849984,"enunciado":"Um usuário, utilizando o gerenciador de arquivos Nautilus, selecionou uma pasta de nome “teste”, usando o mouse. A referida pasta continha apenas um arquivo de nome “teste”. Imediatamente após a seleção, o usuário apertou a tecla “Del” e confirmou a operação. Assinale a alternativa que apresenta CORRETAMENTE o resultado após essas operações:","opcoes":["A pasta “teste” e o seu arquivo “teste” foram movidos para a Lixeira.","A pasta “teste” e o seu arquivo “teste” foram deletados (apagados) do sistema.","O arquivo “teste” foi movido para a Lixeira e nada aconteceu com a pasta “teste”.","O arquivo “teste” foi deletado (apagado) do sistema e nada aconteceu com a pasta “teste”."],"correta":0,"explicacao":"Gabarito: <strong>A pasta “teste” e o seu arquivo “teste” foram movidos para a Lixeira.</strong>.","banca":"UFV","ano":2016,"temas_relacionados":["linux_geral"]},{"id":864369,"enunciado":"O kernel do Linux é:","opcoes":["Um software aplicativo cujo papel principal é gerenciar os recursos de software para o usuário.","Um software de nível de sistema cujo papel principal é gerenciar os recursos de hardware para o usuário.","Um software de nível de sistema cujo papel principal é gerenciar os recursos de uma máquina virtual para o usuário trabalhar com o sistema operacional Windows.","Um software de gestão cujo papel principal é gerenciar os recursos do Open Office para o usuário.","Um software aplicativo cujo papel principal é gerenciar apenas os recursos de hardware para outros computadores em uma rede."],"correta":1,"explicacao":"Gabarito: <strong>Um software de nível de sistema cujo papel principal é gerenciar os recursos de hardware para o usuário.</strong>.","banca":"CPCON","ano":2016,"temas_relacionados":["linux_geral"]},{"id":864370,"enunciado":"Sobre comandos em terminais Linux, assinale a alternativa CORRETA:","opcoes":["O comando top comprime ou expande arquivo.","O comando cmp cria um diretório.","O comando mkdir copia arquivos.","O comando gzip compara dois arquivos.","O comando chmod muda a proteção de um arquivo ou diretório."],"correta":4,"explicacao":"Gabarito: <strong>O comando chmod muda a proteção de um arquivo ou diretório.</strong>.","banca":"CPCON","ano":2016,"temas_relacionados":["linux_geral"]},{"id":888617,"enunciado":"Um usuário digitou o comando vi em um computador com sistema operacional Linux. Isso significa que ele deseja:","opcoes":["abrir o editor de texto padrão.","alterar a senha de usuário.","mudar arquivo de lugar.","mudar grupo do arquivo.","remover diretório."],"correta":0,"explicacao":"Gabarito: <strong>abrir o editor de texto padrão.</strong>.","banca":"IBADE","ano":2018,"temas_relacionados":["linux_geral"]},{"id":888627,"enunciado":"Em um computador com o sistema Linux, um usuário precisa listar todos os arquivos de um diretório via linha de comandos. O comando utilizado nesse caso é o:","opcoes":["df","cmd.","ls.","rsh.","ssh."],"correta":2,"explicacao":"Gabarito: <strong>ls.</strong>.","banca":"IBADE","ano":2018,"temas_relacionados":["linux_geral"]},{"id":898435,"enunciado":"O Sistema Operacional Linux/Ubuntu tem as seguintes características:","opcoes":["gratuito, multiusuário.","software livre, monousuário.","gratuito, monousuário.","software livre, multiusuário."],"correta":3,"explicacao":"Gabarito: <strong>software livre, multiusuário.</strong>.","banca":"IV - UFG","ano":2018,"temas_relacionados":["linux_geral"]},{"id":898436,"enunciado":"O comando chmod do sistema operacional Linux serve para configurar as permissões de uso dos seus arquivos e diretórios. Qual sintaxe deve ser utilizada para configurar o arquivo aluno.txt, atribuindo permissão de leitura, escrita e execução a todos os usuários do sistema?","opcoes":["sudo chmod 777 aluno.txt","chmod 567 aluno.txt","sudo chmod aluno.txt 111","chmod aluno.txt 234"],"correta":0,"explicacao":"Gabarito: <strong>sudo chmod 777 aluno.txt</strong>.","banca":"IV - UFG","ano":2018,"temas_relacionados":["linux_geral"]},{"id":898437,"enunciado":"No sistema operacional Linux, o comando “pwd” mostra","opcoes":["a quantidade de linhas de um arquivo.","a pasta atual na qual o usuário está no momento.","o nome do usuário que está logado no sistema.","o conteúdo do arquivo."],"correta":1,"explicacao":"Gabarito: <strong>a pasta atual na qual o usuário está no momento.</strong>.","banca":"IV - UFG","ano":2018,"temas_relacionados":["linux_geral"]},{"id":898438,"enunciado":"No Linux, os arquivos de configuração e aplicativos do sistema estão disponíveis em uma pasta considerada como a mais importante. Qual é esta pasta?","opcoes":["sbin","dev","etc","var"],"correta":2,"explicacao":"Gabarito: <strong>etc</strong>.","banca":"IV - UFG","ano":2018,"temas_relacionados":["linux_geral"]},{"id":898455,"enunciado":"Qual é a sintaxe do comando usado para verificar a interface de rede configurada no computador e que utiliza o sistema operacional Linux?","opcoes":["sudo ifconfig","sudo ipconfig","sudo netstat","sudo netconf"],"correta":0,"explicacao":"Gabarito: <strong>sudo ifconfig</strong>.","banca":"IV - UFG","ano":2018,"temas_relacionados":["linux_geral"]},{"id":940745,"enunciado":"Em um equipamento rodando Linux, a execução do programa ldconfig informa ao sistema a localização das bibliotecas compartilhadas mais recentemente especificadas em um arquivo de configuração. Assinale a alternativa que contém o arquivo de configuração que será lido pelo programa ldconfig.","opcoes":["/lib/ld.so","/etc/ld.so.cache","/etc/ld.so.conf","/etc/modules.conf"],"correta":2,"explicacao":"Gabarito: <strong>/etc/ld.so.conf</strong>.","banca":"UFU-MG","ano":2018,"temas_relacionados":["linux_geral"]},{"id":940747,"enunciado":"Em um equipamento rodando Linux, o comando tcpdump é um dos mais, se não o mais, \"famoso\" sniffer para sistemas GNU/Linux. Com ele, podemos realizar análises e solucionar problemas. O comando tcpdump permite aos administradores a capacidade de monitorar","opcoes":["desempenho do servidor.","desempenho da aplicação.","tráfego e atividade da rede.","arquivos e diretórios."],"correta":2,"explicacao":"Gabarito: <strong>tráfego e atividade da rede.</strong>.","banca":"UFU-MG","ano":2018,"temas_relacionados":["linux_geral"]},{"id":940748,"enunciado":"Assinale a alternativa que NÃO é considerada um programa filtro em sistemas operacionais Linux.","opcoes":["sort","grep","uniq","echo"],"correta":3,"explicacao":"Gabarito: <strong>echo</strong>.","banca":"UFU-MG","ano":2018,"temas_relacionados":["linux_geral"]},{"id":943038,"enunciado":"Quando criamos arquivos no editor de texto ou em uma planilha eletrônica, esses arquivos são guardados temporariamente na memória RAM. A esse respeito, o que se deve fazer a fim de transferir esses arquivos para o disco rígido?","opcoes":["Abri-los.","Colá-los.","Salvá-los.","Copiá-los."],"correta":2,"explicacao":"Gabarito: <strong>Salvá-los.</strong>.","banca":"Gestão Concurso","ano":2018,"temas_relacionados":["linux_geral"]},{"id":943040,"enunciado":"É sempre complexo responder qual a melhor distribuição do sistema operacional Linux, pois isso depende do gosto do usuário. O sistema que não representa distribuição do Linux é o","opcoes":["Suse.","Intel.","Fedora.","Ubuntu."],"correta":1,"explicacao":"Gabarito: <strong>Intel.</strong>.","banca":"Gestão Concurso","ano":2018,"temas_relacionados":["linux_geral"]},{"id":950806,"enunciado":"Julgue o item a seguir, a respeito do sistema operacional Linux e do editor de texto Word 2013.\n\nNo sistema operacional Linux, é possível utilizar duas extensões para nomear os arquivos. Assim, nesse sistema, um arquivo poderia ser nomeado, por exemplo, como contrato_BNB.tar.gz.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":950807,"enunciado":"Julgue o item a seguir, a respeito do sistema operacional Linux e do editor de texto Word 2013.\n\nQuando se cria um diretório no ambiente Linux, são criados outros dois diretórios: o “.”, que faz referência ao diretório anterior, dentro da árvore de diretórios; e o “..”, que faz referência ao diretório atual.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":950808,"enunciado":"Julgue o item a seguir, a respeito do sistema operacional Linux e do editor de texto Word 2013.\n\nNa utilização do terminal de qualquer sistema operacional Linux, como o Ubuntu, o aparecimento do caractere $ no prompt de comando significa que o usuário que esteja conectado é o superusuário root.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":958086,"enunciado":"Sobre o sistema operacional Linux e a Internet, considere as afirmativas a seguir. I. O comando ping é utilizado para gerenciar as regras do firewall do sistema. II. O protocolo ssh permite a conexão com outro computador que suporte tal recurso. III. O apt-get permite instalar atualizações de pacotes no sistema através de um servidor. IV. O comando scp transfere um arquivo de um computador para outro via Internet. Assinale a alternativa correta.","opcoes":["Somente as afirmativas I e II são corretas.","Somente as afirmativas I e IV são corretas.","Somente as afirmativas III e IV são corretas.","Somente as afirmativas I, II e III são corretas.","Somente as afirmativas II, III e IV são corretas."],"correta":4,"explicacao":"Gabarito: <strong>Somente as afirmativas II, III e IV são corretas.</strong>.","banca":"COPS-UEL","ano":2018,"temas_relacionados":["linux_geral"]},{"id":958088,"enunciado":"Assinale a alternativa que apresenta, corretamente, o comando do terminal utilizado para apagar um arquivo, no sistema operacional Linux.","opcoes":["rm","mv","ln","cp","cd"],"correta":0,"explicacao":"Gabarito: <strong>rm</strong>.","banca":"COPS-UEL","ano":2018,"temas_relacionados":["linux_geral"]},{"id":962534,"enunciado":"Suponha que, no Linux padrão, o subdiretório ‘/home/paula/adir’ possui apenas os arquivos de nomes ‘AAA’, ’BBB’ e ‘CCC’. Foi dado o seguinte comando: ‘/home/paula/adir# ls | sort –r | tail -2’. Indique a alternativa que apresenta a saída do comando (cujos elementos podem aparecer em linhas diferentes).","opcoes":["‘BBB’ ‘AAA’","‘BBB’ ‘CCC’","‘AAA’ ‘BBB’","‘CCC’ ‘BBB’","‘AAA’ ‘CCC’"],"correta":0,"explicacao":"Gabarito: <strong>‘BBB’ ‘AAA’</strong>.","banca":"COVEST-COPSET","ano":2017,"temas_relacionados":["linux_geral"]},{"id":962593,"enunciado":"Suponha que o usuário pressionou a tecla de ‘enter’ do Linux padrão com a linha de comando mostrando: ‘/usr/vac# cp /etc/arq1 /usr/vac/geral/arq2’. Assinale a alternativa que apresenta uma possível resposta do sistema que é coerente com o comando dado.","opcoes":["O sistema copiou o arquivo ‘arq1’ que está em ‘/etc’ para um subdiretório do corrente chamado ‘geral/arq2’.","O sistema comparou o arquivo ‘arq1’, que está em ‘etc’, com o arquivo ‘arq2’, que está em ‘/usr/vac/geral‘, e imprimiu no ‘shell’ as diferenças entre os dois arquivos.","O sistema contabilizou quantos processos estavam sendo executados e que tinham sido invocados a partir dos diretórios ‘/etc/arq1’ e ‘/usr/vac/geral/arq2’ e imprimiu no ‘shell’ o resultado.","O sistema concatenou permanentemente o arquivo ‘arq1’, que estava em ‘etc’, ao arquivo ‘arq2’, que estava em ‘/usr/vac/geral‘.","O sistema recortou (“cut”) o arquivo ‘/etc/arq1’ e colou (“paste”) no diretório ‘/usr/vac/geral’, sobrescrevendo o arquivo ‘arq2’."],"correta":0,"explicacao":"Gabarito: <strong>O sistema copiou o arquivo ‘arq1’ que está em ‘/etc’ para um subdiretório do corrente chamado ‘geral/arq2’.</strong>.","banca":"COVEST-COPSET","ano":2017,"temas_relacionados":["linux_geral"]},{"id":962594,"enunciado":"Suponha que um usuário, utilizando o Linux padrão, executou a seguinte sequência de comandos: ‘cd ~’, ‘cd –‘, ‘pwd’, ‘cd ../../s’, ‘cd .’ e ‘pwd’. O resultado do último comando foi: ‘/usr/a/b/s’. Indique a única alternativa que apresenta uma resposta coerente com o terceiro comando da sequência.","opcoes":["‘/usr/s/c/f’","‘/usr/a/b/s’","‘/usr/a/b/f/d/e’","‘/usr/a/b/g/d","‘/usr/s/f/d/e’"],"correta":3,"explicacao":"Gabarito: <strong>‘/usr/a/b/g/d</strong>.","banca":"COVEST-COPSET","ano":2017,"temas_relacionados":["linux_geral"]},{"id":962595,"enunciado":"Suponha que num sistema Linux padrão um usuário ‘A’, que não pertence ao grupo do usuário ‘B’, deseja modificar o arquivo ‘F.cpp’ pertencente a ‘B’. O arquivo está no subdiretório: ‘/home/B/bdir’. Indique a alternativa que apresenta o que ‘B’ precisa fazer em termos de permissões de acesso do sistema, para que o usuário ‘A’ consiga modificar o arquivo.","opcoes":["É suficiente ‘B’ colocar no subdiretório ‘bdir’ a permissão ‘x’ de grupo (‘g’), e no arquivo ‘F.cpp’ a permissão ‘rw’ para o usuário (‘u’).","É suficiente ‘B’ colocar no subdiretório ‘bdir’ a permissão ‘x’ de usuário (‘u’), e no arquivo ‘F.cpp’ a permissão ‘rw’ para todos (‘a’).","É suficiente ‘B’ colocar nos subdiretórios ‘home’, ‘B’ e ‘bdir’ a permissão ‘rwx’ para outros (‘o’), e no arquivo ‘F.cpp’ a permissão ‘rw’ para outros (‘o’).","É suficiente ‘B’ colocar nos subdiretórios ‘home’, ‘B’ e ‘bdir’ a permissão ‘rw’ de todos (‘a’), e no arquivo ‘F.cpp’ a permissão ‘rw’ para grupo (‘g’).","É suficiente ‘B’ colocar nos subdiretórios ‘B’ e ‘bdir’ a permissão ‘rwx’ de outros (‘o’), e no arquivo ‘F.cpp’ a permissão ‘rwx’ para todos (‘a’)."],"correta":3,"explicacao":"Gabarito: <strong>É suficiente ‘B’ colocar nos subdiretórios ‘home’, ‘B’ e ‘bdir’ a permissão ‘rw’ de todos (‘a’), e no arquivo ‘F.cpp’ a permissão ‘rw’ para grupo (‘g’).</strong>.","banca":"COVEST-COPSET","ano":2017,"temas_relacionados":["linux_geral"]},{"id":989917,"enunciado":"Em um ambiente Linux, deseja-se saber quanto há de espaço em um disco e na memória principal do computador. Para isso usamos, respectivamente, os comandos:","opcoes":["df e free .","ls -al e freemen.","df e du.","du e usage."],"correta":0,"explicacao":"Gabarito: <strong>df e free .</strong>.","banca":"IF-GO","ano":2018,"temas_relacionados":["linux_geral"]},{"id":989930,"enunciado":"Ao instalar um servidor utilizando o sistema operacional Linux, muitos administradores optam por não manter uma interface gráfica, pois isso ocuparia memória principal e armazenamento, diminuindo o desempenho. Quando isso ocorre, o gerenciamento do sistema é feito por meio da interface de linha de comandos, também conhecida como Shell. Sendo assim, torna-se fundamental para os técnicos em informática ter domínio dos comandos do Linux. Sobre comandos de linha no Linux, indique a alternativa CORRETA.","opcoes":["Os comandos free e df podem ser utilizados para exibir informações de memória principal e disco, respectivamente.","Os comandos mem e ps podem ser utilizados para exibir informações de disco e processos, respectivamente.","Os comandos pwd e kill podem ser utilizados para exibir informações de senhas e matar processos, respectivamente.","Os comandos tail e less podem ser utilizados para exibir informações de rede e arquivos, respectivamente."],"correta":0,"explicacao":"Gabarito: <strong>Os comandos free e df podem ser utilizados para exibir informações de memória principal e disco, respectivamente.</strong>.","banca":"IF-GO","ano":2018,"temas_relacionados":["linux_geral"]},{"id":991960,"enunciado":"Sobre o comando “PWD” do sistema operacional Linux é correto afirmar:","opcoes":["Serve para mudar de diretório corrente e acessá-lo.","Exibe os arquivos encontrados dentro da pasta na qual o usuário está no momento.","Informa qual é o tipo de arquivo que foi digitado como parâmetro.","Exibe a pasta atual na qual o usuário se encontra."],"correta":3,"explicacao":"Gabarito: <strong>Exibe a pasta atual na qual o usuário se encontra.</strong>.","banca":"FUNDEP (Gestão de Concursos)","ano":2019,"temas_relacionados":["linux_geral"]},{"id":991962,"enunciado":"Sobre o sistema operacional Linux, analise as seguintes afirmativas: I. É um sistema multitarefa, isto é, permite executar mais de um aplicativo, porém, enquanto um é executado, o outro fica em segundo plano. II. É um sistema multisessão, pois permite haver várias contas de usuários em um único computador. III. É preemptivo, pois permite a interrupção de processos. Estão corretas as afirmativas:","opcoes":["I e II, apenas.","I e III, apenas.","II e III, apenas.","I, II e III."],"correta":2,"explicacao":"Gabarito: <strong>II e III, apenas.</strong>.","banca":"FUNDEP (Gestão de Concursos)","ano":2019,"temas_relacionados":["linux_geral"]},{"id":993833,"enunciado":"Em um sistema operacional Linux, qual dos seguintes arquivos contém as informações sobre cada um dos usuários que pode utilizar o sistema?","opcoes":["/etc/passwd","/etc/group","/etc/home","/etc/user","/etc/info"],"correta":0,"explicacao":"Gabarito: <strong>/etc/passwd</strong>.","banca":"CCV-UFC","ano":2019,"temas_relacionados":["linux_geral"]},{"id":993838,"enunciado":"Em um sistema operacional Linux, em qual dos seguintes comandos é possível visualizar a quantidade de memória utilizada no sistema?","opcoes":["free","yacc","lpstat","netstat","syslogd"],"correta":0,"explicacao":"Gabarito: <strong>free</strong>.","banca":"CCV-UFC","ano":2019,"temas_relacionados":["linux_geral"]},{"id":1082624,"enunciado":"Considere no Linux padrão a questão das permissões de acesso aos arquivos. Suponha que um dado arquivo comum tem permissão total para o dono, permissão de leitura e execução para o grupo e permissão de execução para os demais usuários. O modo de permissões do arquivo, como apresentado pelo comando 'ls', é:","opcoes":["-rwx-wx--x","-x-r--xrwx","--xr-xrwx","-rwxr-x--x","x--rwxr-x"],"correta":3,"explicacao":"Gabarito: <strong>-rwxr-x--x</strong>.","banca":"COVEST-COPSET","ano":2019,"temas_relacionados":["linux_geral"]},{"id":1082625,"enunciado":"Considere no Linux padrão o comando que procura, num conjunto de arquivos-texto, e então imprime, as linhas de texto que contenham um padrão de caracteres prescrito. No caso, suponha que sejam arquivos com nomes “nome1.txt”, “nome2.txt”, etc., e o padrão seja “sol”. Assinale a alternativa que exibe o comando que faz o que se pede.","opcoes":["find “sol” nome?.txt","string “sol” nome*.txt","grep “sol” nome*txt","finger nome#.txt “sol”","cat nome#.txt > “sol”"],"correta":2,"explicacao":"Gabarito: <strong>grep “sol” nome*txt</strong>.","banca":"COVEST-COPSET","ano":2019,"temas_relacionados":["linux_geral"]},{"id":1158555,"enunciado":"Qual o nome da classe de programas que funciona como interpretador de comandos e linguagem de programação no Linux, que é a principal ligação entre o usuário, os programas e o Kernel?","opcoes":["Kerne","Hardware","Scrip","PID","Shell"],"correta":4,"explicacao":"Gabarito: <strong>Shell</strong>.","banca":"IBADE","ano":2020,"temas_relacionados":["linux_geral"]},{"id":1158556,"enunciado":"No Linux, qual comando mostra o conteúdo de um arquivo binário ou texto, só que em ordem inversa do arquivo?","opcoes":["Tac","Cat","Rm","Cp","Mv"],"correta":0,"explicacao":"Gabarito: <strong>Tac</strong>.","banca":"IBADE","ano":2020,"temas_relacionados":["linux_geral"]},{"id":1172976,"enunciado":"Considerando o fragmento de configuração smb.conf, para sistemas Linux citado abaixo qual a função do parâmetro está faltando para permitir para o compartilhamento de impressoras e a impressão de arquivos ? “ [Printers] path = /usr/spool/public read only = yes guest ok = yes comment = all Printers writable = no ”","opcoes":["“ printable = yes","“ netbios name = SRV","” log file = /var/log/samba/log.%m","Nenhuma das alternativas."],"correta":0,"explicacao":"Gabarito: <strong>“ printable = yes</strong>.","banca":"Instituto Excelência","ano":2018,"temas_relacionados":["linux_geral"]},{"id":1172978,"enunciado":"Na página de download do sistema operacional de uma distribuição Linux, há diversas opções de download entre elas ARM,sparc e powerpc. Assinale abaixo qual a diferenças entre as versões:","opcoes":["São versões para diferentes tipos de processadores, e suas instruções relacionadas.","São versões de atualização, mudam o funcionamento de um sistema já instalado.","São nomes de distribuição Linux mudam de acordo com seus produtores independentes.","Nenhuma das alternativas."],"correta":0,"explicacao":"Gabarito: <strong>São versões para diferentes tipos de processadores, e suas instruções relacionadas.</strong>.","banca":"Instituto Excelência","ano":2018,"temas_relacionados":["linux_geral"]},{"id":1177044,"enunciado":"No Linux, qual o nome do comando que fecha todos os processos em execução?","opcoes":["Killall","Jobs","Fg","Bg","Killall5"],"correta":4,"explicacao":"Gabarito: <strong>Killall5</strong>.","banca":"IBADE","ano":2020,"temas_relacionados":["linux_geral"]},{"id":1177045,"enunciado":"O Linux também possui um padrão para ambiente gráfico. Os sistemas Unix mais antigos são baseados somente em caracteres, mas hoje praticamente qualquer sistema Unix, incluindo o Linux, dispõe de um sistema gráfico de janelas. Qual o nome deste sistema?","opcoes":["Apache","X Windows","Fedora","Sendmail","Mozilla Firefox"],"correta":1,"explicacao":"Gabarito: <strong>X Windows</strong>.","banca":"IBADE","ano":2020,"temas_relacionados":["linux_geral"]},{"id":1179796,"enunciado":"Assinale a alternativa que NÃO apresenta um ambiente de Área de Trabalho (interface gráfica ou ambiente X) existente para sistemas operacionais baseados em Linux.","opcoes":["KDE","Gnome","XFCE","Unity","Xtreme"],"correta":4,"explicacao":"Gabarito: <strong>Xtreme</strong>.","banca":"INSTITUTO AOCP","ano":2018,"temas_relacionados":["linux_geral"]},{"id":1179797,"enunciado":"Em um sistema operacional baseado em Linux, o que faz o comando de terminal: ifconfig?","opcoes":["É utilizado para listar arquivos de configuração.","É utilizado para abrir as configurações do sistema.","É um comando inválido.","É utilizado para configurar e inspecionar interfaces de rede.","É utilizado para configurar uma impressora."],"correta":3,"explicacao":"Gabarito: <strong>É utilizado para configurar e inspecionar interfaces de rede.</strong>.","banca":"INSTITUTO AOCP","ano":2018,"temas_relacionados":["linux_geral"]},{"id":1374871,"enunciado":"Algumas ferramentas livres do Linux são desenvolvidas por pessoas de todo o mundo de forma colaborativa. Assinale o módulo que define o núcleo operacional do sistema operacional Linux:","opcoes":["Terminal","Shell","Script","Explorer","Kernel"],"correta":4,"explicacao":"Gabarito: <strong>Kernel</strong>.","banca":"CPCON","ano":2017,"temas_relacionados":["linux_geral"]},{"id":1374872,"enunciado":"Comandos geralmente não podem ser escritos de uma forma aleatória. Eles necessitam de uma estrutura (sintaxe). É (São) componente(s) de comandos Linux:","opcoes":["Comando Teste Memória","Comando Opções Argumentos","Comando Desligar Parâmetros","Argumentos Teste Parâmetros","Ligar Opções Parâmetros"],"correta":1,"explicacao":"Gabarito: <strong>Comando Opções Argumentos</strong>.","banca":"CPCON","ano":2017,"temas_relacionados":["linux_geral"]},{"id":1381426,"enunciado":"O comando em Linux que exibe o conteúdo de um arquivo é:","opcoes":["cat","ls","mkdir","top","man"],"correta":0,"explicacao":"Gabarito: <strong>cat</strong>.","banca":"UFCG","ano":2019,"temas_relacionados":["linux_geral"]},{"id":1381441,"enunciado":"As distribuições Linux vem ganhando popularidade, provendo ambientes amigáveis para o usuário. São exemplos de distribuição Linux, EXCETO:","opcoes":["Ubuntu.","openSUSE.","Slackware.","Fedora.","GIMP."],"correta":4,"explicacao":"Gabarito: <strong>GIMP.</strong>.","banca":"UFCG","ano":2019,"temas_relacionados":["linux_geral"]},{"id":1696380,"enunciado":"Em um ambiente Linux, para incluir usuários e/ou trocar senhas você deve se utilizar de qual userid?","opcoes":["Master","Maint","Admin","Root","Password"],"correta":3,"explicacao":"Gabarito: <strong>Root</strong>.","banca":"IBADE","ano":2020,"temas_relacionados":["linux_geral"]},{"id":1696384,"enunciado":"Em ambiente Linux existem alternativas à suíte MS Office. A planilha oferecida pelo LibreOffice como alternativa ao MS Excel é:","opcoes":["MegaCalc.","Linux Calc.","Calc.","LinCalc.","LibreCalc."],"correta":2,"explicacao":"Gabarito: <strong>Calc.</strong>.","banca":"IBADE","ano":2020,"temas_relacionados":["linux_geral"]},{"id":1721666,"enunciado":"Em linux este diretório armazena executáveis, mas com um diferencial: são aplicativos utilizados por administradores de sistema com o propósito de realizar funções de manutenção e outras tarefas semelhantes. Entre os comandos disponíveis estão o ifconfig, para configurar e controlar interfaces de rede TCP/IP, e o fdisk, que permite particionar discos rígidos, por exemplo. Qual o nome do diretório dessa definição?","opcoes":["/sbin","/bin","/etc","Nenhuma das alternativas."],"correta":0,"explicacao":"Gabarito: <strong>/sbin</strong>.","banca":"Instituto Excelência","ano":2019,"temas_relacionados":["linux_geral"]},{"id":1721667,"enunciado":"Em Linux, qual dos comandos abaixo é utilizado no terminal para obter meu endereço de IP?","opcoes":["ipconfig","ifconfig","getip","Nenhuma das alternativas."],"correta":1,"explicacao":"Gabarito: <strong>ifconfig</strong>.","banca":"Instituto Excelência","ano":2019,"temas_relacionados":["linux_geral"]},{"id":1721668,"enunciado":"Via terminal Linux, qual o comando é utilizado para criação de diretórios?","opcoes":["createdir","rmdir","mkdir","Nenhuma das alternativas."],"correta":2,"explicacao":"Gabarito: <strong>mkdir</strong>.","banca":"Instituto Excelência","ano":2019,"temas_relacionados":["linux_geral"]},{"id":1726077,"enunciado":"No Linux, utilizamos muitos comandos para efetuar vários procedimentos, assim com essa finalidade qual comando que podemos usar para nos orientar como utilizar um comando desconhecido. Marque a alternativa que corresponde a este comando.","opcoes":["help","ls","chmod","Nenhuma das alternativas."],"correta":0,"explicacao":"Gabarito: <strong>help</strong>.","banca":"Instituto Excelência","ano":2019,"temas_relacionados":["linux_geral"]},{"id":1726078,"enunciado":"No Linux, podemos verificar a capacidade de armazenamento de várias maneiras, usando apenas um comando. Marque a alternativa CORRETA que corresponde a este comando.","opcoes":["df -h","rm -rf","ls -la","Nenhuma das alternativas."],"correta":0,"explicacao":"Gabarito: <strong>df -h</strong>.","banca":"Instituto Excelência","ano":2019,"temas_relacionados":["linux_geral"]},{"id":1726079,"enunciado":"O Linux tem muitas pastas e arquivos dentro do sistema, cada uma delas tem sua importância, porém uma delas tem um peso maior, pois é onde se encontram os aplicativos do sistema. Qual pasta estamos falando?","opcoes":["home","etc","dev","Nenhuma das alternativas."],"correta":1,"explicacao":"Gabarito: <strong>etc</strong>.","banca":"Instituto Excelência","ano":2019,"temas_relacionados":["linux_geral"]},{"id":1726080,"enunciado":"No ambiente Linux, usando o console podemos criar, acessar e remover diretórios. Qual desses respectivos comandos abaixo tem relação ao enunciado?","opcoes":["mkdir, cd, rm","pwd, ls, chmod","chown, chmod, rm","Nenhuma das alternativas."],"correta":0,"explicacao":"Gabarito: <strong>mkdir, cd, rm</strong>.","banca":"Instituto Excelência","ano":2019,"temas_relacionados":["linux_geral"]},{"id":1728412,"enunciado":"É o diretório, no Linux, de programas usados pelo superusuário root, para administração e controle do funcionamento do sistema. Trata-se do diretório:","opcoes":["/etc","/mnt","/sbin","/usr"],"correta":2,"explicacao":"Gabarito: <strong>/sbin</strong>.","banca":"AMEOSC","ano":2018,"temas_relacionados":["linux_geral"]},{"id":1728420,"enunciado":"Qual o resultado do comando cd../.. digitado no terminal do SO Linux?","opcoes":["Volta para o diretório raiz.","Volta um nível de diretório.","Volta dois níveis de diretório.","Volta para o diretório /Home."],"correta":2,"explicacao":"Gabarito: <strong>Volta dois níveis de diretório.</strong>.","banca":"AMEOSC","ano":2018,"temas_relacionados":["linux_geral"]},{"id":1791944,"enunciado":"Na utilização de um computador existe um programa que, além de gerenciar a execução de programas aplicativos, atua como a interface entre o usuário e o hardware do computador. O nome desse tipo de programa é","opcoes":["software de prateleira.","aplicativo básico.","programa utilitário.","sistema operacional.","interface humano-computador."],"correta":3,"explicacao":"Gabarito: <strong>sistema operacional.</strong>.","banca":"INSTITUTO AOCP","ano":2021,"temas_relacionados":["linux_geral"]},{"id":1791948,"enunciado":"O Linux possui diferentes ambientes desktop. Dois desses ambientes são:","opcoes":["Explorer e KDE.","Gnome e Shell.","Unity e Xfce.","Bash e Sh.","Nautilus e Konqueror."],"correta":2,"explicacao":"Gabarito: <strong>Unity e Xfce.</strong>.","banca":"INSTITUTO AOCP","ano":2021,"temas_relacionados":["linux_geral"]},{"id":1812582,"enunciado":"A respeito do sistema operacional Linux, dos conceitos de redes de computadores e do programa de navegação Google Chrome, em sua versão mais recente, julgue o item.\nO Ubuntu não permite o agendamento de tarefas. Sendo assim, não é possível programá-lo para executar um programa em um determinado horário.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":1812583,"enunciado":"A respeito do sistema operacional Linux, dos conceitos de redes de computadores e do programa de navegação Google Chrome, em sua versão mais recente, julgue o item.\nNo sistema operacional Linux, não é permitida a execução de comandos por meio de terminal, devido a um mecanismo de segurança imposto por esse sistema.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":1825575,"enunciado":"Considere um computador com UBUNTU v.20.4 em sua instalação padrão. No aplicativo Arquivos, o comando para excluir permanentemente um arquivo selecionado é:","opcoes":["Del","Shift + Del","Ctrl + Del","Alt + Del","Backspace"],"correta":1,"explicacao":"Gabarito: <strong>Shift + Del</strong>.","banca":"NC-UFPR","ano":2021,"temas_relacionados":["linux_geral"]},{"id":1825576,"enunciado":"No sistema UBUNTU v.20.4, no aplicativo Arquivos, uma URL válida para acessar uma pasta compartilhada em um servidor Windows, com as respectivas permissões de acesso, é:","opcoes":["ftp://joao@maquina1/Documentos","http://user@maquina1.com/Documentos","smb://10.10.1.3/Documentos","ntfs:\\\\10.10.1.3\\Documentos","\\\\10.10.1.3\\Documentos"],"correta":2,"explicacao":"Gabarito: <strong>smb://10.10.1.3/Documentos</strong>.","banca":"NC-UFPR","ano":2021,"temas_relacionados":["linux_geral"]},{"id":1827398,"enunciado":"No que se refere ao sistema operacional Linux, julgue o item a seguir.\n\n\n\n\nO comando ls -l permite listar arquivos e diretórios, até mesmo os ocultos.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2021,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":1827399,"enunciado":"No que se refere ao sistema operacional Linux, julgue o item a seguir.\n\n\n\n\nO comando whoami mostra a lista de usuários que estão conectados e fizeram login no sistema.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2021,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":1827400,"enunciado":"No que se refere ao sistema operacional Linux, julgue o item a seguir.\n\n\n\n\nO comando cp -v possibilita a cópia de arquivos e mostra o que está sendo copiado durante a execução.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2021,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":1941950,"enunciado":"Nos sistemas operacionais do tipo Linux, qual o comando que permite criar novos arquivos em branco através de uma linha de comando?","opcoes":["touch.","locate.","find.","grep."],"correta":0,"explicacao":"Gabarito: <strong>touch.</strong>.","banca":"IDECAN","ano":2022,"temas_relacionados":["linux_geral"]},{"id":1941954,"enunciado":"Podemos utilizar em um mesmo computador mais de um sistema operacional ao mesmo tempo, por exemplo: duas distribuições de Linux e uma de Windows ou uma de Linux e outra de Windows. Qual o sistema no Linux que controla o uso do “multiboot” em um computador?","opcoes":["Grub.","Yast.","KDM.","Gimp."],"correta":0,"explicacao":"Gabarito: <strong>Grub.</strong>.","banca":"IDECAN","ano":2022,"temas_relacionados":["linux_geral"]},{"id":1995527,"enunciado":"O sistema operacional Linux é baseado em software livre composto de três diferentes componentes. Assinale a alternativa que apresenta esses componentes.","opcoes":["O acesso ao sistema, o núcleo de operações e as operações de entrada e saída.","O supervisor do sistema operacional, o super-usuário e os scripts.","O setor de boot, o usuário root e os processos multitarefas.","A licença do software livre, as threads do sistema operacional e o buffer de disco.","A biblioteca do sistema, o utilitário do sistema e o kernel."],"correta":4,"explicacao":"Gabarito: <strong>A biblioteca do sistema, o utilitário do sistema e o kernel.</strong>.","banca":"INSTITUTO AOCP","ano":2021,"temas_relacionados":["linux_geral"]},{"id":1995528,"enunciado":"Nos sistemas operacionais Linux, uma forma de programa que recebe os comandos dos usuários e os transfere para o sistema operacional para fins de processamento e, em seguida, mostra o seu resultado é conhecida como","opcoes":["superusuário.","shell.","batch.","script.","programa."],"correta":1,"explicacao":"Gabarito: <strong>shell.</strong>.","banca":"INSTITUTO AOCP","ano":2021,"temas_relacionados":["linux_geral"]},{"id":1998668,"enunciado":"Considerando o Sistema Operacional Linux, um sistema que não necessita de licença para uso e que pode gerar uma economia muito grande em licença de softwares, deve-se fazer um programa, rodando em segundo plano ou parado, rodar em primeiro plano. Dessa forma, o comando a ser utilizado é:","opcoes":["fg","bg","kill","jobs","killall"],"correta":0,"explicacao":"Gabarito: <strong>fg</strong>.","banca":"Instituto Consulplan","ano":2022,"temas_relacionados":["linux_geral"]},{"id":1998669,"enunciado":"Para atualizar qualquer programa em um Sistema Operacional Linux há ferramentas que executam tal trabalho, seja no modo texto, ou até mesmo em modo gráfico. A ferramenta APT (Advanced Packaging Tool) é utilizada na distribuição Debian, assim como suas variantes; trata de forma automática os problemas que podem advir com a dependência de pacotes. Considerando a seguinte sintaxe: “# Apt-Get Update”, assinale a afirmativa correta.","opcoes":["Atualiza a distribuição Linux.","Atualiza a lista de pacotes disponíveis.","Faz busca e obtém informações sobre os pacotes.","Serve para remover os pacotes com a atualização.","O comando não irá gerar efeito, pois não está correto."],"correta":4,"explicacao":"Gabarito: <strong>O comando não irá gerar efeito, pois não está correto.</strong>.","banca":"Instituto Consulplan","ano":2022,"temas_relacionados":["linux_geral"]},{"id":2007520,"enunciado":"Assinale a alternativa que contém uma função válida do utilitário de linha de comando do Linux denominado time.","opcoes":["Definir somente o tempo (hora, minutos e segundos) do sistema operacional.","Definir a data e o tempo (hora, minutos e segundos) hora do sistema operacional.","Informar a data e o tempo (hora, minutos e segundos) do sistema operacional.","Informar o intervalo de tempo que leva para executar um dado comando.","Informar somente o tempo (hora, minutos e segundos) corrente do sistema operacional."],"correta":3,"explicacao":"Gabarito: <strong>Informar o intervalo de tempo que leva para executar um dado comando.</strong>.","banca":"FEPESE","ano":2019,"temas_relacionados":["linux_geral"]},{"id":2007523,"enunciado":"Qual aplicativo Linux é um aplicativo de tecnologia assistiva que consiste em um leitor de tela executado na interface gráfica Gnome?","opcoes":["Orca","e-Read","D-Screen","Amplify","Vinci"],"correta":0,"explicacao":"Gabarito: <strong>Orca</strong>.","banca":"FEPESE","ano":2019,"temas_relacionados":["linux_geral"]},{"id":2029568,"enunciado":"A estrutura de pastas em uma distribuição Linux moderna como o Ubuntu é fortemente inspirada em fundações originais do sistema Unix. Os arquivos e as pastas organizadas em um sistema Linux são bem diferentes das pastas utilizadas no Windows. A figura a seguir apresenta alguns exemplos de pastas; observe. São consideradas descrições de pasta do Linux, EXCETO:","opcoes":["/usr: armazena usuários cadastrados e suas permissões.","/etc: se encontram salvos os arquivos gerais de configuração do sistema e dos programas instalados.","/var: pasta que contém arquivos de log e outras variáveis dos softwares instalados no computador.","/dev: cada dispositivo do computador (placas de som, webcams etc.) tem uma entrada nesta pasta. Cada programa tem acesso aos dispositivos através de itens contidos neste diretório."],"correta":0,"explicacao":"Gabarito: <strong>/usr: armazena usuários cadastrados e suas permissões.</strong>.","banca":"Instituto Consulplan","ano":2022,"temas_relacionados":["linux_geral"]},{"id":2029571,"enunciado":"Um dos elementos mais poderosos do sistema Ubuntu são as linhas de comando, que contribuem para a vida de um usuário desktop. É essencial para administradores de servidores. Ao acessar o terminal do Ubuntu, é possível observar uma série de caracteres terminados com o símbolo $; trata-se do prompt de comando. Diante do exposto, analise as definições dos comandos a seguir. I. Permite saber em qual diretório atual nos encontramos. II. Exibe o espaço em disco utilizado de cada partição. III. Exibe informações do nome da máquina, versão do kernel e arquitetura do sistema. IV. Exibe informações sobre a versão da distribuição Linux executada. V. Lista os dispositivos de hardware conectados ao computador, incluindo o nome do fabricante, o tipo e onde está conectado. A associação está correta em","opcoes":["I. ps II. df III. uname -a IV. lsb_release -a V. lsusb","I. pwd II. df III. uname -a IV. lsb_release -a V. lshw","I. ps II. free III. lsb_release -a IV. uname -a V. ifconfig","I. pwd II. free III. lsb_release -a IV. uname -a V. lshw"],"correta":1,"explicacao":"Gabarito: <strong>I. pwd II. df III. uname -a IV. lsb_release -a V. lshw</strong>.","banca":"Instituto Consulplan","ano":2022,"temas_relacionados":["linux_geral"]},{"id":2029576,"enunciado":"O Ubuntu surgiu em 2004; trata-se de uma das distribuições Linux mais conhecidas. Sobre o Ubuntu, analise as afirmativas a seguir. I. É um projeto dirigido pela comunidade com o objetivo de criar um sistema operacional com um conjunto completo de aplicativos, utilizando softwares livres e de código aberto. II. Todos os usuários têm a liberdade de executar, copiar, distribuir, estudar, compartilhar, alterar e melhorar o software para qualquer propósito sem pagar licença. III. Possui um código de conduta que deverá ser lido e aceito pelo usuário para utilizar o sistema. IV. O ambiente gráfico padrão do Ubuntu é o KDE. Está correto o que se afirma apenas em","opcoes":["I e II.","I e III.","III e IV.","I, II e III."],"correta":0,"explicacao":"Gabarito: <strong>I e II.</strong>.","banca":"Instituto Consulplan","ano":2022,"temas_relacionados":["linux_geral"]},{"id":2034159,"enunciado":"São sistemas de arquivo do Linux, EXCETO:","opcoes":["JFS.","Ext4.","ReiserFS.","NTFS.","Btrfs."],"correta":3,"explicacao":"Gabarito: <strong>NTFS.</strong>.","banca":"IBADE","ano":2022,"temas_relacionados":["linux_geral"]},{"id":2034160,"enunciado":"O “proc” é um diretório do Linux que tem como função:","opcoes":["conter informações sobre os processos do sistema.","armazenar arquivos temporários da inicialização do sistema.","conter informações sobre devices, drivers e características do kernel.","armazenar os diretórios dos usuários do sistema.","conter arquivos temporários."],"correta":0,"explicacao":"Gabarito: <strong>conter informações sobre os processos do sistema.</strong>.","banca":"IBADE","ano":2022,"temas_relacionados":["linux_geral"]},{"id":2044511,"enunciado":"A imagem abaixo representa o menu da aba Configurações do sistema, do sistema operacional Linux. É correto afirmar que o ícone Contas de usuários, é responsável por:","opcoes":["configurar o teclado de acordo com as preferências de quem está utilizando-o.","permitir que o usuário selecione o idioma de sua preferência, para os menus e janelas do sistema.","configurar o gerenciamento de energia do computador.","configurar as preferências de som.","adicionar e remover usuário, alterar o tipo de conta, gerenciar grupos de contas e acionar, modificar ou remover senha."],"correta":4,"explicacao":"Gabarito: <strong>adicionar e remover usuário, alterar o tipo de conta, gerenciar grupos de contas e acionar, modificar ou remover senha.</strong>.","banca":"IBADE","ano":2022,"temas_relacionados":["linux_geral"]},{"id":2044512,"enunciado":"Para que o usuário do sistema operacional Linux feche um aplicativo que está ativo, deve ser utilizado o atalho:","opcoes":["Alt + F2.","Ctrl + Q.","Ctrl + Alt + F7.","Ctrl + F","Alt + Tab."],"correta":1,"explicacao":"Gabarito: <strong>Ctrl + Q.</strong>.","banca":"IBADE","ano":2022,"temas_relacionados":["linux_geral"]},{"id":2044513,"enunciado":"A tecla Tab, na linha de comando do Linux, permite que o usuário:","opcoes":["saia de um comando, ou processo em um terminal.","ative um programa que está em execução em segundo plano.","economize tempo, uma vez que ele completará, automaticamente, o que está sendo digitado ou mostrará todos os resultados possíveis.","desconecte-se do terminal em que se encontra atualmente.","limpe o terminal."],"correta":2,"explicacao":"Gabarito: <strong>economize tempo, uma vez que ele completará, automaticamente, o que está sendo digitado ou mostrará todos os resultados possíveis.</strong>.","banca":"IBADE","ano":2022,"temas_relacionados":["linux_geral"]},{"id":2044514,"enunciado":"Qual é o comando utilizado para delimitar um arquivo em colunas, números de caracteres ou por posição de campo, no terminal do Linux?","opcoes":["Mon.","Dow.","Cmd.","Cut.","Bg."],"correta":3,"explicacao":"Gabarito: <strong>Cut.</strong>.","banca":"IBADE","ano":2022,"temas_relacionados":["linux_geral"]},{"id":2053561,"enunciado":"Num sistema Linux configurado de forma padrão, para o usuário chamado ‘paulo’, quando se entra no sistema pela primeira vez após ligar o computador, o diretório de trabalho corrente é configurado como:","opcoes":["/usr/paulo","/bin/paulo","/home/paulo","/etc/paulo","/lib/Paulo"],"correta":2,"explicacao":"Gabarito: <strong>/home/paulo</strong>.","banca":"COVEST-COPSET","ano":2017,"temas_relacionados":["linux_geral"]},{"id":2055486,"enunciado":"Assinale a alternativa que contém os utilitários de linha de comando do Linux e do Windows, respectivamente, que possibilitam obter informações sobre as interfaces e configurações de rede do computador.","opcoes":["show int e ipconfig","ipconfig e ipconfig","ipconfig e ifconfig","ifconfig e ifconfig","ifconfig e ipconfig"],"correta":4,"explicacao":"Gabarito: <strong>ifconfig e ipconfig</strong>.","banca":"FEPESE","ano":2018,"temas_relacionados":["linux_geral"]},{"id":2055487,"enunciado":"O Linux conta com um utilitário de linha de comando que exibe informações sobre um determinado comando ou utilitário Linux, passado como parâmetro desse utilitário. Como por exemplo a sintaxe, informações gerais, parâmetros e em muitos casos também exemplos sobre como utilizar o comando em questão. Assinale a alternativa que contém o nome desse utilitário Linux.","opcoes":["help","top","hlist","man","more"],"correta":3,"explicacao":"Gabarito: <strong>man</strong>.","banca":"FEPESE","ano":2018,"temas_relacionados":["linux_geral"]},{"id":2057048,"enunciado":"Analise as afirmativas a seguir sobre a organização de arquivos do sistema operacional Linux. I. O diretório “/dev” são para arquivos de dispositivo. II. O diretório “/tmp” são para arquivos temporários. III. O diretório “/bin” é onde a maioria dos programas-padrão é mantida, junto com arquivos de inicialização. Estão corretas as afirmativas","opcoes":["I e II, apenas.","I e III, apenas.","II e III, apenas.","I, II e III."],"correta":0,"explicacao":"Gabarito: <strong>I e II, apenas.</strong>.","banca":"FUNDEP (Gestão de Concursos)","ano":2018,"temas_relacionados":["linux_geral"]},{"id":2057051,"enunciado":"Por definição, um processo no Linux não é automaticamente elegível para receber tempo de CPU. Assinale a alternativa que lista os quatro estados de execução de um processo no Linux.","opcoes":["Executável, Dormente, Rodando e Parado.","Executável, Dormindo, Rodando e Parado.","Executável, Dormindo, Zumbi e Parado.","Executável, Dormente, Zumbi e Parado."],"correta":3,"explicacao":"Gabarito: <strong>Executável, Dormente, Zumbi e Parado.</strong>.","banca":"FUNDEP (Gestão de Concursos)","ano":2018,"temas_relacionados":["linux_geral"]},{"id":2057052,"enunciado":"Analise as afirmativas a seguir referentes aos comandos básicos no sistema operacional Linux e assinale com V as verdadeiras e com F as falsas. ( ) cd: Vai direto para o diretório raiz do usuário conectado. ( ) ls: Lista os arquivos e diretórios da pasta. ( ) df: Mostra as partições usadas ou livres do HD. Assinale a sequência correta.","opcoes":["V V F","F V V","V F V","V V V"],"correta":3,"explicacao":"Gabarito: <strong>V V V</strong>.","banca":"FUNDEP (Gestão de Concursos)","ano":2018,"temas_relacionados":["linux_geral"]},{"id":2064725,"enunciado":"Dado um arquivo denominado test com permissões de uso -rw-r-xr--, qual comando Linux pode-se utilizar para mudar estas permissões para -rwxrw-r-- ?","opcoes":["chmod u-x,g-x,o+w test","chmod test u+x,g-x,g+w","chmod u+x,g-r,g+x test","chmod test u+x,g-x,o+w","chmod u+x,g-x,g+w test"],"correta":4,"explicacao":"Gabarito: <strong>chmod u+x,g-x,g+w test</strong>.","banca":"COVEST-COPSET","ano":2015,"temas_relacionados":["linux_geral"]},{"id":2064726,"enunciado":"O sistema OpenLDAP, utilizado em servidores Linux, serve para acessar e manter serviços de informação de diretório distribuído sobre uma rede IP. O comando que permite que o usuário verifique o acesso a uma lista de atributos é:","opcoes":["slapcat","slapindex","slapacl","slapadd","slaptest"],"correta":2,"explicacao":"Gabarito: <strong>slapacl</strong>.","banca":"COVEST-COPSET","ano":2015,"temas_relacionados":["linux_geral"]},{"id":2094747,"enunciado":"Assinale a alternativa correta. Em um sistema operacional GNU/Linux Ubuntu versão 20.04, é possível utilizar comandos em um terminal para os mais diversos fins. Desta forma, se um usuário que digitou um comando de forma errada e quiser limpar todo o seu conteúdo de uma vez desta linha por teclas de atalho, ele deve utilizar as teclas:","opcoes":["ctrl+s","ctrl+p","ctrl+u","ctrl+k","ctrl+t"],"correta":2,"explicacao":"Gabarito: <strong>ctrl+u</strong>.","banca":"IF-TO","ano":2023,"temas_relacionados":["linux_geral"]},{"id":2094748,"enunciado":"Partindo do diretório raiz “/” em um sistema operacional GNU/Linux Ubuntu versão 20.04, pode-se acessar vários outros diretórios. Dentre esses diretórios, há um que possui os usuários cadastrados no sistema operacional. Assinale a alternativa que representa este diretório.","opcoes":["etc.","tmp.","mnt.","home.","bin."],"correta":3,"explicacao":"Gabarito: <strong>home.</strong>.","banca":"IF-TO","ano":2023,"temas_relacionados":["linux_geral"]},{"id":2145343,"enunciado":"O sistema de arquivos é responsável por gerenciar o meio e o local do disco em que os dados são guardados. Sobre os tipos de sistemas de arquivos existentes, NÃO corresponde a um sistema de arquivos para o sistema operacional Linux:","opcoes":["JFS","XFS","EXT","ReFS"],"correta":3,"explicacao":"Gabarito: <strong>ReFS</strong>.","banca":"Instituto Consulplan","ano":2023,"temas_relacionados":["linux_geral"]},{"id":2145346,"enunciado":"Ubuntu, uma distribuição Linux de código aberto produzido pela empresa Canonical desde 2004, é baseado na distribuição Debian e pode ser instalado em servidores, computadores desktop, na nuvem, e IoT. Sobre a estrutura de diretórios do Linux Ubuntu, corresponde ao diretório responsável por armazenar os arquivos de configuração:","opcoes":["/usr","/var","/etc","/boot"],"correta":2,"explicacao":"Gabarito: <strong>/etc</strong>.","banca":"Instituto Consulplan","ano":2023,"temas_relacionados":["linux_geral"]},{"id":2157312,"enunciado":"O secretário de um dos departamentos da UFSM, que faz uso do sistema operacional GNU/LINUX Ubuntu 20.04, precisa listar os arquivos da pasta “processos” cujos nomes iniciam com 2022. Após listá-los, precisará movê-los para a subpasta “concluídos”. Assinale a alternativa que contém os comandos e os parâmetros necessários que permitirão ao secretário executar essas ações, na sequência apresentada, considerando que já está na pasta “processos”.","opcoes":["ls 2022*; mv 2022* /concluídos","grep 2022*; cp 2022* concluídos","ls ^2022; mv 2022* concluídos","ls 2022*; mv 2022* concluídos","ll 2022; move 2022 concluídos"],"correta":3,"explicacao":"Gabarito: <strong>ls 2022*; mv 2022* concluídos</strong>.","banca":"UFSM","ano":2023,"temas_relacionados":["linux_geral"]},{"id":2157313,"enunciado":"As interfaces gráficas (GUI) das distribuições Linux, em especial, das interfaces de gerenciamento de arquivos, abstraem do usuário o conjunto de comandos básicos para manipulação de arquivos. Porém, sabe-se que os comandos, quando executados no terminal Linux Xubuntu 20.04, possibilitam mais opções de configuração. Com base nisso, três comandos muito usados são caracterizados a seguir. I. Permite mudar para outro diretório. II. Permite renomear um arquivo/diretório. III. Permite modificar os atributos do arquivo. Assinale a alternativa que apresenta os comandos correspondentes às funções descritas em I, II e III respectivamente.","opcoes":["cd, rename, chmod","cd, mv, chmod","cd, mv, chattr","ls, rename, cd","pwd, chmod, chattr"],"correta":2,"explicacao":"Gabarito: <strong>cd, mv, chattr</strong>.","banca":"UFSM","ano":2023,"temas_relacionados":["linux_geral"]},{"id":2160620,"enunciado":"Usando o Linux, em sua configuração original, assinale a alternativa correta sobre o resultado do comando a seguir, considerando que o usuário tem todas as permissões para executá-lo. ls > arquivo.txt","opcoes":["Procura no diretório pelo arquivo arquivo.txt no diretório.","Procura no diretório por arquivos com tamanho maior do que o arquivo arquivo.txt.","Exibe o conteúdo do arquivo arquivo.txt.","Armazena a listagem do conteúdo do diretório em uso no arquivo arquivo.txt.","Marca o arquivo arquivo.txt como apenas leitura."],"correta":3,"explicacao":"Gabarito: <strong>Armazena a listagem do conteúdo do diretório em uso no arquivo arquivo.txt.</strong>.","banca":"VUNESP","ano":2023,"temas_relacionados":["linux_geral"]},{"id":2160621,"enunciado":"No Linux, em sua configuração original, existe uma árvore de diretórios dir1/dir2/dir3/dir4. O comando rmdir dir1/dir2/dir3/dir4 irá apagar","opcoes":["os diretórios dir4, dir3, dir2 e dir1.","os arquivos que existem no diretório dir4, apenas.","o diretorio dir1, apenas.","o diretório dir4, apenas, desde que esteja vazio.","os diretorios dir1 e dir4, apenas."],"correta":3,"explicacao":"Gabarito: <strong>o diretório dir4, apenas, desde que esteja vazio.</strong>.","banca":"VUNESP","ano":2023,"temas_relacionados":["linux_geral"]},{"id":2160622,"enunciado":"Considere a seguinte estrutura de diretórios do Linux, em sua configuração original. dir1/dir2/dir3/dir4 Estando dentro do dir3, ao digitar o comando cd .. e pressionar ENTER, o usuário será posicionado no diretório","opcoes":["root","dir1","dir2","dir3","dir4"],"correta":2,"explicacao":"Gabarito: <strong>dir2</strong>.","banca":"VUNESP","ano":2023,"temas_relacionados":["linux_geral"]},{"id":2161788,"enunciado":"O Ubuntu, uma das distribuições do sistema operacional Linux, permite a utilização de diversos editores de texto. O editor de texto utilizado no Ubuntu que inclui uma interface gráfica ao usuário (GUI) é:","opcoes":["cal","date","top","gedit"],"correta":3,"explicacao":"Gabarito: <strong>gedit</strong>.","banca":"Instituto Consulplan","ano":2023,"temas_relacionados":["linux_geral"]},{"id":2161789,"enunciado":"No sistema operacional Linux, o comando mkdir é empregado para criar diretórios. Para criar os diretórios IFPA e professores em um único comando, em que o diretório professores esteja dentro do diretório IFPA, o usuário deverá executar o seguinte comando:","opcoes":["mkdir ifpa professsores","mkdir ifpa/professsores","mkdir ifpa > professsores","mkdir -p ifpa/professsores"],"correta":3,"explicacao":"Gabarito: <strong>mkdir -p ifpa/professsores</strong>.","banca":"Instituto Consulplan","ano":2023,"temas_relacionados":["linux_geral"]},{"id":2188370,"enunciado":"Um técnico utilizou o seguinte comando Linux para facilitar seu trabalho, em uma máquina operando em condições ideais, cujo shell padrão é o Bash: alias atualiza='sudo apt-get update && sudo apt-get upgrade' Ao final do dia, desligou sua máquina. No dia seguinte, ao utilizar o atualiza, o sistema operacional Linux não mais o reconheceu. Para que, ao ligar sua máquina, ele possa continuar utilizando o atualiza, o comando criado acima deve ser inserido em um arquivo que fica no diretório home do Técnico, de forma que o Bash possa ler o conteúdo deste arquivo e executar o comando, permitindo a utilização do atualiza. Este arquivo é denominado","opcoes":[".bashrc",".bashscript",".stdin",".stdout",".bashinput"],"correta":0,"explicacao":"Gabarito: <strong>.bashrc</strong>.","banca":"FCC","ano":2021,"temas_relacionados":["linux_geral"]},{"id":2188371,"enunciado":"Um técnico utiliza uma máquina com o sistema operacional Linux instalado e funcionando em condições ideais. Existe, no diretório local, um arquivo denominado amazonas.txt, no qual é necessário localizar as ocorrências da palavra Manaus. Para isso, deve-se utilizar o comando","opcoes":["find 'Manaus' amazonas.txt","locate Manaus amazonas.txt","grep Manaus amazonas.txt","head Manaus amazonas.txt","uname 'Manaus' amazonas.txt"],"correta":2,"explicacao":"Gabarito: <strong>grep Manaus amazonas.txt</strong>.","banca":"FCC","ano":2021,"temas_relacionados":["linux_geral"]},{"id":2209645,"enunciado":"Variáveis de ambiente são valores dinâmicos que afetam os programas ou processos que estão em execução em um servidor. Elas existem em todos os sistemas operacionais, sendo que os tipos podem variar. No sistema operacional Linux, existe uma variável do sistema utilizada para localizar arquivos executáveis facilitando a sua execução através da linha de comandos, bastando que se digite o nome da aplicação que pretende executar. Essa variável pode ser definida no arquivo de inicialização do shell no Linux. Assinale a alternativa que indica o nome correto dessa variável.","opcoes":["PWD","DISPLAY","PATH","HOME"],"correta":2,"explicacao":"Gabarito: <strong>PATH</strong>.","banca":"IDIB","ano":2021,"temas_relacionados":["linux_geral"]},{"id":2209648,"enunciado":"A empresa ZYX possui em seus escritórios máquinas com sistemas operacionais Windows e Linux e precisa compartilhar recursos, como arquivos e impressão. Para que as máquinas com esses sistemas diferentes possam realizar o compartilhamento, resolveu-se adotar um servidor para Linux (e outros sistemas baseados em Unix) que permite o gerenciamento e compartilhamento de recursos em redes formadas por computadores com o Windows. Assim, é possível usar o Linux como servidor de arquivos, servidor de impressão, entre outros, como se a rede utilizasse servidores Windows (NT, 2000, XP, Server 2003). Assinale a alternativa que possui o nome do servidor ideal para realizar essa tarefa.","opcoes":["Samba","Postfix","Asterisk","Apache"],"correta":0,"explicacao":"Gabarito: <strong>Samba</strong>.","banca":"IDIB","ano":2021,"temas_relacionados":["linux_geral"]},{"id":2222906,"enunciado":"As alternativas a seguir abordam os conceitos sobre o Microsoft Windows 11 e o Linux Ubuntu 21.10. 1) O Monitor de Recursos de Desempenho é a ferramenta usada para medir o desempenho do Linux Ubuntu 21.10. 2) O Microsoft Windows 11 apresenta o recurso Snap Groups, que é um novo sistema de organização de janelas e aplicativos. 3) O SAR é a ferramenta usada para avaliar o desempenho do Microsoft Windows 11. 4) O Microsoft Teams, aplicativo de videochamadas, está integrado com o Microsoft Windows 11. 5) A interface desktop do Ubuntu 21.10 é a GNOME 40 com suporte a gestos de touchpad, áreas de trabalho dinâmicas e Firefox por via Snap. Estão corretas, apenas:","opcoes":["1, 2 e 3.","1, 3 e 5","2, 3 e 4.","2, 4 e 5.","3, 4 e 5."],"correta":3,"explicacao":"Gabarito: <strong>2, 4 e 5.</strong>.","banca":"UFPE","ano":2022,"temas_relacionados":["linux_geral"]},{"id":2222907,"enunciado":"Em relação aos conceitos de comandos de sistemas operacionais Linux, relacione as descrições da 2ª coluna com as opções indicadas na 1a coluna. A sequência correta, de cima para baixo, é:","opcoes":["1, 3, 2, 5, 4.","2, 1, 4, 3, 5.","3, 5, 1, 2, 4.","4, 1, 5, 3, 2.","5, 2, 3, 4, 1."],"correta":4,"explicacao":"Gabarito: <strong>5, 2, 3, 4, 1.</strong>.","banca":"UFPE","ano":2022,"temas_relacionados":["linux_geral"]},{"id":2233644,"enunciado":"Qual das seguintes opções descreve corretamente o comando chmod no Linux?","opcoes":["É usado para alterar as permissões de um arquivo ou diretório.","É usado para alterar a propriedade modal de um arquivo ou diretório.","É usado para alterar o modo de arquivos.","É usado para alterar o modo do diretório.","É usado para alterar a propriedade de grupo de um arquivo ou diretório."],"correta":0,"explicacao":"Gabarito: <strong>É usado para alterar as permissões de um arquivo ou diretório.</strong>.","banca":"FURB","ano":2023,"temas_relacionados":["linux_geral"]},{"id":2233650,"enunciado":"Considere as seguinte afirmações sobre o Sistema Operacional Linux: I.O Linux é um sistema operacional do tipo Unix, herdando do mesmo alguns de seus princípios. II.No Linux, tanto os comandos 'sudo' quanto 'su' podem ser usados para obter privilégios de superusuário, mas 'su' requer a senha de root, enquanto 'sudo' requer a senha do usuário. III.O kernel do Linux foi desenvolvido por Linus Torvalds, tendo seu desenvolvimento iniciado no final da década de 1990. IV.No Linux, o comando 'ls' com a opção '-l' exibe informações de arquivo ou diretório, incluindo tamanho, data e hora de modificação, nome do arquivo ou diretório e proprietário, em uma visualização de lista, e a opção '-a' lista todos os arquivos, incluindo os ocultos. É correto o que se afirma em:","opcoes":["I, II e IV, apenas.","I e III, apenas.","II e IV, apenas.","I, II, III e IV.","III, apenas."],"correta":0,"explicacao":"Gabarito: <strong>I, II e IV, apenas.</strong>.","banca":"FURB","ano":2023,"temas_relacionados":["linux_geral"]},{"id":2236186,"enunciado":"No sistema operacional Linux, o comando “chmod” modifica as permissões de um arquivo ou diretório baseado em algumas opções, como a letra “r”, por exemplo, que significa:","opcoes":["escrita.","leitura.","execução.","todos os usuários.","grupo."],"correta":1,"explicacao":"Gabarito: <strong>leitura.</strong>.","banca":"IBADE","ano":2023,"temas_relacionados":["linux_geral"]},{"id":2236187,"enunciado":"Das opções abaixo, qual corresponde ao comando do sistema Linux responsável por criar um diretório?","opcoes":["Ls","Mv","Sort","Tail","Mkdir"],"correta":4,"explicacao":"Gabarito: <strong>Mkdir</strong>.","banca":"IBADE","ano":2023,"temas_relacionados":["linux_geral"]},{"id":2253046,"enunciado":"Com relação às permissões em Linux utilizando o método octal do comando chmod, os números 1, 3 e 6 significam, respectivamente, permissão para:","opcoes":["Gravar / Ler / Ler e executar","Gravar / Gravar e executar / Ler e gravar","Executar / Gravar / Ler e gravar","Executar / Gravar e executar / Ler e gravar","Executar / Ler e gravar / Ler, gravar e executar"],"correta":3,"explicacao":"Gabarito: <strong>Executar / Gravar e executar / Ler e gravar</strong>.","banca":"FCC","ano":2007,"temas_relacionados":["linux_geral"]},{"id":2253047,"enunciado":"Com relação ao sistema de arquivos ext do Linux, considere os itens abaixo: I. O ext2 é o sistema que oferece o pior desempenho entre todos os sistemas de arquivos suportados pelo Linux. II. A principal diferença entre o sistema ext2 e ext3 é que o primeiro suporta journaling, enquanto o segundo não. III. O ext3 oferece o crescimento online do sistema de arquivos. É correto o que se afirma em","opcoes":["III, apenas.","II, apenas.","I, II e III.","I e II, apenas.","I e III, apenas."],"correta":0,"explicacao":"Gabarito: <strong>III, apenas.</strong>.","banca":"FCC","ano":2007,"temas_relacionados":["linux_geral"]},{"id":2275467,"enunciado":"No sistema operacional Ubuntu é possível criar várias contas em um mesmo computador, permitindo que duas ou mais pessoas que trabalham em turnos diferentes possam compartilhar o mesmo computador. Considere as afirmativas sobre a criação e uso de contas no sistema operacional Ubuntu. I. Durante uma sessão, é possível trocar de usuário sem encerrar a sessão atual e depois alternar o uso entre esses dois usuários. II. Para compartilhar uma pasta entre dois usuários é necessário que pelo menos um deles seja usuário administrador. III. É possível criar uma conta sem senha para que um visitante possa usar o computador, sem ter acesso aos arquivos dos demais usuários. Está CORRETO o que se afirma em:","opcoes":["I e II, apenas.","I e III, apenas.","II e III, apenas.","I, II e III."],"correta":1,"explicacao":"Gabarito: <strong>I e III, apenas.</strong>.","banca":"UFV","ano":2023,"temas_relacionados":["linux_geral"]},{"id":2275469,"enunciado":"O gerenciador (ou navegador) de arquivos Nautilus, no sistema operacional Ubuntu, é a ferramenta que permite visualizar e realizar as principais operações com arquivos e pastas em um computador conectado à uma rede local. Considerando o gerenciador de arquivos Nautilus, assinale a afirmativa INCORRETA:","opcoes":["A opção “Mover para a Lixeira” apaga o arquivo da pasta atual, mas permite a sua recuperação caso a lixeira não esteja cheia.","A partir da opção “Propriedades” aplicada em uma pasta, é possível compartilhar essa pasta com outros usuários em uma rede local.","A opção de “Renomear” pode ser utilizada para tornar uma pasta invisível, no modo padrão de visualização do navegador de arquivos.","Ao criar uma nova pasta (diretório) dentro de uma pasta de nome Documentos, o novo nome não pode ser igual ao da pasta mãe (Documentos)."],"correta":3,"explicacao":"Gabarito: <strong>Ao criar uma nova pasta (diretório) dentro de uma pasta de nome Documentos, o novo nome não pode ser igual ao da pasta mãe (Documentos).</strong>.","banca":"UFV","ano":2023,"temas_relacionados":["linux_geral"]},{"id":2275470,"enunciado":"Os primeiros sistemas operacionais tinham apenas interface de texto, em vez das interfaces gráficas atuais. A despeito disso, os sistemas operacionais mantêm um aplicativo chamado genericamente de Terminal nos sistemas Linux, que emulam a interface de texto antiga, na qual os comandos precisam ser digitados. A principal razão disso é que algumas tarefas podem ser mais facilmente realizadas pelo terminal. Considere as afirmativas relacionadas ao uso do aplicativo Terminal no Ubuntu, por um usuário administrador (superusuário): I. É possível executar um comando restrito aos administradores digitando no terminal o comando, precedido de “sudo” e seguido da tecla Enter, depois fornecendo a senha de administrador. II. De posse da senha do usuário carlos é possível assumir a identidade de carlos digitando no terminal o comando su carlos e depois a senha do usuário carlos, para acessar todas as pastas de carlos. III. É possível disparar uma instância do gerenciador (navegador) de arquivos como superusuário para ter acesso a todas as pastas do sistema operacional. Está CORRETO o que se afirma em:","opcoes":["I, II e III.","I e II, apenas.","I e III, apenas.","II e III, apenas."],"correta":0,"explicacao":"Gabarito: <strong>I, II e III.</strong>.","banca":"UFV","ano":2023,"temas_relacionados":["linux_geral"]},{"id":2275471,"enunciado":"Dentre as facilidades de operações com arquivos, o sistema operacional Ubuntu possui uma ferramenta para permitir realizar uma cópia de segurança (backup) e posterior restauração do conteúdo do disco rígido, em caso de eventuais defeitos no computador. Considere as afirmativas a seguir relacionadas à ferramenta de backup do Ubuntu, atribuindo V para a(s) verdadeira(s) e F para a(s) falsa(s). ( ) A ferramenta de backup, por padrão, não oferece a possibilidade de efetuar a cópia de segurança dos programas instalados. ( ) A ferramenta backup deve ser usada para restaurar uma pasta de um usuário, com o computador desconectado da rede local. ( ) Na restauração dos dados do backup, é possível selecionar uma pasta específica dentre as que foram copiadas, com os dados restaurados, necessariamente, para a mesma pasta original. ( ) O destino preferencial de uma cópia de segurança deve ser o próprio disco rígido, em uma partição diferente daquela onde estão os dados copiados. Assinale a sequência CORRETA:","opcoes":["F, V, V, F.","F, F, V, V.","V, V, F, V.","V, F, F, F."],"correta":3,"explicacao":"Gabarito: <strong>V, F, F, F.</strong>.","banca":"UFV","ano":2023,"temas_relacionados":["linux_geral"]},{"id":2275472,"enunciado":"Considere uma instalação padrão do sistema operacional Ubuntu, em um computador de mesa (desktop) conectado a uma rede local e à Internet. Em relação à instalação de programas nesse computador, assinale a afirmativa INCORRETA:","opcoes":["A instalação de um programa no Ubuntu deve ser executada fornecendo a senha de administrador do sistema.","A Central de Programas do Ubuntu funciona de maneira similar aos aplicativos para celulares (ex: Google Play e App Store).","O acesso à Internet deve estar disponível para que a instalação de um programa no Ubuntu possa ser realizada com sucesso.","O Ubuntu permite que o administrador do sistema configure a frequência de busca e instalação automática de atualizações de segurança do sistema operacional."],"correta":2,"explicacao":"Gabarito: <strong>O acesso à Internet deve estar disponível para que a instalação de um programa no Ubuntu possa ser realizada com sucesso.</strong>.","banca":"UFV","ano":2023,"temas_relacionados":["linux_geral"]},{"id":2306288,"enunciado":"Quais são as principais diferenças entre o sistema de gerenciamento de pacotes no Linux e a instalação de software no Windows?","opcoes":["No Linux, os programas são instalados manualmente, assim como no Windows.","No Linux, os programas são sempre baixados da loja de aplicativos oficial e, no Windows, os programas são instalados apenas por meio de CD ou DVD.","No Linux, todos os programas são instalados no diretório \"C:\\Program Files\", assim como no Windows.","No Linux, os pacotes são instalados e gerenciados centralmente pelo sistema de gerenciamento de pacotes e, no Windows, os programas são frequentemente instalados manualmente usando instaladores.","No Linux, os programas são instalados manualmente e, no Windows, os programas são instalados centralmente pelo sistema de gerenciamento de pacotes."],"correta":3,"explicacao":"Gabarito: <strong>No Linux, os pacotes são instalados e gerenciados centralmente pelo sistema de gerenciamento de pacotes e, no Windows, os programas são frequentemente instalados manualmente usando instaladores.</strong>.","banca":"COTEC","ano":2023,"temas_relacionados":["linux_geral"]},{"id":2306297,"enunciado":"O que é “distro” (distribuição), no contexto do sistema operacional Linux?","opcoes":["Programa que emula o sistema operacional Windows no Linux.","Versão específica do sistema operacional Linux.","Atualização importante do kernel do Linux.","Dispositivo de hardware usado para conectar periféricos ao computador.","Área de armazenamento de dados no disco rígido do computador."],"correta":1,"explicacao":"Gabarito: <strong>Versão específica do sistema operacional Linux.</strong>.","banca":"COTEC","ano":2023,"temas_relacionados":["linux_geral"]},{"id":2339187,"enunciado":"Ao utilizar o terminal de comando do Linux, um usuário deseja listar todos os arquivos e pastas dentro de um diretório. O comando que permite essa ação é:","opcoes":["find","cat","cd","rm","ls"],"correta":4,"explicacao":"Gabarito: <strong>ls</strong>.","banca":"IVIN","ano":2023,"temas_relacionados":["linux_geral"]},{"id":2339188,"enunciado":"É um comando gerenciador de pacotes. Ele pode utilizar arquivos locais ou remotos para realizar instalação ou atualização de pacotes. É uma ferramenta de linha de comando utilizada em sistemas operacionais Linux para gerenciamento de pacotes:","opcoes":["pack","apt-get","manager","install","mkdir"],"correta":1,"explicacao":"Gabarito: <strong>apt-get</strong>.","banca":"IVIN","ano":2023,"temas_relacionados":["linux_geral"]},{"id":2348218,"enunciado":"Quanto ao sistema operacional Linux e aos meios de transmissão utilizados em redes de computadores, julgue o item. \n\nNo Linux, o comando netstat é utilizado para exibir estatísticas de conexões de rede, portas abertas e tabelas de roteamento.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":2348219,"enunciado":"Quanto ao sistema operacional Linux e aos meios de transmissão utilizados em redes de computadores, julgue o item. \n\nAo executar o comando touch crea_go.txt no ambiente Linux, o timestamp do arquivo crea_go.txt será atualizado, caso esse arquivo exista.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":2348220,"enunciado":"Quanto ao sistema operacional Linux e aos meios de transmissão utilizados em redes de computadores, julgue o item. \n\nPara renomear o arquivo fungos para cultura_de_solo, via console do Linux, é suficiente executar o comando grep fungos cultura_de_solo.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":2393987,"enunciado":"Julgue o item a seguir, que trata de Linux e Windows 10. \n\n\n\n\nA interface gráfica KDE do Linux tem aparência semelhante à interface gráfica do Windows.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2024,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":2437464,"enunciado":"No prompt de comando do sistema operacional Linux, para criar um arquivo vazio pode-se utilizar o comando:","opcoes":["grep","ls","echo","file","touch"],"correta":4,"explicacao":"Gabarito: <strong>touch</strong>.","banca":"FUNDATEC","ano":2023,"temas_relacionados":["linux_geral"]},{"id":2437467,"enunciado":"Assinale a alternativa que apresenta sistemas de firewall que podem ser utilizados, respectivamente, em sistemas operacionais Microsoft Windows 10 e Linux.","opcoes":["Microsoft Defender Antivírus e nftables.","Microsoft Security Essentials e hosts.","Microsoft Defender Firewall e iptables.","Microsoft Network Monitor e Network Manager.","Microsoft Safety Scanner e policy."],"correta":2,"explicacao":"Gabarito: <strong>Microsoft Defender Firewall e iptables.</strong>.","banca":"FUNDATEC","ano":2023,"temas_relacionados":["linux_geral"]},{"id":2451018,"enunciado":"Um usuário de um computador, com sistema operacional Linux, precisa verificar a quantidade de memória do computador (em uso e disponível) via linha de comando. O comando adequado para essa situação é o:","opcoes":["cat","who","free","type"],"correta":2,"explicacao":"Gabarito: <strong>free</strong>.","banca":"SELECON","ano":2024,"temas_relacionados":["linux_geral"]},{"id":2451019,"enunciado":"Um usuário de um computador com Linux, em uma rede de computadores, usou o comando de listar, com opção de lista longa, para verificar as permissões do arquivo1.txt, do qual é o dono. Essa consulta apareceu na seguinte forma: -rw-rwxr-x usuario usuario 2048 Fev 05 18:45 arquivo1.txt Considerando essas informações, pode-se deduzir que o grupo ao qual o usuário pertence tem permissão no arquivo1.txt para somente:","opcoes":["ler","escrever","ler e executar","ler, escrever ou executar"],"correta":3,"explicacao":"Gabarito: <strong>ler, escrever ou executar</strong>.","banca":"SELECON","ano":2024,"temas_relacionados":["linux_geral"]},{"id":2472156,"enunciado":"Um usuário de computador obteve o reprodutor de vídeo VLC Media Player que é um software de código aberto, funcionando para quase todos os sistemas operacionais, incluindo Windows, MacOS X, Linux, Android e iOS. Uma grande vantagem desse reprodutor de vídeo é que ele:","opcoes":["consegue juntar som e imagem, consertando as sincronias","é um software de fácil uso e também é gratuito","sempre é inserido no início do sistema operacional","é atualizado constantemente, com versões mais úteis","não edita vídeos, mas usa outros softwares mais sofisticados"],"correta":1,"explicacao":"Gabarito: <strong>é um software de fácil uso e também é gratuito</strong>.","banca":"SELECON","ano":2024,"temas_relacionados":["linux_geral"]},{"id":2472160,"enunciado":"Um usuário de um computador com Linux obteve um software que pode ser executado, copiado, distribuído e modificado pelo usuário sem restrições. Esse tipo de software é conhecido como:","opcoes":["spyware","malware","commonware","software livre","software proprietário"],"correta":3,"explicacao":"Gabarito: <strong>software livre</strong>.","banca":"SELECON","ano":2024,"temas_relacionados":["linux_geral"]},{"id":2472161,"enunciado":"Um usuário de um computador com sistema operacional Linux deseja usar um comando básico, via linha de comando, de modo que ele possa se posicionar em uma determinada pasta. O comando básico para executar essa ação é o:","opcoes":["rm","ls","df","cp","cd"],"correta":4,"explicacao":"Gabarito: <strong>cd</strong>.","banca":"SELECON","ano":2024,"temas_relacionados":["linux_geral"]},{"id":2525052,"enunciado":"Julgue o item a seguir. \nO Windows, devido à sua arquitetura fechada e ao constante investimento em pesquisa de segurança, supera o Linux em termos de robustez e resistência a ataques cibernéticos. Esse fato se justifica porque a Microsoft tem implementado medidas significativas de segurança ao longo de todos os anos.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"IGEDUC","ano":2024,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":2525059,"enunciado":"Julgue o item a seguir. \nEmbora tanto o Windows quanto o Linux tenham avançado consideravelmente em integração com serviços de nuvem, é no ecossistema Linux que a adaptação é mais fluida e abrangente. Isso se deve à natureza altamente modular e personalizável do Linux, que permite aos usuários ajustar o sistema operacional para atender especificamente aos requisitos de suas cargas de trabalho na nuvem.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"IGEDUC","ano":2024,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":2526547,"enunciado":"Julgue o item subsequente.\n\n\n\n\nO Linux é um sistema operacional de código aberto e gratuito. Ele é amplamente utilizado em servidores web, sistemas embarcados e dispositivos móveis devido à sua flexibilidade e segurança.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"IGEDUC","ano":2024,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":2526558,"enunciado":"Julgue o item subsequente.\n\n\n\n\nO Windows é mais seguro que o Linux contra ataques de vírus e malware devido ao seu amplo suporte de hardware e facilidade de uso.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"IGEDUC","ano":2024,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":2536148,"enunciado":"Julgue o item a seguir.\n\n\n\n\nUma das principais distinções entre o Windows e o Linux é a maneira como são licenciados. O Windows é um sistema operacional proprietário, o que implica que a Microsoft detém os direitos autorais do software e cobra uma taxa para seu uso.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"IGEDUC","ano":2024,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":2536154,"enunciado":"Julgue o item a seguir.\n\n\n\n\nO Linux diferencia entre caracteres maiúsculos e minúsculos, ou seja, ele é case sensitive. Além disso, a extensão dos arquivos é opcional e definida pelo usuário, já que no Linux a extensão não determina o tipo de arquivo. O sistema de arquivos do Linux, como sua desvantagem, é que não permite restringir o acesso a arquivos e diretórios.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"IGEDUC","ano":2024,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":2568620,"enunciado":"No que se refere a função principal de um sistema operacional como o Windows ou o Linux em um computador, assinale a alternativa correta.","opcoes":["Editar vídeos.","Executar programas e gerenciar hardware.","Navegar na internet.","Editar imagens.","Planilhas de cálculos."],"correta":1,"explicacao":"Gabarito: <strong>Executar programas e gerenciar hardware.</strong>.","banca":"Instituto Access","ano":2024,"temas_relacionados":["linux_geral"]},{"id":2568630,"enunciado":"A administração de sistemas operacionais envolve a gestão de processos, serviços e segurança. No ambiente Linux, a compreensão detalhada dos arquivos de configuração e comandos avançados é crucial para garantir a estabilidade e segurança do sistema. No que tange ao Linux, o arquivo /etc/fstab é utilizado para:","opcoes":["Definir os pontos de montagem de sistemas de arquivos.","Especificar as variáveis de ambiente para o shell.","Configurar o firewall e regras de segurança.","Gerenciar a inicialização de serviços de impressão no sistema.","Gerenciar o sistema multimídia."],"correta":0,"explicacao":"Gabarito: <strong>Definir os pontos de montagem de sistemas de arquivos.</strong>.","banca":"Instituto Access","ano":2024,"temas_relacionados":["linux_geral"]},{"id":2666930,"enunciado":"Assinale a alternativa cujas distribuições Linux são todas baseadas na distribuição Debian.","opcoes":["SUSE • CentOS • PureOS","Knoppix • Tails • Ubuntu","ChromeOS • Fedora • Slax","Pentoo • Mandriva • Manjaro","Linux Mint • Mandriva • RHEL"],"correta":1,"explicacao":"Gabarito: <strong>Knoppix • Tails • Ubuntu</strong>.","banca":"FEPESE","ano":2021,"temas_relacionados":["linux_geral"]},{"id":2666931,"enunciado":"Qual distribuição Linux é mais voltada à segurança, cujo foco está voltado à privacidade e segurança, na qual todas as conexões passam pelo tor (The Onion Router)?","opcoes":["Arch","Mandriva","Slackware","Knoppix","Tails"],"correta":4,"explicacao":"Gabarito: <strong>Tails</strong>.","banca":"FEPESE","ano":2021,"temas_relacionados":["linux_geral"]},{"id":2689412,"enunciado":"Sobre o sistema operacional Linux, analise as afirmações abaixo: I. O Linux não pode ser considerado um sistema operacional propriamente dito. II. Seu programa de instalação fará uma mudança nas partições do disco rígido, podendo manter uma parte com FAT32 e uma parte para o Linux. III. O Linux foi modernizado e adaptado para PCs. IV. O Linux é Case Sensitive, diferencia caracteres maiúsculos de caracteres minúsculos para nomeação de pastas e arquivos. Está CORRETO o que se afirma em:","opcoes":["I e II","I e III","I e IV","II, III e IV"],"correta":3,"explicacao":"Gabarito: <strong>II, III e IV</strong>.","banca":"IMA","ano":2019,"temas_relacionados":["linux_geral"]},{"id":2689414,"enunciado":"O sistema operacional Linux, tem as seguintes características, EXCETO:","opcoes":["Multiusuário.","Suporte a nomes extensos de arquivos e pastas.","Utiliza permissões de acesso a arquivos, pastas e programas em execução na memória RAM.","Gratuito e monofásico."],"correta":3,"explicacao":"Gabarito: <strong>Gratuito e monofásico.</strong>.","banca":"IMA","ano":2019,"temas_relacionados":["linux_geral"]},{"id":2698577,"enunciado":"O \"Logical Volume Management (LVM)\" é um gerenciador de disco que trabalha em alto nível, fornecendo uma nova visão na forma de trabalhar com partições no sistema Linux. Nesse contexto, observe a figura que se refere à estrutura do LVM. • ALFA representa as partições por meio da qual é montado o sistema de arquivos no Linux, sendo a única camada realmente acessível para o usuário. • BETA representa o agrupamento de vários componentes ALFA e esse pode ter vários, porém, se um BETA estiver sem espaço e o outro BETA tiver espaço de sobra, o espaço livre de um BETA pode ser utilizado para aumentara outro. Em instalações normais, é necessária a criação de apenas um BETA. • GAMA representa um componente que serve para criar o UUID, um identificador único. Os componentes ALFA, BETA e GAMA são conhecidos, respectivamente, como:","opcoes":["PV - Physical Volume, VG - Volume Group e LV - Logical Volume","LV - Logical Volume, PV - Physical Volume e VG - Volume Group","LV - Logical Volume, VG - Volume Group e PV - Physical Volume","PV- Physical Volume, LV - Logical Volume e VG - Volume Group"],"correta":2,"explicacao":"Gabarito: <strong>LV - Logical Volume, VG - Volume Group e PV - Physical Volume</strong>.","banca":"SELECON","ano":2019,"temas_relacionados":["linux_geral"]},{"id":2698579,"enunciado":"No que diz respeito à estrutura operacional do Linux, um diretório armazena os arquivos de inicialização, do baot-loader, do Grub e do kemel do Linux, enquanto outro armazena os arquivos de configuração (scripts). Esses diretórios são conhecidos, respectivamente, por","opcoes":["/boot e /cfg","/boot e /etc","/root e /cfg","/root e /etc"],"correta":1,"explicacao":"Gabarito: <strong>/boot e /etc</strong>.","banca":"SELECON","ano":2019,"temas_relacionados":["linux_geral"]},{"id":2702519,"enunciado":"Existem várias formas de gerenciar pacotes no GNU/Linux, sendo que a melhor opção é utilizar gerenciadores específicos. O APT (Advanced Package Tool) é uma ferramenta desenvolvida originalmente para Debian. Essa ferramenta gerencia pacotes .deb. Considerando a utilização da ferramenta APT assinale a opção referente a execução do comando: # apt-get source pacote","opcoes":["Realiza uma busca aos pacotes adicionais necessários não existentes.","Faz download do código fonte relativo a um pacote. Com isso será possível recompilar um pacote com outras ações.","Atualiza o sistema, instalando os pacotes adicionais necessários não existentes.","Apaga arquivos baixados por comandos APT para fins de instalação. É uma boa opção para gerar espaço no HD."],"correta":1,"explicacao":"Gabarito: <strong>Faz download do código fonte relativo a um pacote. Com isso será possível recompilar um pacote com outras ações.</strong>.","banca":"FAEPESUL","ano":2019,"temas_relacionados":["linux_geral"]},{"id":2702527,"enunciado":"O Ubuntu é uma distribuição do Linux baseado na versão do Debian, código aberto, gratuito. Depois de instalado no computador essa versão precisa ser configurada. Para a correta configuração é necessário compreender os principais diretórios do Ubuntu. Um dos principais diretórios é o /dev. O que o diretório /dev armazena:","opcoes":["Montagem dos diretórios compartilhados.","Biblioteca básica do sistema.","Arquivos de acesso aos dispositivos físicos e conexões de rede.","Arquivos de configuração."],"correta":2,"explicacao":"Gabarito: <strong>Arquivos de acesso aos dispositivos físicos e conexões de rede.</strong>.","banca":"FAEPESUL","ano":2019,"temas_relacionados":["linux_geral"]},{"id":2702604,"enunciado":"No que se refere às camadas componentes do sistema operacional Linux, analise os itens a seguir e, ao final, assinale a alternativa correta: I – Há uma camada mais extensa denominada “shell”, capaz de oferecer interação entre o usuário e o sistema operacional. II – A camada mais central do sistema também é conhecida como “gunner”. III – As várias camadas que compõem o Linux estão integradas por um dispositivo denominado “streaming”.","opcoes":["Apenas o item I é verdadeiro.","Apenas o item II é verdadeiro.","Apenas o item III é verdadeiro.","Apenas os itens I e II são verdadeiros.","Apenas os itens II e III são verdadeiros."],"correta":0,"explicacao":"Gabarito: <strong>Apenas o item I é verdadeiro.</strong>.","banca":"MetroCapital Soluções","ano":2019,"temas_relacionados":["linux_geral"]},{"id":2702609,"enunciado":"No que se refere ao sistema operacional Linux e a Internet, analise os itens a seguir e, ao final, assinale a alternativa correta: I – O protocolo ssh permite a conexão com outro computador que suporte tal recurso. II – O protocolo “shiva” é compatível com o Linux. III – O comando ping é utilizado para gerenciar as regras do firewall do sistema.","opcoes":["Apenas o item I é verdadeiro.","Apenas o item II é verdadeiro.","Apenas o item III é verdadeiro.","Apenas os itens I e II são verdadeiros.","Apenas os itens II e III são verdadeiros."],"correta":0,"explicacao":"Gabarito: <strong>Apenas o item I é verdadeiro.</strong>.","banca":"MetroCapital Soluções","ano":2019,"temas_relacionados":["linux_geral"]},{"id":2708506,"enunciado":"Para que serve o comando “cat” no sistema operacional Linux?","opcoes":["Mostrar o uso da memória.","Logar de forma segura em outro sistema.","Permitir ou negar mensagens de terminal e pedidos de conversação (talk requests).","Abrir um arquivo.","Abrir o explorador de informações."],"correta":3,"explicacao":"Gabarito: <strong>Abrir um arquivo.</strong>.","banca":"FUNDATEC","ano":2019,"temas_relacionados":["linux_geral"]},{"id":2708540,"enunciado":"Qual das alternativas abaixo corresponde a um diretório do sistema operacional Linux?","opcoes":["/boot/","/bbw/","/bbz/","/xxy/","/xxj/"],"correta":0,"explicacao":"Gabarito: <strong>/boot/</strong>.","banca":"FUNDATEC","ano":2019,"temas_relacionados":["linux_geral"]},{"id":2718437,"enunciado":"No LINUX, qual a função do comando pwd?","opcoes":["Mostrar o caminho completo para o diretório atual.","Mudar o diretório atual.","Desligar o computador.","Entrar na Interface gráfica do Linux.","Copiar um arquivo."],"correta":0,"explicacao":"Gabarito: <strong>Mostrar o caminho completo para o diretório atual.</strong>.","banca":"Ethos Concursos","ano":2016,"temas_relacionados":["linux_geral"]},{"id":2718441,"enunciado":"Qual diretório do Linux é responsável por todas as configurações do sistema operacional?","opcoes":["/root","/etc","/var","/home","/lib"],"correta":1,"explicacao":"Gabarito: <strong>/etc</strong>.","banca":"Ethos Concursos","ano":2016,"temas_relacionados":["linux_geral"]},{"id":2723243,"enunciado":"Os Sistemas de Arquivos são o conjunto de estruturas lógicas e de rotinas, que permitem ao sistema operacional controlar o acesso às mídias de armazenamento, como, por exemplo, o disco rígido. Diferentes sistemas operacionais usam diferentes sistemas de arquivos. Marque a opção que corresponde ao sistema de arquivo nativo do Linux.","opcoes":["EXT2","EXT16","FAT16","FAT32","NTFS"],"correta":0,"explicacao":"Gabarito: <strong>EXT2</strong>.","banca":"COPESE - UFPI","ano":2013,"temas_relacionados":["linux_geral"]},{"id":2723244,"enunciado":"Leia as afirmativas a seguir sobre os sistemas operacionais Windows e Linux: I. O Linux possui um botão chamado iniciar que possibilita acessar todos os programas instalados no computador; II. O Windows é um sistema operacional livre e seu código fonte está disponível para que qualquer pessoa possa utilizá-lo, estudá-lo, modificá-lo e distribuí-lo livremente; III. O Linux possui diversas interfaces gráficas, sendo as mais conhecidas KDE e GNOME. Assinale a opção que corresponde à(s) afirmativa(s) CORRETA(S).","opcoes":["Apenas I.","Apenas II.","Apenas III.","Apenas I e II.","Apenas II e III."],"correta":2,"explicacao":"Gabarito: <strong>Apenas III.</strong>.","banca":"COPESE - UFPI","ano":2013,"temas_relacionados":["linux_geral"]},{"id":2727573,"enunciado":"Nmap é uma ferramenta para exploração de rede. Caso um técnico em redes pretenda instalar a ferramenta em um sistema operacional Ubuntu, poderá usar qual dos comandos a seguir?","opcoes":["sudo get nmap","sudo apt-get soft nmap","sudo get-down install nmap","sudo install-get nmap","sudo apt-get install nmap"],"correta":4,"explicacao":"Gabarito: <strong>sudo apt-get install nmap</strong>.","banca":"INSTITUTO AOCP","ano":2016,"temas_relacionados":["linux_geral"]},{"id":2727595,"enunciado":"Em um sistema operacional Linux, o comando printenv pode ser utilizado para","opcoes":["criar diretrizes e permissões para diretórios.","limpar uma fila de impressão.","exibir informações de requisições de impressões pendentes.","exibir informações sobre as variáveis de ambiente.","exibir as portas de comunicação que estão sendo utilizadas no sistema operacional."],"correta":3,"explicacao":"Gabarito: <strong>exibir informações sobre as variáveis de ambiente.</strong>.","banca":"INSTITUTO AOCP","ano":2016,"temas_relacionados":["linux_geral"]},{"id":2740344,"enunciado":"Os sistemas de arquivos estruturam a informação guardada em uma unidade de armazenamento. A maioria dos sistemas operacionais possui seu próprio sistema de arquivos – podendo alguns inclusive utilizar-se de um ou mais. Apenas um dos itens abaixo não representa um sistema de arquivos. Qual?","opcoes":["FAT32.","NTFS.","EXT2.","SCSI."],"correta":3,"explicacao":"Gabarito: <strong>SCSI.</strong>.","banca":"CRF-TO","ano":2015,"temas_relacionados":["linux_geral"]},{"id":2740350,"enunciado":"Assinale a execução correta dos comandos de terminal do Linux abaixo. ls mkdir","opcoes":["Acessa uma pasta e lista o conteúdo de uma pasta.","Lista o conteúdo de uma pasta e cria uma pasta.","Limpa a tela do terminal e cria uma pasta.","Cria uma pasta e lista o conteúdo de uma pasta."],"correta":1,"explicacao":"Gabarito: <strong>Lista o conteúdo de uma pasta e cria uma pasta.</strong>.","banca":"CRF-TO","ano":2015,"temas_relacionados":["linux_geral"]},{"id":2744131,"enunciado":"Os arquivos de configuração do sistema operacional Linux são armazenados no diretório","opcoes":["/bin.","/etc.","/mnt.","/lib.","/sys."],"correta":1,"explicacao":"Gabarito: <strong>/etc.</strong>.","banca":"FUNRIO","ano":2014,"temas_relacionados":["linux_geral"]},{"id":2744146,"enunciado":"As distribuições de Linux disponibilizam comandos do terminal que facilitam a instalação, atualização e remoção de softwares. Um comando deste tipo da distribuição do Debian é o","opcoes":["apt-get.","checkinstall.","dselect.","make.","rpm."],"correta":0,"explicacao":"Gabarito: <strong>apt-get.</strong>.","banca":"FUNRIO","ano":2014,"temas_relacionados":["linux_geral"]},{"id":2744668,"enunciado":"Sobre os comandos Linux, associe a segunda coluna com a primeira. I) cd II) rm III) cp IV) cat V) gzip ( ) remove arquivos ( ) copia um ou mais arquivos ( ) muda o diretório de trabalho ( ) concatena e exibe arquivos ( ) compacta um ou mais arquivos Assinale a alternativa que contém a sequência CORRETA de associação, de cima para baixo.","opcoes":["II, III, I, IV, V","II, I, III, V, IV","I, II, III, IV, V","V, IV, I, III, II","III, II, IV, I, V"],"correta":0,"explicacao":"Gabarito: <strong>II, III, I, IV, V</strong>.","banca":"IFB","ano":2016,"temas_relacionados":["linux_geral"]},{"id":2744690,"enunciado":"A árvore de diretórios de Linux segue o Filesystem Hierarchy System (FHS), que é um subpadrão do Linux Standard Base. Com relação a essa estrutura, associe a segunda coluna com a primeira. I) /proc II) /dev III) /etc IV) /boot V) /home ( ) Arquivos de configuração do sistema. ( ) Arquivos de dispositivos de hardware. ( ) Diretórios dos usuários. ( ) kernel do sistema. ( ) Sistema de arquivo virtual de informações do kernel e processos. Assinale a alternativa que contém a sequência CORRETA de associação, de cima para baixo.","opcoes":["III, II, V, IV, I","III, II, IV, V, I","I, III, IV, II, V","II, I, III, V, IV","I, V, IV, II, III"],"correta":0,"explicacao":"Gabarito: <strong>III, II, V, IV, I</strong>.","banca":"IFB","ano":2016,"temas_relacionados":["linux_geral"]},{"id":2754392,"enunciado":"O chmod é um comando do Linux/Unix usado para alterar permissões de arquivos e diretórios. Qual comando dá as seguintes permissões: Usuário: leitura, escrita, execução Grupo: leitura Outros: leitura, escrita Marque a opção que contenha a resposta CORRETA","opcoes":["chmod 746 arquivo","chmod 645 arquivo","chmod 655 arquivo","chmod 654 arquivo","chmod 646 arquivo"],"correta":0,"explicacao":"Gabarito: <strong>chmod 746 arquivo</strong>.","banca":"IF-SC","ano":2017,"temas_relacionados":["linux_geral"]},{"id":2754396,"enunciado":"Um conceito importante na inicialização do sistema operacional Linux é o runlevel (nível de execução). O sistema Linux possui, em suas distribuições, vários níveis de execução. Cada um definindo diferentes comportamentos do sistema em relação a que programas (deamons) são carregados e que ações são tomadas. Com relação aos níveis de execução e seus comportamentos, avalie as afirmações adiante e marque com V as verdadeiras e com F as falsas. ( ) runlevel 0 — modo onde o sistema Linux é reinciado. ( ) runlevel 3 — modo multiusuário completo. É o modo mais comum. ( ) runlevel S — modo monousuário, utilizado na inicialização ou para manutenção (funcionalidade pode variar conforme a distribuição linux). ( ) runlevel 6 — Modo onde o sistema é desligado (shutdown) ( ) runlevel 4 — Modo multiusário em modo texto. Comumente usado em ambientes Desktops. Marque a opção que contenha a sequência CORRETA, de cima para baixo:","opcoes":["F, V, V, F, F","F, V, F, F, V","V, V, V, F, F","V, F, V, F, F","F, V, V, F, V"],"correta":0,"explicacao":"Gabarito: <strong>F, V, V, F, F</strong>.","banca":"IF-SC","ano":2017,"temas_relacionados":["linux_geral"]},{"id":2754407,"enunciado":"Complete abaixo as lacunas com os respectivos comandos no sistema Linux: O comando _________ exibe os processos que estão sendo executados. O comando _________ permite usuários comuns de obter privilégios do super usuário. O comando _________ permite alterar o dono (owner) de arquivos ou diretórios. O comando _________ permite alterar as permissões de arquivos ou diretórios Assinale a alternativa que CORRETAMENTE preenche a lacuna dos textos acima na ordem em que eles foram apresentados.","opcoes":["top, sudo, chmod, chown","top, sudo, chown, chmod","sudo, pwd, nano, vi","top, pwd, change user, mkdir","sudo, top, mkdir, chmod"],"correta":1,"explicacao":"Gabarito: <strong>top, sudo, chown, chmod</strong>.","banca":"IF-SC","ano":2017,"temas_relacionados":["linux_geral"]},{"id":2760222,"enunciado":"No Linux, são sistemas de arquivo e gerenciador de boot respectivamente:","opcoes":["XFS e KDE.","Ext3 e GNOME.","ReiserFS e GRUB.","Shell e LILO.","XFCE e Swap."],"correta":2,"explicacao":"Gabarito: <strong>ReiserFS e GRUB.</strong>.","banca":"FUNRIO","ano":2017,"temas_relacionados":["linux_geral"]},{"id":2760223,"enunciado":"No Linux Redhat, o seguinte comando é utilizado para desinstalação manual de pacotes:","opcoes":["# dpkg -r","# rpm -e","# removepkg -keep","# rpm -i","# dpkg -i"],"correta":1,"explicacao":"Gabarito: <strong># rpm -e</strong>.","banca":"FUNRIO","ano":2017,"temas_relacionados":["linux_geral"]},{"id":2768028,"enunciado":"Considere o exemplo de regra de firewall Linux . “ iptables -t nat -A PREROUTING -i eth0 -p tcp --dport 80 -j DNAT --to 172.30.0.25:80“ Qual o protocolo de aplicação referente a regra acima?","opcoes":["HTTP.","FTP.","SSH.","Nenhuma das alternativas."],"correta":0,"explicacao":"Gabarito: <strong>HTTP.</strong>.","banca":"Instituto Excelência","ano":2018,"temas_relacionados":["linux_geral"]},{"id":2768038,"enunciado":"Considerando os sistemas operacionais modernos, e suas correções de segurança funcionalidade e estabilidade, para sistemas Microsoft Windows as atualizações são obtidas via Windows update. Assinale abaixo qual o comando faz a checagem dos pacotes disponíveis para atualização em sistemas Linux com yum.","opcoes":["yum check-update.","yum install updates.","yum provides update.","Nenhuma das alternativas."],"correta":0,"explicacao":"Gabarito: <strong>yum check-update.</strong>.","banca":"Instituto Excelência","ano":2018,"temas_relacionados":["linux_geral"]},{"id":2769757,"enunciado":"Considere o seguinte comando atribuído a um arquivo em um Sistema Operacional Linux: chmod 640 concurso.txt A execução deste comando atribui permissão de:","opcoes":["Execução para o dono do arquivo, somente escrita para usuários do mesmo grupo e somente leitura para outros usuários.","Nenhuma permissão para o dono do arquivo, somente leitura para usuários do mesmo grupo e leitura e escrita para outros usuários.","Leitura e escrita para o dono do arquivo, nenhuma permissão para usuários do mesmo grupo e somente escrita para outros usuários.","Leitura e escrita para o dono do arquivo, somente leitura para usuários do mesmo grupo e nenhuma permissão para outros usuários."],"correta":3,"explicacao":"Gabarito: <strong>Leitura e escrita para o dono do arquivo, somente leitura para usuários do mesmo grupo e nenhuma permissão para outros usuários.</strong>.","banca":"IDECAN","ano":2016,"temas_relacionados":["linux_geral"]},{"id":2769760,"enunciado":"O comando chmod do Sistema Operacional Linux é utilizado para atribuir permissões em um arquivo. Os parâmetros deste comando podem ser representados por números predefinidos que representam, respectivamente, as permissões para o proprietário do arquivo, usuários do mesmo grupo e todos usuários. Caso um usuário necessite atribuir para um arquivo: nenhuma permissão para o grupo, somente leitura para usuários do mesmo grupo e somente execução para todos usuários, pode-se afirmar que a sequência de parâmetros do comando deverá ser respectivamente:","opcoes":["041.","067.","370.","604."],"correta":0,"explicacao":"Gabarito: <strong>041.</strong>.","banca":"IDECAN","ano":2016,"temas_relacionados":["linux_geral"]},{"id":2769762,"enunciado":"Sobre a utilização da ferramenta apt-get em Sistemas Operacionais Linux, analise as afirmativas. I. Para instalar um novo programa deve-se utilizar o comando apt-get new nome_do_programa. II. Para remover um programa deve-se utilizar o comando apt-get remove nome_do_programa. III. Para pesquisar o nome de um pacote deve-se utilizar o comando apt-get scanning nome_do_programa. Está(ão) correta(s) apenas a(s) afirmativa(s)","opcoes":["I.","II.","III.","II e III."],"correta":1,"explicacao":"Gabarito: <strong>II.</strong>.","banca":"IDECAN","ano":2016,"temas_relacionados":["linux_geral"]},{"id":2785023,"enunciado":"Considere as afirmativas abaixo relacionadas ao gerenciador de arquivo Nautilus, utilizado no sistema operacional Ubuntu Linux: I. Permite habilitar ou desabilitar a visualização de arquivos cujos nomes começam com “.” (arquivos ocultos). II. Possui uma ferramenta de busca para localizar arquivo fornecendo seu nome (ou parte do nome). III. Exibe por padrão, no modo de exibição de ícones, detalhes dos arquivos como tamanho em bytes. Está CORRETO o que se afirma em:","opcoes":["I e II, apenas.","I e III, apenas.","II e III, apenas.","I, II e III."],"correta":0,"explicacao":"Gabarito: <strong>I e II, apenas.</strong>.","banca":"UFV","ano":2016,"temas_relacionados":["linux_geral"]},{"id":2785024,"enunciado":"Considere as afirmativas abaixo relacionadas à instalação de programas aplicativos no sistema operacional Ubuntu Linux: I. A instalação de novos programas só pode ser feita usando a central de programas. II. A senha de administrador é necessária para a instalação e/ou remoção de programas. III. A instalação de programas só pode ser feita se o computador estiver conectado à Internet. Está CORRETO o que se afirma apenas em:","opcoes":["I e II.","I e III.","II.","III."],"correta":2,"explicacao":"Gabarito: <strong>II.</strong>.","banca":"UFV","ano":2016,"temas_relacionados":["linux_geral"]},{"id":2792540,"enunciado":"Selecione das alternativas abaixo o comando do Linux que gerou o seguinte retorno: ethO_Linkencap:Ethernet EndereçodeHW26:cf:31:e4:12:03 inet end.: 192.168.1.36 Bcast:192.168.1.255 Masc-266 266 266 f) endereço' ' inet6: fe80::23cf:31ff:fee4:1203/64 Escopo: Link UP BROADCAST RUNNING MULTICAST MTU:1500 Métrica :1 pacotes RX: 1106565 erros:0 descartados:0 excesso:0 quadro:0 Pacotes TX:515214 erros:0 descartados:0 excesso:0 portadora :0 colisões:0 txqueuelen:1000 RX bytes: 1183239817 (1.1 GB) TX bytes:83265719 (83.2 MB) Io ___Link encap:Loopback Local inet end.: 127.0.0.1 Masc:255.0.0.0 endereço inet6: ::1/128 Escopo:Máquina UP LOOPBACK RUNNING MTU:65536 Métrica:1 pacotes RX:725708 erros:0 descartados:0 excesso:0 quadro:0 Pacotes TX:725708 erros:0 descartados:0 excesso:0 portadora :0 colisões:0 txqueuelen:0 RX bytes:38181485 (38.1 MB) TX bytes:38181485 (38.1 MB)","opcoes":["route","ifconfig","ping","traceroute"],"correta":1,"explicacao":"Gabarito: <strong>ifconfig</strong>.","banca":"IBFC","ano":2016,"temas_relacionados":["linux_geral"]},{"id":2792546,"enunciado":"Uma das possibilidades de compartilhar arquivos e impressoras do Sistema Operacional Linux para uma rede Microsoft é por meio do software:","opcoes":["Gimp","Wine","Okular","Samba"],"correta":3,"explicacao":"Gabarito: <strong>Samba</strong>.","banca":"IBFC","ano":2016,"temas_relacionados":["linux_geral"]},{"id":2795111,"enunciado":"Uma das formas de acesso remoto seguro a um servidor linux é a utilização de Secure Shell (SSH). Considerando a necessidade de um acesso via SSH do usuário com login jose a um servidor com IP 10.2.1.22 na porta 1234, deve-se utilizar o comando:","opcoes":["ssh 10.2.1.22 1234.","ssh jose@10.2.1.22 -p 1234.","ssh jose@1234 -p 10.2.1.22.","ssh -P jose@10.2.1.22."],"correta":1,"explicacao":"Gabarito: <strong>ssh jose@10.2.1.22 -p 1234.</strong>.","banca":"COMPERVE - UFRN","ano":2017,"temas_relacionados":["linux_geral"]},{"id":2799180,"enunciado":"Em relação ao comando ifconfig no Linux, marque a alternativa VERDADEIRA:","opcoes":["é utilizado para configurar uma impressora.","é utilizado para configurar um dispositivo usb.","é utilizado para configurar uma interface de rede.","é utilizado para configurar o nome do computador.","é utilizado para configurar uma placa de vídeo."],"correta":2,"explicacao":"Gabarito: <strong>é utilizado para configurar uma interface de rede.</strong>.","banca":"IF-PA","ano":2016,"temas_relacionados":["linux_geral"]},{"id":2799186,"enunciado":"Em relação ao arquivo /etc/hosts no Linux, marque a alternativa CORRETA:","opcoes":["é um banco de dados de nomes e endereço ethernet.","é um banco de dados de nomes e valores de máscara de sub-redes.","é um banco de dados de nomes de protocolos.","é um banco de dados de nomes de serviços.","é um banco de dados de nomes de computadores."],"correta":4,"explicacao":"Gabarito: <strong>é um banco de dados de nomes de computadores.</strong>.","banca":"IF-PA","ano":2016,"temas_relacionados":["linux_geral"]},{"id":2800150,"enunciado":"Uma das principais diferenças entre o Linux e o Windows é?","opcoes":["ambos são sistemas operacionais construídos em linguagem java.","ambos são sistemas operacionais gratuitos.","A diferença mais marcante entre Linux e Windows é o fato do segundo ser um sistema de código aberto, desenvolvido por programadores voluntários espalhados por toda internet e distribuído sob a licença pública GPL. Enquanto o Linux é software proprietário, não possui código-fonte disponível e você ainda precisa comprar uma licença pra ter o direito de usá-lo.","A diferença mais marcante entre Linux e Windows é o fato do primeiro ser um sistema de código aberto, desenvolvido por programadores voluntários espalhados por toda internet e distribuído sob a licença pública GPL. Enquanto o Windows é software proprietário, não possui código-fonte disponível e você ainda precisa comprar uma licença pra ter o direito de usá-lo."],"correta":3,"explicacao":"Gabarito: <strong>A diferença mais marcante entre Linux e Windows é o fato do primeiro ser um sistema de código aberto, desenvolvido por programadores voluntários espalhados por toda internet e distribuído sob a licença pública GPL. Enquanto o Windows é software proprietário, não possui código-fonte disponível e você ainda precisa comprar uma licença pra ter o direito de usá-lo.</strong>.","banca":"Prime Concursos","ano":2017,"temas_relacionados":["linux_geral"]},{"id":2800152,"enunciado":"São exemplos de distribuições Linux, assinale a alternativa correta","opcoes":["Ubuntu, Opensuse, Debian, Slackware, kurumin, Fedora,CentOS, LinuxMint","Ubuntu, Opensuse, Debian, Slackware, kurumin, Fedora, OS X El Capitan","Ubuntu, Opensuse, Debian, Slackware, kurumin, Fedora, Windows 10","Ubuntu, Opensuse, Debian, Slackware, kurumin, Fedora, OpenOffice."],"correta":0,"explicacao":"Gabarito: <strong>Ubuntu, Opensuse, Debian, Slackware, kurumin, Fedora,CentOS, LinuxMint</strong>.","banca":"Prime Concursos","ano":2017,"temas_relacionados":["linux_geral"]},{"id":2801115,"enunciado":"Não é uma distribuição do Linux:","opcoes":["Joli OS.","OpenSUSE.","Ubuntu.","Hinemora."],"correta":3,"explicacao":"Gabarito: <strong>Hinemora.</strong>.","banca":"AMEOSC","ano":2017,"temas_relacionados":["linux_geral"]},{"id":2801116,"enunciado":"Os comandos abaixo, no Linux, mostram conteúdo de arquivos, exceto:","opcoes":["ls.","more.","cat.","less."],"correta":0,"explicacao":"Gabarito: <strong>ls.</strong>.","banca":"AMEOSC","ano":2017,"temas_relacionados":["linux_geral"]},{"id":2826440,"enunciado":"Suponha que ao utilizar um aplicativo no ambiente operacional Linux, o mesmo não esteja mais respondendo e você queira finalizá-lo. Para tal operação, o comando a ser utilizado é:","opcoes":["end","jobs","shell","kill","rm"],"correta":3,"explicacao":"Gabarito: <strong>kill</strong>.","banca":"FUNCAB","ano":2014,"temas_relacionados":["linux_geral"]},{"id":2826441,"enunciado":"Sobre o sistema operacional Linux, é correto afirmar que:","opcoes":["não suporta interface gráfica.","depende do sistema operacional Windows para funcionar em um computador.","é um sistema de código aberto.","possui restrição quanto ao número de máquinas a ser instalado.","é um sistema pago."],"correta":2,"explicacao":"Gabarito: <strong>é um sistema de código aberto.</strong>.","banca":"FUNCAB","ano":2014,"temas_relacionados":["linux_geral"]},{"id":2826443,"enunciado":"No sistema operacional Linux, o KDE representa:","opcoes":["o prompt do sistema operacional.","um navegador da Internet.","uma interface gráfica.","um sistema de busca da Internet.","o Kernel do sistema operacional."],"correta":2,"explicacao":"Gabarito: <strong>uma interface gráfica.</strong>.","banca":"FUNCAB","ano":2014,"temas_relacionados":["linux_geral"]},{"id":2826444,"enunciado":"Sobre a manipulação de contas de usuários no sistema operacional Linux, é correto afirmar que:","opcoes":["o comando adduser não permite adicionar um usuário a um grupo do sistema.","o arquivo /etc/adduser.conf contém os padrões para a criação de novos usuários no sistema.","o arquivo /etc/passwd contém as senhas dos usuários e somente pode ser acessado pelo usuário root.","o comando adduser não permite criar um grupo no sistema.","o arquivo /etc/shadow pode ser acessado por todos os usuários."],"correta":1,"explicacao":"Gabarito: <strong>o arquivo /etc/adduser.conf contém os padrões para a criação de novos usuários no sistema.</strong>.","banca":"FUNCAB","ano":2014,"temas_relacionados":["linux_geral"]},{"id":2855387,"enunciado":"No Linux a implementação do serviço SSH pode ser feita por meio do OpenSSH. Considerando o conjunto de aplicativos e as funcionalidades do OpenSSH, bem como os conceitos acerca do SSH. Assinale a opção INCORRETA.","opcoes":["Em uma implementação padrão, tanto o acesso remoto quanto a transferência de arquivos ocorre através da porta TCP/22.","Ao configurar o OpenSSH no servidor Linux, optou-se pelo uso da versão 1 do protocolo SSH, por meio do parâmetro “Protocol 1” do arquivo de configuração. Nesse cenário, caso o cliente que esteja realizando o acesso remoto só tenha suporte à versão 2 do protocolo, o servidor permitirá o acesso, visto que a versão 2 é mais segura que a 1.","Em um servidor Linux, é possível configurar o OpenSSH para que este aceite somente conexões feitas a partir de máquinas confiáveis, sem a necessidade de pedir senha.","O OpenSSH pode ser configurado de forma a ativar a transferência de arquivos segura (SFTP). Isto é feito por meio do parâmetro “Subsystem” localizado no arquivo de configuração.","Por meio de parâmetros alterados no arquivo de configuração, é possível ajustar o serviço OpenSSH em um servidor Linux para impedir que o usuário “root” possa efetuar login remoto. Da mesma forma, também é possível realizar ajustes para determinar quais usuários do servidor podem realizar o login remoto."],"correta":1,"explicacao":"Gabarito: <strong>Ao configurar o OpenSSH no servidor Linux, optou-se pelo uso da versão 1 do protocolo SSH, por meio do parâmetro “Protocol 1” do arquivo de configuração. Nesse cenário, caso o cliente que esteja realizando o acesso remoto só tenha suporte à versão 2 do protocolo, o servidor permitirá o acesso, visto que a versão 2 é mais segura que a 1.</strong>.","banca":"IF-SC","ano":2019,"temas_relacionados":["linux_geral"]},{"id":2855389,"enunciado":"O serviço Samba em um servidor Linux permite que arquivos e impressoras possam ser compartilhados com estações de trabalho (desktops) Windows 7 Professional. Considerando que está rodando a versão 3 do Samba no servidor, avalie as afirmações adiante e marque com (V) as verdadeiras e com (F) as falsas. ( ) O Samba possui dois processos que atuam como servidor, o “smbd” responsável pela resolução de nomes em redes SMB e o “nmbd”, responsável pelos serviços de compartilhamento de arquivos, impressoras e autenticação. Para reiniciar o Samba, é necessário reiniciar estes dois processos. ( ) Ao compartilhar um diretório, é possível acrescentar o parâmetro “veto file” nas configurações do servidor Samba, para evitar que os usuários gravem determinados tipos de arquivos. ( ) Não é possível ao serviço Samba, em sua versão 3, construir uma topologia de domínios nem fazer controle de acesso aos diretórios por ACLs. Para contornar essas limitações, seria necessário migrar o serviço do Samba para a versão 4. ( ) O arquivo de configuração do Samba, normalmente o “smb.conf”, é dividido em seções e parâmetros. As seções utilizam nomes reservados para configurações específicas. Uma das mais importantes é identificada por “[global]”, a qual define configurações que afetam o comportamento de todo o servidor Samba, com efeito em todos os compartilhamentos. ( ) Ao compartilhar um diretório, o administrador do servidor gostaria que ele ficasse oculto para os usuários. Uma das formas de fazer isto seria editando o arquivo de configuração do Samba e acrescentando o parâmetro “browseable = No” na seção de compartilhamento do diretório. Marque a opção que contenha a sequência CORRETA, de cima para baixo:","opcoes":["F, V, F, V, V","V, V, V, F, F","F, F, F, V, V","V, F, V, F, F","F, V, V, F, F"],"correta":0,"explicacao":"Gabarito: <strong>F, V, F, V, V</strong>.","banca":"IF-SC","ano":2019,"temas_relacionados":["linux_geral"]},{"id":2862714,"enunciado":"No Suse Linux, o sistema de arquivos baseia-se em uma estrutura de árvore de diretórios, sendo que um contém os diretórios pessoais de todos os usuários que possuem conta no sistema enquanto que outro guarda arquivos de configuração do sistema específicos de host. Esses diretórios são denominados, respectivamente:","opcoes":["/home e /etc","/boot e /etc","/root e /etc","/boot e /lib","/home e /lib"],"correta":0,"explicacao":"Gabarito: <strong>/home e /etc</strong>.","banca":"BIO-RIO","ano":2014,"temas_relacionados":["linux_geral"]},{"id":2862720,"enunciado":"No uso dos recursos do Lotus Notes 8.5.3, uma ferramenta se destina a limpar uma instalação, uma desinstalação ou um upgrade com falha. Pode-se usar também essa ferramenta para desinstalar uma versão existente do Notes, e limpar arquivos estranhos, antes de executar uma instalação de upgrade. Essa ferramenta é conhecida como:","opcoes":["Notes Install Cleanup Executable","UpdateSiteMgr","addToKit","Sametime","Domino"],"correta":0,"explicacao":"Gabarito: <strong>Notes Install Cleanup Executable</strong>.","banca":"BIO-RIO","ano":2014,"temas_relacionados":["linux_geral"]},{"id":2877186,"enunciado":"Nos sistemas operacionais Linux, diversos servidores sob licença GNU podem ser instalados. NÃO é um desses servidores o","opcoes":["SENDMAIL server","IPTABLES server","SQUID server","BIND server","ISA server"],"correta":4,"explicacao":"Gabarito: <strong>ISA server</strong>.","banca":"CESGRANRIO","ano":2012,"temas_relacionados":["linux_geral"]},{"id":2877189,"enunciado":"Os sistemas operacionais Linux e Windows 2003 possuem características distintas. Uma diferença entre esses dois sistemas operacionais é que somente o","opcoes":["Linux pode processar comandos em modo texto.","Linux pode ser instalado em máquinas RS/6000.","Windows 2003 é um sistema de código aberto.","Windows 2003 manipula permissões de acesso.","Windows 2003 opera em modo gráfico."],"correta":1,"explicacao":"Gabarito: <strong>Linux pode ser instalado em máquinas RS/6000.</strong>.","banca":"CESGRANRIO","ano":2012,"temas_relacionados":["linux_geral"]},{"id":2884313,"enunciado":"Considere o conteúdo de um arquivo (dados.txt) em um servidor Linux a seguir. 1:Maria 2:João 3:José 4:Nair 5:Adriana Um administrador do sistema deseja ver somente os nomes (Maria, João, etc.) desse arquivo. Que comando deve ser utilizado nessa situação?","opcoes":["cut -f2 -d:|grep dados.txt","cat -2|grep -i dados.txt","cat dados.txt|cut -f2 -d:","echo dados.txt|cut -f2 -d:","echo -i -2 dados.txt"],"correta":2,"explicacao":"Gabarito: <strong>cat dados.txt|cut -f2 -d:</strong>.","banca":"CESGRANRIO","ano":2012,"temas_relacionados":["linux_geral"]},{"id":2884314,"enunciado":"Quando um servidor Linux apresenta, no máximo, load average igual a 0.14 em picos de acessos, significa que","opcoes":["86% do tempo de CPU é utilizado, no máximo.","86% da memória é utilizada, no máximo.","14% do tempo de CPU é utilizado, em média.","14% da memória é utilizada, em média.","o servidor está, em média, sem sobrecarga."],"correta":4,"explicacao":"Gabarito: <strong>o servidor está, em média, sem sobrecarga.</strong>.","banca":"CESGRANRIO","ano":2012,"temas_relacionados":["linux_geral"]},{"id":2884315,"enunciado":"Um servidor Linux, executando um sistema crítico sob o usuário root, excedeu o número de arquivos abertos permitidos. Para saber qual é esse número, o administrador do servidor pode executar o comando","opcoes":["ls -l /root|wc -l","rm -rf /tmp/*","rm -rf /","cat /proc/sys/fs/file-max","cat /etc/filedescriptors|wc -l"],"correta":3,"explicacao":"Gabarito: <strong>cat /proc/sys/fs/file-max</strong>.","banca":"CESGRANRIO","ano":2012,"temas_relacionados":["linux_geral"]},{"id":2891150,"enunciado":"Sobre a criação de usuários no sistema operacional Linux, são feitas as seguintes afirmações: I. O sistema cria automaticamente um diretório para o novo usuário localizado em /var. II. Se o grupo não for especificado, o Linux cria um grupo para o novo usuário cujo nome é definido por “user” + data da criação. III. O novo usuário herda os direitos de acesso do usuário que o criou. Sobre as três afirmações anteriores, assinale o correto.","opcoes":["Apenas a I é falsa.","Apenas a I e a II são falsas.","Apenas a II é falsa.","Todas são falsas."],"correta":3,"explicacao":"Gabarito: <strong>Todas são falsas.</strong>.","banca":"UECE-CEV","ano":2008,"temas_relacionados":["linux_geral"]},{"id":2891166,"enunciado":"Assinale a alternativa que contém, somente, sistemas de arquivos utilizados no sistema operacional Linux.","opcoes":["ext3, Reiser4 e ReiserFS","ext3, ReiserX e ReiserFS","ReiserX, ext3 e FAT32","NTSF, Reiser4 e ext3"],"correta":0,"explicacao":"Gabarito: <strong>ext3, Reiser4 e ReiserFS</strong>.","banca":"UECE-CEV","ano":2008,"temas_relacionados":["linux_geral"]},{"id":2891364,"enunciado":"Os utilitários dos sistemas operacionais Linux e Windows, utilizados para exibir e modificar as configurações IP das interfaces de rede, são, respectivamente:","opcoes":["configip e ipconfig.","ifconfig e ifconfig.","ifconfig e ipconfig.","ipconfig e ifconfig.","ipconfig e ipconfig."],"correta":2,"explicacao":"Gabarito: <strong>ifconfig e ipconfig.</strong>.","banca":"FEPESE","ano":2012,"temas_relacionados":["linux_geral"]},{"id":2891414,"enunciado":"Os utilitários de rede e o respectivo parâmetro para ignorar a resolução de nomes DNS, utilizados para rastreamento de rotas IP, nos sistemas operacionais Windows e Linux, são, respectivamente:","opcoes":["traceroute, -d e tracert, -n.","traceroute, -n e tracert, -d.","traceroute, -n e tracert, -d.","tracert, -n e traceroute, -d.","tracert, -d e traceroute, -n."],"correta":4,"explicacao":"Gabarito: <strong>tracert, -d e traceroute, -n.</strong>.","banca":"FEPESE","ano":2012,"temas_relacionados":["linux_geral"]},{"id":2895566,"enunciado":"Ao executar o script, o que será apresentado na tela?","opcoes":["-rw-r--r-- 1 JPCF staff 130 27 Mar 00:59 teste.bash","JPCF","*","teste.bash"],"correta":3,"explicacao":"Gabarito: <strong>teste.bash</strong>.","banca":"FUMARC","ano":2013,"temas_relacionados":["linux_geral"]},{"id":2895567,"enunciado":"Qual interpretador de shell script foi utilizado para a execução desse script?","opcoes":["Bourne Again Shell","Bourne Shell","Korn Shell","C Shell"],"correta":0,"explicacao":"Gabarito: <strong>Bourne Again Shell</strong>.","banca":"FUMARC","ano":2013,"temas_relacionados":["linux_geral"]},{"id":2908903,"enunciado":"Um novo disco rígido (HD) foi instalado em um computador com o sistema operacional Linux. Para que o disco seja utilizável pelo sistema, uma das primeiras ações que devem ser realizadas é o seu particionamento. Para isso, o Linux disponibiliza, por padrão, o comando","opcoes":["fd","dd","fdisk","pdisk","format"],"correta":2,"explicacao":"Gabarito: <strong>fdisk</strong>.","banca":"VUNESP","ano":2013,"temas_relacionados":["linux_geral"]},{"id":2908909,"enunciado":"O usuário de um computador com o sistema operacional Linux executou o comando ls para o diretório /etc e obteve a seguinte listagem, apresentada parcialmente: A opção do comando ls utilizada pelo usuário para obter essa listagem é:","opcoes":["-a","-c","-d","-g","-l"],"correta":0,"explicacao":"Gabarito: <strong>-a</strong>.","banca":"VUNESP","ano":2013,"temas_relacionados":["linux_geral"]},{"id":2911687,"enunciado":"A melhor forma de desligar uma estação ou servidor Linux, em CPUs com arquitetura x86, é através do comando:","opcoes":["init 0","init 1","init 6","shutdown -r","shutdown immediately"],"correta":0,"explicacao":"Gabarito: <strong>init 0</strong>.","banca":"FEPESE","ano":2012,"temas_relacionados":["linux_geral"]},{"id":2911693,"enunciado":"Identifique abaixo as afirmativas verdadeiras ( V ) e as falsas ( F ), com relação às variáveis de ambiente de sistema operacional: ( ) Estão presentes no Windows, mas não no Linux. ( ) %VARIAVEL% é a sintaxe para referenciá-las no Windows, onde VARIAVEL é o nome da variável de ambiente em questão. ( ) $VARIAVEL é a sintaxe para referenciá-las no Linux, onde VARIAVEL é o nome da variável de ambiente em questão. ( ) Estão presentes no Linux, mas não no Windows. Assinale a alternativa que indica a sequência correta, de cima para baixo.","opcoes":["V – V – F – F","V – F – F – F","F – V – V – F","F – F – V – V","F – F – F – V"],"correta":2,"explicacao":"Gabarito: <strong>F – V – V – F</strong>.","banca":"FEPESE","ano":2012,"temas_relacionados":["linux_geral"]},{"id":2911733,"enunciado":"Assinale a alternativa que melhor caracteriza a função e o uso do comando nslookup, presente nas distribuições linux.","opcoes":["Realizar consultas de endereços de servidores de email utilizando o protocolo DNS.","Realizar consultas de nomes e endereços IP utilizando o protocolo SNMP.","Verificar o status dos endereços IP que trafegam na rede utilizando o protocolo SNMP.","Realizar consultas aos ativos de rede e servidores utilizando o protocolo SNMP.","Realizar consultas e receber eventos dos ativos de rede, utilizando os protocolos SNMP e DNS."],"correta":0,"explicacao":"Gabarito: <strong>Realizar consultas de endereços de servidores de email utilizando o protocolo DNS.</strong>.","banca":"FEPESE","ano":2012,"temas_relacionados":["linux_geral"]},{"id":2913070,"enunciado":"Assinale a alternativa que contém, somente, gerenciadores de janelas/ambientes de desktop para o sistema operacional Linux.","opcoes":["KDE, Gnome e Evolution","fluxbox, icewm e windowmaker","pwm, notepad e mswindowsmanager","rawfish, delighted e xfce"],"correta":1,"explicacao":"Gabarito: <strong>fluxbox, icewm e windowmaker</strong>.","banca":"UECE-CEV","ano":2008,"temas_relacionados":["linux_geral"]},{"id":2913115,"enunciado":"A integração entre os sistemas operacionais Linux e Windows pode ser obtida utilizando","opcoes":["SAMBA.","NetBiosX.","MAMBO.","DNS."],"correta":0,"explicacao":"Gabarito: <strong>SAMBA.</strong>.","banca":"UECE-CEV","ano":2008,"temas_relacionados":["linux_geral"]},{"id":2914385,"enunciado":"A figura a seguir mostra o fragmento de tela que contém a saída de um comando Linux. Host is up ( 1.2s legacy). Not Shown: 994closed ports PORT STATE SERVICE 80/tpc open http 514/tpc filtered shell 888/tpc filtered accessbuider 1058/tpc filtered nim 3889/tpc filtered dandv-tester 5432/tpc open postgresql Os dados apresentados na figura apresentam o status das portas/serviços em host remoto, obtido através da execução do comando","opcoes":["nc.","nmap.","lsoft.","tcpdump."],"correta":1,"explicacao":"Gabarito: <strong>nmap.</strong>.","banca":"COMPERVE - UFRN","ano":2013,"temas_relacionados":["linux_geral"]},{"id":2914396,"enunciado":"A instalação, remoção e atualização de novos programas no Ubuntu 12.04 é fundamental para um bom gerenciamento do computador. Os programas padrões, na linha de comando do Ubuntu, para realizar essas tarefas são","opcoes":["synaptic e ubuntumanager","apt-get e synaptic","apt-get e dpkg","ubuntumanager e dpkg"],"correta":2,"explicacao":"Gabarito: <strong>apt-get e dpkg</strong>.","banca":"COMPERVE - UFRN","ano":2013,"temas_relacionados":["linux_geral"]},{"id":2914399,"enunciado":"No linux Ubuntu 12.04, é possível adicionar novos usuários locais com o comando useradd, que realiza automaticamente um conjunto de ações no arquivos do sistema. O arquivo que contém os nomes dos usuários locais é","opcoes":["/etc/name","/etc/passwd","/home/group","/home/shadow"],"correta":1,"explicacao":"Gabarito: <strong>/etc/passwd</strong>.","banca":"COMPERVE - UFRN","ano":2013,"temas_relacionados":["linux_geral"]},{"id":2914404,"enunciado":"Uma forma de realizar cópias de segurança (backup), no linux Ubuntu 12.04, é com o uso do programa tar. Para realizar uma cópia do conteúdo do usuário jose, que contém seu diretório base em /home/jose e colocar no arquivo copia_jose.tgz, localizado no diretório /tmp deve-se executar o comando","opcoes":["tar -xvzf /tmp/copia_jose.tgz /home/jose","tar -cvzf /tmp/copia_jose.tgz /home/jose","tar -cvzf /home/jose /tmp/copia_jose.tgz","tar -xvzf /home/jose /tmp/copia_jose.tgz"],"correta":1,"explicacao":"Gabarito: <strong>tar -cvzf /tmp/copia_jose.tgz /home/jose</strong>.","banca":"COMPERVE - UFRN","ano":2013,"temas_relacionados":["linux_geral"]},{"id":2921750,"enunciado":"Dos comandos a seguir, quais são utilizados para gerenciamento de pacotes em sistemas Linux baseados em Red Hat e Debian, respectivamente?","opcoes":["yum e apt","rpm e yum","apt e rpm","dkpg e apt"],"correta":0,"explicacao":"Gabarito: <strong>yum e apt</strong>.","banca":"FADESP","ano":2010,"temas_relacionados":["linux_geral"]},{"id":2921814,"enunciado":"Para criar uma conta de nome \"webmaster\", com diretório home em /srv/www, sem direito a conta shell, usa-se o comando","opcoes":["useradd webmaster -d /srv/www -s /bin/false","useradd webmaster --homedir /srv/www --shell /bin/false","useradd webmaster -h /srv/www -s /bin/false","useradd webmaster --home-dir /srv/www -shell /bin/false"],"correta":0,"explicacao":"Gabarito: <strong>useradd webmaster -d /srv/www -s /bin/false</strong>.","banca":"FADESP","ano":2010,"temas_relacionados":["linux_geral"]},{"id":2921816,"enunciado":"Para remover uma usuária de nome \"maria\" e o seu diretório home, usa-se o comando","opcoes":["userdel R maria","userdel -h maria","userdel --home maria","userdel -r maria"],"correta":3,"explicacao":"Gabarito: <strong>userdel -r maria</strong>.","banca":"FADESP","ano":2010,"temas_relacionados":["linux_geral"]},{"id":2921819,"enunciado":"Para que os arquivos criados em /var/www pertençam ao grupo dono do mesmo diretório, usa-se o comando","opcoes":["chmod 775 -R /var/www","chmod 1775 -R /var/www","chmod 2775 -R /var/www","chmod 4775 -R /var/www"],"correta":2,"explicacao":"Gabarito: <strong>chmod 2775 -R /var/www</strong>.","banca":"FADESP","ano":2010,"temas_relacionados":["linux_geral"]},{"id":2921830,"enunciado":"O arquivo de configuração do OpenSSH em um servidor Linux tem o nome de","opcoes":["sshd.conf","ssh.conf","sshd_config","ssh_config"],"correta":2,"explicacao":"Gabarito: <strong>sshd_config</strong>.","banca":"FADESP","ano":2010,"temas_relacionados":["linux_geral"]},{"id":2922259,"enunciado":"No que se refere aos sistemas Linux e Windows, assinale a opção correta.","opcoes":["O comando ln, no Linux, permite a criação de links entre dois arquivos. Somente o usuário com permissão de root pode criar links com o comando ln.","O comando less, no Linux, possibilita listar o conteúdo de um arquivo texto. No Windows XP, o comando list possui funções semelhantes e pode ser executado por meio do prompt de comando.","O arquivo inittab, localizado no diretório /etc do Linux, permite definir o nível de tabulação (endentação) que será utilizado ao se editar arquivo de texto.","No Linux, o diretório /dev tem como principal objetivo armazenar os programas que são acessíveis a todos os usuários.","O comando kill, no Linux, é utilizado para enviar sinais a processos."],"correta":4,"explicacao":"Gabarito: <strong>O comando kill, no Linux, é utilizado para enviar sinais a processos.</strong>.","banca":"CESPE / CEBRASPE","ano":2007,"temas_relacionados":["linux_geral"]},{"id":2922274,"enunciado":"Firewall é um programa que tem por objetivo proteger a máquina contra acessos e tráfego indesejados e proteger serviços que estejam sendo executados na máquina. Acerca desse tema, assinale a opção correta.","opcoes":["O firewall do Windows XP Professional (SP2) ajuda a prevenir que vírus e vermes atinjam o computador e, além disso, permite detectar e remover vírus que já estejam instalados no computador.","O firewall do Windows XP Professional (SP2) pode ser configurado para bloquear e filtrar mensagens eletrônicas não-solicitadas (spam).","O iptables, que é um código de firewall para Linux, kernel 2.4.x e 2.6.x, é um exemplo de firewall que opera no nível de aplicação.","O iptables não possui suporte ao protocolo TCP.","No Linux, o arquivo /etc/syslog.conf é um dos principais arquivos de configuração para o syslogd, o qual permite registrar as mensagens de log de sistema."],"correta":4,"explicacao":"Gabarito: <strong>No Linux, o arquivo /etc/syslog.conf é um dos principais arquivos de configuração para o syslogd, o qual permite registrar as mensagens de log de sistema.</strong>.","banca":"CESPE / CEBRASPE","ano":2007,"temas_relacionados":["linux_geral"]},{"id":2931860,"enunciado":"No Linux, o comando ifconfig está relacionado à","opcoes":["configuração das interfaces de rede.","configuração dos comandos condicionais.","interpretação global dos scripts de configuração.","exibição de configurações opcionais.","listagem de configurações personalizadas."],"correta":0,"explicacao":"Gabarito: <strong>configuração das interfaces de rede.</strong>.","banca":"FUNDAÇÃO SOUSÂNDRADE","ano":2008,"temas_relacionados":["linux_geral"]},{"id":2931874,"enunciado":"No Linux, o comando ls é usado para","opcoes":["liberar o spool","obter uma listagem do spool de impressão","obter uma listagem de arquivos, diretórios e outros objetos do filesystem","criar um soft link","iniciar um login"],"correta":2,"explicacao":"Gabarito: <strong>obter uma listagem de arquivos, diretórios e outros objetos do filesystem</strong>.","banca":"FUNDAÇÃO SOUSÂNDRADE","ano":2008,"temas_relacionados":["linux_geral"]},{"id":2931877,"enunciado":"Para localizar e exibir todas as linhas do arquivo texto abc.txt que contenham a palavra MARIA, pode-se usar, no Linux, o comando","opcoes":["lookfor MARIA abc.txt","find string \"MARIA\" abc.txt","search in abc.txt find MARIA","grep MARIA abc.txt","open abc.txt | find MARIA"],"correta":3,"explicacao":"Gabarito: <strong>grep MARIA abc.txt</strong>.","banca":"FUNDAÇÃO SOUSÂNDRADE","ano":2008,"temas_relacionados":["linux_geral"]},{"id":2931880,"enunciado":"Assinale a alternativa CORRETA.","opcoes":["No Linux, podemos executar um certo número de aplicações compiladas para a plataforma Win32, usando o emulador wine.","Binários compilados para Win32 não podem ser executados, em hipótese alguma, no ambiente Linux.","Não há qualquer diferença entre os executáveis Win32 e Linux, já que ambos são binários da arquitetura i386 e assim podem ser executados em qualquer um dos dois ambientes operacionais.","No Linux, os arquivos executáveis sempre possuem a forma de scripts interpretáveis, portanto são escritos em ASCII puro e absolutamente portáveis para outras plataformas.","O que define se um arquivo executável pode ser utilizado em Linux ou Windows é exclusivamente a linguagem de programação usada para escrever o código fonte do referido programa."],"correta":0,"explicacao":"Gabarito: <strong>No Linux, podemos executar um certo número de aplicações compiladas para a plataforma Win32, usando o emulador wine.</strong>.","banca":"FUNDAÇÃO SOUSÂNDRADE","ano":2008,"temas_relacionados":["linux_geral"]},{"id":2939466,"enunciado":"No Sistema Operacional Linux considere as seguintes definições de permissão para os arquivos: chmod g+rw dicionario.odt chmod u-w dicionario.odt chmod 640 dicionario.odt Os comandos anteriores aplicam-se, respectivamente, às permissões para o arquivo dicionário.odt da seguinte forma","opcoes":["adiciona permissão de leitura ao usuário / remove permissão de escrita ao grupo / atribui permissão de leitura para o dono do arquivo, escrita para usuários do mesmo grupo e escrita para os outros usuários.","atribui permissão de leitura para o dono do arquivo, escrita para usuários do mesmo grupo e escrita para os outros usuários / adiciona permissão de leitura ao usuário / remove permissão de escrita ao grupo.","adiciona permissão de leitura ao grupo / adiciona permissão de escrita a um usuário / atribui permissão de escrita para o dono do arquivo, leitura para usuários do mesmo grupo e escrita para os outros usuários.","remove permissão de escrita ao grupo / remove permissão de escrita a um usuário / atribui permissão de leitura e escrita para o dono do arquivo, leitura para usuários do mesmo grupo e nenhuma permissão para os outros usuários.","adiciona permissão de leitura e escrita ao grupo / remove permissão de escrita a um usuário / atribui permissão de leitura e escrita para o dono do arquivo, somente leitura para usuários do mesmo grupo e nenhuma permissão para os outros usuários."],"correta":4,"explicacao":"Gabarito: <strong>adiciona permissão de leitura e escrita ao grupo / remove permissão de escrita a um usuário / atribui permissão de leitura e escrita para o dono do arquivo, somente leitura para usuários do mesmo grupo e nenhuma permissão para os outros usuários.</strong>.","banca":"IDECAN","ano":2013,"temas_relacionados":["linux_geral"]},{"id":2939469,"enunciado":"Para facilitar o processo de instalação de softwares nos sistemas operacionais de distribuição Linux foi criado o APT (Advanced Packaging Tool), que é uma ferramenta utilizada para instalar e atualizar pacotes de uma maneira mais rápida e prática. Os comandos utilizados para instalar e desinstalar o Mozilla Thunderbird são, respectivamente,","opcoes":["apt-get install mozilla-thunderbird / apt-get clear mozilla-thunderbird.","apt-get new mozilla-thunderbird / apt-get uninstall mozilla-thunderbird.","apt-get install mozilla-thunderbird / apt-get remove mozilla-thunderbird.","apt-get create mozilla-thunderbird / apt-get remove mozilla-thunderbird.","apt-get create mozilla-thunderbird / apt-get uninstall mozilla-thunderbird."],"correta":2,"explicacao":"Gabarito: <strong>apt-get install mozilla-thunderbird / apt-get remove mozilla-thunderbird.</strong>.","banca":"IDECAN","ano":2013,"temas_relacionados":["linux_geral"]},{"id":2939471,"enunciado":"Fernando trabalha em um laboratório de informática de certa instituição de ensino, cujos computadores estão configurados com Sistema Operacional Linux de distribuição Debian. Através do terminal, os comandos utilizados para listar os arquivos de um diretório, copiar arquivos, deletar arquivos, criar diretórios e exibir o conteúdo de um arquivo na tela são, respectivamente,","opcoes":["cat / cp / rm / mdir / ls.","cat / mv / rm / ls / mdir.","ls / cp / rm / mkdir / cat.","ls / rm / cp / mdir / new.","cp / mkdir / new / rm / mv."],"correta":2,"explicacao":"Gabarito: <strong>ls / cp / rm / mkdir / cat.</strong>.","banca":"IDECAN","ano":2013,"temas_relacionados":["linux_geral"]},{"id":2939473,"enunciado":"O gerenciador de arquivos é um programa utilizado para criar e gerenciar diretórios e arquivos nos Sistemas Operacionais. No Sistema Operacional Linux, o usuário tem as seguintes opções de gerenciadores, os quais podem ser instalados de acordo com a necessidade e afinidade do usuário, EXCETO:","opcoes":["Finder.","Dolphin.","Nautilus.","Konqueror.","Gnome Commander."],"correta":0,"explicacao":"Gabarito: <strong>Finder.</strong>.","banca":"IDECAN","ano":2013,"temas_relacionados":["linux_geral"]},{"id":3038942,"enunciado":"Qual comando deve ser utilizado para listar todos os arquivos do diretório do Linux?","opcoes":["Df","Cd","Mkdir","Ls"],"correta":3,"explicacao":"Gabarito: <strong>Ls</strong>.","banca":"Instituto Referência","ano":2024,"temas_relacionados":["linux_geral"]},{"id":3038943,"enunciado":"Leia o trecho abaixo. “Pesquisa informações de utilizadores.” O trecho acima faz referência a um dos comandos do diretório do Linux. Qual?","opcoes":["Finger","Explain","Ispell","Netscape"],"correta":0,"explicacao":"Gabarito: <strong>Finger</strong>.","banca":"Instituto Referência","ano":2024,"temas_relacionados":["linux_geral"]},{"id":3062308,"enunciado":"Qual das alternativas a seguir apresenta uma afirmação falsa sobre o SUSE LINUX SLES 15 SP2?","opcoes":["A partir do SUSE Linux Enterprise Server 15, o meio de instalação consiste apenas no Instalador Unificado, em um sistema mínimo para instalação, atualização e registro de todos os produtos base do SUSE Linux Enterprise.","Durante a instalação do SUSE 15 não é possível adicionar funcionalidades selecionando módulos e extensões para ser instalados em coexistência com o Instalador Unificado.","O meio de instalação padrão SLE-15-SP2-Online- ARCH -GM-media1.iso tem o tamanho otimizado e não inclui módulos e extensões.","O meio de instalação padrão SLE-15-SP2-Online- ARCH -GM-media1.iso requer acesso à rede para registrar seu produto e recuperar os dados do repositório referentes aos módulos e extensões."],"correta":1,"explicacao":"Gabarito: <strong>Durante a instalação do SUSE 15 não é possível adicionar funcionalidades selecionando módulos e extensões para ser instalados em coexistência com o Instalador Unificado.</strong>.","banca":"FUNVAPI","ano":2024,"temas_relacionados":["linux_geral"]},{"id":3062309,"enunciado":"No SUSE SLES 15, qual ambiente gráfico de fácil utilização pode ser personalizado de acordo com suas necessidades e preferências pessoais?","opcoes":["GNOME","Shell","Excel","Malware"],"correta":0,"explicacao":"Gabarito: <strong>GNOME</strong>.","banca":"FUNVAPI","ano":2024,"temas_relacionados":["linux_geral"]},{"id":3062310,"enunciado":"No SUSE SLES 15, qual Suíte Office de código-fonte aberto oferece ferramentas para todos os tipos de tarefas de escritório, como elaboração de textos, trabalho com planilhas ou criação de gráficos e apresentações?","opcoes":["Microsoft Office.","MalwareBytes.","LibreOffice.","BIOS."],"correta":2,"explicacao":"Gabarito: <strong>LibreOffice.</strong>.","banca":"FUNVAPI","ano":2024,"temas_relacionados":["linux_geral"]},{"id":3062311,"enunciado":"Qual browser da Web está incluído no SUSE Linux SLES 15, incluídos neste browser recursos como navegação com guias, bloqueio de janelas popup e gerenciamento de downloads?","opcoes":["Microsoft Edge.","Microsoft Internet Explorer.","Access.","Mozilla Firefox."],"correta":3,"explicacao":"Gabarito: <strong>Mozilla Firefox.</strong>.","banca":"FUNVAPI","ano":2024,"temas_relacionados":["linux_geral"]},{"id":3062312,"enunciado":"Sabemos que é possível implantar o sistema operacional SUSE SLES 15 em uma ampla variedade de hardwares e que é impossível listar todas as combinações diferentes de hardware que o SUSE SLES 15 suporta. Levando isto em consideração, qual das afirmações a seguir é falsa?","opcoes":["Há necessidade de pelo menos 1024 MB de memória RAM para a instalação mínima.","Os requisitos de disco dependem amplamente da instalação selecionada e de como você usa sua máquina.","É possível inicializar o computador de um CD ou de uma rede","Não existe quantidade mínima de memória RAM para instalar e utilizar o SUSE SLES 15."],"correta":3,"explicacao":"Gabarito: <strong>Não existe quantidade mínima de memória RAM para instalar e utilizar o SUSE SLES 15.</strong>.","banca":"FUNVAPI","ano":2024,"temas_relacionados":["linux_geral"]},{"id":3110454,"enunciado":"O uso de software livre nas escolas pode reduzir custos e promover o aprendizado de alternativas ao software proprietário. Entender as diferenças entre os sistemas operacionais e os pacotes de software disponíveis é importante para a gestão tecnológica no ambiente escolar. Qual dos seguintes sistemas operacionais é um exemplo de software livre amplamente utilizado em servidores e computadores pessoais?","opcoes":["Microsoft Windows.","Linux.","MacOS.","Solaris."],"correta":1,"explicacao":"Gabarito: <strong>Linux.</strong>.","banca":"ADM&TEC","ano":2024,"temas_relacionados":["linux_geral"]},{"id":3116692,"enunciado":"Sobre os sistemas operacionais Windows e Linux, analise as afirmativas a seguir: I.O Sistema Operacional Windows permite a criação de pontos de restauração, que possibilitam restaurar o sistema para um estado anterior em caso de falha ou mau funcionamento, sem a perda de arquivos pessoais. II.No sistema operacional GNU/Linux, o comando ls é utilizado para listar o conteúdo de diretórios, e o comando rm serve para criar novos arquivos de texto. III.O Windows, por padrão, oferece suporte nativo ao sistema de arquivos EXT4, amplamente utilizado em distribuições Linux. IV.No Linux, usuários comuns podem realizar a maior parte das tarefas de administração do sistema sem precisar de permissões adicionais, como root ou sudo. Assinale a alternativa correta:","opcoes":["Apenas a afirmativa I é verdadeira","Apenas as afirmativas I, II e III são verdadeiras","Apenas as afirmativas II, III e IV são verdadeiras","Apenas as afirmativas I e II são verdadeiras"],"correta":0,"explicacao":"Gabarito: <strong>Apenas a afirmativa I é verdadeira</strong>.","banca":"AMEOSC","ano":2024,"temas_relacionados":["linux_geral"]},{"id":3127904,"enunciado":"Considere as seguintes afirmações sobre o compartilhamento de pastas em uma rede local entre os sistemas operacionais Windows 11 e  Ubuntu Linux: I- No Windows 11 é possível compartilhar um local de armazenamento diretamente pelas suas \"Propriedades\" habilitando a opção  de compartilhamento na rede e definindo permissões de acesso. II- No Ubuntu Linux é preciso instalar o Samba para compartilhar pastas com máquinas Windows em uma rede local. III- No Windows 11 o compartilhamento de pastas com permissões de leitura e gravação pode ser feito apenas usando o grupo \"Todos\". IV- No Ubuntu Linux, as permissões de pastas compartilhadas podem ser gerenciadas por meio das configurações de \"Permissões\" do Nautilus ou via terminal. É CORRETO o que se afirma apenas em:","opcoes":["I, III e IV.","I, II e IV.","II, III e IV.","I e III.","I e II."],"correta":1,"explicacao":"Gabarito: <strong>I, II e IV.</strong>.","banca":"CPCON","ano":2024,"temas_relacionados":["linux_geral"]},{"id":3135874,"enunciado":"Com relação aos sistemas operacionais, softwares fundamentais que gerenciam o hardware e o software de um computador, permitindo que usuários e aplicativos interajam com o sistema de forma eficiente, analise as afirmativas abaixo: I.O sistema de arquivos NTFS, utilizado pelo Windows, suporta criptografia e permissões avançadas. II.O sistema de arquivos FAT32 é utilizado principalmente em sistemas modernos devido à sua capacidade de armazenar arquivos grandes. III.O sistema de arquivos EXT4 é amplamente utilizado em sistemas Linux. IV.O comando ls em sistemas Linux é utilizado para listar o conteúdo de um diretório. Estão corretas as afirmativas:","opcoes":["II, III e IV, apenas.","I, III e IV, apenas.","I, II, III e IV.","I e III, apenas.","II e IV, apenas."],"correta":1,"explicacao":"Gabarito: <strong>I, III e IV, apenas.</strong>.","banca":"Instituto Acesso","ano":2024,"temas_relacionados":["linux_geral","ortografia"]},{"id":3147089,"enunciado":"Um usuário de um computador com Linux ligou para a área de suporte técnico da empresa relatando problemas na sua conexão com a internet Para resolver o problema, o técnico solicitou ao usuário o IP da máquina. Para obter o IP, o usuário abriu o terminal do Linux e digitou","opcoes":["ip a","ipstatus","getip","myip a","ipinfo --all"],"correta":0,"explicacao":"Gabarito: <strong>ip a</strong>.","banca":"FCC","ano":2024,"temas_relacionados":["linux_geral"]},{"id":3150106,"enunciado":"O Linux é um sistema operacional open source , gratuito e altamente personalizável e disponibilizado sob a licença pública geral (GLP). Já o Ubuntu é uma distribuição Linux baseada no Debian que ficou conhecido por sua facilidade de uso, estabilidade e segurança. Nesse contexto, indique o comando que é utilizado para instalar um pacote no formato .deb no Ubuntu.","opcoes":["sudo yum install nome-do-pacote","sudo apt install nome-do-pacote","sudo dnf install nome-do-pacote","sudo rpm -i nome-do-pacote.deb"],"correta":1,"explicacao":"Gabarito: <strong>sudo apt install nome-do-pacote</strong>.","banca":"IDIB","ano":2024,"temas_relacionados":["linux_geral"]},{"id":3171965,"enunciado":"No sistema operacional Linux, a estrutura de diretórios segue o padrão do Filesystem Hierarchy Standard (FHS), que organiza os arquivos e diretórios de forma hierárquica. Assinale a opção que indica corretamente a finalidade do diretório /var.","opcoes":["Armazenar os arquivos de configuração estática do sistema e serviços, como o arquivo fstab.","Conter os arquivos essenciais do sistema necessários para o boot, como o kernel e os inicializadores.","Armazenar arquivos de dados variáveis, como logs do sistema e arquivos temporários de serviços.","Servir como local para bibliotecas compartilhadas usadas por binários em /usr e /bin.","Conter os arquivos e dados pessoais dos usuários, organizados por nome de usuário."],"correta":2,"explicacao":"Gabarito: <strong>Armazenar arquivos de dados variáveis, como logs do sistema e arquivos temporários de serviços.</strong>.","banca":"FGV","ano":2025,"temas_relacionados":["linux_geral"]},{"id":3174206,"enunciado":"Um usuário de um computador com Linux precisa trabalhar com um software de planilha da família do LibreOffice. Nesse caso, o aplicativo a ser utilizado é o:","opcoes":["calc","ether","numbers","sheets"],"correta":0,"explicacao":"Gabarito: <strong>calc</strong>.","banca":"SELECON","ano":2025,"temas_relacionados":["linux_geral"]},{"id":3185638,"enunciado":"Um administrador de um computador, com sistema operacional Linux, precisa utilizar um comando que permita navegar até determinada pasta. Esse comando é o:","opcoes":["cd","find","ls","rm"],"correta":0,"explicacao":"Gabarito: <strong>cd</strong>.","banca":"SELECON","ano":2024,"temas_relacionados":["linux_geral"]},{"id":3186689,"enunciado":"No Linux, qual comando permite ao usuário trocar temporariamente para outro usuário dentro do terminal?","opcoes":["sudo","su","chown","chmod"],"correta":1,"explicacao":"Gabarito: <strong>su</strong>.","banca":"Instituto Fênix","ano":2025,"temas_relacionados":["linux_geral"]},{"id":3187405,"enunciado":"O Sistema Operacional Linux é considerado um Software Livre. Partindo desta premissa, podemos afirmar que:","opcoes":["será sempre um software gratuito","pode ser um software gratuito","tem o código fonte fechado","é da Microsoft"],"correta":1,"explicacao":"Gabarito: <strong>pode ser um software gratuito</strong>.","banca":"EVO Concursos","ano":2025,"temas_relacionados":["linux_geral"]},{"id":3190327,"enunciado":"Noções de informática são essenciais no ambiente administrativo. O sistema operacional Linux se diferencia do Windows por:","opcoes":["Ser um sistema de código aberto, disponível para modificações pelos usuários.","Ser o único sistema que permite o uso de interface gráfica.","Não permitir a execução de programas de terceiros.","Ser pago e restrito a grandes empresas."],"correta":0,"explicacao":"Gabarito: <strong>Ser um sistema de código aberto, disponível para modificações pelos usuários.</strong>.","banca":"Fênix Concursos","ano":2024,"temas_relacionados":["linux_geral"]},{"id":3196504,"enunciado":"De forma similar ao aplicativo Explorador de Arquivos no sistema operacional Windows 10 BR, as distribuições Linux suportam gerenciadores de pastas e arquivos com a mesma finalidade. Dois exemplos desses gerenciadores no Linux são:","opcoes":["Nautilus e Dolphin","Gnome e Ubuntu","Fedora e Debian","Kernel e Ubuntu"],"correta":0,"explicacao":"Gabarito: <strong>Nautilus e Dolphin</strong>.","banca":"SELECON","ano":2025,"temas_relacionados":["linux_geral"]},{"id":3212320,"enunciado":"No Linux, para que um usuário logue de forma segura em outro sistema Linux/Unix, qual comando pode ser utilizado?","opcoes":["Logout.","Yppassawd.","Talk.","Rlogin."],"correta":3,"explicacao":"Gabarito: <strong>Rlogin.</strong>.","banca":"DECORP","ano":2025,"temas_relacionados":["linux_geral"]},{"id":3212434,"enunciado":"Qual das opções abaixo representa um sistema operacional de código aberto, que pode ser modificado e distribuído livremente?","opcoes":["Windows 10.","macOS.","Linux.","Microsoft Office."],"correta":2,"explicacao":"Gabarito: <strong>Linux.</strong>.","banca":"DECORP","ano":2025,"temas_relacionados":["linux_geral"]},{"id":3213093,"enunciado":"José, ao utilizar o terminal do Linux, verifica que o arquivo prova.txt possui as permissões -rwxrw-r--. Ao executar o comando chmod g-w, o+wx prova.txt, qual será o novo conjunto de permissões do arquivo?","opcoes":["Leitura, escrita e execução para o proprietário, leitura e execução para o grupo, leitura e execução para outros.","Leitura, escrita e execução para o proprietário, leitura e escrita para o grupo, leitura, escrita e execução para outros.","Leitura, escrita e execução para o proprietário, leitura e escrita para o grupo, leitura para outros.","Leitura, escrita e execução para o proprietário, execução para o grupo, leitura e execução para outros.","Leitura, escrita e execução para o proprietário, leitura para o grupo, leitura, escrita e execução para outros."],"correta":4,"explicacao":"Gabarito: <strong>Leitura, escrita e execução para o proprietário, leitura para o grupo, leitura, escrita e execução para outros.</strong>.","banca":"Qconcursos","ano":2025,"temas_relacionados":["linux_geral"]},{"id":3219089,"enunciado":"Um usuário do sistema operacional Linux foi questionado sobre o que seria “SuSE” e “Gnome”. Ele respondeu, de forma correta, que se trata, respectivamente, de","opcoes":["diretório e distribuição.","distribuição e interface gráfica.","interface gráfica e sistema de arquivo.","sistema de arquivo e comando.","comando e diretório."],"correta":1,"explicacao":"Gabarito: <strong>distribuição e interface gráfica.</strong>.","banca":"COSEAC","ano":2025,"temas_relacionados":["linux_geral"]},{"id":3219090,"enunciado":"No trabalho, um colega questiona qual das seguintes opções seria uma característica pertinente a um software livre. A resposta correta para essa pergunta é","opcoes":["ter direito de copyright.","não permitir modificação.","ter distribuição gratuita.","ser freeware.","possuir código aberto."],"correta":4,"explicacao":"Gabarito: <strong>possuir código aberto.</strong>.","banca":"COSEAC","ano":2025,"temas_relacionados":["linux_geral"]},{"id":3219237,"enunciado":"Em sistemas operacionais multitarefas, como o Ubuntu Linux, podem-se executar processos com maior ou menor prioridade. Se, por exemplo, um superusuário atribuir um valor numérico de prioridade mais baixo a um processo, ele passará mais tempo sendo executado pela CPU. No Ubuntu, o comando que permite alterar a prioridade de execução de processo é","opcoes":["nice.","ps.","kill.","top."],"correta":0,"explicacao":"Gabarito: <strong>nice.</strong>.","banca":"COMPERVE - UFRN","ano":2023,"temas_relacionados":["linux_geral"]},{"id":3219238,"enunciado":"Um técnico em TI, para implementar um certo projeto, instalou, em um computador, o Ubuntu Linux, a linguagem e as ferramentas de programação que utilizaria, além de um servidor de páginas web. Para instalar o Apache 2 no Ubuntu Linux, esse técnico em TI poderá utilizar o comando","opcoes":["sudo apt install apache2.","sudo yum install apache2.","sudo service install apache2.","sudo server install apache2."],"correta":0,"explicacao":"Gabarito: <strong>sudo apt install apache2.</strong>.","banca":"COMPERVE - UFRN","ano":2023,"temas_relacionados":["linux_geral"]},{"id":3219239,"enunciado":"Após instalar o Apache2 em uma máquina com Ubuntu Linux, o técnico em TI, para liberar memória nessa máquina, resolveu desligar o serviço. Para tanto, utilizou o comando","opcoes":["sudo service apache2 stop.","sudo apt stop apache2.","sudo server apache2 stop.","sudo yum stop apache2."],"correta":0,"explicacao":"Gabarito: <strong>sudo service apache2 stop.</strong>.","banca":"COMPERVE - UFRN","ano":2023,"temas_relacionados":["linux_geral"]},{"id":3219425,"enunciado":"Um usuário do Linux precisa descobrir algumas informações detalhadas sobre o hardware instalado em seu computador, que incluem processador, memória e dispositivos de armazenamento. Qual dos seguintes comandos pode indicar as informações procuradas pelo usuário?","opcoes":["chmod","hwinfo","grep","mkdir","ls"],"correta":1,"explicacao":"Gabarito: <strong>hwinfo</strong>.","banca":"Avança SP","ano":2025,"temas_relacionados":["linux_geral"]},{"id":3220241,"enunciado":"Das alternativas apresentadas abaixo, qual corresponde ao comando utilizado no Linux, para acessar e gerenciar sistemas remotos de forma segura?","opcoes":["wget.","curl.","ssh.","top."],"correta":2,"explicacao":"Gabarito: <strong>ssh.</strong>.","banca":"DECORP","ano":2025,"temas_relacionados":["linux_geral"]},{"id":3220260,"enunciado":"No contexto dos sistemas operacionais Windows e Linux, qual das afirmativas é correta?","opcoes":["O Windows é um sistema operacional de código aberto, enquanto o Linux é proprietário.","O Linux possui distribuições variadas, permitindo maior personalização e flexibilidade.","O Windows não oferece suporte a interfaces gráficas, sendo baseado apenas em linha de comando.","Ambos os sistemas utilizam exclusivamente o sistema de arquivos NTFS."],"correta":1,"explicacao":"Gabarito: <strong>O Linux possui distribuições variadas, permitindo maior personalização e flexibilidade.</strong>.","banca":"Instituto Fênix","ano":2025,"temas_relacionados":["linux_geral"]},{"id":3220563,"enunciado":"É correto afirmar que no sistema operacional Linux, para copiar arquivos do diretório atual para uma pasta diferente, utiliza-se o comando:","opcoes":["cp.","rm.","sudo.","pwd."],"correta":0,"explicacao":"Gabarito: <strong>cp.</strong>.","banca":"DECORP","ano":2025,"temas_relacionados":["linux_geral"]},{"id":3233283,"enunciado":"Em sistemas operacionais Linux, o comando usermod permite modificar contas de usuários. O argumento utilizado neste comando para estabelecer uma data limite a partir da qual determinada conta será desabilitada é o:","opcoes":["-a","-c","-e","-l","-r"],"correta":2,"explicacao":"Gabarito: <strong>-e</strong>.","banca":"VUNESP","ano":2024,"temas_relacionados":["linux_geral"]},{"id":3233296,"enunciado":"No sistema operacional Linux, o comando touch /forcefsck tem como propósito","opcoes":["forçar a execução de uma checagem da partição raiz do sistema imediatamente, mesmo que ela esteja montada.","forçar a execução de uma checagem da partição raiz do sistema na próxima reinicialização do computador.","reinicializar o sistema imediatamente e, durante o boot, forçar a execução de uma checagem da partição raiz.","forçar a desmontagem da partição raiz do sistema, imediatamente, permitindo que o comando fsck possa ser utilizado em seguida para checar essa partição.","alterar o ponto de montagem /forcefsck, se existir, para somente leitura (read only)."],"correta":1,"explicacao":"Gabarito: <strong>forçar a execução de uma checagem da partição raiz do sistema na próxima reinicialização do computador.</strong>.","banca":"VUNESP","ano":2024,"temas_relacionados":["linux_geral"]},{"id":3239928,"enunciado":"No controle de versões com Git, às vezes é necessário corrigir ou ajustar o último commit feito, como quando ocorre um erro no projeto ou faltam mudanças a serem incluídas. Para isso, existe uma diretiva específica que permite alterar o commit anterior sem criar um novo. Qual comando abaixo é utilizado para modificar o último commit efetuado?","opcoes":["git commit −−stat","git diff","git commit −−amend","git commit –push"],"correta":2,"explicacao":"Gabarito: <strong>git commit −−amend</strong>.","banca":"OBJETIVA","ano":2025,"temas_relacionados":["linux_geral"]},{"id":3245894,"enunciado":"Um comando Linux é uma instrução que você digita na interface de linha de comando (CLI) para que o sistema execute uma ação, como abrir um arquivo, listar pastas ou instalar um programa. Sendo assim, é correto afirmar que para o usuário do sistema operacional Linux poder comparar o conteúdo de dois arquivos, linha por linha, e depois mostrar as linhas que não são comuns entre eles, o comando a ser utilizado é o:","opcoes":["Cd.","Pwd.","Sudo.","Diff."],"correta":3,"explicacao":"Gabarito: <strong>Diff.</strong>.","banca":"DECORP","ano":2025,"temas_relacionados":["linux_geral"]},{"id":3247702,"enunciado":"Sistemas operacionais como Windows e Linux gerenciam recursos de hardware e software, sendo essenciais para o funcionamento estável e seguro do computador. Considerando isso, analise as afirmativas a seguir. I. No Windows, o Windows Update é usado para aplicar atualizações de segurança e melhorias, mantendo o sistema protegido contra vulnerabilidades. II. O Linux utiliza repositórios de software confiáveis para instalar e atualizar programas, garantindo maior controle sobre o que é instalado. III. Ambos os sistemas operacionais dispensam o uso de antivírus, pois possuem proteção nativa contra qualquer ameaça digital. Está correto o que se afirma em:","opcoes":["I e II, apenas.","I, II e III.","II, apenas.","I e III, apenas."],"correta":0,"explicacao":"Gabarito: <strong>I e II, apenas.</strong>.","banca":"IBAM","ano":2025,"temas_relacionados":["linux_geral"]},{"id":3248072,"enunciado":"Um diretório do Linux é simplesmente um arquivo, que é distribuído em forma de hierarquia. Existem diversas estruturas de diretórios, com o “root” como raiz, que usa o símbolo “/”, ao passo que outro diretório armazena todos os ficheiros globais de configuração do sistema operacional. No que diz respeito aos comandos de linha de prompt, um possibilita a exibição dos arquivos que estão dentro da pasta na qual o usuário está no momento, enquanto outro exibe o diretório atual no qual o usuário se encontra. Nesse contexto, o diretório de configuração e os dois comandos caracterizados são, respectivamente:","opcoes":["/cfg/, ls e dir","/etc/, fi les e pwd","/etc/, fi les e show","/cfg/, ls e show","/etc/, ls e pwd"],"correta":4,"explicacao":"Gabarito: <strong>/etc/, ls e pwd</strong>.","banca":"SELECON","ano":2025,"temas_relacionados":["linux_geral"]},{"id":3255501,"enunciado":"Em uma instalação do servidor web Apache 2.4 no sistema operacional Linux, foram encontradas as seguintes diretivas no arquivo de configuração httpd.conf. AllowOverride None AllowOverrideList None O efeito dessas linhas, considerando o seu contexto, é que","opcoes":["nenhum interpretador de scripts CGI está definido.","o registro do log de requisições está desabilitado.","arquivos .htaccess eventualmente existentes na árvore de diretórios são ignorados pelo servidor.","a possibilidade de um cliente web realizar múltiplas requisições HTTP na mesma conexão TCP está desabilitada.","redirecionamentos de URL estão desabilitados."],"correta":2,"explicacao":"Gabarito: <strong>arquivos .htaccess eventualmente existentes na árvore de diretórios são ignorados pelo servidor.</strong>.","banca":"VUNESP","ano":2024,"temas_relacionados":["linux_geral"]},{"id":3267280,"enunciado":"[Questão Inédita] Qual comando no Linux é utilizado para visualizar o conteúdo de um arquivo diretamente no terminal?","opcoes":["ls","cd","cat","mkdir","rm"],"correta":2,"explicacao":"Gabarito: <strong>cat</strong>.","banca":"Qconcursos","ano":2025,"temas_relacionados":["linux_geral"]},{"id":3269509,"enunciado":"No sistema operacional LINUX, o usuário root é o usuário","opcoes":["administrador de dados.","master administrador do sistema.","administrador da rede e suas rotas.","administrador master para desativar o sistema."],"correta":1,"explicacao":"Gabarito: <strong>master administrador do sistema.</strong>.","banca":"FUNCERN","ano":2022,"temas_relacionados":["linux_geral"]},{"id":3274440,"enunciado":"Acerca dos tipos de computadores, do Microsoft Word 2013 e dos conceitos de redes de computadores, julgue o item a seguir.\n\n\n\n\nDe um modo geral, o computador do tipo pessoal (PC) possui um sistema operacional amigável, como o Windows, e é acessível para o público em geral.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":3282194,"enunciado":"Um comando Linux é uma instrução que o usuário digita na interface de linha de comando (CLI) para que o sistema execute uma ação, como abrir um arquivo, listar pastas ou instalar um programa. É uma maneira rápida e eficiente de controlar o sistema sem usar a interface gráfica. Assinale a alternativa que apresenta a funcionalidade do comando “SUDO”.","opcoes":["Compara o conteúdo de dois arquivos linha por linha.","Executa um comando como superusuário.","Pode ser usado para mover ou renomear arquivos.","Remove arquivos e diretórios.","Serve para buscar arquivos em diretórios."],"correta":1,"explicacao":"Gabarito: <strong>Executa um comando como superusuário.</strong>.","banca":"COTEC","ano":2025,"temas_relacionados":["linux_geral"]},{"id":3288498,"enunciado":"No contexto da computação, as extensões de arquivos são usadas para identificar o tipo de conteúdo que um arquivo contém e determinar quais aplicativos devem ser usados para abri-lo. Apesar de amplamente padronizado, o sistema de extensões de arquivos pode variar conforme o sistema operacional e o formato de armazenamento de dados. Com base em seu conhecimento sobre sistemas de arquivos e o funcionamento das extensões, assinale a alternativa a seguir que descreve corretamente o comportamento das extensões e sua relação com os arquivos.","opcoes":["Em sistemas baseados em Linux, a extensão de arquivo é obrigatória e o sistema não consegue identificar o tipo de arquivo sem ela, dependendo exclusivamente da extensão para determinar o aplicativo correto.","No sistema operacional Windows, a remoção da extensão de um arquivo não altera sua estrutura interna, mas impede que o sistema associe automaticamente o arquivo ao programa correto para abri-lo.","Em sistemas de arquivos FAT32, a limitação de nomes de arquivos a 8 caracteres e a extensão a 3 caracteres foi removida completamente nas versões mais recentes, sendo possível usar extensões de qualquer tamanho.","A substituição da extensão original de um arquivo por outra extensão automaticamente altera o conteúdo do arquivo, pois o sistema adapta o formato de acordo com a nova extensão aplicada."],"correta":1,"explicacao":"Gabarito: <strong>No sistema operacional Windows, a remoção da extensão de um arquivo não altera sua estrutura interna, mas impede que o sistema associe automaticamente o arquivo ao programa correto para abri-lo.</strong>.","banca":"IDECAN","ano":2025,"temas_relacionados":["linux_geral"]},{"id":3292014,"enunciado":"O sistema operacional Linux é amplamente utilizado por suas funcionalidades robustas e eficientes para a manipulação de arquivos e pastas. Com comandos simples, é possível gerenciar arquivos, mover, copiar e excluir pastas. Considerando as operações básicas de gerenciamento de arquivos, assinale dentre as alternativas abaixo aquela que descreve corretamente uma ação que pode ser realizada no Linux.","opcoes":["O comando ls serve para editar o conteúdo de arquivos de texto.","O comando cp é usado para copiar arquivos de uma pasta para outra.","O comando rm é empregado para listar os arquivos de uma pasta.","O comando mkdir é utilizado para mover arquivos entre pastas."],"correta":1,"explicacao":"Gabarito: <strong>O comando cp é usado para copiar arquivos de uma pasta para outra.</strong>.","banca":"IDECAN","ano":2025,"temas_relacionados":["linux_geral"]},{"id":3295722,"enunciado":"[Questão Inédita] No Linux, o comando ls é utilizado para listar o conteúdo de diretórios e pode ser combinado com diversas opções para exibir informações específicas. Algumas dessas opções permitem visualizar arquivos ocultos, listar arquivos em ordem reversa ou exibir detalhes adicionais. Qual das alternativas lista o conteúdo do diretório atual com detalhes, incluindo permissões, tamanho, dono e data de modificação?","opcoes":["ls -a","ls ~","ls -m","ls -r","ls -l"],"correta":4,"explicacao":"Gabarito: <strong>ls -l</strong>.","banca":"Qconcursos","ano":2025,"temas_relacionados":["linux_geral"]},{"id":3355491,"enunciado":"Sobre o sistema operacional Linux e suas características, assinale a alternativa correta.","opcoes":["O Linux é um sistema fechado, mantido apenas por uma única empresa com código-fonte proprietário.","O terminal Linux é opcional e não permite executar comandos administrativos ou de sistema.","A estrutura de diretórios no Linux é baseada em uma raiz única representada pelo caractere \"/\".","As distribuições Linux não permitem personalizações no ambiente gráfico nem em permissões de usuário.","O Linux não possui suporte para redes de computadores, sendo usado apenas em dispositivos isolados."],"correta":2,"explicacao":"Gabarito: <strong>A estrutura de diretórios no Linux é baseada em uma raiz única representada pelo caractere \"/\".</strong>.","banca":"Qconcursos","ano":2025,"temas_relacionados":["linux_geral"]},{"id":3383858,"enunciado":"O sistema operacional Linux é um sistema operacional gratuito, disponibilizado sob Licença Pública Geral (GPL). Suas principais caraterísticas são","opcoes":["monotarefa, multiusuário e open source.","monotarefa, monousuário e gratuito.","multitarefa, multiusuário e open source.","monotarefa, monousuário e pago.","multitarefa, multiusuário e pago."],"correta":2,"explicacao":"Gabarito: <strong>multitarefa, multiusuário e open source.</strong>.","banca":"IV - UFG","ano":2024,"temas_relacionados":["linux_geral"]},{"id":3407062,"enunciado":"Os sabores do Ubuntu são versões oficiais do sistema operacional Ubuntu que oferecem diferentes ambientes gráficos e conjuntos de aplicativos padrão, adaptados para variadas preferências e necessidades dos usuários. Cada sabor é mantido por membros da comunidade Ubuntu e proporciona uma experiência única, garantindo compatibilidade com o mesmo repositório de software base. Entre os sabores populares estão o Kubuntu, o Xubuntu e o Lubuntu, conhecido por ser uma versão leve do Ubuntu. Considerando essas informações, qual ambiente gráfico é utilizado pelo Lubuntu?","opcoes":["GNOME","KDE Plasma","Xfce","LXQt","MATE"],"correta":3,"explicacao":"Gabarito: <strong>LXQt</strong>.","banca":"Qconcursos","ano":2025,"temas_relacionados":["linux_geral"]},{"id":3440412,"enunciado":"Com relação ao sistema operacional Linux, assinale a alternativa correta sobre o comando rm -rf /, quando executado com privilégios de superusuário (root)","opcoes":["O comando rm -rf / remove recursivamente e de forma forçada todos os arquivos e diretórios a partir da raiz do sistema, podendo inutilizar o sistema operacional.","O comando rm -rf / apaga apenas arquivos temporários no diretório raiz, sem afetar arquivos do sistema.","A opção -r no comando rm indica que o comando será executado em modo restrito, evitando exclusão acidental.","O comando rm -rf / é seguro e recomendado para liberar espaço em disco no Linux.","A execução do comando rm -rf / sem privilégios de root é suficiente para apagar todos os arquivos do sistema."],"correta":0,"explicacao":"Gabarito: <strong>O comando rm -rf / remove recursivamente e de forma forçada todos os arquivos e diretórios a partir da raiz do sistema, podendo inutilizar o sistema operacional.</strong>.","banca":"Qconcursos","ano":2025,"temas_relacionados":["linux_geral"]},{"id":3451575,"enunciado":"Uma pesquisa foi realizada entre os alunos de um curso preparatório para entender as preferências entre ser escrivão ou agente de polícia. Dos entrevistados, 28 afirmaram que preferem ser escrivães, enquanto 32 declararam que preferem ser apenas agentes. Além disso, 10 desses alunos disseram ter dúvidas sobre suas preferências.\n\n\n\n\nCom base nessa situação hipotética, julgue o item a seguir.\n\n\n\n\nO sistema operacional Linux é operado por meio de comandos no terminal e não possui ambiente gráfico como o Windows ou MacOS","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Qconcursos","ano":2024,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":3454205,"enunciado":"O sistema operacional Linux é operado por meio de comandos no terminal e não possui ambiente gráfico como o Windows ou MacOS","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Qconcursos","ano":2024,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":3522919,"enunciado":"O sistema operacional Linux contém um comando que permite executar tarefas que desativam opções administrativas ou de root. Ao usá-lo, o sistema solicitará que os usuários se autentiquem com uma senha. Em seguida, o sistema Linux deixará um registro de dados e hora como um rastreador. O comando acima é o:","opcoes":["Dif.","Mkdir.","Chmod.","Sudo.","Chown."],"correta":3,"explicacao":"Gabarito: <strong>Sudo.</strong>.","banca":"COTEC","ano":2024,"temas_relacionados":["linux_geral"]},{"id":3530272,"enunciado":"Acerca de Internet e intranet, bem como de tecnologias, ferramentas, aplicativos e procedimentos associados, julgue o próximo item. \n\n\nEm distribuições Linux, o comando ipconfig é utilizado para exibir informações de configuração de rede, como endereço IP e máscara de sub-rede; no Windows, o comando ifconfig desempenha a mesma função, permitindo a visualização e configuração de interfaces de rede.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":3572988,"enunciado":"O Linux é um sistema operacional com diversas ferramentas desenvolvidas, com base nos seus conhecimentos nessas ferramentas, é correto afirmar que","opcoes":["o “cPanel” é um painel de controle utilizado para gerenciar programas instalados no dispositivo, rede de computadores e controle de usuário local.","o “Zenmap” é uma ferramenta de GPS, utilizada para busca de endereços e localização de dispositivos em tempo real.","o “CUPS” é um serviço de impressão que você pode gerenciar impressoras e trabalhos de impressão em impressoras locais e de rede.","o “Shorewall” é uma ferramenta utilizada unicamente para controle e segurança de impressoras realizados em uma rede de computadores de usuários Linux."],"correta":2,"explicacao":"Gabarito: <strong>o “CUPS” é um serviço de impressão que você pode gerenciar impressoras e trabalhos de impressão em impressoras locais e de rede.</strong>.","banca":"Instituto UniFil","ano":2023,"temas_relacionados":["linux_geral"]},{"id":3610474,"enunciado":"Acerca dos tipos de computadores, do uso do Gmail e do sistema operacional Android, julgue o item a seguir.\n\n\n\n\nOs chromebooks são computadores que utilizam, em sua maioria, o sistema operacional Chrome OS, desenvolvido pelo Google, e são voltados para atividades online.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":3610478,"enunciado":"Acerca dos tipos de computadores, do uso do Gmail e do sistema operacional Android, julgue o item a seguir.\n\n\n\n\nO sistema operacional Android é exclusivo para os dispositivos fabricados pela Samsung, não podendo ser utilizado por outras marcas de smartphones e tablets.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":3632497,"enunciado":"Acerca do Google Workspace, dos sistemas operacionais móveis Android e iOS e das ferramentas e aplicativos de Internet e intranet, julgue o item a seguir.\n\nO sistema iOS, utilizado em iPhones, é conhecido por seu ambiente mais fechado e restritivo, exigindo‑se normalmente a App Store como fonte oficial de aplicativos.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":3632498,"enunciado":"Acerca do Google Workspace, dos sistemas operacionais móveis Android e iOS e das ferramentas e aplicativos de Internet e intranet, julgue o item a seguir.\n\nO sistema operacional Android, por padrão, só permite a instalação de aplicativos pela Play Store e impede completamente a instalação de arquivos APK externos.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":3638095,"enunciado":"Acerca dos conceitos de software, do Google Planilhas e do sistema operacional Android, julgue o item a seguir.\n\n\n\n\nNas versões mais recentes do Android, é possível configurar diferentes contas de usuário em um mesmo dispositivo, permitindo que múltiplas pessoas utilizem o aparelho com configurações e aplicativos separados.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":3699888,"enunciado":"Qual comando no Linux é usado para visualizar o espaço disponível e utilizado em discos e partições?","opcoes":["df -h","du -sh","free","memchk","diskfree"],"correta":0,"explicacao":"Gabarito: <strong>df -h</strong>.","banca":"Instituto Avalia","ano":2024,"temas_relacionados":["linux_geral"]},{"id":3741777,"enunciado":"Acerca dos sistemas operacionais e das redes de computadores, julgue o item seguinte.\n\n\n\n\nO comando  permite que o usuário tenha acesso ao histórico de itens copiados, caso essa funcionalidade esteja ativada.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":3741778,"enunciado":"Acerca dos sistemas operacionais e das redes de computadores, julgue o item seguinte.\n\n\n\n\nA fim de liberar espaço no disco, o desfragmentador de disco apaga, por padrão, os arquivos duplicados do computador do usuário.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":3771391,"enunciado":"Em relação às características técnicas e funcionais dos sistemas operacionais e das principais suítes de produtividade (Microsoft Office, LibreOffice, entre outras), bem como ao uso de navegadores de internet em ambientes computacionais diversos, assinale a alternativa que apresenta uma afirmação tecnicamente precisa.","opcoes":["A principal distinção entre navegadores como Google Chrome, Microsoft Edge e Mozilla Firefox reside no suporte ao protocolo HTTPS, sendo que apenas o Edge implementa nativamente recursos como isolamento de abas, atualizações silenciosas e proteção contra rastreamento por fingerprinting.","O Microsoft Excel, por ser proprietário e fechado, não permite exportação de planilhas para formatos abertos como .ods, o que inviabiliza a interoperabilidade com suítes livres como o LibreOffice Calc.","No ambiente Linux, não há suporte nativo para navegadores como o Mozilla Firefox, sendo necessário instalar emuladores específicos de sistemas Windows para executar navegadores modernos com compatibilidade plena de recursos multimídia.","O LibreOffice Writer possui compatibilidade limitada com os formatos .doc e .docx, sendo recomendada sua utilização apenas com arquivos nativos (.odt), uma vez que a conversão automática frequentemente compromete a integridade de fórmulas, imagens e estilos de formatação.","O sistema operacional Windows não permite que programas de código aberto, como o LibreOffice ou navegadores alternativos como o Opera, sejam instalados sem permissões administrativas avançadas, sendo necessário reconfigurar políticas de segurança nativas para sua execução."],"correta":3,"explicacao":"Gabarito: <strong>O LibreOffice Writer possui compatibilidade limitada com os formatos .doc e .docx, sendo recomendada sua utilização apenas com arquivos nativos (.odt), uma vez que a conversão automática frequentemente compromete a integridade de fórmulas, imagens e estilos de formatação.</strong>.","banca":"Unesc","ano":2025,"temas_relacionados":["linux_geral"]},{"id":3783386,"enunciado":"No sistema operacional Linux, todos os arquivos e diretórios são organizados em uma estrutura hierárquica iniciada pelo diretório raiz, representado por \"C:\\\".","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Instituto IBED","ano":2025,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":3785065,"enunciado":"Em sistemas operacionais modernos, como Windows e Linux, a gerência de arquivos é baseada em estruturas hierárquicas padronizadas, onde cada arquivo está contido dentro de um diretório específico. No entanto, ao contrário do Linux, o Windows não permite múltiplas permissões distintas sobre um mesmo arquivo para diferentes usuários, pois seu sistema de arquivos (NTFS) adota um modelo de permissões herdadas exclusivamente por grupos e não individualmente.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Instituto IBED","ano":2025,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":3785069,"enunciado":"Em sistemas operacionais modernos, como Linux e Windows, operações sobre arquivos e pastas, como exclusão ou alteração de permissões, são restritas exclusivamente a usuários com privilégios administrativos locais, sendo impossível sua delegação a usuários comuns por meio de grupos, ACLs (listas de controle de acesso) ou políticas de segurança avançadas.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Instituto IBED","ano":2025,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":3800304,"enunciado":"A utilização do sistema operacional Linux, em comparação com o Windows, oferece maior flexibilidade na instalação e personalização de drivers de hardware, demandando, no entanto, um conhecimento técnico mais aprofundado do usuário para a resolução de eventuais conflitos ou ausência de suporte nativo a determinados dispositivos.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Instituto IBED","ano":2025,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":3801933,"enunciado":"Em sistemas operacionais modernos, como Linux e Windows, tanto a estrutura hierárquica de arquivos quanto o modelo de permissões seguem padrões internacionais semelhantes, sendo que, no Windows, os usuários não conseguem atribuir permissões diferentes sobre um mesmo arquivo para grupos distintos, uma vez que o NTFS adota um modelo rígido de permissões herdadas, sem permitir personalizações refinadas como ocorre no sistema de arquivos EXT4, presente no Linux.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Instituto IBED","ano":2025,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":3815332,"enunciado":"Acerca dos tipos de computadores, do Microsoft Teams e do sistema operacional Android, julgue o item a seguir.\n\n\n\n\nO Android utiliza o sistema de arquivos NTFS como padrão, devido à sua alta compatibilidade com dispositivos externos e devido ao maior suporte às permissões de acesso.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2026,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":3815333,"enunciado":"Acerca dos tipos de computadores, do Microsoft Teams e do sistema operacional Android, julgue o item a seguir.\n\n\n\n\nO sistema Android utiliza o PM (Android Package Manager) para gerenciar a instalação, a atualização e a remoção de aplicativos, validando assinaturas digitais para garantir a integridade e a procedência do pacote (.apk).","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2026,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":3850824,"enunciado":"Assinale o protocolo utilizado para acesso remoto seguro a servidores Linux:","opcoes":["FTP.","Telnet.","HTTP.","SSH.","SMTP."],"correta":3,"explicacao":"Gabarito: <strong>SSH.</strong>.","banca":"Avança SP","ano":2026,"temas_relacionados":["linux_geral"]},{"id":3856984,"enunciado":"O sistema operacional Linux, diferentemente do Windows, não permite a utilização de interfaces gráficas, sendo sua operação restrita a comandos de texto.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Instituto IBED","ano":2026,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":3922558,"enunciado":"No sistema operacional Linux, o serviço adequado para agendar a execução de scripts de backup de forma recorrente é o","opcoes":["CUPS.","Cron.","MySQL.","Samba.","NetworkManager."],"correta":1,"explicacao":"Gabarito: <strong>Cron.</strong>.","banca":"VUNESP","ano":2026,"temas_relacionados":["linux_geral"]},{"id":3962585,"enunciado":"A partir do Android 5.0, o mecanismo SELinux opera exclusivamente em modo permissivo em versões estáveis do sistema, sendo utilizado apenas para geração de logs e auditoria, sem interferir efetivamente no controle de acesso aos recursos do sistema.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2026,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":3970683,"enunciado":"Julgue o próximo item, relativo às unidades de medida da informação, ao gerenciamento de arquivos, pastas e processos no sistema operacional Linux, e à utilização de tabelas no Microsoft Word.\n\n\n\n\nNo Linux, diretórios são considerados arquivos especiais que armazenam referências a outros arquivos e diretórios.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2026,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":3970685,"enunciado":"Julgue o próximo item, relativo às unidades de medida da informação, ao gerenciamento de arquivos, pastas e processos no sistema operacional Linux, e à utilização de tabelas no Microsoft Word.\n\n\n\n\nNo sistema operacional Linux, o comando ps é utilizado para exibir processos em execução, podendo ser combinado com opções como aux para fornecer informações detalhadas.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2026,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":3972012,"enunciado":"Acerca de tipos de computadores e dispositivos móveis, de atualização e aspectos de segurança do sistema operacional Linux e do uso de filtros no Microsoft Excel, julgue o item subsequente.\n\n\n\n\nNo Linux, a execução de atualizações de segurança dispensa a necessidade de reinicialização do sistema, mesmo quando há alterações no kernel.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2026,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":3972013,"enunciado":"Acerca de tipos de computadores e dispositivos móveis, de atualização e aspectos de segurança do sistema operacional Linux e do uso de filtros no Microsoft Excel, julgue o item subsequente.\n\n\n\n\nNo Linux, a atualização de pacotes pode ser realizada por gerenciadores como apt ou yum, que também podem aplicar correções de segurança disponibilizadas pelos repositórios oficiais.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2026,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":3974247,"enunciado":"O comando vi, no Linux, é um editor de textos ASCII poderoso e muito usado na interface de caracteres do Linux para edição de arquivos e programas. Seu uso não é muito intuitivo à primeira vista, mas a edição simples de textos pode ser feita usando poucos comandos. Para as ações “salvar arquivo”, “aplicar alinhamento à esquerda” e “localizar texto à frente” são utilizados, respectivamente, os seguintes comandos:","opcoes":[":w, :le e /texto",":s, :es e ?texto",":b, :ae e #texto",":z, :eq e &texto"],"correta":0,"explicacao":"Gabarito: <strong>:w, :le e /texto</strong>.","banca":"SELECON","ano":2026,"temas_relacionados":["linux_geral"]},{"id":3980335,"enunciado":"Gerenciar e manter sistemas operacionais como Linux e Windows é uma tarefa essencial para técnicos em informática, envolvendo atividades como instalação de atualizações, gerenciamento de usuários, serviços, segurança e backup. Considerando essas responsabilidades, analise as alternativas e escolha a que apresenta corretamente um aspecto relacionado ao gerenciamento e manutenção desses sistemas.","opcoes":["No Linux, o gerenciamento de usuários é feito exclusivamente pelo arquivo /etc/passwd, que armazena todas as senhas dos usuários do sistema em texto claro para facilitar a recuperação.","O Windows utiliza o registro do sistema operacional para armazenar configurações importantes, como contas de usuários, permissões e configurações de inicialização.","O Linux não oferece suporte a sistemas de arquivos modernos, como ext4 e Btrfs, limitandose ao sistema ext2 para armazenamento.","O Windows não possui ferramentas nativas para gerenciamento de permissões de arquivos e pastas, sendo necessário instalar softwares de terceiros."],"correta":1,"explicacao":"Gabarito: <strong>O Windows utiliza o registro do sistema operacional para armazenar configurações importantes, como contas de usuários, permissões e configurações de inicialização.</strong>.","banca":"Instituto JK","ano":2025,"temas_relacionados":["linux_geral"]},{"id":3991270,"enunciado":"Qual é a função do comando “sudo” no prompt de um sistema Linux?","opcoes":["É usado para alternar para o usuário root permanentemente.","Atualiza automaticamente o sistema operacional.","Permite a qualquer usuário executar qualquer comando sem restrições.","Executar comandos com privilégios de superusuário."],"correta":3,"explicacao":"Gabarito: <strong>Executar comandos com privilégios de superusuário.</strong>.","banca":"Instituto JK","ano":2024,"temas_relacionados":["linux_geral"]},{"id":4012993,"enunciado":"Em uma instituição de ensino superior, a equipe de TI administra estações de trabalho com Windows 11 e servidores Linux (distribuição baseada em Debian). Durante uma auditoria interna, foram discutidos aspectos relacionados a gerenciamento de processos, sistemas de arquivos, permissões, inicialização do sistema e administração de usuários. Com base nesse contexto, analise as assertivas a seguir e assinale V (verdadeira) ou F (falsa): (__) No Windows, o Gerenciador de Tarefas permite encerrar processos de usuário e visualizar consumo de CPU e memória, embora determinadas operações dependam de privilégios administrativos. (__) No Linux, o comando ls -l apresenta informações detalhadas sobre os arquivos, incluindo permissões no modelo rwx, número de links, proprietário, grupo, tamanho, data de modificação e um caractere inicial que indica o tipo do arquivo (por exemplo, arquivo regular, diretório ou link simbólico). (__) O Linux utiliza apenas o modelo básico rwx para controle de acesso, não admitindo extensões como ACLs em seus sistemas de arquivos. (__) Em distribuições Linux modernas, o processo de inicialização pode ser gerenciado pelo systemd, responsável por controlar serviços e estados do sistema. (__) No Windows, o Prompt de Comando e o PowerShell possibilitam a execução de tarefas administrativas, sendo o PowerShell orientado a objetos e integrado ao .NET. (__) Tanto no Windows quanto no Linux, usuários comuns podem alterar configurações centrais do sistema, como políticas de segurança e serviços críticos, sem qualquer mecanismo de elevação de privilégio. Assinale a alternativa que apresenta a sequência correta de V (verdadeiro) e F (falso):","opcoes":["F, V, F, V, F, V.","V, F, F, V, V, F.","V, V, F, V, F, V.","V, V, F, V, V, F.","V, V, V, F, V, F."],"correta":3,"explicacao":"Gabarito: <strong>V, V, F, V, V, F.</strong>.","banca":"IGEDUC","ano":2026,"temas_relacionados":["linux_geral"]},{"id":4042709,"enunciado":"Assinale a alternativa correta sobre instalação de programas e periféricos.","opcoes":["Drivers são programas responsáveis pela interação entre o sistema operacional e os dispositivos periféricos. Por padrão, um mesmo driver pode ser instalado em sistemas Windows e Linux.","O sistema operacional Windows já possui drivers para todo e qualquer dispositivo periférico existente, permitindo o funcionamento correto de todos os dispositivos sem a necessidade de instalação de drivers fornecidos pelos fabricantes.","As atualizações de drivers podem ser realizadas apenas através do site do fabricante, não podendo ser obtidas por meio de atualizações automáticas do sistema operacional.","Drivers são programas responsáveis pela interação entre o usuário e o sistema operacional.","Drivers genéricos oferecem uma solução padrão para dispositivos de uma mesma classe que não possuem um driver específico desenvolvido pelo fabricante ou quando o driver específico não está disponível."],"correta":4,"explicacao":"Gabarito: <strong>Drivers genéricos oferecem uma solução padrão para dispositivos de uma mesma classe que não possuem um driver específico desenvolvido pelo fabricante ou quando o driver específico não está disponível.</strong>.","banca":"COPERVE - UFSC","ano":2026,"temas_relacionados":["linux_geral"]},{"id":4076586,"enunciado":"No GNU/Linux, um instrutor deseja demonstrar aos alunos a alteração de permissões de um arquivo para que o proprietário tenha leitura, escrita e execução; o grupo tenha leitura e execução; e os demais tenham leitura. A representação numérica correspondente é:","opcoes":["764.","744.","754.","751."],"correta":2,"explicacao":"Gabarito: <strong>754.</strong>.","banca":"Instituto Fênix","ano":2026,"temas_relacionados":["linux_geral"]},{"id":4085334,"enunciado":"No Sistema Operacional Linux, o arquivo xorg.conf, utilizado na configuração do servidor X (Xwindow), é organizado em várias seções, cada uma iniciando com a palavra-chave Section e terminando com EndSection. Assinale a seção do arquivo xorg.conf que descreve parâmetros físicos do monitor, incluindo sincronização e resoluções de vídeo.","opcoes":["Device.","Screen.","Module.","Monitor."],"correta":3,"explicacao":"Gabarito: <strong>Monitor.</strong>.","banca":"Instituto Consulplan","ano":2022,"temas_relacionados":["linux_geral"]},{"id":4087179,"enunciado":"As permissões de arquivos e diretórios são fundamentais para a segurança de um sistema operacional. Considerando um Sistema Operacional Linux, derivado Debian, ao realizar um comando ls-la, foi verificada a seguinte permissão em um diretório: drwxr-xr-x Representa o octeto que aplica exatamente tal permissão a partir do comando chmod:","opcoes":["644","655","750","755"],"correta":3,"explicacao":"Gabarito: <strong>755</strong>.","banca":"Instituto Consulplan","ano":2022,"temas_relacionados":["linux_geral"]},{"id":4087180,"enunciado":"Muitas vezes é necessário, ao profissional de TI, trabalhar com sistemas operacionais em modo texto. Neste modo, a interação com o sistema se dá através de comandos, sem a possibilidade da utilização de interfaces gráficas baseadas em janelas. mv /home/usuario/*.config /etc/config/ Neste contexto, considerando um Sistema Operacional Linux, com a distribuição Debian, a linha de comando citada anteriormente move:","opcoes":["Todos os arquivos do diretório /home/usuario/ para o diretório /etc/config/","Somente os arquivos do diretório /home/usuario/ o arquivo chamado “*.config” para o diretório etc/config/","Todos os arquivos do diretório /home/usuario/ para o diretório /etc/config/, exceto os que possuem extensão .config","Os arquivos do diretório /home/usuario/ que possuem nomes terminados com o texto “.config” para o diretório etc/config/"],"correta":3,"explicacao":"Gabarito: <strong>Os arquivos do diretório /home/usuario/ que possuem nomes terminados com o texto “.config” para o diretório etc/config/</strong>.","banca":"Instituto Consulplan","ano":2022,"temas_relacionados":["linux_geral"]},{"id":4087184,"enunciado":"Diretórios permitem a organização dos arquivos em um computador. Nos sistemas operacionais, o endereço lógico de um arquivo é dado pelo caminho do diretório em que ele se encontra. Nos Sistemas Operacionais like-Unix, como o Linux, por exemplo, há uma estrutura de diretórios específica. Sobre essa estrutura, analise as afirmativas a seguir. I. No Windows, quando há mais de uma partição de disco, cada uma terá seu diretório raiz, por exemplo: C:\\ e D:\\. Enquanto no Linux, o diretório raiz é sempre o /, independente da quantidade de partições. II. Os programas ficam armazenados no diretório /lib, enquanto os arquivos do usuário se encontram em /home. III. O diretório /dev é o local de montagem de mídias removíveis que estão representados em arquivos do diretório /etc. Está correto o que se afirma em","opcoes":["I, II e III.","I, apenas.","I e III, apenas.","II e III, apenas."],"correta":1,"explicacao":"Gabarito: <strong>I, apenas.</strong>.","banca":"Instituto Consulplan","ano":2022,"temas_relacionados":["linux_geral"]},{"id":4087185,"enunciado":"Sobre as configurações de rede de um computador, marque V para as afirmativas verdadeiras e F para as falsas. ( ) O comando ifconfig exibe o endereço IPv6, a máscara de rede e o endereço MAC de uma interface de rede no Linux Debian 8. ( ) O comando ipconfig /flushdns faz a limpeza do cache de DNS do computador em um Sistema Operacional Windows. ( ) O comando ping envia um pacote para um determinado host e captura sua resposta através do protocolo ICMP. A sequência está correta em","opcoes":["V, V, V.","F, F, V.","V, V, F.","V, F, V."],"correta":0,"explicacao":"Gabarito: <strong>V, V, V.</strong>.","banca":"Instituto Consulplan","ano":2022,"temas_relacionados":["linux_geral"]},{"id":4088965,"enunciado":"Durante a instalação padrão interativa do Ubuntu 24.04.4 LTS em português do Brasil com conexão à internet, existe uma etapa que permite selecionar opções em relação à instalação de software proprietário. Assinale a alternativa que apresenta uma opção disponível nessa etapa da instalação.","opcoes":["Baixar e instalar softwares adicionais com a licença GNU GPL.","Instalar drivers de terceiros para wi-fi e placas gráficas.","Executar a instalação completa, incluindo software proprietário.","Incluir software de terceiros.","Não instalar softwares com licença do tipo Copyleft."],"correta":1,"explicacao":"Gabarito: <strong>Instalar drivers de terceiros para wi-fi e placas gráficas.</strong>.","banca":"INSTITUTO AOCP","ano":2026,"temas_relacionados":["linux_geral"]},{"id":4089427,"enunciado":"No contexto do sistema de arquivos no sistema operacional Linux (em português), diversos comandos são utilizados para manipulação de arquivos e diretórios, como criação, cópia, movimentação e visualização de conteúdo. Assinale a alternativa que apresenta corretamente o comando utilizado para criar um arquivo vazio chamado arquivo.txt no Linux.","opcoes":["touch arquivo.txt","tail arquivo.txt","cp arquivo.txt","mv arquivo.txt","less arquivo.txt"],"correta":0,"explicacao":"Gabarito: <strong>touch arquivo.txt</strong>.","banca":"INSTITUTO AOCP","ano":2026,"temas_relacionados":["linux_geral"]},{"id":4093008,"enunciado":"Em uma repartição pública, servidores utilizam diariamente computadores com Windows 10 e Linux Ubuntu 22.04. Durante um treinamento sobre gerenciamento de arquivos, o instrutor apresentou as seguintes afirmações: I - No Windows, o atalho Ctrl+X recorta um arquivo, armazenando-o na área de transferência até que seja colado com Ctrl+V. II - No Linux, assim como no Windows, a extensão do arquivo é obrigatória para que o sistema operacional identifique o tipo de arquivo, sendo impossível abrir um arquivo sem extensão. III - A compactação de arquivos no formato ZIP reduz o tamanho total, mas pode comprometer a integridade dos dados em arquivos de texto simples. IV - Tanto no Windows quanto no Linux, mover um arquivo entre pastas no mesmo dispositivo de armazenamento é mais rápido que copiar, pois apenas as referências ao arquivo são alteradas. É CORRETO o que se afirma apenas em:","opcoes":["I e IV.","II e III.","I, II e IV.","III e IV.","I, II e III."],"correta":0,"explicacao":"Gabarito: <strong>I e IV.</strong>.","banca":"CPCON","ano":2026,"temas_relacionados":["linux_geral"]},{"id":4094180,"enunciado":"Sobre versões LTS (Long-Term Support), analise a seguintes preposições. I- LTS é uma versão que recebe atualizações de segurança e correção de bugs por um período estendido, sendo ideal para ambientes críticos. II- As versões LTS sempre oferecem suporte gratuito, enquanto versões regulares requerem a compra de licenças. III- As versões LTS focam em estabilidade. Por esse motivo, oferecem interface gráfica simplificada. É CORRETO o que se afirma em:","opcoes":["II e III apenas.","I e II apenas.","I, II e III.","I apenas.","III apenas."],"correta":3,"explicacao":"Gabarito: <strong>I apenas.</strong>.","banca":"CPCON","ano":2026,"temas_relacionados":["linux_geral"]},{"id":4116108,"enunciado":"Assinale a alternativa que apresenta o único comando universal, tanto para o Windows, MacOS ou Linux que possibilita testar a velocidade de resposta de um site.","opcoes":["ping","man","more","sudo"],"correta":0,"explicacao":"Gabarito: <strong>ping</strong>.","banca":"IBFC","ano":2022,"temas_relacionados":["linux_geral"]},{"id":4132206,"enunciado":"Um usuário precisava organizar documentos de trabalho em seu computador e, para isso, realizou algumas ações tanto no Windows 11 quanto em um sistema Linux. Ele criou pastas, utilizou atalhos para acessar programas rapidamente, compactou arquivos para enviá-los por e-mail e copiou informações utilizando a área de transferência. Com base nesse cenário, assinale a alternativa correta.","opcoes":["Na área de transferência só é possível armazenar texto, impossibilitando o armazenamento de imagens ou arquivos.","Sistemas Linux não possibilitam a organização em diretórios para armazenamento de arquivos.","Os atalhos que foram criados na área de trabalho servem apenas para alterar o nome dos arquivos armazenados no computador.","Os arquivos que foram compactados só podem ser abertos no mesmo computador em que foram criados.","A compactação de arquivos auxiliou na redução do espaço ocupado, melhorando a possibilidade de compartilhamento."],"correta":4,"explicacao":"Gabarito: <strong>A compactação de arquivos auxiliou na redução do espaço ocupado, melhorando a possibilidade de compartilhamento.</strong>.","banca":"Ápice Consultoria","ano":2026,"temas_relacionados":["linux_geral"]},{"id":4135167,"enunciado":"Em um ambiente de escritório que utiliza o Linux Ubuntu, um usuário frequentemente alterna entre a interface gráfica e o terminal para realizar tarefas de organização de documentos e busca de informações. Diferente do Windows, o sistema Linux trata a localização de arquivos de forma hierárquica a partir da raiz (/). Um usuário precisa localizar rapidamente um arquivo cujo nome ele lembra parcialmente (contém a palavra \"projeto\"), dentro de uma pasta de documentos, mas não sabe em qual subdiretório ele foi salvo. Qual comando, executado via terminal, é o mais adequado para realizar essa busca de forma recursiva a partir do diretório atual?","opcoes":["cat projeto.*","find . -name \"*projeto*\"","ls -l projeto","grep \"projeto\" /","cd projeto/"],"correta":1,"explicacao":"Gabarito: <strong>find . -name \"*projeto*\"</strong>.","banca":"FAFIPA","ano":2026,"temas_relacionados":["linux_geral"]},{"id":4137218,"enunciado":"Selecione a alterativa que contém o atalho de fechamento do terminal no Linux Debian:","opcoes":["Ctrl + D (Tecla Ctrl esquerda e a tecla d).","Ctrl + T (Tecla Ctrl esquerda e a tecla t).","Ctrl + R (Tecla Ctrl esquerda e a tecla r).","Ctrl + B (Tecla Ctrl esquerda e a tecla b).","Ctrl + Q (Tecla Ctrl esquerda e a tecla q)."],"correta":0,"explicacao":"Gabarito: <strong>Ctrl + D (Tecla Ctrl esquerda e a tecla d).</strong>.","banca":"UNIFAP","ano":2022,"temas_relacionados":["linux_geral"]},{"id":4147243,"enunciado":"O repositório é uma série de endereços que permitem a gerência de pacotes instalados no sistema operacional Linux, quando estamos trabalhando com a distribuição Linux Debian 10, o arquivo nativo que é responsável por esta lista de endereços é:","opcoes":["/etc/apt/repo.list","/etc/softwares.list","/etc/sites.list","/etc/apt/sources.list","/etc/apt/update.list"],"correta":3,"explicacao":"Gabarito: <strong>/etc/apt/sources.list</strong>.","banca":"UNIFAP","ano":2022,"temas_relacionados":["linux_geral"]},{"id":4147263,"enunciado":"Assinale a alternativa que NÃO corresponde a um comando de gestão de arquivos no sistema operacional Linux Ubuntu.","opcoes":["cmp","crypt","chgrp","chmod","write"],"correta":4,"explicacao":"Gabarito: <strong>write</strong>.","banca":"UNIFAP","ano":2022,"temas_relacionados":["linux_geral"]},{"id":4147264,"enunciado":"Assinale a alternativa que NÃO é um comando de edição de texto no sistema operacional Linux Ubuntu.","opcoes":["emacs","pico","grep","sed","vim"],"correta":2,"explicacao":"Gabarito: <strong>grep</strong>.","banca":"UNIFAP","ano":2022,"temas_relacionados":["linux_geral"]},{"id":4182382,"enunciado":"A imagem representa um ícone nativo da barra de favoritos do Ubuntu Linux, observe: Com base na imagem, assinale a alternativa que indica CORRETAMENTE a função do botão selecionado.","opcoes":["Acessar as configurações de baixo nível do hardware, como a ordem de inicialização de discos, através da BIOS/UEFI.","Gerenciar o ciclo de vida das aplicações do sistema, permitindo que o usuário localize, instale, atualize e remova softwares e bibliotecas de forma centralizada.","Organizar arquivos e pastas pessoais do usuário em um ambiente puramente visual, conhecido como Área de Trabalho.","Configurar regras de filtragem de pacotes de rede e controle de portas de comunicação através do Firewall."],"correta":1,"explicacao":"Gabarito: <strong>Gerenciar o ciclo de vida das aplicações do sistema, permitindo que o usuário localize, instale, atualize e remova softwares e bibliotecas de forma centralizada.</strong>.","banca":"CONSULPAM","ano":2026,"temas_relacionados":["linux_geral"]},{"id":4182388,"enunciado":"Após a instalação do Linux Ubuntu em uma estação de trabalho, o Técnico observou três situações. Um usuário comum não conseguia gravar arquivos em um diretório utilizado por outro setor. A instalação de um pacote pela ferramenta de gerenciamento apresentava erro relacionado ao repositório configurado. Além disso, um serviço necessário para a aplicação interna não era iniciado automaticamente após a reinicialização do sistema. Diante do exposto, assinale a alternativa que indica a abordagem CORRETA para solucionar os problemas descritos.","opcoes":["A gravação no diretório deve ser corrigida apenas com a troca do nome do usuário. O erro no repositório indica falha física no disco. O serviço que não inicia automaticamente deve ser tratado pela reinstalação completa do ambiente gráfico.","A permissão de gravação deve ser analisada com base em proprietário, grupo e permissões do diretório. O erro de instalação pode exigir verificação das fontes de pacotes, conectividade e atualização dos índices. O serviço deve ser verificado quanto ao estado, habilitação na inicialização e registros de log.","A falha de gravação em diretório compartilhado deve ser resolvida com a alteração da resolução de tela. O erro no repositório decorre necessariamente de incompatibilidade do teclado. O serviço que não inicia deve ser corrigido com a troca do navegador padrão do sistema.","A permissão de gravação depende exclusivamente da senha do usuário no momento do login. O erro no repositório deve ser ignorado quando há acesso à internet pelo navegador. O serviço interno deve iniciar automaticamente sempre que o pacote estiver instalado, sem necessidade de habilitação ou análise de logs."],"correta":1,"explicacao":"Gabarito: <strong>A permissão de gravação deve ser analisada com base em proprietário, grupo e permissões do diretório. O erro de instalação pode exigir verificação das fontes de pacotes, conectividade e atualização dos índices. O serviço deve ser verificado quanto ao estado, habilitação na inicialização e registros de log.</strong>.","banca":"CONSULPAM","ano":2026,"temas_relacionados":["linux_geral"]},{"id":4182856,"enunciado":"No sistema operacional Linux, o comando “kill” é utilizado pelo usuário com o objetivo de:","opcoes":["Exibir primeiras/últimas linhas de arquivo.","Instalar/atualizar/remover pacotes.","Mostrar as configurações de rede.","Enviar sinal para finalizar um processo."],"correta":3,"explicacao":"Gabarito: <strong>Enviar sinal para finalizar um processo.</strong>.","banca":"CONSULPAM","ano":2026,"temas_relacionados":["linux_geral"]},{"id":4186924,"enunciado":"No sistema Linux, as permissões de arquivos e diretórios são representadas por um conjunto de caracteres, como -rwxr-xr--. Considerando a estrutura padrão de permissões (onde o primeiro caractere indica o tipo e os nove seguintes representam as permissões de usuário, grupo e outros), qual é o nível de acesso permitido especificamente ao grupo no exemplo acima?","opcoes":["O grupo tem permissão apenas de leitura e escrita, mas não pode executar o arquivo.","O grupo tem permissão de leitura e execução, mas não tem permissão de escrita.","O grupo tem permissão apenas de execução.","O grupo tem permissão de leitura, escrita e execução.","O grupo não tem nenhuma permissão sobre o arquivo."],"correta":1,"explicacao":"Gabarito: <strong>O grupo tem permissão de leitura e execução, mas não tem permissão de escrita.</strong>.","banca":"ISET","ano":2026,"temas_relacionados":["linux_geral"]},{"id":4187819,"enunciado":"Em ambientes Linux, o comando ls -l exibe detalhes sobre os arquivos, incluindo uma string de 10 caracteres que define as permissões de acesso. Considere um arquivo cuja permissão exibida na listagem é -rwxr-xr-x. Com base nessa representação, assinale a alternativa que descreve corretamente as permissões concedidas a cada categoria de usuário:","opcoes":["Todos os usuários (proprietário, grupo e outros) possuem permissão de leitura, escrita e execução no arquivo.","O proprietário, o grupo e os outros usuários possuem permissões completas de leitura, escrita e execução.","O proprietário possui permissões de leitura e escrita; o grupo e os outros usuários possuem permissões apenas de leitura.","O proprietário possui permissão apenas de leitura; o grupo e os outros usuários possuem permissões de escrita e execução.","O proprietário possui permissões de leitura, escrita e execução; o grupo e os outros usuários possuem permissões de leitura e execução."],"correta":4,"explicacao":"Gabarito: <strong>O proprietário possui permissões de leitura, escrita e execução; o grupo e os outros usuários possuem permissões de leitura e execução.</strong>.","banca":"ISET","ano":2026,"temas_relacionados":["linux_geral"]},{"id":4191626,"enunciado":"Em sistemas Linux, o comando mkdir permite criar diretórios tanto em partições locais quanto em diretórios montados via rede, como NFS ou SMB, respeitando as permissões do sistema de arquivos.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2026,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":4197946,"enunciado":"João foi um usuário de sistema operacional Windows durante toda a sua vida, porém agora ele decidiu experimentar o sistema operacional Ubuntu, após sugestão de seus colegas. No site do Ubuntu é possível baixar gratuitamente este sistema operacional, que é disponibilizado em um arquivo com extensão","opcoes":[".ISO",".O",".PY",".SO",".UBUNTU"],"correta":0,"explicacao":"Gabarito: <strong>.ISO</strong>.","banca":"VUNESP","ano":2023,"temas_relacionados":["linux_geral"]},{"id":4200885,"enunciado":"No gerenciamento de memória, o swapping é a técnica utilizada pelo sistema operacional para mover temporariamente um processo da memória principal para o disco quando todos os processos ativos aguardam uma operação de entrada/saída (E/S).","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2026,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":4216637,"enunciado":"Assinale a alternativa em que o primeiro item é um caminho relativo e o segundo item é um caminho absoluto, considerando a notação usual de caminhos em Windows e Linux.","opcoes":["/home/ana/Doc/relatorio.txt;","/home/ana/Doc/relatorio.txt;","C:\\Users\\Ana\\Doc\\relatorio.txt;","../Doc/relatorio.txt;","Doc\\relatorio.txt;"],"correta":4,"explicacao":"Gabarito: <strong>Doc\\relatorio.txt;</strong>.","banca":"Ápice Consultoria","ano":2026,"temas_relacionados":["linux_geral"]},{"id":4218911,"enunciado":"O MPES está evoluindo sua infraestrutura de TI com a adoção de ambientes heterogêneos baseados em Linux e Windows, exigindo da equipe técnica domínio aprofundado sobre instalação, gerenciamento de usuários, controle de privilégios e organização interna dos sistemas. Dessa forma, com base nas características de instalação e administração básica de sistemas operacionais Linux e Windows, analise as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) No Windows, o SID (Security Identifier) de um usuário é derivado do nome da conta, assim, ao excluir e recriar um usuário com o mesmo nome, o sistema reaproveita o SID anterior, preservando automaticamente as permissões associadas. ( ) No Linux, o arquivo /etc/shadow armazena hashes de senha e possui permissões restritas, enquanto o /etc/passwd é legível por usuários comuns para permitir a correta resolução de nomes de usuários e identificadores. ( ) No Linux, a aplicação do comando chmod 1777 /tmp permite que qualquer usuário crie arquivos nesse diretório, porém a exclusão ou renomeação de arquivos é restrita ao respectivo proprietário, ao proprietário do diretório ou ao superusuário. As afirmativas são, respectivamente,","opcoes":["V – F – V.","F – V – V.","F – V – F.","V – V – F.","F – F – V."],"correta":1,"explicacao":"Gabarito: <strong>F – V – V.</strong>.","banca":"FGV","ano":2026,"temas_relacionados":["linux_geral"]},{"id":4241192,"enunciado":"Julgue o item que se segue, relativos a organização e gerenciamento de informações, arquivos, pastas e programas.\n\nOs documentos pessoais dos usuários, quando se requer segurança em seu acesso, devem ficar armazenados em locais específicos: no ambiente Windows, na pasta /Windows/system; no Linux, no diretório /bin. Em ambos os casos, a organização dos arquivos se dá por meio de acesso restrito da raiz até a folha.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2015,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":4303077,"enunciado":"Quando os comandos Linux encadeados pelo pipe não produzem um resultado esperado, podem ser depurados com auxílio do comando","opcoes":["ping.","tee.","find.","whereis.","traceront."],"correta":1,"explicacao":"Gabarito: <strong>tee.</strong>.","banca":"FCC","ano":2007,"temas_relacionados":["linux_geral"]},{"id":4303078,"enunciado":"Em uma empresa que utiliza servidores Linux, a senha de root do principal servidor da rede foi perdida e é necessário entrar no servidor e configurar uma nova senha. Assinale a opção que indica o caminho correto para se configurar essa nova senha de root.","opcoes":["Iniciar o Linux em runlevel 1 e “init=/bin/sh” como opção de boot. Depois, usar o comando passwd para mudar a senha.","Ligar o servidor, pressionar Stop+A e mudar o kernel do boot.","Ligar o servidor com o disco de instalação do Linux. Depois, iniciar o console de recuperação de sistema e escolher a opção de editar arquivo /etc/passwd. Por fim, editar manualmente a senha.","Substituir o arquivo /etc/shadow por um de outro servidor.","Usar um sniffer para pegar a senha durante o boot do servidor."],"correta":4,"explicacao":"Gabarito: <strong>Usar um sniffer para pegar a senha durante o boot do servidor.</strong>.","banca":"MOVENS","ano":2010,"temas_relacionados":["linux_geral"]},{"id":4303079,"enunciado":"Sobre o Linux, responda à questão usando a imagem a seguir. Ao executar um comando nativo do Linux, o usuário obteve o retorno explicitado na imagem. Nessas condições, é correto afirmar que o comando executado foi","opcoes":["dir /opt/etc /s /w /color.","ls /opt/etc --color -a –R.","files /etc -color –s.","list /opt/etc –color.","flist --color -a –R."],"correta":1,"explicacao":"Gabarito: <strong>ls /opt/etc --color -a –R.</strong>.","banca":"CEFET-BA","ano":2013,"temas_relacionados":["linux_geral"]},{"id":4303080,"enunciado":"Na configuração do hardware no Linux, a nomenclatura padrão para designar o segundo disco rígido instalado como escravo na máquina, é:","opcoes":["hda","hdb","ext2","fd1","fd2"],"correta":2,"explicacao":"Gabarito: <strong>ext2</strong>.","banca":"FUNCAB","ano":2014,"temas_relacionados":["linux_geral"]},{"id":4303081,"enunciado":"O Linux é um sistema operacional que tem seu código fonte aberto que foi e é desenvolvido ao longo do tempo com a colaboração voluntária de desenvolvedores de várias partes do mundo. Sobre o Linux, julgue os itens que se seguem. I. Para verificar informações básicas sobre todas as interfaces de redes ativas no sistema utilizamos os comandos ifconfig e ipconfig. II. O diretório /etc contém os arquivos de dispositivos do sistema. III. Para listar o conteúdo de um diretório, emprega-se o comando ln. IV. O diretório padrão para o armazenamento de arquivos de log no linux é /var/log. Está correto o contido em","opcoes":["I e IV, apenas.","I, apenas.","I, II, III e IV.","II e III, apenas."],"correta":0,"explicacao":"Gabarito: <strong>I e IV, apenas.</strong>.","banca":"CONSESP","ano":2017,"temas_relacionados":["linux_geral"]},{"id":4303082,"enunciado":"Um usuário de computador realiza os seus trabalhos diretamente no sistema operacional Unix, por meio","opcoes":["do shell.","de um processo.","de um diretório.","de uma sessão.","do kernel."],"correta":3,"explicacao":"Gabarito: <strong>de uma sessão.</strong>.","banca":"FCC","ano":2007,"temas_relacionados":["linux_geral"]},{"id":4303083,"enunciado":"Qual das opções listadas a seguir, demonstra o resultado do comando: $ ls -l digitado em um terminal Linux:","opcoes":["lista o conteúdo de um diretório detalhadamente","lista os diretórios ocultos","volta ao diretório anterior","cria um diretório","volta para o diretório /home"],"correta":0,"explicacao":"Gabarito: <strong>lista o conteúdo de um diretório detalhadamente</strong>.","banca":"AMAUC","ano":2017,"temas_relacionados":["linux_geral"]},{"id":4303084,"enunciado":"Suponha que um usuário root da distribuição Ubuntu tenha utilizado o comando “ls –l” e como resultado tenha obtido, entre outras, a linha “drwxrwxr-x 2 root root 4096 Mar 10 09:44 teste”. Pode-se dizer que o grupo a que pertence o usuário pode acessar a pasta “teste”:","opcoes":["Apenas para execução.","Apenas para leitura.","Apenas para leitura e execução.","Apenas para execução e escrita.","Com acesso completo."],"correta":4,"explicacao":"Gabarito: <strong>Com acesso completo.</strong>.","banca":"FUNDATEC","ano":2016,"temas_relacionados":["linux_geral"]},{"id":4303085,"enunciado":"O usuário ‘luis’, que é gerente do setor de contabilidade da empresa, solicita ao administrador do servidor de arquivos (montado em um sistema Linux Ubuntu 16.04 LTS) permissões de acesso para escrita ao arquivo abaixo listado, para todos os usuário do grupo ‘contabilidade’: -rw-r----- 1 pedro controle 101 Abr 16 14:32 contratos.doc Para isso, o administrador do sistema necessita alterar o nome do grupo do arquivo para o grupo ‘contabilidade’ e alterar as permissões de grupo do arquivo para que todos os usuários do grupo ‘contabilidade’ possam ter acesso ao arquivo. As permissões do usuário ‘pedro’ ao arquivo não devem ser alteradas e outros usuários ou grupos não poderão ter acesso algum ao arquivo. Quais comandos devem ser executados pelo administrador?","opcoes":["chown contabilidade contratos.doc; chmod 777 contratos.doc","chown :contabilidade contratos.doc; chmod g+w contratos.doc","chown contabilidade: contratos.doc; chmod go+rw contratos.doc","chown contabilidade:contabilidade contratos.doc; chmod a+w contratos.doc"],"correta":1,"explicacao":"Gabarito: <strong>chown :contabilidade contratos.doc; chmod g+w contratos.doc</strong>.","banca":"UNIFAL-MG","ano":2018,"temas_relacionados":["linux_geral"]},{"id":4303086,"enunciado":"O Ubuntu Linux 14.04.1 LTS divide os arquivos do sistema em diversos diretórios, partindo do diretório raiz “/”. O diretório de configurações do sistema, o diretório dos usuários e o diretório onde são montados discos, nessa ordem, são:","opcoes":["/etc, /home, /media.","/bin, /var, /dev.","/var, /usr, /mnt.","/boot, /etc, /tmp.","/dev, /bin, /etc."],"correta":2,"explicacao":"Gabarito: <strong>/var, /usr, /mnt.</strong>.","banca":"UFES","ano":2017,"temas_relacionados":["linux_geral"]},{"id":4303087,"enunciado":"A coluna da esquerda apresenta comandos de impressão do sistema operacional Linux Ubuntu 16.04 e a da direita, funcionalidade de cada um. Numere a coluna da direita de acordo com a da esquerda. 1 - Lpq 2 - lpr 3 - lprm 4 - pr ( ) Imprime um ficheiro. ( ) Examina a spooling queue da impressora. ( ) Remove jobs da spooling queue da impressora. ( ) Pagina um ficheiro para posterior impressão. Marque a sequência correta.","opcoes":["3, 4, 2, 1","1, 3, 4, 2","2, 1, 3, 4","4, 2, 1, 3"],"correta":2,"explicacao":"Gabarito: <strong>2, 1, 3, 4</strong>.","banca":"UFMT","ano":2017,"temas_relacionados":["linux_geral"]},{"id":4303088,"enunciado":"Todas as aplicações precisam armazenar e recuperar informações. O espaço de endereçamento virtual pode ser pequeno demais para as aplicações. Além disso, as informações mantidas na memória são perdidas com o término do processo e múltiplos processos não acessam a mesma informação ao mesmo tempo. A solução para armazenar a informação em discos é criar arquivos. A informação deve ser persistente, ou seja, um arquivo desaparecerá quando for removida explicitamente. O sistema de arquivos (parte do SO) é responsável pelo modo como são estruturados, nomeados, acessados, usados, protegidos e implementados. (CASTILHO, Ana Lucia. Informática para Concursos Públicos: passo a passo. 1. ed. Policom: São Paulo, 2008.) Diante disso, considere as afirmativas a seguir, sobre sistemas de arquivos: I - FAT é a sigla para File Allocation Table (ou tabela de alocação de arquivos). O primeiro FAT surgiu em 1977, para funcionar com a primeira versão do DOS; II - As limitações do FAT, principalmente quanto à segurança, capacidade e confiança, fizeram do FAT um sistema de arquivos adequado para uso em servidores e aplicações críticas; III - O NTFS possui características importantes, que o fez ser considerado um sistema de arquivos. Entre essas qualidades estão: confiança, pois permite que o sistema operacional se recupere de problemas sem perder informações, fazendo-o ser tolerante a falhas; IV - O sistema de arquivos ext3 é basicamente o sistema de arquivos ext2 com recursos de Journaling. Está (ão) correta (s) afirmativa (s):","opcoes":["II, apenas.","I e II, apenas.","I e III, apenas.","I, II, III e IV.","I, III e IV."],"correta":0,"explicacao":"Gabarito: <strong>II, apenas.</strong>.","banca":"Master Consultoria","ano":2016,"temas_relacionados":["linux_geral"]},{"id":4303089,"enunciado":"No Linux, o comando mkdir é utilizado para:","opcoes":["Remover um arquivo/diretório.","Mostrar a quantidade de espaço usada no disco rígido.","Criar um diretório.","Listar todos os arquivos do diretório.","Acessar uma determinada pasta (diretório)."],"correta":2,"explicacao":"Gabarito: <strong>Criar um diretório.</strong>.","banca":"AMAUC","ano":2016,"temas_relacionados":["linux_geral"]},{"id":4303090,"enunciado":"Assinale a alternativa que corresponda a um Sistema Operacional que é considerado um software livre e de código aberto.","opcoes":["Java","Windows","MySQL","Linux"],"correta":2,"explicacao":"Gabarito: <strong>MySQL</strong>.","banca":"IBFC","ano":2019,"temas_relacionados":["linux_geral"]},{"id":4303091,"enunciado":"O teclado possui vários atalhos que possibilitam ao operador ou mantenedor do computador agilizar sua atividade, sem depender diretamente do mouse para isso. Dentre os atalhos muito utilizados, pode-se citar o Alt+Tab, que é um comando universal, utilizado tanto no Windows quanto no Linux, e que serve para","opcoes":["alternar entre janelas abertas sem depender de cursor.","armazenar dados na Área de Transferência.","selecionar todo o conteúdo de um documento.","transitar entre as abas de um navegador, como o Chrome."],"correta":0,"explicacao":"Gabarito: <strong>alternar entre janelas abertas sem depender de cursor.</strong>.","banca":"IV - UFG","ano":2022,"temas_relacionados":["linux_geral"]},{"id":4303092,"enunciado":"Em relação ao Domínio do ambiente Windows e Linux, analise os Sistemas Operacionais abaixo: I. Debian. II. FreeBSD. III. Ubuntu. IV. Fedora. V. MacOS. Quais NÃO possuem kernel com base Linux?","opcoes":["Apenas I e IV.","Apenas II e V.","Apenas IV e V.","Apenas I, III e IV.","Apenas II, III e V."],"correta":1,"explicacao":"Gabarito: <strong>Apenas II e V.</strong>.","banca":"FUNDATEC","ano":2023,"temas_relacionados":["linux_geral"]},{"id":4303093,"enunciado":"Em um sistema operacional Linux, qual é a função do comando sudo?","opcoes":["Mostrar informações detalhadas sobre o sistema operacional instalado.","Desligar o computador.","Exibir uma lista de processos que estão em execução.","Permitir que usuários administradores possam executar comandos como root.","Modificar as permissões de leitura, gravação e execução de um arquivo ou diretório."],"correta":3,"explicacao":"Gabarito: <strong>Permitir que usuários administradores possam executar comandos como root.</strong>.","banca":"FUNDATEC","ano":2023,"temas_relacionados":["linux_geral"]},{"id":4303094,"enunciado":"Qual comando utilizado pelo Linux para listar todos os arquivos em um diretório?","opcoes":["mv","cp","ls","rm"],"correta":2,"explicacao":"Gabarito: <strong>ls</strong>.","banca":"Instituto JK","ano":2024,"temas_relacionados":["linux_geral"]},{"id":4303095,"enunciado":"Precisa-se utilizar o sistema operacional Linux. Verifica-se que o Linux possui as seguintes características:","opcoes":["monotarefa e multitarefa","monotarefa e monousuário","multiusuário e monotarefa","multitarefa e multiusuário","monousuário e multiusuário"],"correta":3,"explicacao":"Gabarito: <strong>multitarefa e multiusuário</strong>.","banca":"COSEAC","ano":2023,"temas_relacionados":["linux_geral"]},{"id":4303096,"enunciado":"Na raiz do diretório sergipe de um computador com o sistema operacional Linux, existem dois arquivos de nomes pirambu.jpg e atalaia.jpg e um subdiretório de nome aracaju. O subdiretório aracaju está vazio. Tendo como referência as informações precedentes, julgue os itens a seguir, que apresentam procedimentos realizados por meio do prompt de comandos do Linux, depois de se acessar o diretório sergipe. I Ao digitar o comando mv atalaia.jpg /aracaju e teclar Enter, o arquivo atalaia.jpg será movido para o subdiretório aracaju, que fica dentro do diretório sergipe. II Ao digitar o comando mv pirambu.jpg aruana.jpg e teclar Enter, o arquivo pirambu.jpg será renomeado para aruana.jpg. III Ao digitar o comando cd aracaju e teclar Enter, todos os arquivos que estiverem na raiz do diretório sergipe serão copiados para o subdiretório aracaju. Assinale a opção correta.","opcoes":["Apenas o item I está certo.","Apenas o item II está certo.","Apenas os itens I e III está certo.","Apenas os itens II e III estão certos.","Todos os itens estão certos."],"correta":1,"explicacao":"Gabarito: <strong>Apenas o item II está certo.</strong>.","banca":"CESPE / CEBRASPE","ano":2022,"temas_relacionados":["linux_geral"]},{"id":4303097,"enunciado":"Um usuário de um computador, com sistema operacional Linux, precisa acessar o diretório no qual estão os arquivos de configuração para esse computador. Esse diretório é o:","opcoes":["/opt","/lib","/etc","/bin"],"correta":2,"explicacao":"Gabarito: <strong>/etc</strong>.","banca":"SELECON","ano":2023,"temas_relacionados":["linux_geral"]},{"id":4303098,"enunciado":"No contexto dos sistemas operacionais de microcomputadores e notebooks, I. um atalho de teclado é utilizado no Windows 10 BR com o objetivo e significado de permitir o acesso compartilhado aos programas abertos e em execução no sistema na modalidade multitarefa preemptiva; II. nas distribuições Linux como o Ubuntu, uma pasta ou diretório armazena as configurações e aplicativos do sistema. O atalho de teclado e a pasta descritos acima são, respectivamente:","opcoes":["Alt + F9 e /sys","Alt + F9 e /etc","Alt + Tab e /sys","Alt+Tab e/etc"],"correta":3,"explicacao":"Gabarito: <strong>Alt+Tab e/etc</strong>.","banca":"SELECON","ano":2022,"temas_relacionados":["linux_geral"]},{"id":4303099,"enunciado":"Assinale a alternativa que apresenta qual dos seguintes sistemas operacionais é de código aberto:","opcoes":["Windows Server","macOS","iOS","Windows 10","Linux"],"correta":4,"explicacao":"Gabarito: <strong>Linux</strong>.","banca":"IBFC","ano":2024,"temas_relacionados":["linux_geral"]},{"id":4303100,"enunciado":"Ubuntu é uma distribuição do sistema operacional Linux baseado em Debian, e principalmente composto por softwares livres. Alguns dos exemplos encontrados como softwares livres são:","opcoes":["LibreOffice, Paint e Word.","Internet Explorer, Word e Power Point.","Mozilla, Calc e Thunderbird.","Mozilla, Thunderbird e Excel."],"correta":2,"explicacao":"Gabarito: <strong>Mozilla, Calc e Thunderbird.</strong>.","banca":"IV - UFG","ano":2023,"temas_relacionados":["linux_geral"]},{"id":4303101,"enunciado":"Em um sistema operacional Linux, para trocar o dono de um arquivo, pode-se utilizar o comando:","opcoes":["file","who","touch","man","chown"],"correta":4,"explicacao":"Gabarito: <strong>chown</strong>.","banca":"FUNDATEC","ano":2023,"temas_relacionados":["linux_geral"]},{"id":4303102,"enunciado":"No sistema operacional Linux, em sua configuração padrão, o comando usado para criar uma pasta é o","opcoes":["mkdir","cat","cd","dir","vdir"],"correta":0,"explicacao":"Gabarito: <strong>mkdir</strong>.","banca":"VUNESP","ano":2023,"temas_relacionados":["linux_geral"]},{"id":4303103,"enunciado":"A existência de diversas distribuições de Linux e sua manutenção por organizações comerciais ou projetos comunitários é amplamente conhecida. São consideradas distribuições Linux, respectivamente:","opcoes":["Ubuntu, Debian e Opera mini.","Ubuntu, Debian e Linux Mint.","Debian, Opera mini e Linux Mint.","Debian e Opera mini."],"correta":1,"explicacao":"Gabarito: <strong>Ubuntu, Debian e Linux Mint.</strong>.","banca":"IV - UFG","ano":2023,"temas_relacionados":["linux_geral"]},{"id":4303104,"enunciado":"No que se refere aos sistemas operacionais Windows e Linux, dois componentes são caraterizados a seguir. I. Há um programa que é o firmware responsável pela execução de tarefas imprescindíveis, como o reconhecimento dos hardwares instalados, a verificação das horas no relógio interno e a inicialização do sistema operacional. II. Há um componente que representa o núcleo entre o hardware de um computador e seus processos, estabelecendo a comunicação e gerenciando recursos com a maior eficiência possível. Os componentes em I e II são denominados, respectivamente:","opcoes":["bios e kernel","kernel e swap","swap e setup","setup e bios"],"correta":0,"explicacao":"Gabarito: <strong>bios e kernel</strong>.","banca":"IDECAN","ano":2023,"temas_relacionados":["linux_geral"]},{"id":4303105,"enunciado":"Um servidor Linux de uma empresa está apresentando problemas de funcionamento. O administrador do sistema desconfia de mau uso de memória por processos. O comando do Linux que o ajudaria a verificar como os processos estão sendo executados na memória é o","opcoes":["df","ls","tar","top"],"correta":3,"explicacao":"Gabarito: <strong>top</strong>.","banca":"SELECON","ano":2023,"temas_relacionados":["linux_geral"]},{"id":4303106,"enunciado":"Um usuário deseja agendar uma rotina diária de backup de arquivos no sistema operacional Linux. Qual comando de prompt ele pode utilizar para agendar uma tarefa repetitiva de backup?","opcoes":["chmod","time","jobs","crontab","man"],"correta":3,"explicacao":"Gabarito: <strong>crontab</strong>.","banca":"FUNDATEC","ano":2023,"temas_relacionados":["linux_geral"]},{"id":4303107,"enunciado":"Analise as assertivas abaixo sobre software básico: I. O sistema operacional tem três encargos principais: gerenciar a execução de programas e ações realizadas na memória, gerenciar o armazenamento de arquivos e gerenciar as atividades de entrada e saída. II. Software básico é um conjunto de programas utilizados com um sistema de hardware para facilitar seu uso por programadores e operadores do sistema, definindo o padrão de comportando do equipamento, tornando-o utilizável. III. Software de aplicação são programas escritos para resolver problemas específicos ou que realizam funções especiais, como, por exemplo, planilhas, editores, jogos eletrônicos. Quais estão corretas?","opcoes":["Apenas I.","Apenas II.","Apenas III.","Apenas I e III.","I, II e III."],"correta":4,"explicacao":"Gabarito: <strong>I, II e III.</strong>.","banca":"FUNDATEC","ano":2023,"temas_relacionados":["linux_geral"]},{"id":4303108,"enunciado":"Qual o comando utilizado para instalar o Postfix para utilizá-lo como um servidor no Linux Debian?","opcoes":["apt-get install postfix","sudo apt-get install sendmail","apt-get install smtp","yum install postfix","sudo apt-get install qmail"],"correta":0,"explicacao":"Gabarito: <strong>apt-get install postfix</strong>.","banca":"FUNDATEC","ano":2023,"temas_relacionados":["linux_geral"]},{"id":4303109,"enunciado":"O comando Linux, que mostra os arquivos que estão na pasta em que o usuário está naquele momento, está representado na alternativa:","opcoes":["list","mv","cat","file","ls"],"correta":4,"explicacao":"Gabarito: <strong>ls</strong>.","banca":"CPCON","ano":2019,"temas_relacionados":["linux_geral"]},{"id":4303110,"enunciado":"Considere que, no sistema operacional de determinada máquina, o Gnome esteja apresentando erros quando tenta acessar os aplicativos na área de trabalho. Nesse caso, o sistema operacional instalado nessa máquina é o","opcoes":["Linux, sendo o Gnome uma forma de interação do usuário correspondente à interface da área de trabalho do Windows.","Windows 11, sendo o Gnome a interface de acesso à nuvem Azure da Microsoft.","Linux, sendo o Gnome um aplicativo para a busca de dados na plataforma Google.","Windows 10, sendo o Gnome o assistente de produtividade pessoal da Microsoft.","Windows 11, sendo o Gnome um emulador nativo voltado para sistemas Android."],"correta":0,"explicacao":"Gabarito: <strong>Linux, sendo o Gnome uma forma de interação do usuário correspondente à interface da área de trabalho do Windows.</strong>.","banca":"CESPE / CEBRASPE","ano":2022,"temas_relacionados":["linux_geral"]},{"id":4303111,"enunciado":"Assinale a alternativa que contenha o diretório, numa distribuição Linux, onde se localizam as informações sobre os recursos do sistema.","opcoes":["/root","/proc","/etc","/home"],"correta":1,"explicacao":"Gabarito: <strong>/proc</strong>.","banca":"CONSESP","ano":2018,"temas_relacionados":["linux_geral"]},{"id":4303112,"enunciado":"Ao utilizar a combinação de teclas CTRL + C no terminal do sistema operacional Linux Ubuntu, a ação será:","opcoes":["Limpo.","Copiado.","Deletado.","Cancelado."],"correta":3,"explicacao":"Gabarito: <strong>Cancelado.</strong>.","banca":"CONSULPAM","ano":2019,"temas_relacionados":["linux_geral"]},{"id":4303113,"enunciado":"No que diz respeito ao sistema operacional Linux, ao editor de texto MS Word 2016, aos conceitos de redes de computadores e ao armazenamento de dados na nuvem, julgue o item seguinte. \n\nPelo fato de ser um sistema operacional robusto, o Linux somente pode ser instalado em servidores, já que sua robustez o torna incompatível com os computadores pessoais de 32 e 64 bits.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2022,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":4303114,"enunciado":"Apt é uma ferramenta baseada em linha de comando que é usada para a manutenção de pacotes de software em sistemas Linux baseados no Debian. Sobre essa ferramenta, é INCORRETO afirmar:","opcoes":["Como parte de sua operação, o Apt utiliza um arquivo que lista as fontes (repositórios) das quais os pacotes podem ser obtidos. Este arquivo é /bin/apt/sources.list.","As ações do comando apt do mês atual, como instalação e remoção de pacotes, são registradas no arquivo de log /var/log/dpkg.log.","O comando “sudo apt update && sudo apt upgrade” irá atualizar o banco de dados de pacotes disponíveis e então atualizar os pacotes instalados no sistema.","Deve-se usar o comando “apt-get purge” caso queira remover além do pacote quaisquer arquivos deixados por este programa."],"correta":1,"explicacao":"Gabarito: <strong>As ações do comando apt do mês atual, como instalação e remoção de pacotes, são registradas no arquivo de log /var/log/dpkg.log.</strong>.","banca":"UNIOESTE","ano":2022,"temas_relacionados":["linux_geral"]},{"id":4303115,"enunciado":"Jorge, Assistente de Administração da UFRJ, precisa de uma lista com todos os documentos e diretórios contidos no seu diretório principal. Como ele usa o Sistema Operacional Linux, preferiu usar o shell (prompt de comando) para gerar a lista. Os comandos para que ele acesse seu diretório principal e gere a lista de forma ordenada com todos os documentos e subdiretórios, inclusive os ocultos, usando o shell, são, respectivamente:","opcoes":["cd ~ e iptables -L","cd /home e ls -la","cd ~ e ls -la","cd /boot/Jorge e du -h","cd /home e du -h"],"correta":2,"explicacao":"Gabarito: <strong>cd ~ e ls -la</strong>.","banca":"PR-4 UFRJ","ano":2022,"temas_relacionados":["linux_geral"]},{"id":4303116,"enunciado":"Em relação aos conceitos sobre os sistemas operacionais Linux Distribuição Ubuntu 14.10 e Windows 10 Professional, assinale a alternativa correta.","opcoes":["Se o dispositivo for perdido ou roubado, o BitLocker do Linux Distribuição Ubuntu 14.10 aciona o bloqueio do acesso aos sistemas ou dados.","O comando top do Windows 10 Professional exibe informações sobre processos em andamento e recursos do sistema, incluindo CPU, memória RAM e uso do swap, além do número total de tarefas que estão sendo executadas.","iostat, mpstat, vmstat, pidstat e sar são ferramentas de desempenho do Windows 10 Professional.","O Linux Distribuição Ubuntu 14.10 proporciona o gerenciamento de dispositivos móveis (MDM).","O comando free do Linux Distribuição Ubuntu 14.10 mostra a quantidade de memória livre e usada no sistema."],"correta":4,"explicacao":"Gabarito: <strong>O comando free do Linux Distribuição Ubuntu 14.10 mostra a quantidade de memória livre e usada no sistema.</strong>.","banca":"UFRPE","ano":2022,"temas_relacionados":["linux_geral"]},{"id":4303117,"enunciado":"O Ubuntu Linux 20.04 LTS possui quatro áreas de trabalho, de modo que um usuário possa abrir diferentes janelas de aplicativos em diferentes áreas de trabalho para organizar seu espaço. Sobre esse assunto, analise as afirmativas a seguir. I. É possível enviar uma janela de um espaço de trabalho a outro ao clicar com o botão direito do mouse sobre a barra de títulos da janela e selecionar a opção “Mover para outro espaço de trabalho”. II. Ao clicar no ícone de um aplicativo no lançador, cuja janela esteja em outro espaço de trabalho, a tela trocará automaticamente para a área correspondente. III. Os espaços de trabalho estão organizados em uma grade 2 x 2 e podem ser visualizados simultaneamente por meio do atalho de teclado Super + S. IV. É possível alternar o espaço de trabalho que está sendo exibido na tela por meio do atalho de teclado Ctrl + Alt + seta, na direção desejada. É CORRETO o que se afirma em:","opcoes":["I, II e III, apenas.","I, II e IV, apenas.","I, III e IV, apenas.","II, III e IV, apenas.","I, II, III e IV."],"correta":4,"explicacao":"Gabarito: <strong>I, II, III e IV.</strong>.","banca":"UFES","ano":2021,"temas_relacionados":["linux_geral"]},{"id":4303118,"enunciado":"No Ubuntu 20.04, o dash mostra os aplicativos em execução e os aplicativos favoritos para acesso rápido. O procedimento para se afixar um aplicativo favorito ao dash é: 1. Abra o ______________ clicando em “Atividades” no canto superior ______________ da tela. 2. Clique no ______________ no dash e localize o aplicativo que você deseja adicionar. 3. Clique com o botão ______________ no ícone do aplicativo e selecione “Adicionar aos favoritos”. A opção que preenche, correta e respectivamente, as lacunas acima é:","opcoes":["Painel de controle, esquerdo, botão de grade, esquerdo","Painel de controle, direito, Ambiente de trabalho, direito","Panorama de Atividades, esquerdo, botão de grade, direito","Menu de Configurações, esquerdo, botão de grade, esquerdo","Panorama de Atividades, direito, Ambiente de trabalho, esquerdo"],"correta":0,"explicacao":"Gabarito: <strong>Painel de controle, esquerdo, botão de grade, esquerdo</strong>.","banca":"CEFET-MG","ano":2021,"temas_relacionados":["linux_geral"]},{"id":4303119,"enunciado":"Ao visitar uma agência, um funcionário de TI de um banco percebeu, durante sua conversa com um bancário, que a cada 15 minutos, um alarme tocava no celular do empregado, e que, nesse momento, ele executava um programa no computador servidor do banco, que rodava o Linux SUSE. Descobriu, depois, que o mesmo se repetia em todas as agências. Percebendo isso como um sinal de que havia uma demanda interna de executar esse programa de tempos em tempos, o funcionário de TI resolveu mudar o processo, fazendo esse programa ser executado automaticamente de forma periódica. Para alcançar esse objetivo, esse funcionário utilizou a funcionalidade do comando","opcoes":["cron","curl","jobs","timedatectl","touch"],"correta":0,"explicacao":"Gabarito: <strong>cron</strong>.","banca":"CESGRANRIO","ano":2021,"temas_relacionados":["linux_geral"]},{"id":4303120,"enunciado":"Um Sistema Operacional pode ser definido como um programa que gerencia o computador, de modo que trabalhe de maneira correta, gerando um ambiente de comunicação, que faz a interação entre o usuário e a máquina. Dois subsistemas do Sistema Operacional desempenham essas funções; assinale-os.","opcoes":["BIOS e Setup.","Shell e Kernel.","Processador e Memória.","Registradores e Memória Cache."],"correta":1,"explicacao":"Gabarito: <strong>Shell e Kernel.</strong>.","banca":"Instituto Consulplan","ano":2020,"temas_relacionados":["linux_geral"]},{"id":4303121,"enunciado":"É possível citar como função básica de um sistema operacional:","opcoes":["Gerenciar a atualização de registros em um banco de dados.","Organizar o armazenamento de arquivos no disco rígido de um computador.","Controlar a edição de um texto.","Permitir o acesso de um usuário à Internet.","Realizar a compactação de arquivos."],"correta":1,"explicacao":"Gabarito: <strong>Organizar o armazenamento de arquivos no disco rígido de um computador.</strong>.","banca":"FADESP","ano":2021,"temas_relacionados":["linux_geral"]},{"id":4303122,"enunciado":"Quanto à utilização de recursos em sistemas operacionais Linux, dois atalhos de teclado devem ser usados nas situações listadas a seguir. I. A execução de um atalho de teclado serve para imprimir um documento ou imagem. II. A execução de outro atalho de teclado cola um item ou texto que já estiver copiado na área de transferência do sistema. Os atalhos de teclado listados em I e II são, respectivamente:","opcoes":["Ctrl + P e Ctrl + V","Ctrl + I e Ctrl + W","Alt + Pe Alt + V","Alt + I e Alt + W"],"correta":0,"explicacao":"Gabarito: <strong>Ctrl + P e Ctrl + V</strong>.","banca":"SELECON","ano":2021,"temas_relacionados":["linux_geral"]},{"id":4303123,"enunciado":"Assinale a alternativa que apresente um sistema operacional utilizado em computadores desktops:","opcoes":["Excel.","Linux.","Word.","Navegador."],"correta":0,"explicacao":"Gabarito: <strong>Excel.</strong>.","banca":"AMEOSC","ano":2019,"temas_relacionados":["linux_geral"]},{"id":4303124,"enunciado":"A respeito de Internet e de intranet, julgue o item a seguir.\n\n\n\n\nNo Linux, o comando pwd é utilizado para realizar a troca de senha das contas de usuários do sistema, ação que somente pode ser realizada por usuário que tenha determinados privilégios no ambiente para executá-la.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2021,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":4303125,"enunciado":"O Linux, sistema operacional gratuito, pode ser utilizado em substituição ao Windows, sistema operacional pago, em ambientes administrativos, atendendo muito bem as necessidades básicas dos usuários. Sobre o Linux, considere as afirmações abaixo. I O Ubuntu Linux pode ser instalado sem substituir o Windows previamente instalado na máquina, permitindo ao usuário selecionar qual sistema deseja usar ao ligar o computador. II Há programas que possuem versões compiladas para o Linux e para o Windows, tais como, o Google Chrome e o Mozilla Firefox. III O Ubuntu Linux não permite que usuários acessem arquivos compartilhados pela rede que estão em uma máquina rodando Windows, por motivos de segurança. IV Não existem vírus para Linux, o que torna esse sistema operacional bastante confiável para uso em um ambiente administrativo. Estão corretas as afirmações","opcoes":["I e IV.","I e II.","III e IV.","II e III."],"correta":1,"explicacao":"Gabarito: <strong>I e II.</strong>.","banca":"COMPERVE - UFRN","ano":2019,"temas_relacionados":["linux_geral"]},{"id":4303126,"enunciado":"No sistema operacional Linux, por padrão, um diretório armazena os arquivos pessoais, como documentos e fotografias, sempre dentro de pastas que levam o nome de cada usuário, exceção para o administrador. Esse diretório é conhecido por","opcoes":["/sys","/lib","/home","/user","/root"],"correta":2,"explicacao":"Gabarito: <strong>/home</strong>.","banca":"ACCESS","ano":2020,"temas_relacionados":["linux_geral","ortografia"]},{"id":4303127,"enunciado":"Por definição, sistema operacional constitui um programa ou um conjunto de programas, cuja função é servir de interface entre o computador e o usuário, com as funções de gerenciamento do processamento, dos dados, dos dispositivos de entrada e saída e da memória. No contexto das chamadas distros, o Linux em si é o kernel do sistema, ou seja, um software que o usuário não vê, mas que é o núcleo responsável por controlar as interações entre o hardware e outros programas da máquina. Sempre que um aplicativo recebe ou envia dados, é o kernel que traduz essas informações ao processador e outros componentes eletrônicos do computador. São exemplos de sistemas operacionais Linux, as seguintes distros:","opcoes":["Ubuntu e Fedora.","Fedora e Android.","Android e Debian.","Debian e Mozilla.","Mozilla e Ubuntu."],"correta":0,"explicacao":"Gabarito: <strong>Ubuntu e Fedora.</strong>.","banca":"ACCESS","ano":2020,"temas_relacionados":["linux_geral"]},{"id":4303128,"enunciado":"Tanto no Linux quanto no Windows, ao utilizar um dispositivo de armazenamento externo conectado via USB para acesso a arquivos e pastas nele contidos, antes de desconectá-lo do computador, deve-se \"removê-lo com segurança\". Este procedimento é necessário porque","opcoes":["o computador pode estar conectado à Internet e algum hacker pode tentar acessar os arquivos contidos no dispositivo externo, o que exige medidas adequadas para garantir a segurança dos dados.","o dispositivo externo talvez esteja sendo utilizado no momento por algum aplicativo, e a falta desse procedimento pode causar a remoção do referido aplicativo.","o dispositivo externo pode estar sendo utilizado por algum aplicativo, sendo que a remoção com segurança é necessária para evitar a perda ou o dano a arquivos contidos no dispositivo.","o ato de apenas desconectar o dispositivo fisicamente irá causar uma falha no sistema, impedindo que o usuário acesse outros dispositivos ou aplicativos instalados no computador."],"correta":0,"explicacao":"Gabarito: <strong>o computador pode estar conectado à Internet e algum hacker pode tentar acessar os arquivos contidos no dispositivo externo, o que exige medidas adequadas para garantir a segurança dos dados.</strong>.","banca":"IV - UFG","ano":2014,"temas_relacionados":["linux_geral"]},{"id":4303129,"enunciado":"Nas distribuições Linux, existem diversos comandos que facilitam a operação do sistema, para serem utilizados no modo prompt/linha de comando. Um se destina a listar todos os arquivos gravados em um diretório; enquanto o outro possibilita o acesso a um determinado diretório. Esses comandos são, respectivamente,","opcoes":["ls e md.","Is e ad.","ls e cd.","df e ad.","df e md."],"correta":2,"explicacao":"Gabarito: <strong>ls e cd.</strong>.","banca":"ACCESS","ano":2020,"temas_relacionados":["linux_geral"]},{"id":4303130,"enunciado":"Com relação a sistemas operacionais, analise as seguintes afirmações: I. Um driver é um programa que perminte que um hardware conectado ao computador, por exemplo, uma placa de vídeo ou uma impressora, funcione corretamente. II. Bluetooth é uma tecnologia de comunicação sem fio que permite conectar ao computador outros dispositivos, tais como: telefones celulares, teclados, mouses sem fio, entre outros. III. Plugin é um software que permite rastrear programas maliciosos que visam roubar número de cartão de crédito, senhas, logins, entre outros, instalados no seu computador. Está(ão) CORRETA(S) apenas:","opcoes":["I","I e II","I e III","II e III","II"],"correta":1,"explicacao":"Gabarito: <strong>I e II</strong>.","banca":"CPCON","ano":2016,"temas_relacionados":["linux_geral"]},{"id":4303131,"enunciado":"O Linux é um:","opcoes":["Sistema operacional","Browser","Editor de planilhas","Editor de textos","Banco de dados"],"correta":0,"explicacao":"Gabarito: <strong>Sistema operacional</strong>.","banca":"CPCON","ano":2015,"temas_relacionados":["linux_geral"]},{"id":4303132,"enunciado":"Sobre o comando pwd no Linux, sua execução em terminal informará:","opcoes":["Senha do usuário logado.","Lista do conteúdo de um diretório.","Total de linhas, palavras e mesmo caracteres num arquivo.","Exibe arquivos ps e pdf.","Caminho completo do diretório local."],"correta":2,"explicacao":"Gabarito: <strong>Total de linhas, palavras e mesmo caracteres num arquivo.</strong>.","banca":"UFCG","ano":2019,"temas_relacionados":["linux_geral"]},{"id":4303133,"enunciado":"O comando em Linux para informar o espaço de disco usado e disponível é:","opcoes":["df","ls","cd","cp","hd"],"correta":0,"explicacao":"Gabarito: <strong>df</strong>.","banca":"UFCG","ano":2019,"temas_relacionados":["linux_geral"]},{"id":4303134,"enunciado":"No console do sistema operacional Linux, qual é o comando que permite criar e acessar um diretório, respectivamente?","opcoes":["md e ls","mkdir e  cd","md e cd","cdir e lsdir"],"correta":1,"explicacao":"Gabarito: <strong>mkdir e  cd</strong>.","banca":"CONSESP","ano":2017,"temas_relacionados":["linux_geral"]},{"id":4303135,"enunciado":"Nas alternativas, encontram-se alguns conceitos básicos de informática, exceto:","opcoes":["Hardware são os componentes físicos do computador, ou seja, a máquina propriamente dita.","Software é o conjunto de programas que permite o funcionamento e utilização da máquina.","Entre os principais sistemas operacionais, pode-se destacar o Windows, Linux e o BrOffice.","O primeiro software necessário para o funcionamento de um computador é o Sistema Operacional.","No software livre, existe a liberdade de estudar o funcionamento do programa e de adaptá-lo as suas necessidades"],"correta":2,"explicacao":"Gabarito: <strong>Entre os principais sistemas operacionais, pode-se destacar o Windows, Linux e o BrOffice.</strong>.","banca":"MSConcursos","ano":2018,"temas_relacionados":["linux_geral"]},{"id":4303136,"enunciado":"O Microsoft Office é uma suíte (pacote) de aplicativos para escritório, líder de mercado, que contém programas como: editor e processador de textos, editor de planilhas eletrônicas, gerenciador de bancos de dados, editor de apresentações gráficas, gerenciador de e-mails, entre outros. No entanto existem outras opções de pacotes disponíveis, como por exemplo o LibreOffice, que possuem alguns aplicativos com funcionalidades equivalentes aos do Microsoft Office. Considerando o contexto apresentado, avalie as asserções a seguir e a relação proposta entre elas: I. O editor de textos WRITER e o editor de planilhas CALC, assim como o sistema operacional LINUX, são exemplos de softwares proprietários. PORQUE II. Softwares proprietários são aqueles cuja cópia, redistribuição ou modificação são em alguma medida controlados pelo seu criador ou distribuidor. Normalmente, a fim de que se possa utilizar, copiar, ter acesso ao código-fonte ou redistribuir, deve-se solicitar permissão ao proprietário, ou pagar para poder fazê-lo: será necessário, portanto, adquirir uma licença, tradicionalmente onerosa, para cada uma destas ações. A respeito das asserções I e II, é correto afirmar que:","opcoes":["as asserções I e II são proposições falsas.","a asserção I é uma proposição verdadeira, e a II é uma proposição falsa.","a asserção I é uma proposição falsa, e a II é uma proposição verdadeira.","as asserções I e II são proposições verdadeiras, e a II é uma justificativa correta da I.","as asserções I e II são proposições verdadeiras, mas a II não é uma justificativa correta da I."],"correta":3,"explicacao":"Gabarito: <strong>as asserções I e II são proposições verdadeiras, e a II é uma justificativa correta da I.</strong>.","banca":"AJURI","ano":2018,"temas_relacionados":["linux_geral"]},{"id":4303137,"enunciado":"Hoje em dia o sistema operacional Linux é muito bem reconhecido entre a comunidade de tecnologia mundial. A ideia é de um sistema gratuito que tem como principal caraterística fornecer seu código aos desenvolvedores de todo o mundo. Existem hoje diversas versões desse sistema operacional. Aponte a alternativa cujo conteúdo não apresenta uma versão/distribuição do Linux.","opcoes":["Camaleon.","Ubuntu.","Fedora.","Debian.","Mandriva."],"correta":0,"explicacao":"Gabarito: <strong>Camaleon.</strong>.","banca":"INAZ do Pará","ano":2019,"temas_relacionados":["linux_geral"]},{"id":4303138,"enunciado":"Em um sistema operacional Linux (Ubuntu 18.04, instalação padrão em português), dada a estrutura de diretórios padrão dos sistemas, os arquivos pessoais dos usuários (Documentos, Planilhas, Imagens, Vídeos) ficam em qual diretório?","opcoes":["/home","/users","/desktop","/inicio","/etc"],"correta":0,"explicacao":"Gabarito: <strong>/home</strong>.","banca":"INSTITUTO AOCP","ano":2019,"temas_relacionados":["linux_geral"]},{"id":4303139,"enunciado":"O sistema operacional é responsável por controlar todos os componentes do computador. No mercado internacional existem diversos sistemas operacional para computadores pessoais. Marque a opção que contém apenas nomes de sistemas operacionais","opcoes":["Windows, Ubuntu, Android;","IOS, Solares, PowerPoint;","Unix, Fortex, Word;","Mozilla, Edge, Opera."],"correta":0,"explicacao":"Gabarito: <strong>Windows, Ubuntu, Android;</strong>.","banca":"INSTITUTO PRÓ-MUNICÍPIO","ano":2019,"temas_relacionados":["linux_geral"]},{"id":4303140,"enunciado":"O Sistema Operacional Android é","opcoes":["baseado em núcleo Linux e é utilizado exclusivamente em celulares.","um sistema operacional proprietário e é utilizado principalmente em dispositivos móveis.","um sistema operacional proprietário e é utilizado exclusivamente em celulares.","um sistema operacional livre e é utilizado exclusivamente em celulares.","baseado em núcleo Linux e é utilizado principalmente em dispositivos móveis."],"correta":4,"explicacao":"Gabarito: <strong>baseado em núcleo Linux e é utilizado principalmente em dispositivos móveis.</strong>.","banca":"AOCP","ano":2017,"temas_relacionados":["linux_geral"]},{"id":4303141,"enunciado":"Leia a frase abaixo referente a Sistema Operacional e Software: \"Dentro dos vários Sistemas Operacionais que encontramos no mercado o _____ e o _____ se destacam atualmente.\" Assinale a alternativa que preencha correta e respectivamente as lacunas.","opcoes":["Outlook / Windows","Linux / Oracle","Oracle / Windows","Linux / Outlook","Linux / Windows"],"correta":2,"explicacao":"Gabarito: <strong>Oracle / Windows</strong>.","banca":"IBFC","ano":2020,"temas_relacionados":["linux_geral"]},{"id":4303142,"enunciado":"A respeito de componentes funcionais de computadores e do sistema operacional Linux, julgue o item a seguir.\n\n\n\n\nNo Linux, o diretório /home é o local onde é instalada a maior parte dos aplicativos e das bibliotecas do sistema operacional, enquanto no diretório /usr são armazenados os arquivos dos usuários.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2020,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":4303143,"enunciado":"O técnico de informática da empresa FRT Max foi designado a localizar dados do funcionário Pedro Roberto Borges. Considerando que o técnico já esteja no terminal Linux e na pasta em que se encontra o arquivo salarios.txt que contém tais informações, assinale a alternativa correta quanto ao comando para realizar esta pesquisa.","opcoes":["get “Pedro Roberto Borges” from salarios.txt","ls “Pedro Roberto Borges” in salarios.txt","grep “Pedro Roberto Borges” salarios.txt","locate “Pedro Roberto Borges” >> salarios.txt"],"correta":2,"explicacao":"Gabarito: <strong>grep “Pedro Roberto Borges” salarios.txt</strong>.","banca":"IBFC","ano":2019,"temas_relacionados":["linux_geral"]},{"id":4303144,"enunciado":"Considere que um usuário de um computador com sistema operacional Linux solicitou a ajuda do Auxiliar de Computação para localizar um arquivo de documento que estava editando. Para evitar interferir no ambiente gráfico do usuário, o Auxiliar abriu um terminal em modo texto pressionando a combinação de teclas:","opcoes":["Alt+F7","Alt+Tab","Ctrl+Alt+F5","Ctrl+Shift+F2","Ctrl+Tab"],"correta":2,"explicacao":"Gabarito: <strong>Ctrl+Alt+F5</strong>.","banca":"VUNESP","ano":2019,"temas_relacionados":["linux_geral"]},{"id":4303145,"enunciado":"Um Analista de TI deseja: I. Mostrar arquivos que estão na pasta em que o usuário está naquele momento, com informações detalhadas dos arquivos. II. Mostrar a pasta atual que o usuário está no momento, para auxiliar quando for salvar ou criar arquivos. III. Mostrar o conteúdo do arquivo. No Linux, para executar as ações I, II e III devem ser usados, correta e respectivamente, os comandos","opcoes":["rm  mv  cd","ls -l  pwd  cat","cp   cal  cd","cat -s   cd -l   cal","ls     rm -s    pwd"],"correta":1,"explicacao":"Gabarito: <strong>ls -l  pwd  cat</strong>.","banca":"FCC","ano":2019,"temas_relacionados":["linux_geral"]},{"id":4303146,"enunciado":"Os sistemas operacionais oferecem serviços como acesso ao ambiente computacional, execução de programas e gerenciamento de entrada e saída de dados. Assinale a opção que apresenta exemplo de sistema operacional gratuito para uso em computadores do tipo desktop.","opcoes":["Android","Apple MacOS","Linux","Microsoft Windows","IOS"],"correta":2,"explicacao":"Gabarito: <strong>Linux</strong>.","banca":"CESPE / CEBRASPE","ano":2019,"temas_relacionados":["linux_geral"]},{"id":4303147,"enunciado":"Qual é o tamanho máximo para um nome de arquivo no Linux?","opcoes":["8 caracteres.","255 caracteres.","11 caracteres.","12 caracteres.","128 caracteres."],"correta":1,"explicacao":"Gabarito: <strong>255 caracteres.</strong>.","banca":"CPCON","ano":2019,"temas_relacionados":["linux_geral"]},{"id":4303148,"enunciado":"Sobre as camadas que compõem o sistema operacional Linux pode-se afirmar que:","opcoes":["“Kernel” é a camada mais interna do sistema e tem a principal finalidade de controlar todo o tráfego de dados enviado pelo processador.","A camada mais central do sistema, também chamada de núcleo ou cerne, é a “profile”. Ela tem a incumbência de enviar os dados à camada interna.","A camada “profile”, por ser considerada uma camada interpretadora de comandos de alto nível, pode ser considerada uma linguagem de programação.","Apresenta uma camada mais externa chamada de “shell”, que é responsável pela interação entre o usuário e o sistema operacional.","Pode-se elaborar um programa em “kernel”, também chamado de “script”. Constitui-se numa ferramenta simples de construção de aplicações."],"correta":3,"explicacao":"Gabarito: <strong>Apresenta uma camada mais externa chamada de “shell”, que é responsável pela interação entre o usuário e o sistema operacional.</strong>.","banca":"INAZ do Pará","ano":2019,"temas_relacionados":["linux_geral"]},{"id":4303149,"enunciado":"Considere um computador com sistema operacional Ubuntu 16.04 em português no qual foi instalado um navegador Web diferente do navegador que acompanha o sistema. Assinale a alternativa que descreve corretamente como alterar o navegador padrão usando o aplicativo de “Configurações do sistema”, mostrado na figura abaixo.","opcoes":["Clicar no ícone “Rede” para abrir a janela de mesmo nome; selecionar a opção “Acesso à rede”; na caixa de seleção “Navegador”, selecionar o programa desejado.","Clicar no ícone “Detalhes” para abrir a janela de mesmo nome; selecionar a opção “Aplicativos padrão”; na caixa de seleção “Web”, selecionar o navegador desejado.","Clicar no ícone “Programas e atualizações” para abrir a janela de mesmo nome; na aba “Programas padrão”, selecionar o navegador desejado na caixa de seleção “Navegador”.","Clicar no ícone “Aparência” para abrir a janela de mesmo nome; na aba “Aplicativos”, selecionar o navegador desejado na caixa de seleção “Web”.","Clicar no ícone “Contas on-line” para abrir a janela de mesmo nome; selecionar a opção “Web”; na caixa de seleção “Navegador padrão”, escolher o navegador desejado."],"correta":1,"explicacao":"Gabarito: <strong>Clicar no ícone “Detalhes” para abrir a janela de mesmo nome; selecionar a opção “Aplicativos padrão”; na caixa de seleção “Web”, selecionar o navegador desejado.</strong>.","banca":"UFSC","ano":2019,"temas_relacionados":["linux_geral"]},{"id":4303150,"enunciado":"Acerca do sistema operacional Linux, do gerenciador de arquivos Windows Explorer e do Microsoft Excel 2010, julgue o item subsequente.\n\n\n\n\nHá uma diversidade grande de distribuições do sistema Linux, cada uma delas com estrutura de diretórios e kernel diferentes.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":4303151,"enunciado":"No sistema operacional Linux é possível executar diversos ambientes gráficos que fornecem os recursos necessários para uma interface (Área de Trabalho) do usuário. Marque a alternativa que NÃO é um ambiente gráfico do Linux.","opcoes":["Gnome","KDE","XFCE","iOs","Unity"],"correta":0,"explicacao":"Gabarito: <strong>Gnome</strong>.","banca":"NUCEPE","ano":2018,"temas_relacionados":["linux_geral"]},{"id":4303153,"enunciado":"A respeito de sistemas operacionais e de aplicativos de edição de textos e planilhas, julgue o item a seguir.\n\n\n\n\nWindows e Linux são exemplos de sistemas operacionais de núcleo monolítico, em que um único processo executa as principais funções.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":4303155,"enunciado":"Um sistema operacional é capaz de gerenciar hardware e software, além de interagir com o usuário. Marque abaixo a alternativa que corresponde a dois tipos de Sistemas Operacionais.","opcoes":["Windows XP e Windows Explorer","Windows 7 e Windows Explorer","Windows Vista e Ubuntu – Linux","Windows Vista e Internet Explorer","Windows Explorer e Ubuntu - Lunux"],"correta":2,"explicacao":"Gabarito: <strong>Windows Vista e Ubuntu – Linux</strong>.","banca":"EPL Concursos","ano":2013,"temas_relacionados":["linux_geral"]},{"id":4303156,"enunciado":"A respeito da estrutura de diretórios e sua principal finalidade no Linux e distribuição Ubuntu Server padrão, é correto afirmar que","opcoes":["/bin é o local onde são armazenados os links simbólicos do sistema de arquivo.","/boot é o principal local onde ficam armazenadas as chaves criptográficas de sessões de login remoto no sistema de arquivos.","/dev é o local onde se armazenam todos os arquivos de desenvolvimento.","/etc é o local onde normalmente se armazenam arquivos de configurações globais do sistema.","/home é o local onde todos os arquivos binários são armazenados."],"correta":3,"explicacao":"Gabarito: <strong>/etc é o local onde normalmente se armazenam arquivos de configurações globais do sistema.</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"temas_relacionados":["linux_geral"]},{"id":4303157,"enunciado":"No sistema operacional Linux, por meio do comando cd /iff/ digitado em um terminal, um usuário que possua todos os privilégios necessários poderá","opcoes":["listar o conteúdo do diretório iff.","compactar o diretório iff.","remover o diretório iff.","criar o diretório iff.","abrir o diretório iff."],"correta":4,"explicacao":"Gabarito: <strong>abrir o diretório iff.</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"temas_relacionados":["linux_geral"]},{"id":4303158,"enunciado":"Utilizando o console de uma distribuição Linux, um usuário executou, em um diretório específico, o comando ls – l e obteve como saída a seguinte linha. Considerando-se essas informações, é correto afirmar que","opcoes":["docentes.pdf é um arquivo do tipo executável.","o primeiro termo iff se refere a um diretório, enquanto o segundo termo iff se refere ao usuário que criou esse diretório.","4096 se refere à quantidade de usuários que acessaram o arquivo docentes.pdf.","rw–r– –r– – se refere às permissões sobre o arquivo docentes.pdf.","todos os usuários que fazem parte do grupo iff podem editar o arquivo docentes.pdf."],"correta":3,"explicacao":"Gabarito: <strong>rw–r– –r– – se refere às permissões sobre o arquivo docentes.pdf.</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"temas_relacionados":["linux_geral"]},{"id":4303159,"enunciado":"A Área de Transferência é um recurso utilizado por sistemas operacionais, como o Windows e o Linux, para que pequenas quantidades de dados sejam armazenadas para posteriormente serem transferidas apenas entre","opcoes":["aplicativos.","mensagens de e-mails ou documentos.","documentos ou aplicativos.","mensagens de e-mails.","documentos."],"correta":2,"explicacao":"Gabarito: <strong>documentos ou aplicativos.</strong>.","banca":"VUNESP","ano":2018,"temas_relacionados":["linux_geral"]},{"id":4303160,"enunciado":"Muitas vezes um usuário do sistema operacional Linux Ubuntu precisa executar programas com permissão de superusuário. Para isso, ele pode usar o comando","opcoes":["root.","chmod.","sudo.","chown."],"correta":2,"explicacao":"Gabarito: <strong>sudo.</strong>.","banca":"IV - UFG","ano":2018,"temas_relacionados":["linux_geral"]},{"id":4303161,"enunciado":"O CentOS (Community Enterprise Operating System) é uma distribuição Linux de classe Enterprise, derivada de códigos-fonte, gratuitamente fornecidos pela distribuição","opcoes":["Gentoo.","Kurumin.","Red Hat.","Slackware.","Ubuntu."],"correta":2,"explicacao":"Gabarito: <strong>Red Hat.</strong>.","banca":"FAURGS","ano":2014,"temas_relacionados":["linux_geral"]},{"id":4303162,"enunciado":"Os comandos para deletar um arquivo em um utilitário de linha de comando no Windows e no Linux são, respectivamente,","opcoes":["del e delete.","del e rm.","delete e remove.","del e remove.","delete e rm."],"correta":1,"explicacao":"Gabarito: <strong>del e rm.</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"temas_relacionados":["linux_geral"]},{"id":4303163,"enunciado":"Sistemas Operacionais não proprietários com base Linux têm diversas vantagens, sendo a principal delas, a opção de não pagar licença de instalação e uso. Todas as alternativas a seguir apresentam distribuições LINUX não proprietárias, EXCETO:","opcoes":["Ubuntu","Slackware.","OS X.","OpenSuse.","Fedora."],"correta":2,"explicacao":"Gabarito: <strong>OS X.</strong>.","banca":"PR-4 UFRJ","ano":2017,"temas_relacionados":["linux_geral"]},{"id":4303164,"enunciado":"A distribuição do Linux de código aberto que se caracteriza por ser não comercial, amplamente utilizada e baseada na Debian/GNU, denomina-se","opcoes":["Linspire.","Fedora","Slackware Linux.","Ubuntu.","Gentoo Linux."],"correta":3,"explicacao":"Gabarito: <strong>Ubuntu.</strong>.","banca":"CESPE / CEBRASPE","ano":2017,"temas_relacionados":["linux_geral"]},{"id":4303165,"enunciado":"São extensões de arquivos nativos e comumente utilizados por aplicativos do Sistema Operacional Linux:","opcoes":[".deb, .odt, .ods, .rpm",".pdf, .doc, .cad, .xls",".exe, .txt, .pdf, .cad",".deb, .pdf, .cad, .exe"],"correta":0,"explicacao":"Gabarito: <strong>.deb, .odt, .ods, .rpm</strong>.","banca":"UFV","ano":2016,"temas_relacionados":["linux_geral"]},{"id":4303166,"enunciado":"O Ubuntu Linux 16.04.2 LTS possui um navegador de arquivos chamado Nautilus. Considere que esse navegador de arquivos esteja exibindo o conteúdo da pasta pessoal do usuário e que, nessa pasta, exista um arquivo chamado Documento. Uma forma de fazer com que esse se torne um arquivo oculto é","opcoes":["clicar com o botão direito sobre o arquivo, selecionar Propriedades e marcar a opção Oculto.","acessar o menu de aplicativo Editar e selecionar o item Ocultar arquivo.","abrir uma janela do terminal e utilizar o comando hide Documento.","clicar com o botão direito sobre o arquivo e selecionar Ocultar arquivo.","renomeá-lo, inserindo um ponto antes de seu nome: .Documento."],"correta":4,"explicacao":"Gabarito: <strong>renomeá-lo, inserindo um ponto antes de seu nome: .Documento.</strong>.","banca":"UFES","ano":2017,"temas_relacionados":["linux_geral"]},{"id":4303167,"enunciado":"Na estrutura de diretórios do sistema operacional Linux, os diretórios /tmp e /dev são destinados, respectivamente, a","opcoes":["arquivos variáveis, ou seja, passíveis de mudanças, como arquivos de logs do sistema; e armazenamento de informações referentes aos usuários do sistema operacional.","arquivos temporários; e arquivos de configurações específicas de programas.","processos que estejam sendo executados; e arquivos de dispositivos.","arquivos temporários; e arquivos de dispositivos."],"correta":3,"explicacao":"Gabarito: <strong>arquivos temporários; e arquivos de dispositivos.</strong>.","banca":"CESPE / CEBRASPE","ano":2017,"temas_relacionados":["linux_geral"]},{"id":4303168,"enunciado":"Com relação aos sistemas operacionais Linux e Windows e seus programas, avalie as afirmações abaixo e marque (V) para verdadeiro ou (F) para falso. ( ) O arquivo de instalação do Microsoft Office para o Windows é o mesmo para o Linux. ( ) O navegador web Google Chrome pode ser instalado tanto no Windows quanto no Linux. ( ) A ferramenta de escritório LibreOffice pode ser instalada tanto no Windows quanto no Linux. Com relação às afirmações, a sequência correta é","opcoes":["V, V, F.","F, V, F.","V, F, F","F, F, V.","F, V, V."],"correta":4,"explicacao":"Gabarito: <strong>F, V, V.</strong>.","banca":"FCM","ano":2017,"temas_relacionados":["linux_geral"]},{"id":4303169,"enunciado":"Com relação aos sistemas operacionais Linux e Windows, avalie as afirmações abaixo e marque (V) para verdadeiro ou (F) para falso. ( ) Os sistemas Linux e Windows podem estar instalados, ao mesmo tempo, em um único computador. ( ) O gerenciador de arquivos do Windows utiliza a combinação de teclas Ctrl+X como atalho de teclado para a operação de recortar um arquivo ou uma pasta. ( ) A compactação de um arquivo, utilizando o gerenciador de arquivos do Linux, move automaticamente para a Lixeira o arquivo descompactado. De acordo com as afirmações, a sequência correta é","opcoes":["V, V, F.","F, V, F.","V, F, F.","F, F, V.","F, V, V."],"correta":0,"explicacao":"Gabarito: <strong>V, V, F.</strong>.","banca":"FCM","ano":2017,"temas_relacionados":["linux_geral"]},{"id":4303170,"enunciado":"Com relação aos Sistemas Operacionais Windows e Linux, marque (V) para as afirmativas VERDADEIRAS e (F) para as FALSAS. ( ) Pelo Dual Boot, é possível instalar mais de um sistema operacional no mesmo disco rígido. ( ) O Windows é classificado como sistema operacional monotarefa, pois apenas a tarefa da janela ativa é executada em um determinado instante, enquanto as demais tarefas ficam aguardando para serem executadas. ( ) O Linux é classificado como sistema operacional multitarefa e a distribuição do tempo compartilhado entre os processos é feita de modo que o usuário tenha a impressão de que diversos processos estão sendo executados simultaneamente. ( ) Os sistemas operacionais Linux e Windows são classificados como livres e seus códigos-fontes podem ser baixados da internet sem nenhum custo. Assinale a alternativa que contém a sequência CORRETA, de cima para baixo.","opcoes":["F, F, V, F","V, F, V, F","F, V, F, V","V, F, F, V","F, V, V, F"],"correta":1,"explicacao":"Gabarito: <strong>V, F, V, F</strong>.","banca":"IFB","ano":2016,"temas_relacionados":["linux_geral"]},{"id":4303171,"enunciado":"Com relação ao sistema operacional Linux, ao editor de texto Microsoft Office Word 2013 e ao programa de navegação Microsoft Internet Explorer 11, julgue o próximo item.\n\nO sistema operacional Linux, embora seja amplamente difundido, está indisponível para utilização em computadores pessoais, estando o seu uso restrito aos computadores de grandes empresas.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2016,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":4303172,"enunciado":"A respeito de sistemas operacionais, julgue o item a seguir.\n\nOs drivers para uso no sistema operacional Windows são desenvolvidos pelos fabricantes e precisam ser instalados manualmente, após a instalação do sistema operacional. No Linux, os drivers são incorporados diretamente ao kernel e vêm pré-instalados no sistema.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":4303173,"enunciado":"O Campus Caruaru recebeu da Reitoria do IFPE um computador já instalado em dualboot (Windows 7 e Ubuntu Desktop 15.10). O técnico em TI precisa configurar para que ambos os sistemas operacionais acessem a rede Wi-Fi chamada CampusCaruaruSecretaria, com segurança WPA2. Tomando como base esse cenário, analise as afirmações abaixo. I. Para conectar à rede sem fio CampusCaruaruSecretaria no Ubuntu, vá à Configuração do Sistema, abra as configurações de rede, escolha a opção 'rede sem fio', procure pelo nome da rede na lista de redes, selecione a segurança WPA2 e clique em 'conectar'. II. Na Configuração do Sistema no Ubuntu, abra as configurações de rede, escolha a opção 'rede sem fio', procure por CampusCaruaruSecretaria na lista de redes, digite a senha e clique em 'conectar'. III. No terminal do Ubuntu, executar o comando 'ifconfig -eth0 -connect CampusCaruaruSecretaria wpa2' para conectar à rede sem fio do Campus. IV. Para o Windows, basta clicar no ícone de rede para abrir o 'Conectar a uma Rede', escolher na lista de redes aquela que deseja conectar, selecionar a opção 'WPA2' e, então, clicar em 'conectar'. V. Para o Windows, clique no ícone de rede para abrir o 'Conectar a uma Rede', escolha na lista de redes aquela que deseja conectar, informe a senha da rede e clique em 'conectar'. Assinale a alternativa que melhor representa o procedimento para conectar ambos os sistemas operacionais à rede CampusCaruaruSecretaria.","opcoes":["I e IV.","II e V.","III e IV.","III e V.","II e IV."],"correta":1,"explicacao":"Gabarito: <strong>II e V.</strong>.","banca":"IF-PE","ano":2016,"temas_relacionados":["linux_geral"]},{"id":4303174,"enunciado":"A respeito de conceitos de ambientes Windows e Linux, julgue o próximo item.\n\nArquivos criados no ambiente Linux não podem ser lidos por aplicativos que sejam executados no Windows XP, a menos que a versão do arquivo seja do tipo xdtl.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":4303175,"enunciado":"No ambiente Linux, o comando $ ls:","opcoes":["Mostra a quantidade de espaço usada no disco rígido.","Mostra o uso da memória.","Lista todos os arquivos do diretório.","Abre um arquivo.","Abre o explorador de informações."],"correta":4,"explicacao":"Gabarito: <strong>Abre o explorador de informações.</strong>.","banca":"UFCG","ano":2016,"temas_relacionados":["linux_geral"]},{"id":4303176,"enunciado":"São características do sistema operacional Linux, EXCETO:","opcoes":["Conectividade com outros tipos de plataformas como: Windows, Apple, DOS.","Não é Case Sensitive.","Multiusuário.","Preemptivo.","Proteção entre processos executados na memória RAM."],"correta":1,"explicacao":"Gabarito: <strong>Não é Case Sensitive.</strong>.","banca":"UFCG","ano":2016,"temas_relacionados":["linux_geral"]},{"id":4303177,"enunciado":"Para aferir o uso da CPU e da memória de uma estação de trabalho instalada com Linux, deve(m) ser utilizado(s) o(s) comando(s)","opcoes":["top.","system.","proc e mem.","cpu e memory.","fs e du."],"correta":0,"explicacao":"Gabarito: <strong>top.</strong>.","banca":"CESPE / CEBRASPE","ano":2016,"temas_relacionados":["linux_geral"]},{"id":4303178,"enunciado":"O diretório /home, que faz parte da estrutura do Linux, definida no momento da instalação desse sistema,","opcoes":["armazena os arquivos dos dispositivos do sistema.","é o diretório de trabalho do usuário.","contém os arquivos de inicialização do sistema.","armazena as ferramentas de administração do sistema.","contém os arquivos de configuração dos principais serviços."],"correta":1,"explicacao":"Gabarito: <strong>é o diretório de trabalho do usuário.</strong>.","banca":"CESPE / CEBRASPE","ano":2016,"temas_relacionados":["linux_geral"]},{"id":4303179,"enunciado":"No sistema operacional Linux, qual o comando para mover todos os arquivos com extensão .jpg de uma pasta com muitos arquivos para outra?","opcoes":["$ vm *.jpg /outra-pasta","$ mv *.jpg /outra-pasta","$ rd *.jpg /outra-pasta","$ cp *.jpg /outra-pasta"],"correta":1,"explicacao":"Gabarito: <strong>$ mv *.jpg /outra-pasta</strong>.","banca":"UFMT","ano":2015,"temas_relacionados":["linux_geral"]},{"id":4303180,"enunciado":"Assinale a opção que apresenta o comando que um usuário deve utilizar, no ambiente Linux, para visualizar, em um arquivo de texto (nome-arquivo), apenas as linhas que contenham determinada palavra (nome-palavra).","opcoes":["pwd nome-arquivo | locate nome-palavra","find nome-palavra | ls -la nome-arquivo","cat nome-arquivo | grep nome-palavra","lspci nome-arquivo | find nome-palavra","cd nome-arquivo | search nome-palavra"],"correta":2,"explicacao":"Gabarito: <strong>cat nome-arquivo | grep nome-palavra</strong>.","banca":"CESPE / CEBRASPE","ano":2016,"temas_relacionados":["linux_geral"]},{"id":4303181,"enunciado":"Assinale a opção que apresenta o comando por meio do qual um usuário poderá criar um arquivo vazio com o nome arquivo.txt no sistema operacional Linux.","opcoes":["pwd > arquivo.txt","echo \"oi mundo\" > arquivo.txt","grep 'root' /etc/passwd > arquivo.txt","touch arquivo.txt","ls –la /home > arquivo.txt"],"correta":2,"explicacao":"Gabarito: <strong>grep 'root' /etc/passwd > arquivo.txt</strong>.","banca":"CESPE / CEBRASPE","ano":2016,"temas_relacionados":["linux_geral"]},{"id":4303182,"enunciado":"Assinale a opção que apresenta o comando, no sistema operacional Linux, que deve ser utilizado para determinar quanto espaço em disco está sendo ocupado por um diretório e seus subdiretórios.","opcoes":["pwd","file","du","head","lshw"],"correta":2,"explicacao":"Gabarito: <strong>du</strong>.","banca":"CESPE / CEBRASPE","ano":2016,"temas_relacionados":["linux_geral"]},{"id":4303183,"enunciado":"Relacione as duas colunas quanto as características dos Sistemas Operacionais: (1) Windows (2) Linux (A) sistema operacional proprietário. (B) sistema operacional muito seguro. (C) sistema operacional de código aberto. (D) sistema de arquivos típico: NTFS Assinale a alternativa correta:","opcoes":["1B-1D-2A-2C","1 A -1C -2 B-2D","1 A -1D -2 B-2C","1A- 1B-2C-2D"],"correta":2,"explicacao":"Gabarito: <strong>1 A -1D -2 B-2C</strong>.","banca":"IBFC","ano":2015,"temas_relacionados":["linux_geral"]},{"id":4303184,"enunciado":"Em um sistema operacional Linux já instalado e configurado em um computador, um usuário com direitos de root criou novos usuários, que por padrão cria seus respectivos diretórios. Assinale a opção que apresenta a localização padrão em que são criados os diretórios particulares dos usuários.","opcoes":["/home","/var","/opt","/tmp","/usr/sbin"],"correta":0,"explicacao":"Gabarito: <strong>/home</strong>.","banca":"CESPE / CEBRASPE","ano":2015,"temas_relacionados":["linux_geral"]},{"id":4303185,"enunciado":"Julgue o item subsecutivo acerca de computação na nuvem, de conceitos de organização e gerenciamento de arquivos e de segurança da informação.\n\nPara que um arquivo seja executado por usuário no ambiente Linux, é suficiente acrescentar a extensão sh ao arquivo para torná-lo executável.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2015,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":4303186,"enunciado":"A principal característica que define um software livre é:","opcoes":["estar disponível para download.","rodar no sistema operacional Linux.","ser gratuito.","ser multiplataforma.","ter código fonte aberto."],"correta":3,"explicacao":"Gabarito: <strong>ser multiplataforma.</strong>.","banca":"FGV","ano":2010,"temas_relacionados":["linux_geral"]},{"id":4303187,"enunciado":"Quanto as características dos Sistemas Operacionais, analise as afirmativas abaixo, dê valores Verdadeiro (V) ou Falso (F) e assinale a alternativa que apresenta a seqüência correta (de cima para baixo): ( ) 0 Windows é considerado um Sistema Operacional proprietário. ( ) O Linux somente funciona com processadores da Intel.","opcoes":["V - V","V - F","F - V","F - F"],"correta":1,"explicacao":"Gabarito: <strong>V - F</strong>.","banca":"IBFC","ano":2015,"temas_relacionados":["linux_geral"]},{"id":4303188,"enunciado":"A respeito dos sistemas operacionais Linux e Windows, do Microsoft PowerPoint 2013 e de redes de computadores, julgue o item a seguir.\n\n\n\n\nNo console de uma distribuição qualquer do Linux, como, por exemplo, o Ubuntu, é possível cancelar um comando em execução a partir do uso da combinação das teclas .","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2015,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":4303189,"enunciado":"A árvore de diretório do Sistema Operacional Linux possui diretórios específicos para o funcionamento, configuração e carga do sistema. Sobre o diretório /etc é CORRETO afirmar que possui:","opcoes":["os comandos necessários durante a inicialização do sistema.","os arquivos de dispositivos.","os arquivos necessários de configuração específicos da máquina.","as bibliotecas compartilhadas."],"correta":2,"explicacao":"Gabarito: <strong>os arquivos necessários de configuração específicos da máquina.</strong>.","banca":"FIDESA","ano":2012,"temas_relacionados":["linux_geral"]},{"id":4303190,"enunciado":"No Sistema Operacional Linux, o acesso remoto via linha de comando a computadores e a listagem dos arquivos que fazem parte do diretório local atual podem ser feitos, respectivamente, por meio dos comandos","opcoes":["https, dir","ftp, passwd","http, more","ssh, ls","telnet, chmod"],"correta":3,"explicacao":"Gabarito: <strong>ssh, ls</strong>.","banca":"CEFET-MG","ano":2014,"temas_relacionados":["linux_geral"]},{"id":4303191,"enunciado":"O sistema operacional é o software responsável pelo gerenciamento do hardware e também atua como interface entre o homem e a máquina. O Linux e o Windows XP são bons exemplos de sistemas operacionais, e ambos possibilitam a manipulação de arquivos e diretórios, tais como criar, copiar, apagar e mover. Comuns em distribuição Linux, os seguintes comandos são usados para criar diretórios e copiar arquivos, respectivamente:","opcoes":["md e copy","mkdir e cp","make e copy","mdiretory e copyfile"],"correta":1,"explicacao":"Gabarito: <strong>mkdir e cp</strong>.","banca":"UEG","ano":2008,"temas_relacionados":["linux_geral"]},{"id":4303192,"enunciado":"Acerca de conceitos de informática, julgue o item a seguir.\nPor ser o Linux o kernel, ou seja, o sistema operacional em si, para que ele funcione, será necessária a sua instalação em conjunto com outros aplicativos ou utilitários, especialmente em distribuições como Debian e Ubuntu.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":4303193,"enunciado":"No Linux, o comando rm eventos.odt:","opcoes":["apaga o diretório eventos.odt.","renomeia o arquivo eventos para odt.","move o arquivo eventos.odt para o diretório imediatamente acima.","restringe o direito de acesso ao arquivo eventos.odt.","apaga o arquivo eventos.odt no diretório atual."],"correta":4,"explicacao":"Gabarito: <strong>apaga o arquivo eventos.odt no diretório atual.</strong>.","banca":"FUNCAB","ano":2014,"temas_relacionados":["linux_geral"]},{"id":4303194,"enunciado":"No Linux, é uma maneira de compartilhar arquivos como Windows por meio de um servidor de arquivos:","opcoes":["Squid.","LILO.","KDE.","GRUB.","Samba."],"correta":4,"explicacao":"Gabarito: <strong>Samba.</strong>.","banca":"FUNCAB","ano":2014,"temas_relacionados":["linux_geral"]},{"id":4303195,"enunciado":"Acerca dos sistemas operacionais Windows e Linux, julgue o item subsequente.\n\nNo Linux, o comando free -cpu exibe em tempo real informações acerca do sistema, tais como processos em andamento, recursos do sistema e uso do swap, além do número total de tarefas que estiverem sendo executadas.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":4303196,"enunciado":"Numa instalação Unix (ou Linux), o comando cat xxx1 xxx2 > xxx3 provoca:","opcoes":["a cópia dos arquivos xxx1 e xxx2 para a pasta xxx3;","a criação da pasta xxx3 contendo cópias dos arquivos xxx1 e xxx2;","a anexação do conteúdo dos arquivos xxx1 e xxx2, nessa ordem, ao arquivo xxx3;","a gravação do arquivo xxx3 com o conteúdo dos arquivos xxx1 e xxx2;","a transferência dos arquivos das pastas xxx1 e xxx2 para a pasta xxx3."],"correta":3,"explicacao":"Gabarito: <strong>a gravação do arquivo xxx3 com o conteúdo dos arquivos xxx1 e xxx2;</strong>.","banca":"FGV","ano":2014,"temas_relacionados":["linux_geral"]},{"id":4303197,"enunciado":"Em um computador com o sistema operacional Linux, é possível criar várias contas de usuários e armazenar os dados de configuração referentes a essas contas em um único diretório — /home/users.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":4303198,"enunciado":"Assinale a alternativa que descreve o resultado da execução do seguinte comando em um ambiente Linux: cp /home/ocorrencias.txt /home/backup Considere que a pasta /home/backup está vazia, e que as permissões de acesso e o espaço em disco são suficientes para a ação.","opcoes":["Uma cópia do arquivo ocorrencias.txt será enviada para a pasta /home/backup.","O arquivo ocorrencias.txt será renomeado para backup.","O arquivo ocorrencias.txt será apagado da pasta /home e da pasta /home/backup.","O arquivo ocorrencias.txt será apagado da pasta /home, apenas.","O arquivo ocorrencias.txt será apagado da pasta /home e uma cópia será enviada para a pasta /home/backup."],"correta":0,"explicacao":"Gabarito: <strong>Uma cópia do arquivo ocorrencias.txt será enviada para a pasta /home/backup.</strong>.","banca":"VUNESP","ano":2014,"temas_relacionados":["linux_geral"]},{"id":4303199,"enunciado":"Com relação ao sistema operacional Linux, assinale a opção correta.","opcoes":["Para acessar o diretório /TJCE por meio do Linux, o usuário pode fazer uso dos comandos cd /TJCE ou cd /tjce.","Por questões de segurança, no sistema Linux, um usuário simples pode fazer parte do grupo de qualquer outro usuário, mas não pode ser adicionado ao grupo root.","No Linux, um usuário pode abrir diversas sessões de trabalho, embora não lhe seja permitido manter abertas sessões no modo texto e no modo gráfico em um mesmo computador.","No sistema Linux, é possível criar arquivos com nomes extensos, como, por exemplo: Tabelas_de_Custas_Processuais_do_Tribunal_de_ Justica_do_Estado_do_Ceara.odt.","As informações referentes às configurações de um programa são armazenadas em arquivos de texto no sistema Linux, em um único local: /etc/config."],"correta":3,"explicacao":"Gabarito: <strong>No sistema Linux, é possível criar arquivos com nomes extensos, como, por exemplo: Tabelas_de_Custas_Processuais_do_Tribunal_de_ Justica_do_Estado_do_Ceara.odt.</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"temas_relacionados":["linux_geral"]},{"id":4303200,"enunciado":"Com relação aos sistemas operacionais Windows e Linux, julgue os itens subsecutivos.\n\nNo Linux, o comando cat arq1 >> arq2 | less lista o conteúdo dos arquivos arq1 e arq2 com paginação das telas.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":4303201,"enunciado":"No que diz respeito aos sistemas operacionais Windows e Linux, julgue os próximos itens.\n\n\nNo ambiente Linux, é possível utilizar comandos para copiar arquivos de um diretório para um pen drive.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":4303202,"enunciado":"O sistema operacional cujas características são utilizar código aberto e interface por linha de comando é o.","opcoes":["Mac OS","iOS","Linux","Windows","Android"],"correta":2,"explicacao":"Gabarito: <strong>Linux</strong>.","banca":"CESGRANRIO","ano":2014,"temas_relacionados":["linux_geral"]},{"id":4303203,"enunciado":"Assinale a opção correta no que se refere aos sistemas operacionais Windows e Linux","opcoes":["O comando 1s~ do Linux Ubuntu faz que sejam mostrados todos os arquivos ocultos gravados no diretório corrente","O Windows RT é projetado para ser usado em trânsito, pois executa somente aplicativos internos ou baixados da Windows Store, tendo sido otimizado para PCs leves e dinâmicos.","O Windows 8 é voltado para computadores com monitores touch-screen e para tablets, que têm como modo de entrada apenas o teclado e os dispositivos de toque.","O Windows Vista possui tela inicial com atualizações dinâmicas por padrão e configurações pessoais que podem ser compartilhadas em computadores diferentes.","A desinstalação de programas no Linux só pode ser feita por meio de comandos digitados na shell com a senha de root."],"correta":1,"explicacao":"Gabarito: <strong>O Windows RT é projetado para ser usado em trânsito, pois executa somente aplicativos internos ou baixados da Windows Store, tendo sido otimizado para PCs leves e dinâmicos.</strong>.","banca":"CESPE / CEBRASPE","ano":2013,"temas_relacionados":["linux_geral"]},{"id":4303205,"enunciado":"Fedora, OS X, Red Hat, Solaris e Ubuntu são sistemas operacionais que utilizam kernel Linux.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2013,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":4303208,"enunciado":"Com referência à suíte de aplicativos LibreOffice, julgue o item abaixo.\n\nO LibreOffice é uma suíte de escritório livre, criada para ser executada exclusivamente no ambiente Linux e oferecer todas as funções esperadas de uma suíte profissional: editor de textos, planilha, apresentação, editor de desenhos e banco de dados.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2013,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":4303209,"enunciado":"Considere que, após a execução do comando ls , um usuário obtenha a seguinte resposta:\n\ndrwxrwxrwx João users teste\n\nNesse caso, no trecho drwxrwxrwx, d identifica o tipo de arquivo como arquivo comum; a segunda, a terceira e a quarta letras — rwx — garantem a João a permissão de ler, gravar e executar o arquivo teste; respectivamente; e a quinta, a sexta e a sétima letras — rwx — especificam, respectivamente, que, do grupo users, apenas João terá acesso ao arquivo teste.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":4303210,"enunciado":"O Linux é um sistema operacional multiusuário, por permitir que vários usuários possam utilizá-lo simultaneamente, e multitarefa, já que não possui restrições quanto à utilização de diversos programas ao mesmo tempo.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":4303211,"enunciado":"Apesar das interfaces gráficas com o usuário oferecerem mais interatividade, em determinadas situações o uso de comandos de console possibilita agilidade para usuários acostumados com essa modalidade de comandos. Considerando os comandos de console no Linux, juntamente com o uso de metacaracteres, e supondo que em um determinado diretório existam apenas os arquivos (file1, file2, file3 e file04), atribua V (verdadeiro) ou F (falso) às afirmativas a seguir. ( ) Os comandos #ls -l file1 file2 file3 file04 e #ls -l file* exibirão omesmo resultado. ( ) O comando #ls -l file? exibirá como resultado os quatro arquivos contidos no diretório. ( ) O comando #ls -l file[2-3] exibirá como resultado apenas os arquivos file2 e file3. ( ) O comando #ls -l file0* file[1-3] exibirá como resultado os quatro arquivos contidos no diretório. ( ) O comando #ls ~ exibirá como resultado uma lista de todos os arquivos que foram excluídos do diretório. Assinale a alternativa que contém, de cima para baixo, a sequência correta.","opcoes":["V, V, V, F, F.","V, V, F, F, V.","V, F, V, V, F.","F, V, V, F, F.","F, F, F, V, V."],"correta":2,"explicacao":"Gabarito: <strong>V, F, V, V, F.</strong>.","banca":"COPS-UEL","ano":2013,"temas_relacionados":["linux_geral"]},{"id":4303212,"enunciado":"Por ser um sistema operacional aberto, o Linux, comparativamente aos demais sistemas operacionais, proporciona maior facilidade de armazenamento de dados em nuvem.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2013,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":4303213,"enunciado":"No Linux, o diretório padrão de usuários é o /home. Nesse diretório, o usuário tem permissão de escrita, de execução e de leitura.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2012,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":4303214,"enunciado":"No Linux, quando se trata de diretórios, os comandos gzip e tar têm exatamente a mesma função: criar e compactar arquivos que contêm, internamente, outros arquivos ou diretórios.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2011,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":4303215,"enunciado":"No sistema Linux, existe um usuário de nome root, que tem poder de superusuário. Esse nome é reservado exclusivamente ao usuário que detém permissão para executar qualquer operação válida em qualquer arquivo ou processo. Há um único superusuário com esse perfil.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2012,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":4303216,"enunciado":"Por ser um sistema multitarefa, o Linux pode ser acessado por vários consoles ao mesmo tempo. Nesse sistema, para se alternar o acesso entre os consoles de 1 a 6, é correto utilizar o comando  + N, em que N representa o número do console desejado.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2012,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":4303217,"enunciado":"Analise as assertivas sobre conceitos básicos de sistemas operacionais: I - Windows Vista, Linux e JavaOS são exemplos de sistemas operacionais. II - Nos sistemas de tempo compartilhado, o tempo do processador é dividido em pequenos intervalos de tempo (time slices), dando a impressão de que diversos programas são executados ao mesmo tempo. III - O processamento em batch é caracterizado pela constante interação do usuário com a aplicação. IV - Os sistemas monoprogramáveis tem a característica de que o processador, a memória e os periféricos permanecem exclusivamente dedicados à execução de um único programa. Estão corretas:","opcoes":["Apenas I e III.","Apenas II e IV.","Apenas II, III e IV","Apenas I, II e IV.","I, II, III e IV."],"correta":1,"explicacao":"Gabarito: <strong>Apenas II e IV.</strong>.","banca":"PaqTcPB","ano":2012,"temas_relacionados":["linux_geral"]},{"id":4303218,"enunciado":"Julgue os itens seguintes, relativos a sistemas operacionais, redes sociais e organização de arquivos.\n\nTanto no sistema operacional Windows quanto no Linux, cada arquivo, diretório ou pasta encontra-se em um caminho, podendo cada pasta ou diretório conter diversos arquivos que são gravados nas unidades de disco nas quais permanecem até serem apagados. Em uma mesma rede é possível haver comunicação e escrita de pastas, diretórios e arquivos entre máquinas com Windows e máquinas com Linux.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2012,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":4303219,"enunciado":"Apesar de multiusuário e multiprogramável, o sistema operacional Linux não permite o redirecionamento de entrada e saída de dados.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2011,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":4303220,"enunciado":"Por meio do processo de escolha de pacotes, o usuário pode selecionar software que já estão pré-compilados para o funcionamento com o Fedora 10.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2009,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":4303221,"enunciado":"O Linux é um programa de edição de conteúdo que permite a colaboração de diversos usuários.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2009,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":4303222,"enunciado":"Gnome é uma interface gráfica que facilita o uso do ambiente Linux e apresenta uma aparência semelhante à oferecida pelos sistemas Windows. Comparando Gnome com a interface gráfica do Windows, analise as afirmativas a seguir e marque a alternativa CORRETA. I- O Gnome tem uma área de trabalho; II- O Gnome permite utilizar o botão direito do mouse; III- O Gnome permite criar pastas; IV- O Gnome permite as operações de copiar e colar; V- Quando houver uma leitora de CD disponível, o Gnome permitirá ver arquivos que se encontram em um CD.","opcoes":["Somente a afirmativa III está correta.","Somente a afirmativa IV está correta.","Somente as afirmativas I, III, IV e V estão corretas.","Somente as afirmativas I, II, III e V estão corretas.","Todas as afirmativas estão corretas."],"correta":2,"explicacao":"Gabarito: <strong>Somente as afirmativas I, III, IV e V estão corretas.</strong>.","banca":"Fundação CETAP","ano":2010,"temas_relacionados":["linux_geral"]},{"id":4303223,"enunciado":"No Linux, o comando pwd é utilizado para alterar a senha de usuário.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":4303224,"enunciado":"Com relação ao software é CORRETO afirmar que: I. Software gratuito ou freeware é qualquer programa de computador que pode ser utilizado livremente, não implicando no pagamento de licença de uso. II. Software proprietário é qualquer programa de computador cuja utilização, cópia, redistribuição ou modificação são, em alguma medida, proibidos pelo seu criador ou distribuidor, implicando na aquisição de uma licença para tais finalidades. III. Software livre é qualquer programa de computador que pode ser usado, copiado, estudado e modificado sem nenhuma restrição. IV. Software shareware é qualquer programa de computador disponibilizado gratuitamente, porém com algum tipo de limitação, quer sejam funcionalidades e/ou tempo de uso limitados, ao final do qual o usuário é requisitado a pagar uma quantia para acessar as funcionalidades completas ou poder continuar utilizando o programa. A sequência correta é:","opcoes":["Apenas as assertivas I, II e III estão corretas.","Apenas as assertivas I, II e IV estão corretas.","As assertivas I, II, III e IV estão corretas.","Apenas as assertivas I, III e IV estão corretas."],"correta":2,"explicacao":"Gabarito: <strong>As assertivas I, II, III e IV estão corretas.</strong>.","banca":"IESES","ano":2010,"temas_relacionados":["linux_geral"]},{"id":4303225,"enunciado":"No Linux, quando um processo recebe um determinado sinal, via de regra, executa as instruções contidas naquele sinal. O kill, que é um comando utilizado para \"matar\" um processo, pode, também, ser usado para enviar qualquer sinal. Entretanto, se for usado sem o parâmetro de um sinal, ele executará a mesma função do sinal","opcoes":["STOP.","SEGV.","TERM.","CONT.","ILL."],"correta":2,"explicacao":"Gabarito: <strong>TERM.</strong>.","banca":"FCC","ano":2011,"temas_relacionados":["linux_geral"]},{"id":4303226,"enunciado":"No Linux, o diretório raiz, que é representado pela barra /, e o diretório representado por /dev servem para duas funções primordiais ao funcionamento do ambiente: o primeiro é onde fica localizada a estrutura de diretórios e subdiretórios do sistema; o segundo é onde ficam os arquivos de dispositivos de hardware do computador em que o Linux está instalado.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":4303227,"enunciado":"O sistema operacional Linux não é","opcoes":["capaz de dar suporte a diversos tipos de sistema de arquivos.","um sistema monousuário.","um sistema multitarefa.","capaz de ser compilado de acordo com a necessidade do usuário.","capaz de suportar diversos módulos de dispositivos externos."],"correta":1,"explicacao":"Gabarito: <strong>um sistema monousuário.</strong>.","banca":"CESPE / CEBRASPE","ano":2009,"temas_relacionados":["linux_geral"]},{"id":4303228,"enunciado":"Com relação ao sistema operacional e ao ambiente Linux, assinale a opção correta.","opcoes":["O kernel é um software que se instala dentro do Linux e faz com que o Linux possa ser distribuído gratuitamente.","O Linux oferece a opção de que um novo usuário possa abrir uma sessão de uso do ambiente para utilizar seus aplicativos mesmo que outro usuário esteja logado no sistema.","O Linux pode ser acessado a partir da área de trabalho do Gnome apenas, pois o KDE é uma GUI que só pode ser utilizada em computador que tiver instalado o Windows para uso simultâneo.","Debian é uma das distribuições do Linux mais utilizadas no mundo; no entanto, sua interface não suporta a língua portuguesa, sendo necessário conhecimento de inglês para acesso.","O Linux oferece facilidade de interação entre software de diversas plataformas; no entanto, não permite que sejam criados drivers de configuração para que outros hardware possam rodar no Linux."],"correta":4,"explicacao":"Gabarito: <strong>O Linux oferece facilidade de interação entre software de diversas plataformas; no entanto, não permite que sejam criados drivers de configuração para que outros hardware possam rodar no Linux.</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"temas_relacionados":["linux_geral"]},{"id":4303229,"enunciado":"O Linux, sistema operacional muito utilizado por administradores de ambientes de tecnologia da informação, é pouco utilizado pelos usuários de computadores do tipo PC, por apresentar comandos complexos e interface apenas textual, sem elementos gráficos.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2009,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":4303230,"enunciado":"Acerca dos sistemas operacionais Windows e Linux, assinale a opção correta.","opcoes":["Arquivos criados no Linux podem ser lidos no Windows por meio da ferramenta Restauração do sistema, existente no menu Iniciar do Windows.","No Linux, o programa PlanCalc permite a elaboração de planilhas eletrônicas, de forma equivalente ao Excel no Windows.","No sistema Windows, o aplicativo Windows Explorer tem a função exclusiva de facilitar o gerenciamento das informações em um computador, permitindo criar, excluir e renomear arquivos e pastas; enquanto o Internet Explorer é um browser que permite a navegação na Internet.","Por ser software livre, o usuário tem a liberdade de copiar e modificar uma distribuição do Linux, sem solicitar qualquer tipo de permissão.","Por meio da opção Windows UpDate, é possível ajustar data, hora e fuso horário do computador."],"correta":3,"explicacao":"Gabarito: <strong>Por ser software livre, o usuário tem a liberdade de copiar e modificar uma distribuição do Linux, sem solicitar qualquer tipo de permissão.</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"temas_relacionados":["linux_geral"]},{"id":4303231,"enunciado":"Entre as diferentes distribuições do sistema operacional Linux estão","opcoes":["Conectiva, OpenOffice, StarOffice e Debian.","GNU, Conectiva, Debian e Kernel.","KDE, Blackbox, Debian e Pipe.","Debian, Conectiva, Turbo Linux e Slackware.","Fedora, RedHat, Kurumim e Posix."],"correta":3,"explicacao":"Gabarito: <strong>Debian, Conectiva, Turbo Linux e Slackware.</strong>.","banca":"CESPE / CEBRASPE","ano":2009,"temas_relacionados":["linux_geral"]},{"id":4303232,"enunciado":"O Linux, sistema operacional bastante difundido atualmente e adotado por grandes empresas, possui capacidade de multitarefa, multiprocessamento, memória virtual por paginação e bibliotecas compartilhadas.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2009,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":4303233,"enunciado":"O Apache, um servidor web livre amplamente utilizado no mundo, é compatível com os sistemas operacionais Unix, Linux, Windows e Novell Netware.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":4303234,"enunciado":"Remove arquivos no Linux o comando","opcoes":["pwd","mkdir","cd","rm","tar"],"correta":3,"explicacao":"Gabarito: <strong>rm</strong>.","banca":"FCC","ano":2010,"temas_relacionados":["linux_geral"]},{"id":4303235,"enunciado":"No que se refere ao sistema operacional Linux, assinale a opção correta.","opcoes":["No Linux, Konqueror é um editor de textos que tem funcionalidades semelhantes às do Word, mas permite acesso a arquivos em diversos formatos, além do .doc.","Não é possível instalar o Linux em uma máquina em que já esteja instalado outro sistema operacional, pois isso gera incompatibilidade entre eles.","O Linux tem-se tornado atrativo para uso em função da redução progressiva do custo de suas versões, que se tornam mais baratas quando comparadas às soluções de mercado, além de ser mais fácil de se instalar.","O KDE Control Center oferece opções de configuração do ambiente Linux, tendo funcionalidades equivalentes às do Painel de controle do Windows.","A segurança do sistema operacional Linux está no fato de permitir o uso de apenas um usuário por computador, o que evita a necessidade de senhas ou outras formas de restrição de acesso."],"correta":3,"explicacao":"Gabarito: <strong>O KDE Control Center oferece opções de configuração do ambiente Linux, tendo funcionalidades equivalentes às do Painel de controle do Windows.</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"temas_relacionados":["linux_geral"]},{"id":4303236,"enunciado":"Considere as características abaixo em relação ao sistema operacional Linux I. multiusuário e monotarefa; II. leitura de executáveis sob demanda; III. memória virtual. É correto o que se afirma APENAS em","opcoes":["I.","II.","III.","I e II.","II e III."],"correta":4,"explicacao":"Gabarito: <strong>II e III.</strong>.","banca":"FCC","ano":2006,"temas_relacionados":["linux_geral"]},{"id":4303237,"enunciado":"O comando Linux que lista o conteúdo de um diretório, arquivos ou subdiretórios é o","opcoes":["init 0.","init 6.","exit.","ls.","cd."],"correta":3,"explicacao":"Gabarito: <strong>ls.</strong>.","banca":"FCC","ano":2010,"temas_relacionados":["linux_geral"]},{"id":4303238,"enunciado":"O Linux é um sistema operacional que pode ser usado apenas em servidores, não sendo adequado para a utilização em estações de trabalho do tipo PC. No entanto, é um sistema cujo código-fonte fica disponível para alterações, permitindo que os usuários contribuam para a sua melhoria.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":4303239,"enunciado":"Assim como o Windows XP, o Linux também disponibiliza o browser Internet Explorer na sua instalação.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":4303240,"enunciado":"Diferentemente do que ocorre no sistema Windows XP, no Linux, para se obter maior velocidade de acesso, os dados são armazenados diretamente em pastas, e não em subpastas.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2009,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":4303241,"enunciado":"O Linux é pouco vulnerável a vírus de computador devido à separação de privilégios entre processos, desde que sejam respeitadas as recomendações padrão de política de segurança e uso de contas privilegiadas.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2009,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":4303242,"enunciado":"Considere que a janela do Windows XP acima ilustrada esteja sendo executada em um computador PC e julgue os seguintes\nitens.\n\nSe o processador do computador for do tipo Pentium dualcore da Intel e utilizar a tecnologia denominada hyperthreading, tais recursos farão que esse computador tenha capacidade de executar simultaneamente os sistemas operacionais Windows e o Unix/Linux.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2006,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":4303243,"enunciado":"Acerca de sistemas operacionais e aplicativos, julgue o item a seguir. \nO sistema operacional atua no gerenciamento de arquivos, embora não seja o único responsável pela velocidade de acesso a esses arquivos.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2013,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":4303244,"enunciado":"Julgue o item a seguir, acerca do sistema operacional Linux e do editor de texto BrOffice Writer.\n\nO sistema Linux pode ser inicializado no modo manual, sendo necessária, nessa situação, uma interferência do operador antes da execução completa dos scripts de inicialização do modo automático.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2013,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":4335563,"enunciado":"Com relação à implementação e ao gerenciamento de backups, à recuperação de dados e à identificação e à correção de falhas e de problemas, julgue o item a seguir.\n\n\n\n\nAo digitar o comando rsync ‑avz dentro do diretório /etc/config_sys do Linux, todos os arquivos de sistema serão restaurados, possibilitando, dessa forma, que o Linux retorne para suas configurações iniciais.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["linux_geral"]},{"id":4335564,"enunciado":"Sobre o sistema operacional Linux, é INCORRETO afirmar que:","opcoes":["Suas funcionalidades permitem que um computador seja utilizado como estação de trabalho para edição de textos, planilhas e apresentações.","Ambientes de desenvolvimento e compiladores distribuídos livremente permitem o uso do sistema para desenvolvimento de programas em diversas linguagens.","Pacotes de programas diversos permitem que o computador atue como servidor de arquivos, de www, de autenticação e de aplicações.","A incompatibilidade dos formatos de arquivos impede a comunicação com sistemas com Windows.","Emuladores permitem a execução de diversos programas originalmente desenvolvidos para sistemas com Windows."],"correta":4,"explicacao":"Gabarito: <strong>Emuladores permitem a execução de diversos programas originalmente desenvolvidos para sistemas com Windows.</strong>.","banca":"UFABC","ano":2006,"temas_relacionados":["linux_geral"]},{"id":4335565,"enunciado":"No Linux, o diretório /etc contém a maioria dos arquivos básicos de configuração do sistema operacional. O compartilhamento de diretórios locais via Network File System (NFS) é um exemplo. Você, como um administrador Linux, pode ser o responsável pelo NFS dos servidores de sua organização. Dessa forma, para configurar o compartilhamento de diretórios locais via NFS, o arquivo a ser usado seria o","opcoes":["bashrc.","export.","mtab.","named.conf.","services."],"correta":1,"explicacao":"Gabarito: <strong>export.</strong>.","banca":"FGV","ano":2024,"temas_relacionados":["linux_geral"]},{"id":4335566,"enunciado":"Qual comando do Linux é responsável por remover um diretório/arquivo?","opcoes":["mkdir.","cat.","rm.","mesg."],"correta":2,"explicacao":"Gabarito: <strong>rm.</strong>.","banca":"UNIVIDA","ano":2024,"temas_relacionados":["linux_geral"]},{"id":4335567,"enunciado":"No Ubuntu Linux, a principal função do comando grep é","opcoes":["criar um diretório.","listar os processos em execução no sistema.","copiar arquivos de um local para outro.","procurar por padrões em arquivos de texto.","criar arquivos compactados."],"correta":3,"explicacao":"Gabarito: <strong>procurar por padrões em arquivos de texto.</strong>.","banca":"FGV","ano":2024,"temas_relacionados":["linux_geral"]},{"id":4335568,"enunciado":"O Linux Ubuntu é um Sistema Operacional fácil de usar, instalar e configurar. Além do ambiente gráfico no Linux, existem 6 ambientes de linha de comando, conhecidos pelo nome de TTY (TeleTYpe) ou terminais virtuais. Nesse contexto, estando no modo de linha de comando e desejando retornar ao modo gráfico, deve-se pressionar simultaneamente as teclas:","opcoes":["Ctrl + Alt + F2;","Ctrl + Alt + F3;","Ctrl + Alt + F5;","Ctrl + Alt + F6;","Ctrl + Alt + F7."],"correta":1,"explicacao":"Gabarito: <strong>Ctrl + Alt + F3;</strong>.","banca":"FGV","ano":2024,"temas_relacionados":["linux_geral"]},{"id":4335569,"enunciado":"Qual comando do terminal Linux deve ser utilizado para exibir quem está logado no sistema?","opcoes":["Ps.","History.","Who.","Pwd."],"correta":1,"explicacao":"Gabarito: <strong>History.</strong>.","banca":"UNIVIDA","ano":2024,"temas_relacionados":["linux_geral"]},{"id":4335570,"enunciado":"Analise as opções abaixo e responda. I- ls II- df III- cd IV- mkdir Dos comandos apresentados acima, qual é responsável por criar um diretório no Linux?","opcoes":["II.","IV.","I.","III."],"correta":1,"explicacao":"Gabarito: <strong>IV.</strong>.","banca":"UNIVIDA","ano":2024,"temas_relacionados":["linux_geral"]},{"id":4335571,"enunciado":"Um usuário de um computador com sistema operacional Linux precisa usar um comando que permite atualizar os tempos de acesso e modificação de arquivos especificados. Esse comando é conhecido como:","opcoes":["cat","pwd","move","touch"],"correta":3,"explicacao":"Gabarito: <strong>touch</strong>.","banca":"INQC","ano":2024,"temas_relacionados":["linux_geral"]},{"id":4335572,"enunciado":"No sistema operacional Linux, o comando que informa o diretório absoluto corrente, ou seja, o caminho completo desde a raiz do sistema, é o","opcoes":["dir.","cd.","pwd.","ls.","cat."],"correta":2,"explicacao":"Gabarito: <strong>pwd.</strong>.","banca":"Quadrix","ano":2023,"temas_relacionados":["linux_geral"]},{"id":4335573,"enunciado":"É um exemplo de Sistema Operacional Linux:","opcoes":["Switch","Avg","Avira","Fedora","Firefox"],"correta":3,"explicacao":"Gabarito: <strong>Fedora</strong>.","banca":"IVIN","ano":2023,"temas_relacionados":["linux_geral"]},{"id":4335574,"enunciado":"No Linux, alguns comandos fazem modificações importantes na instalação e recuperação do sistema. O comando chroot, por exemplo, é usado para","opcoes":["alterar o nível de permissão de usuário que seja dono de um arquivo, pasta ou documento.","mostrar a quantidade de espaço usado no disco rígido onde o sistema operacional está instalado.","alterar o diretório aparente do root para criar um novo ambiente logicamente separado do diretório root do sistema principal.","criar um novo diretório home para o usuário, fazendo com que os arquivos do diretório atual do usuário sejam movidos para o novo diretório."],"correta":2,"explicacao":"Gabarito: <strong>alterar o diretório aparente do root para criar um novo ambiente logicamente separado do diretório root do sistema principal.</strong>.","banca":"INSTITUTO MAIS","ano":2023,"temas_relacionados":["linux_geral"]},{"id":4335575,"enunciado":"No sistema operacional Linux, dentre as alternativas a seguir, os comandos que servem para (i) criar um usuário, (ii) alterar permissões de leitura e escrita de um arquivo e (iii) editar um arquivo-texto são, respectivamente:","opcoes":["usercreate, chmod e nano.","adduser, chmod e vi.","useradd, permission e edit.","useradd, chown e edit.","insertuser, chown e vi."],"correta":1,"explicacao":"Gabarito: <strong>adduser, chmod e vi.</strong>.","banca":"VUNESP","ano":2022,"temas_relacionados":["linux_geral"]},{"id":4335576,"enunciado":"Com relação à estrutura de diretórios usada no Linux Ubuntu, assinale a alternativa que apresenta os diretórios que são destinados, respectivamente, à montagem temporária de dispositivos removíveis, como, por exemplo, os pen drives, e ao ponto de montagem temporário para dispositivos.","opcoes":["/bin e /mnt","/dev e /bin","/dev e /media","/media e /mnt","/etc e /boot"],"correta":4,"explicacao":"Gabarito: <strong>/etc e /boot</strong>.","banca":"Quadrix","ano":2023,"temas_relacionados":["linux_geral"]},{"id":4335577,"enunciado":"Caso o usuário do sistema operacional Linux deseje criar um arquivo vazio (sem conteúdo), via terminal, ele deverá fazer uso do comando","opcoes":["ls.","df.","mkdir.","touch.","date."],"correta":3,"explicacao":"Gabarito: <strong>touch.</strong>.","banca":"Quadrix","ano":2022,"temas_relacionados":["linux_geral"]},{"id":4335578,"enunciado":"No contexto do sistema operacional Linux, assinale o comando que serve para concatenar arquivos.","opcoes":["cat","cd","chmod","ls","mv"],"correta":0,"explicacao":"Gabarito: <strong>cat</strong>.","banca":"FGV","ano":2022,"temas_relacionados":["linux_geral"]},{"id":4335579,"enunciado":"No Google Chrome, em computadores com o sistema operacional Linux, o botão , localizado no canto superior direito da tela, tem a função de","opcoes":["compartilhar página.","ativar a pesquisa rápida.","copiar a URL.","adicionar a página aos favoritos.","mostrar painel lateral."],"correta":4,"explicacao":"Gabarito: <strong>mostrar painel lateral.</strong>.","banca":"Quadrix","ano":2022,"temas_relacionados":["linux_geral"]},{"id":4335580,"enunciado":"O Linux foi criado com o objetivo de ser um software:","opcoes":["gratuito e com o código fonte aberto.","pago com código fonte fechado.","pago sem código fonte.","gratuito e com código fonte fechado.","pago com código fonte aberto."],"correta":0,"explicacao":"Gabarito: <strong>gratuito e com o código fonte aberto.</strong>.","banca":"IBADE","ano":2022,"temas_relacionados":["linux_geral"]},{"id":4335581,"enunciado":"O comando cd /home/funcel/dados/, executado em um terminal do sistema operacional Linux, tem a finalidade de","opcoes":["criar um link simbólico chamado /home/funcel/dados/, apontando para o diretório corrente do usuário.","apagar toda a estrutura de diretórios /home/funcel/dados/ do Linux.","mover todos os arquivos do diretório atual do usuário para o subdiretório dados.","entrar no subdiretório dados.","criar a estrutura de diretórios /home/funcel/dados/ no Linux."],"correta":4,"explicacao":"Gabarito: <strong>criar a estrutura de diretórios /home/funcel/dados/ no Linux.</strong>.","banca":"Quadrix","ano":2021,"temas_relacionados":["linux_geral"]},{"id":4335582,"enunciado":"No sistema operacional Linux, o comando destinado a alterar as permissões de um arquivo ou grupo de arquivos é o","opcoes":["pwd.","mkdir.","ls.","cd.","chmod."],"correta":4,"explicacao":"Gabarito: <strong>chmod.</strong>.","banca":"Quadrix","ano":2021,"temas_relacionados":["linux_geral"]},{"id":4335583,"enunciado":"Para ser uma distribuição GNU/Linux considerada completamente livre, os desenvolvedores desses sistemas precisam se comprometer em","opcoes":["incluir ao menos um software livre nativo no sistema operacional e, opcionalmente, softwares proprietários.","atender aos parâmetros da ISO 45001.","seguir as diretrizes para distribuição de sistemas livres.","desenvolver o sistema operacional utilizando-se apenas de ferramentas de código aberto.","ter um meio de distribuição de mídias em formato ROM gratuito."],"correta":2,"explicacao":"Gabarito: <strong>seguir as diretrizes para distribuição de sistemas livres.</strong>.","banca":"INSTITUTO AOCP","ano":2021,"temas_relacionados":["linux_geral"]},{"id":4335584,"enunciado":"Assinale a alternativa que apresenta o usuário do sistema operacional Linux que é conhecido como superusuário e que pode atuar como o proprietário de qualquer arquivo ou processo.","opcoes":["administrator","kernel","admin","root","init"],"correta":3,"explicacao":"Gabarito: <strong>root</strong>.","banca":"Quadrix","ano":2021,"temas_relacionados":["linux_geral"]},{"id":4335585,"enunciado":"No terminal Linux mostrado acima, caso o usuário digite o comando ls B* e pressione a tecla , será possível","opcoes":["calcular o total de bytes ocupados pelos arquivos existentes no diretório crbio6.","visualizar os arquivos que possuem o nome começando com a letra B (maiúscula).","alterar o nome de todos os arquivos, adicionando a letra B (maiúscula) no início de cada nome.","apagar todos os arquivos que começam com a letra B, independentemente de a letra B ser maiúscula ou minúscula.","abrir os arquivos que possuem o nome começando com a letra B (maiúscula)."],"correta":1,"explicacao":"Gabarito: <strong>visualizar os arquivos que possuem o nome começando com a letra B (maiúscula).</strong>.","banca":"Quadrix","ano":2021,"temas_relacionados":["linux_geral"]},{"id":4335586,"enunciado":"Os computadores que equipam os laboratórios de informática do IFTO destinados às atividades acadêmicas possuem instalados os sistemas operacionais Windows e Linux. Na lista a seguir, marque a opção que não representa uma função ou serviço oferecido aos usuários de um sistema operacional.","opcoes":["Imprimir documentos, editar textos e scanear imagens.","Gerenciar os dispositivos de entrada e saída de informações.","Administrar a capacidade de processamento da CPU entre as aplicações em uso.","Gerenciar o uso da memória de trabalho (RAM) fornecida a cada aplicação em uso.","Administrar o armazenamento de arquivos em mídias permanentes, definindo regras de acesso e uso."],"correta":0,"explicacao":"Gabarito: <strong>Imprimir documentos, editar textos e scanear imagens.</strong>.","banca":"IF-TO","ano":2021,"temas_relacionados":["linux_geral"]},{"id":4335587,"enunciado":"Um comando no GNU/Linux é uma terminologia especial que pode representar uma ou mais ações. Nesse sentido, qual é o comando que mostra o caminho inteiro de um diretório atual?","opcoes":["pwd","mv","ls","rm","df"],"correta":0,"explicacao":"Gabarito: <strong>pwd</strong>.","banca":"INSTITUTO AOCP","ano":2021,"temas_relacionados":["linux_geral"]},{"id":4335588,"enunciado":"Em Linux ao inserir o comando ________ o mesmo cancela os trabalhos de impressão que foram colocados na fila para impressão. Se nenhum argumento for fornecido, o trabalho atual no destino padrão será cancelado. Qual alternativa abaixo completa a lacuna de forma CORRETA:","opcoes":["ls","lprm","lpq","Nenhuma das alternativas."],"correta":1,"explicacao":"Gabarito: <strong>lprm</strong>.","banca":"Instituto Excelência","ano":2019,"temas_relacionados":["linux_geral"]},{"id":4335589,"enunciado":"Podemos definir o sistema operacional como um software primário que opera entre o hardware do dispositivo e milhares de outros softwares, os aplicativos. Sua função é administrar e gerenciar os recursos de um sistema, desde componentes de hardware e sistemas de arquivos a programas de terceiros, estabelecendo a interface entre o computador e o usuário. É possível afirmar que entre as alternativas abaixo, não é um sistema operacional:","opcoes":["Syllable.","ChromeOS.","Opera.","eComStation.","Linux."],"correta":2,"explicacao":"Gabarito: <strong>Opera.</strong>.","banca":"Dédalus Concursos","ano":2020,"temas_relacionados":["linux_geral"]},{"id":4335590,"enunciado":"No sistema operacional Linux, o diretório onde se encontram os arquivos de configuração e aplicativos do sistema tais como Apache é conhecido como:","opcoes":["/etc","/lib","/Bin","/sys","/cfg"],"correta":1,"explicacao":"Gabarito: <strong>/lib</strong>.","banca":"FUNRIO","ano":2018,"temas_relacionados":["linux_geral"]},{"id":4335591,"enunciado":"O sistema operacional que possui código aberto é:","opcoes":["Windows 7.","Windows Server.","Vmware.","Linux.","Z/OS."],"correta":1,"explicacao":"Gabarito: <strong>Windows Server.</strong>.","banca":"IBADE","ano":2020,"temas_relacionados":["linux_geral"]},{"id":4335592,"enunciado":"Qual dos softwares abaixo é um exemplo de software livre?","opcoes":["Microsoft Windows","Linux","Oracle","Mac OS","SAP ERP"],"correta":1,"explicacao":"Gabarito: <strong>Linux</strong>.","banca":"IBADE","ano":2019,"temas_relacionados":["linux_geral"]},{"id":4335593,"enunciado":"Pedro é o proprietário do arquivo header.txt em um sistema Linux e gostaria de assegurar que somente ele tivesse permissão de leitura, gravação e execução a este arquivo, enquanto que todos os demais usuários com acesso ao sistema tivessem somente a permissão de leitura. Assinale a opção que indica o comando que pode ser usado para conseguir esse objetivo.","opcoes":["chmod ug+r header.txt","chmod 766 header.txt","chmod 722 header.txt","chmod +r header.txt","chmod 744 header.txt"],"correta":4,"explicacao":"Gabarito: <strong>chmod 744 header.txt</strong>.","banca":"FGV","ano":2018,"temas_relacionados":["linux_geral"]},{"id":4335594,"enunciado":"Assinale a alternativa incorreta sobre o Sistema Operacional Linux:","opcoes":["O Linux foi desenvolvido para realizar a função de Spyware.","O Linux é um sistema operacional complexo e possui muitas falhas, por este motivo é inseguro para utilização.","O Linux é um software livre e gratuito.","O pacote Office é compatível com o Linux.","O Linux é essencialmente um software bancário."],"correta":2,"explicacao":"Gabarito: <strong>O Linux é um software livre e gratuito.</strong>.","banca":"Dédalus Concursos","ano":2018,"temas_relacionados":["linux_geral"]},{"id":4335595,"enunciado":"Em relação ao Sistema Operacional Ubuntu Linux, assinale a alternativa correta indicando o comando abaixo que pode ser utilizado para manipulação de arquivos.","opcoes":["mv","kill","top","netstat","awk"],"correta":0,"explicacao":"Gabarito: <strong>mv</strong>.","banca":"UFRR","ano":2018,"temas_relacionados":["linux_geral"]},{"id":4335596,"enunciado":"Assinale a opção que indica o comando do sistema operacional Linux que pode ser utilizado para exibir o conteúdo de um arquivo texto.","opcoes":["ln","touch","bg","cal","less"],"correta":4,"explicacao":"Gabarito: <strong>less</strong>.","banca":"FGV","ano":2018,"temas_relacionados":["linux_geral"]},{"id":4335597,"enunciado":"Em um computador com sistema operacional Linux, o comando fdisk consegue gerenciar partições no HD. Todavia, é importante conhecer a funcionalidade do comando, para evitar a perda de dados. Um comando com grande utilidade no Linux, que permite mostrar o conteúdo de um arquivo, está presente na alternativa:","opcoes":["cat","cal","top","type"],"correta":0,"explicacao":"Gabarito: <strong>cat</strong>.","banca":"FAUEL","ano":2016,"temas_relacionados":["linux_geral"]},{"id":4335598,"enunciado":"Windows e Linux têm em comum o fato de serem responsáveis, entre outras funções, pelo gerenciamento:","opcoes":["do acesso às páginas da Internet;","das senhas de login em sites e portais;","da extração e recuperação de backups;","do sistema de arquivos;","das senhas de aplicativos."],"correta":3,"explicacao":"Gabarito: <strong>do sistema de arquivos;</strong>.","banca":"FGV","ano":2015,"temas_relacionados":["linux_geral"]},{"id":4335599,"enunciado":"Com relação ao software livre, analise as afirmativas a seguir. I. É definido como qualquer programa de computador que pode ser executado, copiado, modificado e redistribuído pelos usuários. II. É o software em que os usuários possuem livre acesso ao código-fonte, e fazem alterações conforme as suas necessidades. III. É o software que oferece a liberdade de uso por qualquer tipo de pessoa ou organização, em qualquer sistema computacional, ou em qualquer tipo de trabalho, não sendo necessário comunicar o uso a nenhuma entidade específica. Assinale:","opcoes":["se somente a afirmativa I estiver correta.","se somente a afirmativa II estiver correta.","se somente a afirmativa III estiver correta.","se somente as afirmativas I e II estiverem corretas.","se todas as afirmativas estiverem corretas."],"correta":1,"explicacao":"Gabarito: <strong>se somente a afirmativa II estiver correta.</strong>.","banca":"FGV","ano":2013,"temas_relacionados":["linux_geral"]}];
